REQ: 白色椭圆平滑跟随鼠标指针移动，跟随速度为240
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 使用 Graphics 绘制白色椭圆并生成纹理
2. 创建椭圆精灵对象
3. 在 update 中获取鼠标指针位置
4. 计算椭圆到鼠标的距离和角度
5. 根据速度240和时间差计算移动距离，平滑移动椭圆
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let ellipse;
let pointer;
const FOLLOW_SPEED = 240; // 每秒移动的像素数

function preload() {
  // 使用 Graphics 绘制白色椭圆并生成纹理
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });
  graphics.fillStyle(0xffffff, 1);
  graphics.fillEllipse(30, 30, 60, 40); // 中心点(30,30)，宽60，高40
  graphics.generateTexture('ellipse', 60, 60);
  graphics.destroy();
}

function create() {
  // 创建椭圆精灵，初始位置在屏幕中心
  ellipse = this.add.sprite(400, 300, 'ellipse');

  // 获取鼠标指针引用
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // delta 是毫秒，转换为秒
  const deltaSeconds = delta / 1000;

  // 获取鼠标位置
  const targetX = pointer.x;
  const targetY = pointer.y;

  // 计算椭圆到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    ellipse.x,
    ellipse.y,
    targetX,
    targetY
  );

  // 如果距离大于1像素，则移动椭圆
  if (distance > 1) {
    // 计算移动角度
    const angle = Phaser.Math.Angle.Between(
      ellipse.x,
      ellipse.y,
      targetX,
      targetY
    );

    // 计算本帧应该移动的距离
    const moveDistance = Math.min(FOLLOW_SPEED * deltaSeconds, distance);

    // 根据角度和距离计算新位置
    ellipse.x += Math.cos(angle) * moveDistance;
    ellipse.y += Math.sin(angle) * moveDistance;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 创建一个橙色菱形，使用 Tween 动画在 4 秒内旋转一周并循环
API: Graphics, generateTexture, add.sprite, tweens.add
STEPS:
1. 使用 Graphics 绘制橙色菱形形状
2. 将 Graphics 转换为纹理以便应用于 Sprite
3. 创建 Sprite 对象并设置到画布中心
4. 使用 tweens.add 创建旋转动画，设置 4 秒完成 360 度旋转
5. 设置动画循环播放（loop: -1）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制橙色菱形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xFF8C00, 1); // 橙色

  // 绘制菱形（四个顶点）
  const size = 60;
  graphics.beginPath();
  graphics.moveTo(0, -size);      // 上顶点
  graphics.lineTo(size, 0);       // 右顶点
  graphics.lineTo(0, size);       // 下顶点
  graphics.lineTo(-size, 0);      // 左顶点
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('diamond', size * 2, size * 2);
  graphics.destroy(); // 销毁 Graphics 对象，因为已经生成纹理

  // 创建 Sprite 并放置在画布中心
  const diamond = this.add.sprite(400, 300, 'diamond');

  // 创建旋转动画
  this.tweens.add({
    targets: diamond,
    angle: 360,           // 旋转 360 度
    duration: 4000,       // 持续 4 秒（4000 毫秒）
    ease: 'Linear',       // 线性缓动，保持匀速旋转
    repeat: -1,           // 无限循环
    onRepeat: function() {
      // 每次循环重复时重置角度为 0，避免角度累积
      diamond.angle = 0;
    }
  });
}

new Phaser.Game(config);
```

