let ellipse;
let currentRotation = 0; // 当前旋转角度（弧度）

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  ellipse = this.add.graphics();

  // 设置椭圆的位置（中心点）
