  const degreesPerSecond = 200;

  // delta 是毫秒，转换为秒
  const deltaInSeconds = delta / 1000;

  // 计算本帧应旋转的角度（度）
  const rotationDegrees = degreesPerSecond * deltaInSeconds;

  // 转换为弧度并累加到当前旋转角度
  currentRotation += Phaser.Math.DegToRad(rotationDegrees);

  // 应用旋转
  ellipse.rotation = currentRotation;
