REQ: 让一个菱形以每秒 160 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Container, Phaser.Game, Phaser.Scene
STEPS:
1. 创建 Graphics 对象绘制菱形形状
2. 将 Graphics 添加到 Container 中以便于旋转控制
3. 在 update 方法中根据 delta 时间累加旋转角度（160度/秒 = 160 * delta/1000）
4. 使用 Container.setRotation 或 angle 属性应用旋转
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let diamond;
const ROTATION_SPEED = 160; // 每秒旋转160度

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建容器用于旋转
  diamond = this.add.container(400, 300);

  // 创建 Graphics 对象绘制菱形
  const graphics = this.add.graphics();

  // 设置菱形样式
  graphics.fillStyle(0x00ffff, 1);
  graphics.lineStyle(3, 0xffffff, 1);

  // 绘制菱形（四个顶点）
  const size = 80;
  graphics.beginPath();
  graphics.moveTo(0, -size);      // 上顶点
  graphics.lineTo(size, 0);       // 右顶点
  graphics.lineTo(0, size);       // 下顶点
  graphics.lineTo(-size, 0);      // 左顶点
  graphics.closePath();

  // 填充和描边
  graphics.fillPath();
  graphics.strokePath();

  // 将 graphics 添加到容器中
  diamond.add(graphics);

  // 添加提示文本
  this.add.text(400, 50, '菱形旋转速度: 160°/秒', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

function update(time, delta) {
  // 根据 delta 时间计算旋转增量
  // delta 单位是毫秒，需要转换为秒
  const rotationDelta = ROTATION_SPEED * (delta / 1000);

  // 累加旋转角度（angle 属性使用度数）
  diamond.angle += rotationDelta;

  // 可选：防止角度值无限增长
  if (diamond.angle >= 360) {
    diamond.angle -= 360;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 黄色敌人死亡时触发粒子爆炸效果，发射20个粒子向四周扩散后消失，持续4秒
API: ParticleEmitter, Graphics, Physics.Arcade, Sprite, Tween
STEPS:
1. 创建黄色敌人精灵和玩家精灵（使用Graphics生成纹理）
2. 配置物理系统，设置碰撞检测
3. 创建粒子发射器，配置粒子数量、速度、生命周期等参数
4. 监听敌人死亡事件，在死亡位置触发粒子爆炸
5. 添加状态变量记录击杀数和粒子爆炸次数
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.killCount = 0;
    this.explosionCount = 0;
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 创建黄色敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xffff00, 1); // 黄色
    enemyGraphics.fillCircle(16, 16, 16);
    enemyGraphics.generateTexture('enemy', 32, 32);
    enemyGraphics.destroy();

    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0000ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建粒子纹理（红色小圆点）
    const particleGraphics = this.add.graphics();
    particleGraphics.fillStyle(0xff6600, 1); // 橙红色
    particleGraphics.fillCircle(4, 4, 4);
    particleGraphics.generateTexture('particle', 8, 8);
    particleGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 创建多个黄色敌人
    for (let i = 0; i < 5; i++) {
      const enemy = this.enemies.create(
        100 + i * 150,
        100 + Math.sin(i) * 50,
        'enemy'
      );
      enemy.setVelocity(
        Phaser.Math.Between(-100, 100),
        Phaser.Math.Between(50, 150)
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }

    // 创建粒子发射器（初始时停止）
    this.particleEmitter = this.add.particles(0, 0, 'particle', {
      speed: { min: 100, max: 300 },
      angle: { min: 0, max: 360 },
      scale: { start: 1, end: 0 },
      alpha: { start: 1, end: 0 },
      lifespan: 4000, // 持续4秒
      gravityY: 150,
      quantity: 20, // 每次发射20个粒子
      frequency: -1, // 手动触发，不自动发射
      blendMode: 'ADD'
    });

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.hitEnemy,
      null,
      this
    );

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();
    this.spaceKey = this.input.keyboard.addKey(
      Phaser.Input.Keyboard.KeyCodes.SPACE
    );

    // 显示状态信息
    this.statusText = this.add.text(16, 16, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.updateStatus();

    // 提示文本
    this.add.text(400, 550, 'Arrow Keys: Move | Space: Kill Enemy', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    }).setOrigin(0.5);
  }

  update(time, delta) {
    // 玩家移动
    const speed = 200;
    this.player.setVelocity(0);

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    }

    // 空格键测试：杀死最近的敌人
    if (Phaser.Input.Keyboard.JustDown(this.spaceKey)) {
      const nearestEnemy = this.physics.closest(this.player, this.enemies.getChildren());
      if (nearestEnemy) {
        this.killEnemy(nearestEnemy);
      }
    }
  }

  hitEnemy(player, enemy) {
    // 碰撞时杀死敌人
    this.killEnemy(enemy);
  }

  killEnemy(enemy) {
    // 触发粒子爆炸效果
    this.triggerExplosion(enemy.x, enemy.y);

    // 销毁敌人
    enemy.destroy();

    // 更新击杀计数
    this.killCount++;
    this.updateStatus();

    // 如果所有敌人都被消灭，重新生成
    if (this.enemies.countActive() === 0) {
      this.time.delayedCall(2000, () => {
        this.respawnEnemies();
      });
    }
  }

  triggerExplosion(x, y) {
    // 在指定位置触发粒子爆炸
    this.particleEmitter.setPosition(x, y);
    this.particleEmitter.explode(20); // 发射20个粒子

    // 更新爆炸计数
    this.explosionCount++;
    this.updateStatus();

    // 添加闪光效果
    const flash = this.add.circle(x, y, 30, 0xffff00, 0.8);
    this.tweens.add({
      targets: flash,
      alpha: 0,
      scale: 2,
      duration: 500,
      onComplete: () => flash.destroy()
    });
  }

  respawnEnemies() {
    // 重新生成敌人
    for (let i = 0; i < 5; i++) {
      const enemy = this.enemies.create(
        100 + i * 150,
        100 + Math.sin(i) * 50,
        'enemy'
      );
      enemy.setVelocity(
        Phaser.Math.Between(-100, 100),
        Phaser.Math.Between(50, 150)
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }
  }

  updateStatus() {
    this.statusText.setText(
      `Kills: ${this.killCount} | Explosions: ${this.explosionCount} | Enemies: ${this.enemies.countActive()}`
    );
  }
}

