  this.tweens.add({
    targets: triangle,
    x: 700, // 目标 x 坐标（右侧）
    duration: 1000, // 持续时间 1 秒
    ease: 'Linear', // 线性缓动
    yoyo: true, // 启用往返效果（到达终点后返回起点）
    repeat: -1 // 无限循环（-1 表示永久重复）
  });
}

