REQ: 蓝色矩形平滑跟随鼠标指针移动，跟随速度为80
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Linear
STEPS:
1. 创建蓝色矩形 Graphics 对象作为跟随目标
2. 在 create 中获取 activePointer 获取鼠标位置
3. 在 update 中使用线性插值实现平滑跟随效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: {
    preload: preload,
    create: create,
    update: update
  },
  backgroundColor: '#2d2d2d'
};

let blueRect;
let pointer;
const followSpeed = 80; // 跟随速度

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 创建蓝色矩形
  blueRect = this.add.graphics();
  blueRect.fillStyle(0x0000ff, 1); // 蓝色
  blueRect.fillRect(-25, -25, 50, 50); // 以中心点为原点绘制 50x50 的矩形

  // 设置初始位置为屏幕中心
  blueRect.x = 400;
  blueRect.y = 300;

  // 获取鼠标指针
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // 计算跟随速度（考虑帧率差异）
  const speed = followSpeed * (delta / 1000);

  // 计算当前位置到目标位置的距离
  const dx = pointer.x - blueRect.x;
  const dy = pointer.y - blueRect.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // 如果距离大于阈值，则移动矩形
  if (distance > 1) {
    // 使用线性插值实现平滑跟随
    // 计算移动比例，确保不会超过目标位置
    const moveRatio = Math.min(speed / distance, 1);

    blueRect.x += dx * moveRatio;
    blueRect.y += dy * moveRatio;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央绘制一个青色星形，大小约为 80 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布尺寸为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的 5 个外顶点和 5 个内顶点坐标（基于中心点和半径）
4. 使用 beginPath、moveTo、lineTo 绘制星形路径
5. 使用青色填充星形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置青色填充样式 (cyan: 0x00ffff)
  graphics.fillStyle(0x00ffff, 1);

  // 画布中心点
  const centerX = 400;
  const centerY = 300;

  // 星形参数
  const outerRadius = 40; // 外半径 40px，总大小约 80px
  const innerRadius = 18; // 内半径约为外半径的 0.45 倍
  const points = 5; // 五角星

  // 开始绘制路径
  graphics.beginPath();

  // 绘制星形的各个顶点
  for (let i = 0; i < points * 2; i++) {
    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算角度（从顶部开始，逆时针旋转）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 计算顶点坐标
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    // 第一个点使用 moveTo，其他点使用 lineTo
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充星形
  graphics.fillPath();
}

new Phaser.Game(config);
```

[PLAN]
REQ: 绿色方块平滑跟随鼠标指针移动，跟随速度为160
API: Phaser.GameObjects.Graphics, Phaser.Input.InputPlugin, Phaser.Math.Distance, Phaser.Math.Angle
STEPS:
1. 使用 Graphics 绘制绿色方块并生成纹理
2. 创建 Sprite 对象作为可移动的方块
3. 在 update 中获取鼠标指针位置
4. 计算方块到鼠标的距离和角度
5. 根据速度和 delta 时间平滑移动方块朝向鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let square;
let pointer;
const FOLLOW_SPEED = 160; // 跟随速度（像素/秒）

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 创建绿色方块纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('squareTex', 50, 50);
  graphics.destroy();

  // 创建方块精灵，初始位置在屏幕中心
  square = this.add.sprite(400, 300, 'squareTex');
  square.setOrigin(0.5, 0.5);

  // 获取鼠标指针引用
  pointer = this.input.activePointer;

  // 添加提示文本
  const text = this.add.text(10, 10, '移动鼠标，绿色方块会跟随', {
    fontSize: '18px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 获取鼠标当前位置
  const mouseX = pointer.x;
  const mouseY = pointer.y;

  // 计算方块到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    square.x,
    square.y,
    mouseX,
    mouseY
  );

  // 如果距离大于1像素，则移动方块
  if (distance > 1) {
    // 计算方块到鼠标的角度
    const angle = Phaser.Math.Angle.Between(
      square.x,
      square.y,
      mouseX,
      mouseY
    );

    // 计算本帧应该移动的距离（速度 * 时间）
    const moveDistance = FOLLOW_SPEED * (delta / 1000);

    // 如果移动距离大于剩余距离，直接到达目标位置
    if (moveDistance >= distance) {
      square.x = mouseX;
      square.y = mouseY;
    } else {
      // 根据角度和移动距离计算新位置
      square.x += Math.cos(angle) * moveDistance;
      square.y += Math.sin(angle) * moveDistance;
    }
  }
}

new Phaser.Game(config);
```

