[PLAN]
REQ: 实现5关难度递增游戏，第1关12个绿色敌人，每关增加2个，显示关卡和敌人数
API: Phaser.Scene, Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Physics.Arcade.Group
STEPS:
1. 创建游戏场景，初始化关卡系统（currentLevel, enemiesPerLevel）
2. 使用 Graphics 生成玩家（蓝色方块）和敌人（绿色圆形）纹理
3. 创建物理系统，添加玩家精灵和敌人组（Physics.Arcade.Group）
4. 实现玩家键盘控制（方向键移动）
5. 实现碰撞检测，玩家碰到敌人则消灭敌人
6. 当所有敌人被消灭后进入下一关，重新生成更多敌人
7. 显示UI文本：当前关卡、剩余敌人数
8. 完成5关后显示胜利信息
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.currentLevel = 1;
    this.maxLevel = 5;
    this.baseEnemies = 12;
    this.enemiesIncrement = 2;
    this.remainingEnemies = 0;
  }

  preload() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    playerGraphics.fillStyle(0x0000ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（绿色圆形）
    const enemyGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    enemyGraphics.fillStyle(0x00ff00, 1);
    enemyGraphics.fillCircle(16, 16, 16);
    enemyGraphics.generateTexture('enemy', 32, 32);
    enemyGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 创建UI文本
    this.levelText = this.add.text(16, 16, '', {
      fontSize: '24px',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    this.enemyCountText = this.add.text(16, 50, '', {
      fontSize: '20px',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    this.messageText = this.add.text(400, 300, '', {
      fontSize: '32px',
      color: '#ffff00',
      backgroundColor: '#000000',
      padding: { x: 20, y: 10 }
    });
    this.messageText.setOrigin(0.5);
    this.messageText.setVisible(false);

    // 键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.collectEnemy,
      null,
      this
    );

    // 开始第一关
    this.startLevel();
  }

  startLevel() {
    // 清空现有敌人
    this.enemies.clear(true, true);

    // 计算当前关卡敌人数量
    const enemyCount = this.baseEnemies + (this.currentLevel - 1) * this.enemiesIncrement;
    this.remainingEnemies = enemyCount;

    // 更新UI
    this.updateUI();

    // 生成敌人（使用固定种子确保可重复性）
    const seed = this.currentLevel * 1000;
    for (let i = 0; i < enemyCount; i++) {
      // 简单的伪随机位置生成（确定性）
      const x = ((seed + i * 137) % 700) + 50;
      const y = ((seed + i * 211) % 400) + 50;

      const enemy = this.enemies.create(x, y, 'enemy');
      enemy.setVelocity(
        ((seed + i * 73) % 200) - 100,
        ((seed + i * 97) % 200) - 100
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }

    // 隐藏消息文本
    this.messageText.setVisible(false);
  }

  collectEnemy(player, enemy) {
    // 消灭敌人
    enemy.destroy();
    this.remainingEnemies--;

    // 更新UI
    this.updateUI();

    // 检查是否通关
    if (this.remainingEnemies === 0) {
      this.levelComplete();
    }
  }

  levelComplete() {
    // 停止玩家移动
    this.player.setVelocity(0, 0);

    if (this.currentLevel < this.maxLevel) {
      // 进入下一关
      this.currentLevel++;
      this.messageText.setText(`Level ${this.currentLevel - 1} Complete!\nStarting Level ${this.currentLevel}...`);
      this.messageText.setVisible(true);

      // 延迟2秒后开始下一关
      this.time.delayedCall(2000, () => {
        this.startLevel();
      });
    } else {
      // 游戏胜利
      this.messageText.setText('Congratulations!\nYou completed all 5 levels!');
      this.messageText.setVisible(true);

      // 停止所有敌人
      this.enemies.children.entries.forEach(enemy => {
        enemy.setVelocity(0, 0);
      });
    }
  }

  updateUI() {
    this.levelText.setText(`Level: ${this.currentLevel}/${this.maxLevel}`);
    this.enemyCountText.setText(`Enemies: ${this.remainingEnemies}`);
  }

  update(time, delta) {
    // 玩家控制
    const speed = 300;

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    } else {
      this.player.setVelocityY(0);
    }
  }
}

