    targets: star,
    scale: 0.16,           // 目标缩放值 16%
    duration: 500,         // 持续时间 0.5 秒
    yoyo: true,            // 启用往返效果（缩小后再放大）
    loop: -1,              // 无限循环
    ease: 'Sine.easeInOut' // 使用平滑的缓动函数
  });

  // 添加文字说明
  this.add.text(400, 550, 'Star scaling animation (1.0 → 0.16 → 1.0)', {
    fontSize: '20px',
    color: '#ffffff',
    align: 'center'
  }).setOrigin(0.5);
}

