    x: 700, // 目标 x 坐标（右侧）
    duration: 500, // 持续时间 0.5 秒
    yoyo: true, // 往返效果
    loop: -1, // 无限循环（-1 表示永久循环）
    ease: 'Linear' // 线性缓动
  });

  // 添加文字说明
  this.add.text(300, 50, '蓝色圆形左右往返循环', {
