REQ: 灰色圆形以360速度移动并在边界反弹
API: Graphics, GameObject.setVelocity, Physics.Arcade, World.setBoundsCollision
STEPS:
1. 创建 Arcade 物理系统配置
2. 使用 Graphics 绘制灰色圆形并生成纹理
3. 创建物理精灵并设置初始速度为 360
4. 设置精灵与世界边界碰撞并反弹
5. 在 update 中确保速度保持恒定
[/PLAN]

```javascript
const config = {
  type: Phaser.HEADLESS,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let ball;
const SPEED = 360;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制灰色圆形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1); // 灰色
  graphics.fillCircle(25, 25, 25); // 半径 25 的圆形

  // 生成纹理
  graphics.generateTexture('ballTexture', 50, 50);
  graphics.destroy();

  // 创建物理精灵
  ball = this.physics.add.sprite(400, 300, 'ballTexture');

  // 设置初始速度（随机方向）
  const angle = Phaser.Math.Between(0, 360);
  const vx = Math.cos(Phaser.Math.DegToRad(angle)) * SPEED;
  const vy = Math.sin(Phaser.Math.DegToRad(angle)) * SPEED;
  ball.setVelocity(vx, vy);

  // 设置与世界边界碰撞
  ball.setCollideWorldBounds(true);

  // 设置反弹系数为 1（完全弹性碰撞）
  ball.setBounce(1, 1);
}

function update(time, delta) {
  // 确保速度保持恒定（归一化速度向量并乘以固定速度）
  const velocity = ball.body.velocity;
  const currentSpeed = Math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y);

  if (currentSpeed > 0) {
    const normalizedX = velocity.x / currentSpeed;
    const normalizedY = velocity.y / currentSpeed;
    ball.setVelocity(normalizedX * SPEED, normalizedY * SPEED);
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 让一个圆形以每秒 360 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Container, Scene.update
STEPS:
1. 使用 Graphics 绘制一个圆形，并在圆形上添加标记（如一条线）以便观察旋转
2. 将 Graphics 添加到场景中央
3. 在 update 方法中根据 delta 时间计算旋转角度增量
4. 每帧更新 Graphics 的 rotation 属性，实现每秒 360 度（2π 弧度）的旋转速度
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let circle;

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 创建 Graphics 对象绘制圆形
  circle = this.add.graphics();

  // 设置圆形位置到屏幕中央
  circle.x = 400;
  circle.y = 300;

  // 绘制圆形主体
  circle.fillStyle(0x00aaff, 1);
  circle.fillCircle(0, 0, 80);

  // 绘制一条从圆心到边缘的线作为旋转标记
  circle.lineStyle(4, 0xffffff, 1);
  circle.beginPath();
  circle.moveTo(0, 0);
  circle.lineTo(80, 0);
  circle.strokePath();

  // 在圆形边缘添加一个小圆点作为额外的旋转参考
  circle.fillStyle(0xff0000, 1);
  circle.fillCircle(80, 0, 10);

  // 添加提示文本
  const text = this.add.text(400, 50, '圆形以每秒 360° 的速度旋转', {
    fontSize: '24px',
    color: '#ffffff'
  });
  text.setOrigin(0.5);
}

function update(time, delta) {
  // 计算旋转增量
  // 每秒 360 度 = 2π 弧度/秒
  // delta 是毫秒，需要转换为秒
  const rotationSpeed = Math.PI * 2; // 2π 弧度/秒
  const rotationDelta = rotationSpeed * (delta / 1000); // 根据帧时间计算旋转增量

  // 更新圆形的旋转角度
  circle.rotation += rotationDelta;
}

new Phaser.Game(config);
```

