[PLAN]
REQ: 实现WASD控制玩家旋转和朝向射击，子弹速度80
API: Phaser.Physics.Arcade.Group, Phaser.Input.Keyboard.createCursorKeys, Phaser.Physics.Arcade.Sprite#setVelocity, Phaser.GameObjects.Graphics#generateTexture
STEPS:
1. 创建玩家精灵，使用Graphics绘制三角形表示朝向
2. 设置WASD键盘输入监听，AD控制旋转，W发射子弹
3. 创建子弹物理组，使用Graphics绘制圆形子弹
4. 在update中处理旋转逻辑，按W时根据玩家角度发射子弹
5. 子弹超出边界时自动销毁，添加bulletsFired计数器作为验证信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.bulletsFired = 0; // 验证信号：发射的子弹数量
    this.playerRotationSpeed = 0; // 验证信号：当前旋转速度
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    const { width, height } = this.cameras.main;

    // 创建玩家纹理（三角形，指向上方）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.beginPath();
    playerGraphics.moveTo(16, 0);      // 顶点
    playerGraphics.lineTo(0, 32);      // 左下
    playerGraphics.lineTo(32, 32);     // 右下
    playerGraphics.closePath();
    playerGraphics.fillPath();
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建子弹纹理（小圆形）
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(width / 2, height / 2, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.setDamping(true);
    this.player.setDrag(0.99);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 50
    });

    // 设置键盘输入
    this.keys = this.input.keyboard.addKeys({
      W: Phaser.Input.Keyboard.KeyCodes.W,
      A: Phaser.Input.Keyboard.KeyCodes.A,
      S: Phaser.Input.Keyboard.KeyCodes.S,
      D: Phaser.Input.Keyboard.KeyCodes.D
    });

    // 射击冷却
    this.lastFired = 0;
    this.fireRate = 200; // 毫秒

    // 添加调试文本
    this.debugText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff'
    });
  }

  update(time, delta) {
    // 处理旋转
    this.playerRotationSpeed = 0;
    const rotationSpeed = 3; // 度/帧

    if (this.keys.A.isDown) {
      this.player.angle -= rotationSpeed;
      this.playerRotationSpeed = -rotationSpeed;
    }
    if (this.keys.D.isDown) {
      this.player.angle += rotationSpeed;
      this.playerRotationSpeed = rotationSpeed;
    }

    // 处理射击
    if (this.keys.W.isDown && time > this.lastFired + this.fireRate) {
      this.fireBullet();
      this.lastFired = time;
    }

    // 清理超出边界的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active) {
        const bounds = this.physics.world.bounds;
        if (bullet.x < bounds.x - 50 || bullet.x > bounds.right + 50 ||
            bullet.y < bounds.y - 50 || bullet.y > bounds.bottom + 50) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      }
    });

    // 更新调试信息
    this.debugText.setText([
      `Bullets Fired: ${this.bulletsFired}`,
      `Player Angle: ${Math.round(this.player.angle)}°`,
      `Rotation Speed: ${this.playerRotationSpeed}°/frame`,
      `Active Bullets: ${this.bullets.countActive(true)}`,
      '',
      'Controls:',
      'A/D - Rotate',
      'W - Fire'
    ]);
  }

  fireBullet() {
    // 获取或创建子弹
    let bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 计算子弹速度（根据玩家角度）
      // Phaser中角度0度指向右侧，-90度指向上方
      const angleInRadians = Phaser.Math.DegToRad(this.player.angle - 90);
      const bulletSpeed = 400;

      const velocityX = Math.cos(angleInRadians) * bulletSpeed;
      const velocityY = Math.sin(angleInRadians) * bulletSpeed;

      bullet.setVelocity(velocityX, velocityY);
      bullet.setRotation(angleInRadians);

      // 增加发射计数
      this.bulletsFired++;
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#000000',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 用15x15二维数组生成粉色棋盘格地图，交替显示两种颜色
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Rectangle, Phaser.Scene
STEPS:
1. 创建 15x15 的二维数组来存储棋盘格状态
2. 使用 Graphics 或 Rectangle 绘制两种粉色（深粉和浅粉）的棋盘格
3. 根据行列索引奇偶性交替显示颜色
4. 添加状态变量记录棋盘格数量和生成状态
[/PLAN]

```javascript
class CheckerboardScene extends Phaser.Scene {
  constructor() {
    super('CheckerboardScene');
    this.boardSize = 15;
    this.tileSize = 40;
    this.boardData = [];
    this.tilesGenerated = 0; // 状态信号：已生成的格子数
    this.isComplete = false; // 状态信号：是否完成生成
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 初始化二维数组
    this.initBoardData();

    // 创建棋盘格纹理
    this.createTileTextures();

    // 渲染棋盘格
    this.renderCheckerboard();

    // 添加标题文本
    const titleText = this.add.text(
      400, 
      20, 
      'Pink Checkerboard 15x15', 
      {
        fontSize: '24px',
        fontFamily: 'Arial',
        color: '#ff1493',
        fontStyle: 'bold'
      }
    );
    titleText.setOrigin(0.5, 0);

    // 显示状态信息
    this.statusText = this.add.text(
      400,
      660,
      `Tiles: ${this.tilesGenerated} | Complete: ${this.isComplete}`,
      {
        fontSize: '18px',
        fontFamily: 'Arial',
        color: '#333333'
      }
    );
    this.statusText.setOrigin(0.5, 0);

    // 添加鼠标悬停效果
    this.addInteraction();
  }

  /**
   * 初始化15x15的二维数组
   */
  initBoardData() {
    for (let row = 0; row < this.boardSize; row++) {
      this.boardData[row] = [];
      for (let col = 0; col < this.boardSize; col++) {
        // 根据行列索引奇偶性决定颜色类型（0或1）
        const colorType = (row + col) % 2;
        this.boardData[row][col] = {
          row: row,
          col: col,
          colorType: colorType,
          isHovered: false
        };
      }
    }
  }

  /**
   * 创建两种粉色纹理
   */
  createTileTextures() {
    // 深粉色 (HotPink)
    const graphics1 = this.add.graphics();
    graphics1.fillStyle(0xff69b4, 1);
    graphics1.fillRect(0, 0, this.tileSize, this.tileSize);
    graphics1.lineStyle(1, 0xffffff, 0.3);
    graphics1.strokeRect(0, 0, this.tileSize, this.tileSize);
    graphics1.generateTexture('pinkTile1', this.tileSize, this.tileSize);
    graphics1.destroy();

    // 浅粉色 (LightPink)
    const graphics2 = this.add.graphics();
    graphics2.fillStyle(0xffb6c1, 1);
    graphics2.fillRect(0, 0, this.tileSize, this.tileSize);
    graphics2.lineStyle(1, 0xffffff, 0.3);
    graphics2.strokeRect(0, 0, this.tileSize, this.tileSize);
    graphics2.generateTexture('pinkTile2', this.tileSize, this.tileSize);
    graphics2.destroy();
  }

  /**
   * 渲染棋盘格
   */
  renderCheckerboard() {
    const startX = (800 - this.boardSize * this.tileSize) / 2;
    const startY = 60;

    for (let row = 0; row < this.boardSize; row++) {
      for (let col = 0; col < this.boardSize; col++) {
        const cellData = this.boardData[row][col];
        const x = startX + col * this.tileSize;
        const y = startY + row * this.tileSize;

        // 根据颜色类型选择纹理
        const textureName = cellData.colorType === 0 ? 'pinkTile1' : 'pinkTile2';

        // 创建图像对象
        const tile = this.add.image(x, y, textureName);
        tile.setOrigin(0, 0);
        tile.setInteractive();

        // 存储引用以便后续交互
        cellData.sprite = tile;

        // 增加已生成计数
        this.tilesGenerated++;
      }
    }

    // 标记完成
    this.isComplete = true;
    this.updateStatusText();
  }

  /**
   * 添加交互效果
   */
  addInteraction() {
    this.input.on('gameobjectover', (pointer, gameObject) => {
      // 鼠标悬停时改变透明度
      gameObject.setAlpha(0.7);
    });

    this.input.on('gameobjectout', (pointer, gameObject) => {
      // 鼠标移出时恢复透明度
      gameObject.setAlpha(1.0);
    });

    this.input.on('gameobjectdown', (pointer, gameObject) => {
      // 点击时闪烁效果
      this.tweens.add({
        targets: gameObject,
        alpha: 0.3,
        duration: 100,
        yoyo: true,
        repeat: 1
      });
    });
  }

  /**
   * 更新状态文本
   */
  updateStatusText() {
    if (this.statusText) {
      this.statusText.setText(
        `Tiles: ${this.tilesGenerated} | Complete: ${this.isComplete}`
      );
    }
  }

  update(time, delta) {
    // 可以在这里添加动画或其他更新逻辑
  }
}

// Phaser 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 700,
  backgroundColor: '#f5f5f5',
  scene: CheckerboardScene,
  parent: 'game-container'
};

// 创建游戏实例
const game = new Phaser.Game(config);
```

