REQ: 生成 8x8 随机障碍地图（30% 密度），玩家可点击寻路移动
API: Phaser.Tilemaps.Tilemap, Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Geom.Point
STEPS:
1. 使用 Graphics 生成地砖和障碍物纹理
2. 创建 8x8 Tilemap，随机放置约 30% 障碍
3. 实现 A* 寻路算法
4. 监听点击事件，计算路径并移动玩家
5. 添加状态信号（移动次数、当前位置等）
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.mapSize = 8;
    this.tileSize = 64;
    this.obstacleRate = 0.3;
    this.moveCount = 0; // 状态信号：移动次数
    this.playerTileX = 0; // 状态信号：玩家位置
    this.playerTileY = 0;
  }

  preload() {
    // 程序化生成纹理
    this.createTextures();
  }

  createTextures() {
    // 创建地板纹理
    const floorGraphics = this.add.graphics();
    floorGraphics.fillStyle(0xcccccc, 1);
    floorGraphics.fillRect(0, 0, this.tileSize, this.tileSize);
    floorGraphics.lineStyle(2, 0x999999, 1);
    floorGraphics.strokeRect(0, 0, this.tileSize, this.tileSize);
    floorGraphics.generateTexture('floor', this.tileSize, this.tileSize);
    floorGraphics.destroy();

    // 创建障碍物纹理
    const wallGraphics = this.add.graphics();
    wallGraphics.fillStyle(0x333333, 1);
    wallGraphics.fillRect(0, 0, this.tileSize, this.tileSize);
    wallGraphics.lineStyle(2, 0x000000, 1);
    wallGraphics.strokeRect(0, 0, this.tileSize, this.tileSize);
    wallGraphics.generateTexture('wall', this.tileSize, this.tileSize);
    wallGraphics.destroy();

    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillCircle(this.tileSize / 2, this.tileSize / 2, this.tileSize / 3);
    playerGraphics.lineStyle(3, 0x00aa00, 1);
    playerGraphics.strokeCircle(this.tileSize / 2, this.tileSize / 2, this.tileSize / 3);
    playerGraphics.generateTexture('player', this.tileSize, this.tileSize);
    playerGraphics.destroy();

    // 创建路径标记纹理
    const pathGraphics = this.add.graphics();
    pathGraphics.fillStyle(0xffff00, 0.5);
    pathGraphics.fillCircle(this.tileSize / 2, this.tileSize / 2, this.tileSize / 6);
    pathGraphics.generateTexture('path', this.tileSize, this.tileSize);
    pathGraphics.destroy();
  }

  create() {
    // 初始化地图数据
    this.mapData = this.generateMap();

    // 渲染地图
    this.renderMap();

    // 创建玩家
    this.player = this.add.sprite(
      this.tileSize / 2,
      this.tileSize / 2,
      'player'
    );

    // 创建UI文本
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.updateStatusText();

    // 监听点击事件
    this.input.on('pointerdown', this.handleClick, this);

    // 路径标记组
    this.pathMarkers = this.add.group();
  }

  generateMap() {
    const map = [];
    for (let y = 0; y < this.mapSize; y++) {
      map[y] = [];
      for (let x = 0; x < this.mapSize; x++) {
        // 起点不放障碍
        if (x === 0 && y === 0) {
          map[y][x] = 0;
        } else {
          map[y][x] = Math.random() < this.obstacleRate ? 1 : 0;
        }
      }
    }
    return map;
  }

  renderMap() {
    this.tiles = [];
    for (let y = 0; y < this.mapSize; y++) {
      this.tiles[y] = [];
      for (let x = 0; x < this.mapSize; x++) {
        const texture = this.mapData[y][x] === 1 ? 'wall' : 'floor';
        const tile = this.add.sprite(
          x * this.tileSize + this.tileSize / 2,
          y * this.tileSize + this.tileSize / 2,
          texture
        );
        this.tiles[y][x] = tile;
      }
    }
  }

  handleClick(pointer) {
    const tileX = Math.floor(pointer.x / this.tileSize);
    const tileY = Math.floor(pointer.y / this.tileSize);

    // 检查点击是否在地图范围内
    if (tileX < 0 || tileX >= this.mapSize || tileY < 0 || tileY >= this.mapSize) {
      return;
    }

    // 检查目标是否是障碍
    if (this.mapData[tileY][tileX] === 1) {
      return;
    }

    // 寻路
    const path = this.findPath(
      { x: this.playerTileX, y: this.playerTileY },
      { x: tileX, y: tileY }
    );

    if (path && path.length > 0) {
      this.moveAlongPath(path);
    }
  }

  findPath(start, end) {
    // A* 寻路算法
    const openList = [];
    const closedList = [];
    const startNode = {
      x: start.x,
      y: start.y,
      g: 0,
      h: this.heuristic(start, end),
      f: 0,
      parent: null
    };
    startNode.f = startNode.g + startNode.h;
    openList.push(startNode);

    while (openList.length > 0) {
      // 找到 f 值最小的节点
      let currentIndex = 0;
      for (let i = 1; i < openList.length; i++) {
        if (openList[i].f < openList[currentIndex].f) {
          currentIndex = i;
        }
      }
      const current = openList[currentIndex];

      // 到达终点
      if (current.x === end.x && current.y === end.y) {
        return this.reconstructPath(current);
      }

      // 移到关闭列表
      openList.splice(currentIndex, 1);
      closedList.push(current);

      // 检查邻居
      const neighbors = this.getNeighbors(current);
      for (const neighbor of neighbors) {
        // 跳过已在关闭列表中的节点
        if (closedList.find(n => n.x === neighbor.x && n.y === neighbor.y)) {
          continue;
        }

        const g = current.g + 1;
        const existing = openList.find(n => n.x === neighbor.x && n.y === neighbor.y);

        if (!existing) {
          const h = this.heuristic(neighbor, end);
          openList.push({
            x: neighbor.x,
            y: neighbor.y,
            g: g,
            h: h,
            f: g + h,
            parent: current
          });
        } else if (g < existing.g) {
          existing.g = g;
          existing.f = g + existing.h;
          existing.parent = current;
        }
      }
    }

    return null; // 无路径
  }

  heuristic(a, b) {
    // 曼哈顿距离
    return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
  }

  getNeighbors(node) {
    const neighbors = [];
    const directions = [
      { x: 0, y: -1 }, // 上
      { x: 1, y: 0 },  // 右
      { x: 0, y: 1 },  // 下
      { x: -1, y: 0 }  // 左
    ];

    for (const dir of directions) {
      const x = node.x + dir.x;
      const y = node.y + dir.y;

      if (x >= 0 && x < this.mapSize && y >= 0 && y < this.mapSize) {
        if (this.mapData[y][x] === 0) {
          neighbors.push({ x, y });
        }
      }
    }

    return neighbors;
  }

  reconstructPath(node) {
    const path = [];
    let current = node;
    while (current.parent) {
      path.unshift({ x: current.x, y: current.y });
      current = current.parent;
    }
    return path;
  }

  moveAlongPath(path) {
    // 清除旧的路径标记
    this.pathMarkers.clear(true, true);

    // 显示路径
    for (const point of path) {
      const marker = this.add.sprite(
        point.x * this.tileSize + this.tileSize / 2,
        point.y * this.tileSize + this.tileSize / 2,
        'path'
      );
      this.pathMarkers.add(marker);
    }

    // 移动玩家
    let index = 0;
    const moveNext = () => {
      if (index < path.length) {
        const point = path[index];
        this.tweens.add({
          targets: this.player,
          x: point.x * this.tileSize + this.tileSize / 2,
          y: point.y * this.tileSize + this.tileSize / 2,
          duration: 200,
          onComplete: () => {
            this.playerTileX = point.x;
            this.playerTileY = point.y;
            this.moveCount++;
            this.updateStatusText();
            index++;
            moveNext();
          }
        });
      } else {
        // 移动完成，清除路径标记
        this.time.delayedCall(300, () => {
          this.pathMarkers.clear(true, true);
        });
      }
    };
    moveNext();
  }

  updateStatusText() {
    this.statusText.setText(
      `Position: (${this.playerTileX}, ${this.playerTileY}) | Moves: ${this.moveCount}`
    );
  }
}

const config = {
  type: Phaser.AUTO,
  width: 512,
  height: 512,
  backgroundColor: '#222222',
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现 3 格血条显示，鼠标右键扣血，每 0.5 秒自动回复 1 点
API: Phaser.GameObjects.Graphics, Phaser.Input.Mouse, Phaser.Time.TimerEvent, Phaser.Time.Clock#addEvent
STEPS:
1. 创建 3 个血条格子的 Graphics 对象，初始为满血状态
2. 监听鼠标右键点击事件，每次点击扣除 1 点生命值
3. 使用 TimerEvent 创建定时器，每 0.5 秒回复 1 点生命值
4. 更新血条显示函数，根据当前生命值绘制对应数量的红色格子
5. 添加文本显示当前生命值便于验证
[/PLAN]

```javascript
class HealthBarScene extends Phaser.Scene {
  constructor() {
    super('HealthBarScene');
    this.health = 3; // 当前生命值
    this.maxHealth = 3; // 最大生命值
    this.healthBars = []; // 存储血条格子
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 创建标题文本
    this.add.text(400, 50, 'Health Bar Demo', {
      fontSize: '32px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 创建说明文本
    this.add.text(400, 100, 'Right Click to take damage\nAuto heal 1HP every 0.5s', {
      fontSize: '18px',
      color: '#cccccc',
      align: 'center'
    }).setOrigin(0.5);

    // 创建血条容器
    this.createHealthBar();

    // 创建生命值文本显示
    this.healthText = this.add.text(400, 400, `Health: ${this.health}/${this.maxHealth}`, {
      fontSize: '24px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 监听鼠标右键点击
    this.input.on('pointerdown', (pointer) => {
      if (pointer.rightButtonDown()) {
        this.takeDamage(1);
      }
    });

    // 创建自动回血定时器，每 0.5 秒执行一次
    this.healTimer = this.time.addEvent({
      delay: 500, // 0.5 秒
      callback: this.autoHeal,
      callbackScope: this,
      loop: true
    });

    // 添加调试信息文本
    this.debugText = this.add.text(10, 10, '', {
      fontSize: '16px',
      color: '#00ff00'
    });
  }

  // 创建血条显示
  createHealthBar() {
    const startX = 250; // 血条起始 X 坐标
    const startY = 250; // 血条起始 Y 坐标
    const barWidth = 80; // 每格血条宽度
    const barHeight = 30; // 血条高度
    const gap = 10; // 格子间距

    // 创建 3 个血条格子
    for (let i = 0; i < this.maxHealth; i++) {
      const x = startX + i * (barWidth + gap);

      // 创建背景（空血槽）
      const background = this.add.graphics();
      background.fillStyle(0x333333, 1);
      background.fillRect(x, startY, barWidth, barHeight);
      background.lineStyle(2, 0x666666, 1);
      background.strokeRect(x, startY, barWidth, barHeight);

      // 创建前景（血量显示）
      const foreground = this.add.graphics();
      foreground.fillStyle(0xff0000, 1);
      foreground.fillRect(x + 2, startY + 2, barWidth - 4, barHeight - 4);

      this.healthBars.push({
        background: background,
        foreground: foreground,
        x: x,
        y: startY,
        width: barWidth,
        height: barHeight
      });
    }

    this.updateHealthBar();
  }

  // 更新血条显示
  updateHealthBar() {
    for (let i = 0; i < this.maxHealth; i++) {
      const bar = this.healthBars[i];
      bar.foreground.clear();

      // 如果当前索引小于生命值，显示红色血条
      if (i < this.health) {
        bar.foreground.fillStyle(0xff0000, 1);
        bar.foreground.fillRect(bar.x + 2, bar.y + 2, bar.width - 4, bar.height - 4);
      }
    }

    // 更新生命值文本
    this.healthText.setText(`Health: ${this.health}/${this.maxHealth}`);
  }

  // 扣血函数
  takeDamage(amount) {
    if (this.health > 0) {
      this.health = Math.max(0, this.health - amount);
      this.updateHealthBar();
      this.debugText.setText(`Took ${amount} damage! Health: ${this.health}`);

      // 闪烁效果
      this.cameras.main.shake(100, 0.005);
    }
  }

  // 自动回血函数
  autoHeal() {
    if (this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + 1);
      this.updateHealthBar();
      this.debugText.setText(`Healed 1HP! Health: ${this.health}`);

      // 回血闪光效果
      this.cameras.main.flash(100, 0, 255, 0, false);
    }
  }

  update(time, delta) {
    // 可以在这里添加其他更新逻辑
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: HealthBarScene,
  input: {
    mouse: {
      target: null,
      capture: true
    }
  }
};

// 创建游戏实例
new Phaser.Game(config);
