    this.tweens.add({
      targets: diamond,
      x: initialX,
      y: initialY,
      duration: 300,
      ease: 'Power2'
    });
  });

  // 添加提示文本
  const instructionText = this.add.text(400, 50, '拖动菱形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  });
  instructionText.setOrigin(0.5);
}

