  this.input.on('pointerdown', (pointer) => {
    // 创建 Graphics 对象用于绘制菱形
    const graphics = this.add.graphics();

    // 设置填充颜色为白色
    graphics.fillStyle(0xffffff, 1);

    // 计算菱形的四个顶点坐标
    // 菱形尺寸为48像素，即从中心到各顶点距离为24像素
    const centerX = pointer.x;
    const centerY = pointer.y;
