    const points = [
      centerX, centerY - halfSize,  // 上顶点
      centerX + halfSize, centerY,  // 右顶点
      centerX, centerY + halfSize,  // 下顶点
      centerX - halfSize, centerY   // 左顶点
    ];

    // 绘制填充的菱形
    graphics.fillPoints(points, true);
  });

