  rectangle.on('drag', function(pointer, dragX, dragY) {
    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件 - 恢复原始大小
  rectangle.on('dragend', function(pointer) {
    this.setScale(1.0);
