  const graphics = this.add.graphics();
  graphics.fillStyle(0x0000ff, 1); // 蓝色
  graphics.fillEllipse(40, 30, 80, 60); // 中心点(40,30)，宽80，高60

  // 生成纹理
  graphics.generateTexture('ellipseTex', 80, 60);
  graphics.destroy(); // 销毁 graphics 对象，纹理已生成

  // 创建椭圆精灵，放置在画布中心
  ellipse = this.add.sprite(400, 300, 'ellipseTex');

  // 创建方向键
  cursors = this.input.keyboard.createCursorKeys();
}

function update(time, delta) {
  // 计算移动距离（速度 * 时间差，转换为秒）
  const distance = SPEED * (delta / 1000);

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 检测方向键输入
  if (cursors.left.isDown) {
    velocityX = -distance;
  } else if (cursors.right.isDown) {
    velocityX = distance;
  }

  if (cursors.up.isDown) {
    velocityY = -distance;
  } else if (cursors.down.isDown) {
    velocityY = distance;
  }

  // 更新椭圆位置
  ellipse.x += velocityX;
  ellipse.y += velocityY;

  // 限制在画布边界内
  const halfWidth = ellipse.width / 2;
  const halfHeight = ellipse.height / 2;

  if (ellipse.x - halfWidth < 0) {
    ellipse.x = halfWidth;
  } else if (ellipse.x + halfWidth > config.width) {
    ellipse.x = config.width - halfWidth;
  }

  if (ellipse.y - halfHeight < 0) {
    ellipse.y = halfHeight;
  } else if (ellipse.y + halfHeight > config.height) {
    ellipse.y = config.height - halfHeight;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央绘制一个紫色六边形，大小约为 24 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算六边形的六个顶点坐标（中心点在画布中央，半径为 24 像素）
4. 使用 Graphics API 绘制六边形路径并填充紫色
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置紫色填充
  graphics.fillStyle(0x9932CC, 1); // 紫色

  // 画布中心点
  const centerX = 400;
  const centerY = 300;

  // 六边形半径
  const radius = 24;

  // 绘制六边形
  graphics.beginPath();

  // 计算六个顶点（从顶部开始，顺时针）
  for (let i = 0; i < 6; i++) {
    // 角度：从 -90 度开始（顶部），每次增加 60 度
    const angle = (Math.PI / 180) * (-90 + i * 60);
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

new Phaser.Game(config);
