REQ: 创建一个绿色六边形，使用 Tween 动画实现 1.5 秒的弹跳循环效果
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.GameObjects.Sprite
STEPS:
1. 使用 Graphics 绘制绿色六边形并生成纹理
2. 创建 Sprite 对象使用该六边形纹理
3. 使用 Tween 创建 y 轴弹跳动画，设置 ease 为 'Bounce.easeOut'
4. 配置 Tween 为循环模式，duration 为 1500ms
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 创建六边形纹理
  const graphics = this.add.graphics();

  // 绘制绿色六边形
  const hexagonRadius = 50;
  const hexagonSides = 6;
  const centerX = 64;
  const centerY = 64;

  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(3, 0x00aa00, 1);

  // 计算六边形顶点
  graphics.beginPath();
  for (let i = 0; i < hexagonSides; i++) {
    const angle = (Math.PI / 3) * i - Math.PI / 6; // 旋转30度使六边形平顶
    const x = centerX + hexagonRadius * Math.cos(angle);
    const y = centerY + hexagonRadius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 128, 128);
  graphics.destroy();

  // 创建六边形精灵
  const hexagon = this.add.sprite(400, 200, 'hexagon');

  // 创建弹跳动画
  // 使用 yoyo 模式实现上下弹跳，配合 Bounce ease 实现弹跳效果
  this.tweens.add({
    targets: hexagon,
    y: 400, // 弹跳到的目标位置
    duration: 750, // 单程 0.75 秒
    ease: 'Bounce.easeOut', // 弹跳缓动
    yoyo: true, // 往返运动
    repeat: -1, // 无限循环
    hold: 0, // 到达目标位置后不停留
    repeatDelay: 0 // 重复之间无延迟
  });

  // 添加说明文字
  this.add.text(400, 550, '绿色六边形弹跳动画 (1.5秒循环)', {
    fontSize: '20px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 创建一个收集游戏，玩家控制角色收集20个随机分布的三角形，收集完成后显示通关文本
API: Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Input.Keyboard
STEPS:
1. 使用 Graphics 创建玩家纹理（圆形）和三角形纹理
2. 创建玩家物理精灵，添加键盘控制
3. 创建20个三角形物理组，随机分布在场景中
4. 添加碰撞检测，收集三角形时增加分数并销毁三角形
5. 当分数达到20时显示"恭喜通关"文本
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let triangles;
let cursors;
let scoreText;
let winText;
let score = 0;
const TOTAL_TRIANGLES = 20;

function preload() {
  // 创建玩家纹理（圆形）
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillCircle(16, 16, 16);
  graphics.generateTexture('player', 32, 32);
  graphics.destroy();

  // 创建三角形纹理
  const triangleGraphics = this.make.graphics({ x: 0, y: 0, add: false });
  triangleGraphics.fillStyle(0xffff00, 1);
  triangleGraphics.beginPath();
  triangleGraphics.moveTo(15, 5);
  triangleGraphics.lineTo(25, 25);
  triangleGraphics.lineTo(5, 25);
  triangleGraphics.closePath();
  triangleGraphics.fillPath();
  triangleGraphics.generateTexture('triangle', 30, 30);
  triangleGraphics.destroy();
}

function create() {
  // 创建玩家
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(true);
  player.setDamping(true);
  player.setDrag(0.8);
  player.setMaxVelocity(300);

  // 创建三角形组
  triangles = this.physics.add.group();

  // 随机生成20个三角形
  for (let i = 0; i < TOTAL_TRIANGLES; i++) {
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 550);
    const triangle = triangles.create(x, y, 'triangle');
    triangle.setCircle(10); // 设置碰撞体为圆形，更精确
  }

  // 添加碰撞检测
  this.physics.add.overlap(player, triangles, collectTriangle, null, this);

  // 创建键盘控制
  cursors = this.input.keyboard.createCursorKeys();

  // 创建分数文本
  scoreText = this.add.text(16, 16, '收集: 0 / ' + TOTAL_TRIANGLES, {
    fontSize: '24px',
    fill: '#ffffff',
    fontFamily: 'Arial'
  });

  // 创建通关文本（初始隐藏）
  winText = this.add.text(400, 300, '恭喜通关！', {
    fontSize: '48px',
    fill: '#ffff00',
    fontFamily: 'Arial',
    stroke: '#000000',
    strokeThickness: 6
  });
  winText.setOrigin(0.5);
  winText.setVisible(false);

  // 添加提示文本
  this.add.text(16, 50, '使用方向键移动', {
    fontSize: '18px',
    fill: '#aaaaaa',
    fontFamily: 'Arial'
  });
}

function update() {
  // 玩家移动控制
  const speed = 300;

  if (cursors.left.isDown) {
    player.setVelocityX(-speed);
  } else if (cursors.right.isDown) {
    player.setVelocityX(speed);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-speed);
  } else if (cursors.down.isDown) {
    player.setVelocityY(speed);
  }
}

function collectTriangle(player, triangle) {
  // 销毁三角形
  triangle.destroy();

  // 增加分数
  score++;

  // 更新分数文本
  scoreText.setText('收集: ' + score + ' / ' + TOTAL_TRIANGLES);

  // 检查是否通关
  if (score >= TOTAL_TRIANGLES) {
    winText.setVisible(true);
    // 停止玩家移动
    player.setVelocity(0, 0);
    cursors = null;
  }
}

// 创建游戏实例
const game = new Phaser.Game(config);
```

