REQ: 绘制8个随机位置的红色菱形，每个大小为16像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Graphics.setRandomPosition
STEPS:
1. 创建 Phaser.Game 配置，设置场景宽高为 800x600
2. 在 create 方法中循环8次，每次创建一个 Graphics 对象
3. 使用 Graphics API 绘制菱形路径（moveTo 到顶点，lineTo 连接四个顶点）
4. 使用 fillStyle 设置红色，fillPath 填充菱形
5. 使用 setRandomPosition 将每个菱形放置在随机位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建8个红色菱形
  for (let i = 0; i < 8; i++) {
    const graphics = this.add.graphics();

    // 设置红色填充
    graphics.fillStyle(0xff0000, 1);

    // 绘制菱形（大小16像素，即从中心点到边缘8像素）
    // 菱形的四个顶点：上、右、下、左
    graphics.beginPath();
    graphics.moveTo(0, -8);  // 上顶点
    graphics.lineTo(8, 0);   // 右顶点
    graphics.lineTo(0, 8);   // 下顶点
    graphics.lineTo(-8, 0);  // 左顶点
    graphics.closePath();
    graphics.fillPath();

    // 设置随机位置（考虑菱形大小，避免超出边界）
    const randomX = Phaser.Math.Between(8, 792);
    const randomY = Phaser.Math.Between(8, 592);
    graphics.setPosition(randomX, randomY);
  }
}

