```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

let diamond;
let initialX = 400;
let initialY = 300;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 创建紫色菱形纹理
  const graphics = this.add.graphics();

  // 绘制紫色菱形
  graphics.fillStyle(0x9b59b6, 1); // 紫色
  graphics.beginPath();
  graphics.moveTo(50, 0);    // 上顶点
  graphics.lineTo(100, 50);  // 右顶点
  graphics.lineTo(50, 100);  // 下顶点
  graphics.lineTo(0, 50);    // 左顶点
  graphics.closePath();
  graphics.fillPath();

  // 生成紫色菱形纹理
  graphics.generateTexture('diamondPurple', 100, 100);
  graphics.clear();

  // 绘制橙色菱形纹理（拖拽时使用）
  graphics.fillStyle(0xe67e22, 1); // 橙色
  graphics.beginPath();
  graphics.moveTo(50, 0);
  graphics.lineTo(100, 50);
  graphics.lineTo(50, 100);
  graphics.lineTo(0, 50);
  graphics.closePath();
  graphics.fillPath();

  // 生成橙色菱形纹理
