REQ: 实现按方向键发射灰色子弹，子弹速度80，离开边界自动回收对象池
API: Phaser.Physics.Arcade.Group, this.input.keyboard.addKey, Graphics.generateTexture, Group.get, Group.killAndHide
STEPS:
1. 创建物理系统配置，启用 arcade 物理引擎
2. 使用 Graphics 生成灰色子弹纹理和玩家纹理
3. 创建玩家精灵并设置物理属性
4. 创建子弹对象池（Physics.Arcade.Group）
5. 监听方向键输入，根据方向发射子弹
6. 在 update 中检测子弹越界并回收到对象池
7. 添加 bulletsFired 状态变量用于验证
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let bullets;
let cursors;
let lastFiredTime = 0;
const fireRate = 200; // 发射间隔（毫秒）
let bulletsFired = 0; // 状态信号：已发射子弹数

function preload() {
  // 创建玩家纹理
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x00ff00, 1);
  playerGraphics.fillRect(0, 0, 32, 32);
  playerGraphics.generateTexture('player', 32, 32);
  playerGraphics.destroy();

  // 创建灰色子弹纹理
  const bulletGraphics = this.add.graphics();
  bulletGraphics.fillStyle(0x808080, 1);
  bulletGraphics.fillCircle(8, 8, 8);
  bulletGraphics.generateTexture('bullet', 16, 16);
  bulletGraphics.destroy();
}

function create() {
  // 创建玩家
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(true);

  // 创建子弹对象池
  bullets = this.physics.add.group({
    defaultKey: 'bullet',
    maxSize: 50,
    runChildUpdate: false
  });

  // 设置键盘输入
  cursors = this.input.keyboard.createCursorKeys();

  // 添加说明文字
  this.add.text(10, 10, 'Use Arrow Keys to Shoot', {
    fontSize: '16px',
    fill: '#ffffff'
  });

  // 显示发射计数
  this.bulletCountText = this.add.text(10, 30, 'Bullets Fired: 0', {
    fontSize: '16px',
    fill: '#ffffff'
  });

  // 显示活跃子弹数
  this.activeBulletsText = this.add.text(10, 50, 'Active Bullets: 0', {
    fontSize: '16px',
    fill: '#ffffff'
  });
}

function update(time, delta) {
  // 检测方向键并发射子弹
  if (time > lastFiredTime + fireRate) {
    let velocityX = 0;
    let velocityY = 0;

    if (cursors.up.isDown) {
      velocityY = -80;
      fireBullet(velocityX, velocityY);
      lastFiredTime = time;
    } else if (cursors.down.isDown) {
      velocityY = 80;
      fireBullet(velocityX, velocityY);
      lastFiredTime = time;
    } else if (cursors.left.isDown) {
      velocityX = -80;
      fireBullet(velocityX, velocityY);
      lastFiredTime = time;
    } else if (cursors.right.isDown) {
      velocityX = 80;
      fireBullet(velocityX, velocityY);
      lastFiredTime = time;
    }
  }

  // 检查子弹是否越界，越界则回收
  bullets.children.entries.forEach(bullet => {
    if (bullet.active) {
      if (bullet.x < -20 || bullet.x > 820 || 
          bullet.y < -20 || bullet.y > 620) {
        bullets.killAndHide(bullet);
        bullet.body.reset(0, 0);
      }
    }
  });

  // 更新UI
  const activeBullets = bullets.countActive(true);
  this.bulletCountText.setText('Bullets Fired: ' + bulletsFired);
  this.activeBulletsText.setText('Active Bullets: ' + activeBullets);
}

function fireBullet(velocityX, velocityY) {
  // 从对象池获取子弹
  const bullet = bullets.get(player.x, player.y);

  if (bullet) {
    bullet.setActive(true);
    bullet.setVisible(true);
    bullet.body.enable = true;
    bullet.setVelocity(velocityX, velocityY);

    bulletsFired++;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 创建8秒倒计时器，屏幕中央显示剩余时间，归零显示"时间到"
API: Phaser.Time.Clock#addEvent, Phaser.GameObjects.Text, Phaser.Time.TimerEvent
STEPS:
1. 创建 Scene 并在 create 中添加文本对象显示倒计时
2. 使用 this.time.addEvent 创建定时器，设置 delay=1000ms，repeat=7 次
3. 在定时器回调中更新文本内容，递减剩余秒数
4. 倒计时结束时（repeat 完成后）显示"时间到"
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

let timeText;
let remainingTime = 8;

function preload() {
  // 无需加载外部资源
}

function create() {
  // 创建倒计时文本，居中显示
  timeText = this.add.text(
    this.cameras.main.centerX,
    this.cameras.main.centerY,
    remainingTime.toString(),
    {
      fontSize: '128px',
      color: '#ffffff',
      fontStyle: 'bold'
    }
  );

  // 设置文本原点为中心，实现居中对齐
  timeText.setOrigin(0.5, 0.5);

  // 创建定时器事件
  // delay: 1000ms（每秒触发一次）
  // repeat: 7（总共触发8次：初始1次 + repeat 7次）
  // callback: 每次触发时更新倒计时
  this.time.addEvent({
    delay: 1000,
    callback: updateTimer,
    callbackScope: this,
    repeat: 7
  });
}

function updateTimer() {
  // 递减剩余时间
  remainingTime--;

  if (remainingTime > 0) {
    // 更新显示的数字
    timeText.setText(remainingTime.toString());
  } else {
    // 倒计时结束，显示"时间到"
    timeText.setText('时间到');
