    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件
  hexagon.on(Phaser.Input.Events.DRAG_END, function(pointer) {
    // 恢复白色
    this.setTexture('hexWhite');

    // 添加缓动动画回到初始位置
    this.scene.tweens.add({
      targets: this,
      x: this.initialX,
      y: this.initialY,
      duration: 300,
      ease: 'Back.easeOut'
    });
  });

  // 添加提示文本
  this.add.text(400, 50, '拖拽六边形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

