4. 设置 Tween 循环播放（loop: -1）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 创建 Graphics 对象绘制六边形
  const graphics = this.add.graphics();

  // 设置六边形参数
  const hexRadius = 80; // 六边形半径
  const centerX = 100;
  const centerY = 100;

  // 绘制六边形
  graphics.fillStyle(0x00ff88, 1);
  graphics.lineStyle(4, 0xffffff, 1);

  graphics.beginPath();

  // 计算六边形的6个顶点
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 每个顶点间隔60度
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 200, 200);
  graphics.destroy(); // 销毁 graphics 对象，只保留纹理

  // 创建六边形精灵
  const hexagon = this.add.sprite(400, 300, 'hexagon');

  // 创建缩放动画
  this.tweens.add({
    targets: hexagon,
    scaleX: 0.32, // 缩放到32%
    scaleY: 0.32,
    duration: 3000, // 3秒
    yoyo: true, // 自动反向播放（恢复到原始大小）
    loop: -1, // 无限循环
    ease: 'Sine.easeInOut' // 使用平滑的缓动函数
  });

  // 添加提示文本
  const text = this.add.text(400, 550, '六边形循环缩放动画 (3秒缩放到32%，然后恢复)', {
    fontSize: '20px',
    color: '#ffffff',
    align: 'center'
  });
  text.setOrigin(0.5);
}

new Phaser.Game(config);
