REQ: 实现灰色星形在2秒内左右往返循环移动的补间动画
API: Graphics.fillStyle, Graphics.fillStar, Tweens.add, BaseTween.yoyo, BaseTween.repeat
STEPS:
1. 使用 Graphics 绘制灰色星形并生成纹理
2. 创建 Sprite 对象并设置初始位置在左侧
3. 使用 tweens.add 创建补间动画，设置 x 坐标从左到右
4. 配置 yoyo 为 true 实现往返效果，repeat 为 -1 实现无限循环
5. 设置 duration 为 2000 毫秒完成单程移动
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 使用 Graphics 绘制星形纹理
  const graphics = this.add.graphics();

  // 设置灰色填充
  graphics.fillStyle(0x808080, 1);

  // 绘制星形 (x, y, points, innerRadius, outerRadius)
  graphics.fillStar(50, 50, 5, 20, 40);

  // 生成纹理
  graphics.generateTexture('star', 100, 100);

  // 销毁 graphics 对象
  graphics.destroy();
}

function create() {
  // 创建星形精灵，初始位置在左侧
  const star = this.add.sprite(100, 300, 'star');

  // 创建补间动画
  this.tweens.add({
    targets: star,           // 动画目标对象
    x: 700,                  // 目标 x 坐标（右侧）
    duration: 2000,          // 持续时间 2 秒
    yoyo: true,              // 启用往返效果（到达终点后反向播放）
    repeat: -1,              // 无限循环（-1 表示永久重复）
    ease: 'Linear'           // 线性缓动，匀速移动
  });

