    if (!particles.emitting) {
      particles.start();
    }
  });

  // 监听指针离开画布事件，停止发射
  this.input.on('pointerout', () => {
    particles.stop();
  });

  // 添加提示文本
  const text = this.add.text(400, 30, '移动鼠标查看粒子拖尾效果', {
