```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制一个矩形
  const graphics = this.add.graphics();

  // 设置填充样式为红色
  graphics.fillStyle(0xff0000, 1);

  // 在屏幕中心绘制一个 200x150 的矩形
  const rectX = 300;
  const rectY = 225;
  const rectWidth = 200;
  const rectHeight = 150;
