REQ: 黄色矩形以240速度移动并在画布边界反弹
API: Graphics, GameObject.setVelocity, Physics.Arcade, World.setBoundsCollision
STEPS:
1. 创建带有 Arcade 物理系统的游戏配置
2. 使用 Graphics 绘制黄色矩形并生成纹理
3. 创建物理精灵并设置初始速度为240
4. 启用世界边界碰撞和精灵边界反弹
5. 在 update 中保持速度恒定
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: { preload, create, update }
};

let rectangle;
const SPEED = 240;

function preload() {
  // 使用 Graphics 创建黄色矩形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffff00, 1); // 黄色
  graphics.fillRect(0, 0, 50, 30);
  graphics.generateTexture('yellowRect', 50, 30);
  graphics.destroy();
}

function create() {
  // 创建物理精灵
  rectangle = this.physics.add.sprite(400, 300, 'yellowRect');

  // 设置初始速度（随机方向）
  const angle = Phaser.Math.Between(0, 360);
  const velocityX = Math.cos(angle * Math.PI / 180) * SPEED;
  const velocityY = Math.sin(angle * Math.PI / 180) * SPEED;
  rectangle.setVelocity(velocityX, velocityY);

  // 启用与世界边界的碰撞
  rectangle.setCollideWorldBounds(true);

  // 启用边界反弹
  rectangle.setBounce(1, 1);

  // 设置世界边界
  this.physics.world.setBoundsCollision(true, true, true, true);
}

function update(time, delta) {
  // 保持恒定速度（防止速度衰减）
  const velocity = rectangle.body.velocity;
  const currentSpeed = Math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y);

  if (currentSpeed > 0) {
    const scale = SPEED / currentSpeed;
    rectangle.setVelocity(velocity.x * scale, velocity.y * scale);
  }
}

new Phaser.Game(config);
```

