function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制三角形
  const graphics = this.add.graphics();

  // 设置填充颜色（蓝色）
  graphics.fillStyle(0x00aaff, 1);

  // 绘制三角形（等边三角形）
  // 中心点在 (50, 50)，大小为 80x80
  graphics.beginPath();
  graphics.moveTo(50, 10);      // 顶点
  graphics.lineTo(10, 90);       // 左下角
