let ellipseGraphics;
let currentRotation = 0;

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 创建 Graphics 对象并绘制椭圆
  ellipseGraphics = this.add.graphics();

  // 设置椭圆的填充颜色
  ellipseGraphics.fillStyle(0x00ff00, 1);

  // 绘制椭圆（中心在原点，宽度 200，高度 100）
  ellipseGraphics.fillEllipse(0, 0, 200, 100);

  // 设置椭圆位置到屏幕中心
