[PLAN]
REQ: 实现橙色星形在4秒内左右往返循环移动的补间动画
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制橙色星形并生成纹理
2. 创建 Sprite 对象使用星形纹理
3. 使用 tweens.add 创建补间动画，设置 x 坐标从左到右移动
4. 配置 yoyo 为 true 实现往返效果，repeat 为 -1 实现无限循环
5. 设置 duration 为 4000 毫秒（4秒）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制橙色星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xff8800, 1); // 橙色

  // 绘制五角星
  const starPoints = [];
  const outerRadius = 30;
  const innerRadius = 15;
  const points = 5;

  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (i * Math.PI) / points - Math.PI / 2;
    starPoints.push(radius * Math.cos(angle));
    starPoints.push(radius * Math.sin(angle));
  }

  graphics.fillPoints(starPoints, true);

  // 生成纹理
  graphics.generateTexture('star', outerRadius * 2, outerRadius * 2);
  graphics.destroy(); // 销毁 graphics 对象，只保留纹理

  // 创建星形精灵，初始位置在左侧
  const star = this.add.sprite(100, 300, 'star');

  // 创建补间动画：从左到右移动，4秒完成，往返循环
  this.tweens.add({
    targets: star,
    x: 700, // 移动到右侧
    duration: 4000, // 4秒
    yoyo: true, // 往返效果
    repeat: -1, // 无限循环
    ease: 'Linear' // 线性移动
  });

  // 添加提示文本
  this.add.text(400, 50, '橙色星形往返移动动画', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现5关递增难度的敌人消灭游戏，每关敌人数+2，显示关卡和敌人数信息
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Scene, Phaser.Input.Keyboard
STEPS:
1. 创建玩家精灵和敌人组，使用Graphics生成纯色纹理
2. 实现关卡系统，初始12个敌人，每关+2，共5关
3. 添加碰撞检测，玩家接触敌人则消灭敌人
4. 显示当前关卡数和剩余敌人数的UI文本
5. 当前关敌人全部消灭后自动进入下一关，5关通关后显示胜利信息
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.currentLevel = 1;
    this.maxLevel = 5;
    this.baseEnemyCount = 12;
    this.enemyIncrement = 2;
    this.remainingEnemies = 0;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillCircle(16, 16, 16);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0x808080, 1); // 灰色
    enemyGraphics.fillRect(0, 0, 30, 30);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 设置键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建UI文本
    this.levelText = this.add.text(16, 16, '', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial'
    });

    this.enemyCountText = this.add.text(16, 50, '', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial'
    });

    this.messageText = this.add.text(400, 300, '', {
      fontSize: '32px',
      fill: '#ffff00',
      fontFamily: 'Arial'
    });
    this.messageText.setOrigin(0.5);
    this.messageText.setVisible(false);

    // 添加碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.collectEnemy,
      null,
      this
    );

    // 开始第一关
    this.startLevel(this.currentLevel);
  }

  startLevel(level) {
    // 清除现有敌人
    this.enemies.clear(true, true);

    // 计算当前关卡敌人数量
    const enemyCount = this.baseEnemyCount + (level - 1) * this.enemyIncrement;
    this.remainingEnemies = enemyCount;

    // 生成敌人
    const seed = level * 1000; // 固定种子保证确定性
    let rng = this.createSeededRandom(seed);

    for (let i = 0; i < enemyCount; i++) {
      const x = 50 + rng() * 700;
      const y = 50 + rng() * 350;
      const enemy = this.enemies.create(x, y, 'enemy');
      enemy.setVelocity(
        (rng() - 0.5) * 100,
        (rng() - 0.5) * 100
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }

    // 更新UI
    this.updateUI();
  }

  createSeededRandom(seed) {
    // 简单的伪随机数生成器
    let state = seed;
    return function() {
      state = (state * 9301 + 49297) % 233280;
      return state / 233280;
    };
  }

  collectEnemy(player, enemy) {
    // 消灭敌人
    enemy.destroy();
    this.remainingEnemies--;

    // 更新UI
    this.updateUI();

    // 检查是否完成当前关卡
    if (this.remainingEnemies <= 0) {
      this.levelComplete();
    }
  }

  levelComplete() {
    if (this.currentLevel >= this.maxLevel) {
      // 游戏通关
      this.showMessage('恭喜通关！所有关卡完成！');
      this.physics.pause();
    } else {
      // 进入下一关
      this.currentLevel++;
      this.showMessage(`第 ${this.currentLevel} 关开始！`, () => {
        this.startLevel(this.currentLevel);
      });
    }
  }

  showMessage(text, callback) {
    this.messageText.setText(text);
    this.messageText.setVisible(true);
    this.physics.pause();

    this.time.delayedCall(2000, () => {
      this.messageText.setVisible(false);
      this.physics.resume();
      if (callback) {
        callback();
      }
    });
  }

  updateUI() {
    this.levelText.setText(`关卡: ${this.currentLevel}/${this.maxLevel}`);
    this.enemyCountText.setText(`剩余敌人: ${this.remainingEnemies}`);
  }

  update(time, delta) {
    // 玩家移动控制
    const speed = 300;

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    } else {
      this.player.setVelocityY(0);
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#000000',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

const game = new Phaser.Game(config);
```

[PLAN]
REQ: 使用 seed 生成 12x12 迷宫并显示 seed 以便复现
API: Phaser.Math.RND, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Scene
STEPS:
1. 配置 Game 使用固定 seed，在界面显示当前 seed
2. 使用深度优先搜索（DFS）算法生成 12x12 迷宫
3. 用 Graphics 绘制迷宫墙壁和通道
4. 标记起点（绿色）和终点（红色）
5. 添加状态变量记录迷宫生成信息（seed、尺寸、路径数等）
[/PLAN]

```javascript
class MazeScene extends Phaser.Scene {
  constructor() {
    super('MazeScene');
    this.mazeSize = 12;
    this.cellSize = 40;
    this.maze = [];
    this.seed = Date.now() % 1000000; // 使用时间戳生成 seed
    this.pathCount = 0; // 可验证状态：路径单元格数量
  }

  preload() {
    // 无需预加载资源
  }

  create() {
    // 设置随机种子
    this.game.config.seed = [this.seed.toString()];
    Phaser.Math.RND.sow([this.seed.toString()]);

    // 显示 seed 信息
    this.add.text(10, 10, `Seed: ${this.seed}`, {
      fontSize: '20px',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 显示迷宫信息
    this.infoText = this.add.text(10, 50, '', {
      fontSize: '16px',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 生成迷宫
    this.generateMaze();

    // 绘制迷宫
    this.drawMaze();

    // 更新信息显示
    this.infoText.setText(
      `Size: ${this.mazeSize}x${this.mazeSize}\n` +
      `Paths: ${this.pathCount}\n` +
      `Press R to regenerate`
    );

    // 添加重新生成按钮
    this.input.keyboard.on('keydown-R', () => {
      this.seed = Date.now() % 1000000;
      this.scene.restart();
    });
  }

  generateMaze() {
    // 初始化迷宫：所有墙壁都存在
    // 每个单元格存储四个方向的墙壁状态：{ top, right, bottom, left }
    this.maze = [];
    for (let y = 0; y < this.mazeSize; y++) {
      this.maze[y] = [];
      for (let x = 0; x < this.mazeSize; x++) {
        this.maze[y][x] = {
          visited: false,
          walls: { top: true, right: true, bottom: true, left: true }
        };
      }
    }

    // 使用深度优先搜索生成迷宫
    const stack = [];
    let currentX = 0;
    let currentY = 0;
    this.maze[currentY][currentX].visited = true;
    this.pathCount = 1;

    while (true) {
      // 获取未访问的邻居
      const neighbors = this.getUnvisitedNeighbors(currentX, currentY);

      if (neighbors.length > 0) {
        // 随机选择一个邻居
        const next = Phaser.Math.RND.pick(neighbors);

        // 压栈当前位置
        stack.push({ x: currentX, y: currentY });

        // 移除当前单元格和邻居之间的墙壁
        this.removeWall(currentX, currentY, next.x, next.y);

        // 移动到邻居
        currentX = next.x;
        currentY = next.y;
        this.maze[currentY][currentX].visited = true;
        this.pathCount++;
      } else if (stack.length > 0) {
        // 回溯
        const prev = stack.pop();
        currentX = prev.x;
        currentY = prev.y;
      } else {
        // 完成
        break;
      }
    }
  }

  getUnvisitedNeighbors(x, y) {
    const neighbors = [];
    const directions = [
      { dx: 0, dy: -1 }, // 上
      { dx: 1, dy: 0 },  // 右
      { dx: 0, dy: 1 },  // 下
      { dx: -1, dy: 0 }  // 左
    ];

    for (const dir of directions) {
      const nx = x + dir.dx;
      const ny = y + dir.dy;

      if (nx >= 0 && nx < this.mazeSize && 
          ny >= 0 && ny < this.mazeSize && 
          !this.maze[ny][nx].visited) {
        neighbors.push({ x: nx, y: ny });
      }
    }

    return neighbors;
  }

  removeWall(x1, y1, x2, y2) {
    const dx = x2 - x1;
    const dy = y2 - y1;

    if (dx === 1) {
      // 向右移动
      this.maze[y1][x1].walls.right = false;
      this.maze[y2][x2].walls.left = false;
    } else if (dx === -1) {
      // 向左移动
      this.maze[y1][x1].walls.left = false;
      this.maze[y2][x2].walls.right = false;
    } else if (dy === 1) {
      // 向下移动
      this.maze[y1][x1].walls.bottom = false;
      this.maze[y2][x2].walls.top = false;
    } else if (dy === -1) {
      // 向上移动
      this.maze[y1][x1].walls.top = false;
      this.maze[y2][x2].walls.bottom = false;
    }
  }

  drawMaze() {
    const graphics = this.add.graphics();
    const offsetX = 100;
    const offsetY = 120;

    // 绘制背景
    graphics.fillStyle(0x1a1a1a, 1);
    graphics.fillRect(
      offsetX,
      offsetY,
      this.mazeSize * this.cellSize,
      this.mazeSize * this.cellSize
    );

    // 绘制路径
    graphics.fillStyle(0x333333, 1);
    for (let y = 0; y < this.mazeSize; y++) {
      for (let x = 0; x < this.mazeSize; x++) {
        graphics.fillRect(
          offsetX + x * this.cellSize + 2,
          offsetY + y * this.cellSize + 2,
          this.cellSize - 4,
          this.cellSize - 4
        );
      }
    }

    // 绘制墙壁
    graphics.lineStyle(3, 0xffffff, 1);
    for (let y = 0; y < this.mazeSize; y++) {
      for (let x = 0; x < this.mazeSize; x++) {
        const cell = this.maze[y][x];
        const px = offsetX + x * this.cellSize;
        const py = offsetY + y * this.cellSize;

        if (cell.walls.top) {
          graphics.beginPath();
          graphics.moveTo(px, py);
          graphics.lineTo(px + this.cellSize, py);
          graphics.strokePath();
        }
        if (cell.walls.right) {
          graphics.beginPath();
          graphics.moveTo(px + this.cellSize, py);
          graphics.lineTo(px + this.cellSize, py + this.cellSize);
          graphics.strokePath();
        }
        if (cell.walls.bottom) {
          graphics.beginPath();
          graphics.moveTo(px, py + this.cellSize);
          graphics.lineTo(px + this.cellSize, py + this.cellSize);
          graphics.strokePath();
        }
        if (cell.walls.left) {
          graphics.beginPath();
          graphics.moveTo(px, py);
          graphics.lineTo(px, py + this.cellSize);
          graphics.strokePath();
        }
      }
    }

    // 标记起点（左上角，绿色）
    graphics.fillStyle(0x00ff00, 0.6);
    graphics.fillRect(
      offsetX + 5,
      offsetY + 5,
      this.cellSize - 10,
      this.cellSize - 10
    );

    // 标记终点（右下角，红色）
    graphics.fillStyle(0xff0000, 0.6);
    graphics.fillRect(
      offsetX + (this.mazeSize - 1) * this.cellSize + 5,
      offsetY + (this.mazeSize - 1) * this.cellSize + 5,
      this.cellSize - 10,
      this.cellSize - 10
    );

    // 添加标签
    this.add.text(offsetX, offsetY - 25, 'Start', {
      fontSize: '14px',
      color: '#00ff00'
    });
    this.add.text(
      offsetX + (this.mazeSize - 1) * this.cellSize,
      offsetY + this.mazeSize * this.cellSize + 5,
      'End',
      { fontSize: '14px', color: '#ff0000' }
    );
  }

  update(time, delta) {
    // 无需每帧更新
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 700,
  backgroundColor: '#000000',
  scene: MazeScene
};

new Phaser.Game(config);
```

