REQ: 实现粉色Boss战，8点血量，被速度80的子弹命中扣血，血量归零显示胜利
API: Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.Input.Keyboard, Phaser.GameObjects.Text
STEPS:
1. 创建物理系统配置，初始化场景
2. 使用Graphics绘制粉色Boss（矩形）和玩家飞船（三角形）
3. 实现键盘控制玩家移动和空格键发射子弹
4. 添加物理碰撞检测，子弹命中Boss扣血
5. 显示Boss血量条和血量文本
6. Boss血量归零时显示胜利文本并停止游戏
[/PLAN]

```javascript
class BossBattleScene extends Phaser.Scene {
  constructor() {
    super('BossBattleScene');
    this.bossHealth = 8;
    this.maxBossHealth = 8;
    this.bulletSpeed = 80;
    this.canShoot = true;
    this.shootCooldown = 500;
    this.gameWon = false;
  }

  preload() {
    // 创建纹理
    this.createTextures();
  }

  createTextures() {
    // 粉色Boss纹理
    const bossGraphics = this.add.graphics();
    bossGraphics.fillStyle(0xff69b4, 1); // 粉色
    bossGraphics.fillRect(0, 0, 80, 60);
    bossGraphics.generateTexture('boss', 80, 60);
    bossGraphics.destroy();

    // 玩家飞船纹理（三角形）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1); // 绿色
    playerGraphics.fillTriangle(16, 0, 0, 32, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 子弹纹理
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1); // 黄色
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();
  }

  create() {
    // 创建背景
    const bg = this.add.graphics();
    bg.fillStyle(0x000033, 1);
    bg.fillRect(0, 0, 800, 600);

    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建Boss
    this.boss = this.physics.add.sprite(400, 100, 'boss');
    this.boss.setCollideWorldBounds(true);
    this.boss.body.setVelocityX(100);

    // Boss左右移动逻辑
    this.physics.world.on('worldbounds', (body) => {
      if (body.gameObject === this.boss) {
        this.boss.body.setVelocityX(-this.boss.body.velocity.x);
      }
    });
    this.boss.body.setCollideWorldBounds(true);
    this.boss.body.onWorldBounds = true;

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 20
    });

    // 键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();
    this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

    // 碰撞检测
    this.physics.add.overlap(
      this.bullets,
      this.boss,
      this.hitBoss,
      null,
      this
    );

    // UI元素
    this.createUI();

    // 状态信号（用于验证）
    this.registry.set('bossHealth', this.bossHealth);
    this.registry.set('gameWon', false);
  }

  createUI() {
    // Boss血量文本
    this.healthText = this.add.text(16, 16, `Boss HP: ${this.bossHealth}/${this.maxBossHealth}`, {
      fontSize: '24px',
      fill: '#fff',
      fontFamily: 'Arial'
    });

    // Boss血量条背景
    this.healthBarBg = this.add.graphics();
    this.healthBarBg.fillStyle(0x666666, 1);
    this.healthBarBg.fillRect(300, 20, 200, 20);

    // Boss血量条
    this.healthBar = this.add.graphics();
    this.updateHealthBar();

    // 胜利文本（初始隐藏）
    this.winText = this.add.text(400, 300, 'VICTORY!', {
      fontSize: '64px',
      fill: '#ffff00',
      fontFamily: 'Arial',
      stroke: '#000',
      strokeThickness: 6
    });
    this.winText.setOrigin(0.5);
    this.winText.setVisible(false);

    // 操作提示
    this.add.text(16, 560, 'Arrow Keys: Move | Space: Shoot', {
      fontSize: '16px',
      fill: '#aaa',
      fontFamily: 'Arial'
    });
  }

  updateHealthBar() {
    this.healthBar.clear();
    const healthPercent = this.bossHealth / this.maxBossHealth;
    const barWidth = 200 * healthPercent;

    // 根据血量变色
    let color = 0x00ff00; // 绿色
    if (healthPercent < 0.3) {
      color = 0xff0000; // 红色
    } else if (healthPercent < 0.6) {
      color = 0xffaa00; // 橙色
    }

    this.healthBar.fillStyle(color, 1);
    this.healthBar.fillRect(300, 20, barWidth, 20);
  }

  hitBoss(bullet, boss) {
    if (this.gameWon) return;

    // 销毁子弹
    bullet.destroy();

    // Boss扣血
    this.bossHealth--;
    this.registry.set('bossHealth', this.bossHealth);

    // 更新UI
    this.healthText.setText(`Boss HP: ${this.bossHealth}/${this.maxBossHealth}`);
    this.updateHealthBar();

    // Boss闪烁效果
    this.tweens.add({
      targets: boss,
      alpha: 0.3,
      duration: 100,
      yoyo: true,
      repeat: 1
    });

    // 检查胜利条件
    if (this.bossHealth <= 0) {
      this.winGame();
    }
  }

  winGame() {
    this.gameWon = true;
    this.registry.set('gameWon', true);

    // 停止Boss移动
    this.boss.body.setVelocity(0, 0);

    // Boss消失动画
    this.tweens.add({
      targets: this.boss,
      alpha: 0,
      scale: 0,
      duration: 500,
      ease: 'Power2'
    });

    // 显示胜利文本
    this.winText.setVisible(true);
    this.tweens.add({
      targets: this.winText,
      scale: { from: 0, to: 1.2 },
      duration: 500,
      ease: 'Back.easeOut'
    });

    // 停止玩家输入
    this.input.keyboard.enabled = false;
  }

  shootBullet() {
    if (!this.canShoot || this.gameWon) return;

    const bullet = this.bullets.get(this.player.x, this.player.y - 20);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);
      bullet.body.setVelocityY(-this.bulletSpeed);

      // 冷却时间
      this.canShoot = false;
      this.time.delayedCall(this.shootCooldown, () => {
        this.canShoot = true;
      });
    }
  }

  update(time, delta) {
    if (this.gameWon) return;

    // 玩家移动
    const speed = 200;

    if (this.cursors.left.isDown) {
      this.player.body.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.body.setVelocityX(speed);
    } else {
      this.player.body.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.body.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.body.setVelocityY(speed);
    } else {
      this.player.body.setVelocityY(0);
    }

    // 发射子弹
    if (Phaser.Input.Keyboard.JustDown(this.spaceKey)) {
      this.shootBullet();
    }

    // 清理超出屏幕的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && bullet.y < -10) {
        bullet.destroy();
      }
    });
  }
}

