REQ: 实现一个青色星形在 2 秒内从左移动到右并往返循环的补间动画
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#generateTexture, Phaser.GameObjects.Image, Phaser.Tweens.TweenManager#add, Phaser.Tweens.BaseTween.yoyo, Phaser.Tweens.BaseTween.repeat
STEPS:
1. 使用 Graphics 绘制青色星形并生成纹理
2. 创建 Image 对象使用生成的星形纹理
3. 使用 Tween 系统创建从左到右的移动动画，设置 yoyo 为 true 实现往返，repeat 为 -1 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制青色星形
  const graphics = this.add.graphics();

  // 设置青色填充
  graphics.fillStyle(0x00ffff, 1);

  // 绘制星形（5个顶点）
  const centerX = 50;
  const centerY = 50;
  const outerRadius = 40;
  const innerRadius = 20;
  const points = 5;

  graphics.beginPath();

  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy();

  // 创建星形精灵，初始位置在左侧
  const star = this.add.image(100, 300, 'star');

  // 创建补间动画：从左移动到右，往返循环
  this.tweens.add({
    targets: star,
    x: 700,                // 目标 x 坐标（右侧）
    duration: 2000,        // 持续 2 秒
    yoyo: true,            // 往返（到达终点后返回起点）
    repeat: -1,            // 无限循环（-1 表示永久重复）
    ease: 'Linear'         // 线性缓动
  });
}

new Phaser.Game(config);
```

