REQ: 实现相机跟随自动向左下移动的六边形
API: Phaser.GameObjects.Graphics, Phaser.Cameras.Scene2D.Camera#startFollow, Phaser.GameObjects.Graphics#generateTexture
STEPS:
1. 使用 Graphics 绘制六边形并生成纹理
2. 创建 Sprite 对象并应用六边形纹理
3. 在 update 中让六边形持续向左下移动
4. 使用 Camera.startFollow 让相机跟随六边形
5. 设置世界边界以便观察跟随效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let hexagon;
const MOVE_SPEED = 100; // 每秒移动的像素数

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 设置世界边界，让场景足够大以便观察跟随效果
  this.cameras.main.setBounds(0, 0, 2000, 2000);
  this.physics.world.setBounds(0, 0, 2000, 2000);

  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(3, 0xffffff, 1);

  // 绘制六边形（中心点为原点）
  const hexRadius = 30;
  const hexPath = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i;
    const x = hexRadius * Math.cos(angle);
    const y = hexRadius * Math.sin(angle);
    hexPath.push(new Phaser.Math.Vector2(x, y));
  }

  graphics.beginPath();
  graphics.moveTo(hexPath[0].x, hexPath[0].y);
  for (let i = 1; i < hexPath.length; i++) {
    graphics.lineTo(hexPath[i].x, hexPath[i].y);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', hexRadius * 2 + 10, hexRadius * 2 + 10);
  graphics.destroy();

  // 创建六边形精灵，初始位置在场景中心偏右上
  hexagon = this.add.sprite(1000, 500, 'hexagon');

  // 添加一些参考网格线以便观察移动
  const gridGraphics = this.add.graphics();
  gridGraphics.lineStyle(1, 0x444444, 0.5);
  for (let x = 0; x <= 2000; x += 100) {
    gridGraphics.lineTo(x, 0);
    gridGraphics.lineTo(x, 2000);
    gridGraphics.moveTo(x + 100, 0);
  }
  for (let y = 0; y <= 2000; y += 100) {
    gridGraphics.moveTo(0, y);
    gridGraphics.lineTo(2000, y);
  }
  gridGraphics.strokePath();

  // 添加坐标文本提示
  const infoText = this.add.text(10, 10, '', {
    fontSize: '16px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });
  infoText.setScrollFactor(0); // 固定在相机视图上

  // 存储文本对象以便在 update 中更新
  this.infoText = infoText;

  // 相机跟随六边形
  this.cameras.main.startFollow(hexagon, true, 0.1, 0.1);

  // 可选：设置跟随偏移，让六边形不完全居中
  // this.cameras.main.setFollowOffset(0, 0);
}

function update(time, delta) {
  // 计算移动距离（基于帧时间）
  const moveDistance = (MOVE_SPEED * delta) / 1000;

  // 向左下移动（左：x减小，下：y增大）
  // 45度角移动
  const moveX = -moveDistance * Math.cos(Math.PI / 4);
  const moveY = moveDistance * Math.sin(Math.PI / 4);

  hexagon.x += moveX;
  hexagon.y += moveY;

  // 更新信息文本
  this.infoText.setText([
    `六边形位置: (${Math.round(hexagon.x)}, ${Math.round(hexagon.y)})`,
    `相机位置: (${Math.round(this.cameras.main.scrollX)}, ${Math.round(this.cameras.main.scrollY)})`,
    '相机正在跟随六边形移动'
  ]);

  // 可选：当六边形移出世界边界时重置位置
  if (hexagon.x < 0 || hexagon.y > 2000) {
    hexagon.x = 1000;
    hexagon.y = 500;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现5关递增难度游戏，每关增加2个敌人，显示关卡和敌人数信息
API: Phaser.Scene, Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Physics.Arcade.Group
STEPS:
1. 创建主游戏场景，初始化物理系统和关卡变量
2. 使用Graphics生成玩家和敌人的纹理（蓝色玩家，灰色敌人）
3. 创建敌人组，根据当前关卡数生成对应数量的敌人（5 + (level-1)*2）
4. 添加碰撞检测，玩家触碰敌人则消灭敌人
5. 当所有敌人被消灭时进入下一关，超过5关则显示胜利
6. 显示UI文本：当前关卡、剩余敌人数
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.currentLevel = 1;
    this.maxLevel = 5;
    this.enemiesPerLevel = 0;
    this.remainingEnemies = 0;
    this.player = null;
    this.enemies = null;
    this.levelText = null;
    this.enemyCountText = null;
    this.cursors = null;
  }

  preload() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0088ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（灰色圆形）
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0x808080, 1);
    enemyGraphics.fillCircle(16, 16, 16);
    enemyGraphics.generateTexture('enemy', 32, 32);
    enemyGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.body.setSize(28, 28);

    // 创建键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建UI文本
    this.levelText = this.add.text(16, 16, '', {
      fontSize: '24px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    this.enemyCountText = this.add.text(16, 50, '', {
      fontSize: '20px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 游戏完成标志
    this.gameComplete = false;

    // 开始第一关
    this.startLevel();
  }

  startLevel() {
    // 清除旧敌人
    if (this.enemies) {
      this.enemies.clear(true, true);
    }

    // 计算当前关卡敌人数量：第1关5个，每关增加2个
    this.enemiesPerLevel = 5 + (this.currentLevel - 1) * 2;
    this.remainingEnemies = this.enemiesPerLevel;

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 使用固定种子生成敌人位置（保证确定性）
    const seed = this.currentLevel * 1000;
    for (let i = 0; i < this.enemiesPerLevel; i++) {
      // 使用伪随机算法生成位置
      const x = ((seed + i * 137) % 700) + 50;
      const y = ((seed + i * 211) % 300) + 50;

      const enemy = this.enemies.create(x, y, 'enemy');
      enemy.setCollideWorldBounds(true);
      enemy.body.setSize(28, 28);

      // 给敌人随机速度
      const vx = ((seed + i * 173) % 100) - 50;
      const vy = ((seed + i * 197) % 100) - 50;
      enemy.setVelocity(vx, vy);
      enemy.setBounce(1);
    }

    // 添加碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.collectEnemy,
      null,
      this
    );

    // 更新UI
    this.updateUI();
  }

  collectEnemy(player, enemy) {
    // 消灭敌人
    enemy.destroy();
    this.remainingEnemies--;

    // 更新UI
    this.updateUI();

    // 检查是否完成当前关卡
    if (this.remainingEnemies === 0) {
      if (this.currentLevel < this.maxLevel) {
        // 进入下一关
        this.currentLevel++;
        this.time.delayedCall(500, () => {
          this.startLevel();
        });
      } else {
        // 游戏胜利
        this.gameComplete = true;
        this.showVictory();
      }
    }
  }

  updateUI() {
    this.levelText.setText(`Level: ${this.currentLevel}/${this.maxLevel}`);
    this.enemyCountText.setText(`Enemies: ${this.remainingEnemies}/${this.enemiesPerLevel}`);
  }

  showVictory() {
    // 停止所有敌人
    this.enemies.children.entries.forEach(enemy => {
      enemy.setVelocity(0, 0);
    });

    // 显示胜利文本
    const victoryText = this.add.text(400, 300, 'VICTORY!\nAll Levels Complete!', {
      fontSize: '48px',
      fill: '#00ff00',
      backgroundColor: '#000000',
      padding: { x: 20, y: 10 },
      align: 'center'
    });
    victoryText.setOrigin(0.5);

    // 停止玩家移动
    this.player.setVelocity(0, 0);
  }

  update() {
    if (this.gameComplete) {
      return;
    }

    // 玩家移动控制
    const speed = 200;

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    } else {
      this.player.setVelocityY(0);
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#222222',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

const game = new Phaser.Game(config);

// 导出状态用于验证
game.getState = function() {
  const scene = game.scene.scenes[0];
  return {
    currentLevel: scene.currentLevel,
    maxLevel: scene.maxLevel,
    remainingEnemies: scene.remainingEnemies,
    enemiesPerLevel: scene.enemiesPerLevel,
    gameComplete: scene.gameComplete
  };
};
```

