API: Graphics.fillRect, Input.Keyboard.createCursorKeys, GameObject.x, GameObject.y
STEPS:
1. 创建 Graphics 对象绘制黄色矩形并生成纹理
2. 创建 Sprite 对象使用该纹理
3. 在 create 中初始化键盘方向键输入
4. 在 update 中检测方向键状态并更新矩形位置
5. 限制矩形位置在画布边界内
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: {
    preload: preload,
    create: create,
    update: update
  },
  backgroundColor: '#2d2d2d'
};

let player;
let cursors;
const SPEED = 240;
const PLAYER_WIDTH = 50;
const PLAYER_HEIGHT = 50;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 创建黄色矩形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffff00, 1); // 黄色
  graphics.fillRect(0, 0, PLAYER_WIDTH, PLAYER_HEIGHT);
  graphics.generateTexture('playerRect', PLAYER_WIDTH, PLAYER_HEIGHT);
  graphics.destroy();

  // 创建玩家精灵，放置在画布中心
  player = this.add.sprite(400, 300, 'playerRect');
  player.setOrigin(0.5, 0.5);

  // 创建方向键输入
  cursors = this.input.keyboard.createCursorKeys();
}

function update(time, delta) {
  // 计算移动距离（像素/秒 * 秒 = 像素）
  const distance = SPEED * (delta / 1000);

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 检测方向键按下状态
  if (cursors.left.isDown) {
    velocityX = -distance;
  } else if (cursors.right.isDown) {
    velocityX = distance;
  }

  if (cursors.up.isDown) {
    velocityY = -distance;
  } else if (cursors.down.isDown) {
    velocityY = distance;
  }

  // 更新玩家位置
  player.x += velocityX;
  player.y += velocityY;

  // 限制在画布边界内
  const halfWidth = PLAYER_WIDTH / 2;
  const halfHeight = PLAYER_HEIGHT / 2;

  if (player.x < halfWidth) {
    player.x = halfWidth;
  } else if (player.x > config.width - halfWidth) {
    player.x = config.width - halfWidth;
  }

  if (player.y < halfHeight) {
    player.y = halfHeight;
  } else if (player.y > config.height - halfHeight) {
    player.y = config.height - halfHeight;
  }
}

new Phaser.Game(config);
