REQ: 实现射击敌人游戏，鼠标左键发射子弹击杀敌人并显示击杀数
API: Phaser.Physics.Arcade.Group, Phaser.Input.Pointer, Phaser.Physics.Arcade.Collider, Phaser.GameObjects.Text
STEPS:
1. 创建玩家角色（使用 Graphics 绘制矩形）
2. 创建子弹组和敌人组（使用物理引擎）
3. 监听鼠标左键点击事件，从玩家位置发射子弹
4. 创建多个敌人并设置随机移动
5. 设置子弹与敌人的碰撞检测，命中时销毁双方并增加击杀数
6. 显示击杀数文本并实时更新
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.killCount = 0;
  }

  preload() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillRect(0, 0, 40, 40);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();

    // 创建子弹纹理
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(5, 5, 5);
    bulletGraphics.generateTexture('bullet', 10, 10);
    bulletGraphics.destroy();

    // 创建敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillRect(0, 0, 30, 30);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 50
    });

    // 创建敌人组
    this.enemies = this.physics.add.group({
      defaultKey: 'enemy',
      maxSize: 20
    });

    // 生成初始敌人
    this.spawnEnemies(5);

    // 设置子弹与敌人的碰撞
    this.physics.add.collider(
      this.bullets,
      this.enemies,
      this.hitEnemy,
      null,
      this
    );

    // 监听鼠标左键点击
    this.input.on('pointerdown', (pointer) => {
      if (pointer.leftButtonDown()) {
        this.shootBullet(pointer);
      }
    });

    // 显示击杀数文本
    this.killText = this.add.text(16, 16, 'Kills: 0', {
      fontSize: '32px',
      fill: '#fff',
      fontFamily: 'Arial'
    });

    // 定时生成新敌人
    this.time.addEvent({
      delay: 2000,
      callback: this.spawnEnemies,
      args: [1],
      callbackScope: this,
      loop: true
    });
  }

  update(time, delta) {
    // 移动玩家跟随鼠标X轴
    const pointer = this.input.activePointer;
    if (pointer.x > 0 && pointer.x < 800) {
      this.player.x = Phaser.Math.Linear(this.player.x, pointer.x, 0.1);
    }

    // 移除超出屏幕的子弹
    this.bullets.children.entries.forEach((bullet) => {
      if (bullet.active && bullet.y < -10) {
        bullet.setActive(false);
        bullet.setVisible(false);
      }
    });

    // 敌人移动逻辑
    this.enemies.children.entries.forEach((enemy) => {
      if (enemy.active) {
        // 向下移动
        enemy.y += 1;

        // 左右摇摆
        enemy.x += Math.sin(time * 0.002 + enemy.getData('offset')) * 2;

        // 超出屏幕底部则移除
        if (enemy.y > 650) {
          enemy.setActive(false);
          enemy.setVisible(false);
        }
      }
    });
  }

  shootBullet(pointer) {
    // 从对象池获取子弹
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 计算子弹方向（从玩家指向鼠标位置）
      const angle = Phaser.Math.Angle.Between(
        this.player.x,
        this.player.y,
        pointer.x,
        pointer.y
      );

      // 设置子弹速度（速度为 80）
      const speed = 400;
      bullet.setVelocity(
        Math.cos(angle) * speed,
        Math.sin(angle) * speed
      );

      // 如果只想向上发射，使用以下代码替代上面的方向计算
      // bullet.setVelocityY(-400);
    }
  }

  spawnEnemies(count) {
    for (let i = 0; i < count; i++) {
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(-100, -50);

      const enemy = this.enemies.get(x, y);

      if (enemy) {
        enemy.setActive(true);
        enemy.setVisible(true);
        enemy.setVelocity(0, 0);
        // 存储随机偏移用于摇摆运动
        enemy.setData('offset', Math.random() * Math.PI * 2);
      }
    }
  }

  hitEnemy(bullet, enemy) {
    // 销毁子弹和敌人
    bullet.setActive(false);
    bullet.setVisible(false);
    bullet.setVelocity(0, 0);

    enemy.setActive(false);
    enemy.setVisible(false);

    // 增加击杀数
    this.killCount++;
    this.killText.setText('Kills: ' + this.killCount);

    // 创建击杀特效（可选）
    const explosion = this.add.graphics();
    explosion.fillStyle(0xffa500, 1);
    explosion.fillCircle(enemy.x, enemy.y, 20);

    this.tweens.add({
      targets: explosion,
      alpha: 0,
      scale: 2,
      duration: 300,
      onComplete: () => {
        explosion.destroy();
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#000000',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 使用对象池管理 20 个橙色可复用对象，对象离开屏幕后自动回收并重新使用
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Sprite
STEPS:
1. 使用 Graphics 生成橙色圆形纹理
2. 创建 Physics.Arcade.Group 作为对象池，设置 maxSize 为 20
3. 配置对象池的 createCallback 和 removeCallback 实现对象的初始化和回收
4. 在 create 中批量生成 20 个对象，设置随机位置和速度
5. 在 update 中检测对象是否离开屏幕，离开则 kill 回收到对象池
6. 定时从对象池中获取对象并重新激活，实现复用
7. 添加状态变量追踪活跃对象数和回收次数
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.activeCount = 0;  // 当前活跃对象数
    this.recycleCount = 0;  // 回收次数
    this.spawnCount = 0;    // 生成次数
  }

  preload() {
    // 创建橙色圆形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xFF8C00, 1);  // 橙色
    graphics.fillCircle(16, 16, 16);
    graphics.generateTexture('orangeCircle', 32, 32);
    graphics.destroy();
  }

  create() {
    // 创建物理对象池
    this.objectPool = this.physics.add.group({
      defaultKey: 'orangeCircle',
      maxSize: 20,
      createCallback: (obj) => {
        // 对象创建时的回调
        obj.setActive(false);
        obj.setVisible(false);
      }
    });

    // 初始化 20 个对象
    for (let i = 0; i < 20; i++) {
      this.spawnObject();
    }

    // 添加状态显示文本
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 定时器：每 2 秒尝试重新激活一个对象
    this.time.addEvent({
      delay: 2000,
      callback: this.respawnObject,
      callbackScope: this,
      loop: true
    });

    // 更新状态显示
    this.updateStatus();
  }

  spawnObject() {
    // 从对象池获取或创建对象
    const obj = this.objectPool.get();

    if (obj) {
      // 随机位置（屏幕内）
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 550);

      // 激活对象
      obj.setPosition(x, y);
      obj.setActive(true);
      obj.setVisible(true);

      // 设置随机速度
      const velocityX = Phaser.Math.Between(-200, 200);
      const velocityY = Phaser.Math.Between(-200, 200);
      obj.setVelocity(velocityX, velocityY);

      // 设置边界反弹
      obj.setBounce(1, 1);
      obj.setCollideWorldBounds(false);  // 不反弹，离开屏幕后回收

      this.spawnCount++;
      this.updateActiveCount();
    }
  }

  respawnObject() {
    // 尝试从对象池中获取一个未激活的对象并重新激活
    const inactiveObjects = this.objectPool.getChildren().filter(obj => !obj.active);

    if (inactiveObjects.length > 0) {
      const obj = inactiveObjects[0];

      // 随机新位置
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 550);

      obj.setPosition(x, y);
      obj.setActive(true);
      obj.setVisible(true);

      // 新的随机速度
      const velocityX = Phaser.Math.Between(-200, 200);
      const velocityY = Phaser.Math.Between(-200, 200);
      obj.setVelocity(velocityX, velocityY);

      this.spawnCount++;
      this.updateActiveCount();
    }
  }

  recycleObject(obj) {
    // 回收对象到对象池
    obj.setActive(false);
    obj.setVisible(false);
    obj.setVelocity(0, 0);

    this.recycleCount++;
    this.updateActiveCount();
  }

  updateActiveCount() {
    // 更新活跃对象计数
    this.activeCount = this.objectPool.getChildren().filter(obj => obj.active).length;
  }

  updateStatus() {
    // 更新状态文本
    const poolSize = this.objectPool.getLength();
    const text = [
      `Pool Size: ${poolSize}/20`,
      `Active Objects: ${this.activeCount}`,
      `Recycled: ${this.recycleCount}`,
      `Total Spawned: ${this.spawnCount}`
    ].join('\n');

    this.statusText.setText(text);
  }

  update(time, delta) {
    // 检查所有活跃对象是否离开屏幕
    this.objectPool.getChildren().forEach(obj => {
      if (obj.active) {
        // 检查是否完全离开屏幕（包含对象大小）
        const margin = 50;
        if (obj.x < -margin || obj.x > 800 + margin || 
            obj.y < -margin || obj.y > 600 + margin) {
          this.recycleObject(obj);
        }
      }
    });

    // 更新状态显示
    this.updateStatus();
  }
}

