REQ: 红色圆形平滑跟随鼠标指针移动，跟随速度为80
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 创建红色圆形并使用 Graphics 生成纹理
2. 在 create 中获取鼠标指针对象
3. 在 update 中计算圆形与鼠标位置的距离和角度
4. 根据速度和角度更新圆形位置，实现平滑跟随效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let circle;
let pointer;
const FOLLOW_SPEED = 80;

function preload() {
  // 使用 Graphics 生成红色圆形纹理
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });
  graphics.fillStyle(0xff0000, 1);
  graphics.fillCircle(25, 25, 25);
  graphics.generateTexture('redCircle', 50, 50);
  graphics.destroy();
}

function create() {
  // 创建红色圆形精灵，初始位置在屏幕中心
  circle = this.add.sprite(400, 300, 'redCircle');

  // 获取鼠标指针对象
  pointer = this.input.activePointer;

  // 添加提示文本
  this.add.text(10, 10, 'Move your mouse to see the red circle follow', {
    fontSize: '16px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 计算圆形与鼠标指针之间的距离
  const distance = Phaser.Math.Distance.Between(
    circle.x,
    circle.y,
    pointer.x,
    pointer.y
  );

  // 只有当距离大于一定阈值时才移动，避免抖动
  if (distance > 1) {
    // 计算从圆形指向鼠标的角度
    const angle = Phaser.Math.Angle.Between(
      circle.x,
      circle.y,
      pointer.x,
      pointer.y
    );

    // 根据速度和时间差计算本帧应移动的距离
    const moveDistance = FOLLOW_SPEED * (delta / 1000);

    // 如果移动距离小于实际距离，则按速度移动；否则直接到达目标点
    if (moveDistance < distance) {
      circle.x += Math.cos(angle) * moveDistance;
      circle.y += Math.sin(angle) * moveDistance;
    } else {
      circle.x = pointer.x;
      circle.y = pointer.y;
    }
  }
}

new Phaser.Game(config);
