REQ: 实现躲避游戏，敌人速度随时间加快，显示生存时间
API: Phaser.Physics.Arcade.Factory#group, Phaser.GameObjects.Text, Phaser.Time.TimerEvent, Phaser.Physics.Arcade.World#overlap
STEPS:
1. 创建玩家角色（使用 Graphics 绘制），支持键盘控制移动
2. 创建敌人组，定时生成从顶部下落的敌人
3. 实现敌人速度随时间递增机制（基础速度200，每秒增加一定速度）
4. 添加碰撞检测，碰到敌人游戏结束
5. 显示生存时间文本，实时更新
6. 游戏结束时显示最终生存时间
[/PLAN]

```javascript
class DodgeGameScene extends Phaser.Scene {
  constructor() {
    super('DodgeGameScene');
    this.survivalTime = 0; // 可验证状态：生存时间（秒）
    this.isGameOver = false; // 可验证状态：游戏是否结束
    this.baseEnemySpeed = 200; // 基础敌人速度
    this.currentEnemySpeed = 200; // 当前敌人速度
    this.speedIncreaseRate = 20; // 每秒速度增加量
  }

  preload() {
    // 使用 Graphics 创建纹理，无需外部资源
  }

  create() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillCircle(16, 16, 16);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillRect(0, 0, 30, 30);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 550, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人组
    this.enemies = this.physics.add.group({
      defaultKey: 'enemy',
      maxSize: 20
    });

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 显示生存时间文本
    this.timeText = this.add.text(16, 16, 'Time: 0.0s', {
      fontSize: '24px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 显示速度文本
    this.speedText = this.add.text(16, 50, 'Speed: 200', {
      fontSize: '20px',
      fill: '#ffff00',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 游戏结束文本（初始隐藏）
    this.gameOverText = this.add.text(400, 300, '', {
      fontSize: '48px',
      fill: '#ff0000',
      backgroundColor: '#000000',
      padding: { x: 20, y: 10 }
    });
    this.gameOverText.setOrigin(0.5);
    this.gameOverText.setVisible(false);

    // 定时生成敌人（每1秒生成一个）
    this.enemyTimer = this.time.addEvent({
      delay: 1000,
      callback: this.spawnEnemy,
      callbackScope: this,
      loop: true
    });

    // 碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.hitEnemy,
      null,
      this
    );

    // 重置游戏状态
    this.isGameOver = false;
    this.survivalTime = 0;
    this.currentEnemySpeed = this.baseEnemySpeed;
    this.startTime = this.time.now;
  }

  update(time, delta) {
    if (this.isGameOver) {
      return;
    }

    // 更新生存时间
    this.survivalTime = (time - this.startTime) / 1000;
    this.timeText.setText(`Time: ${this.survivalTime.toFixed(1)}s`);

    // 更新敌人速度（每秒增加速度）
    this.currentEnemySpeed = this.baseEnemySpeed + (this.survivalTime * this.speedIncreaseRate);
    this.speedText.setText(`Speed: ${Math.floor(this.currentEnemySpeed)}`);

    // 玩家移动控制
    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-300);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(300);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-300);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(300);
    } else {
      this.player.setVelocityY(0);
    }

    // 更新所有敌人的速度
    this.enemies.getChildren().forEach(enemy => {
      if (enemy.active) {
        enemy.setVelocityY(this.currentEnemySpeed);
      }
    });

    // 移除超出屏幕的敌人
    this.enemies.getChildren().forEach(enemy => {
      if (enemy.y > 620) {
        enemy.destroy();
      }
    });
  }

  spawnEnemy() {
    if (this.isGameOver) {
      return;
    }

    // 在顶部随机位置生成敌人
    const x = Phaser.Math.Between(30, 770);
    const enemy = this.enemies.create(x, -30, 'enemy');

    if (enemy) {
      enemy.setVelocityY(this.currentEnemySpeed);
    }
  }

  hitEnemy(player, enemy) {
    if (this.isGameOver) {
      return;
    }

    // 游戏结束
    this.isGameOver = true;

    // 停止所有物理运动
    this.physics.pause();

    // 停止生成敌人
    this.enemyTimer.remove();

    // 玩家变色表示死亡
    this.player.setTint(0xff0000);

    // 显示游戏结束信息
    this.gameOverText.setText(
      `GAME OVER\nSurvival Time: ${this.survivalTime.toFixed(1)}s\nFinal Speed: ${Math.floor(this.currentEnemySpeed)}`
    );
    this.gameOverText.setVisible(true);

    // 3秒后重启游戏
    this.time.delayedCall(3000, () => {
      this.scene.restart();
    });
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: DodgeGameScene
};

// 创建游戏实例
new Phaser.Game(config);
