  // 绘制 5 个随机位置的橙色方块
  for (let i = 0; i < 5; i++) {
    // 生成随机坐标，确保方块完全在画布内
    const x = Phaser.Math.Between(0, config.width - squareSize);
    const y = Phaser.Math.Between(0, config.height - squareSize);

    // 绘制方块
    graphics.fillRect(x, y, squareSize, squareSize);
  }
}

