REQ: 键盘方向键控制白色圆形移动，速度360，限制在画布边界内
API: this.add.graphics(), this.input.keyboard.createCursorKeys(), graphics.fillCircle(), Phaser.Math.Clamp()
STEPS:
1. 使用 Graphics 绘制白色圆形并生成纹理
2. 创建精灵对象并设置初始位置
3. 创建键盘方向键输入监听
4. 在 update 中根据方向键状态更新位置
5. 使用 Clamp 限制精灵位置在画布边界内
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create, update },
  backgroundColor: '#2d2d2d'
};

let player;
let cursors;
const SPEED = 360;
const RADIUS = 20;

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制白色圆形并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);
  graphics.fillCircle(RADIUS, RADIUS, RADIUS);
  graphics.generateTexture('playerCircle', RADIUS * 2, RADIUS * 2);
  graphics.destroy();

  // 创建玩家精灵，位置在画布中心
  player = this.add.sprite(400, 300, 'playerCircle');

  // 创建方向键输入
  cursors = this.input.keyboard.createCursorKeys();
}

function update(time, delta) {
  // 计算移动距离（速度 * 时间间隔，转换为秒）
  const distance = SPEED * (delta / 1000);

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 根据方向键状态设置速度
  if (cursors.left.isDown) {
    velocityX = -1;
  } else if (cursors.right.isDown) {
    velocityX = 1;
  }

  if (cursors.up.isDown) {
    velocityY = -1;
  } else if (cursors.down.isDown) {
    velocityY = 1;
  }

  // 归一化对角线移动速度
  if (velocityX !== 0 && velocityY !== 0) {
    const factor = Math.sqrt(2) / 2; // 约 0.707
    velocityX *= factor;
    velocityY *= factor;
  }

  // 更新玩家位置
  player.x += velocityX * distance;
  player.y += velocityY * distance;

  // 限制在画布边界内（考虑圆形半径）
  player.x = Phaser.Math.Clamp(player.x, RADIUS, config.width - RADIUS);
  player.y = Phaser.Math.Clamp(player.y, RADIUS, config.height - RADIUS);
}

new Phaser.Game(config);
```

