2. 创建星形精灵对象并设置初始位置
3. 在 create 中监听鼠标指针位置
4. 在 update 中计算星形到鼠标的距离和角度
5. 使用速度和 delta 时间实现平滑跟随效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let star;
let pointer;
const FOLLOW_SPEED = 360; // 像素/秒

function preload() {
  // 使用 Graphics 绘制星形并生成纹理
  const graphics = this.add.graphics();

  // 绘制粉色星形
  graphics.fillStyle(0xff69b4, 1); // 粉色
  graphics.lineStyle(2, 0xffffff, 1); // 白色边框

  // 绘制五角星
  const centerX = 32;
  const centerY = 32;
  const outerRadius = 30;
  const innerRadius = 12;
  const points = 5;

  graphics.beginPath();

  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('star', 64, 64);
  graphics.destroy();
}

function create() {
  // 创建星形精灵
  star = this.add.sprite(400, 300, 'star');
  star.setOrigin(0.5, 0.5);

  // 获取指针引用
  pointer = this.input.activePointer;

  // 添加提示文本
  this.add.text(10, 10, '移动鼠标，星形会平滑跟随', {
    fontSize: '18px',
    fill: '#ffffff'
  });
}

function update(time, delta) {
  // 计算星形到鼠标指针的距离
  const distance = Phaser.Math.Distance.Between(
    star.x,
    star.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素，则移动星形
  if (distance > 1) {
    // 计算移动角度
    const angle = Phaser.Math.Angle.Between(
      star.x,
      star.y,
      pointer.x,
      pointer.y
    );

    // 计算本帧应移动的距离（速度 * 时间）
    const moveDistance = Math.min(FOLLOW_SPEED * (delta / 1000), distance);

    // 更新星形位置
    star.x += Math.cos(angle) * moveDistance;
    star.y += Math.sin(angle) * moveDistance;
  }

  // 添加旋转效果让星形更生动
  star.rotation += 0.02;
}

new Phaser.Game(config);
```

