REQ: 白色椭圆平滑跟随鼠标指针移动，跟随速度为240
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 使用 Graphics 绘制白色椭圆并生成纹理
2. 创建 Sprite 对象使用该纹理
3. 在 update 中获取鼠标指针位置
4. 计算椭圆与鼠标的距离和角度
5. 根据速度240和delta时间平滑移动椭圆朝向鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let ellipse;
let pointer;
const FOLLOW_SPEED = 240; // 像素/秒

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制白色椭圆并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);
  graphics.fillEllipse(40, 30, 80, 60); // 中心点(40,30)，宽80，高60
  graphics.generateTexture('ellipseTex', 80, 60);
  graphics.destroy();

  // 创建椭圆精灵，初始位置在屏幕中心
  ellipse = this.add.sprite(400, 300, 'ellipseTex');

  // 获取指针引用
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // 计算椭圆与鼠标指针的距离
  const distance = Phaser.Math.Distance.Between(
    ellipse.x,
    ellipse.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素才移动（避免抖动）
  if (distance > 1) {
    // 计算移动角度
    const angle = Phaser.Math.Angle.Between(
      ellipse.x,
      ellipse.y,
      pointer.x,
      pointer.y
    );

    // 计算本帧应移动的距离（速度 * 时间）
    const moveDistance = FOLLOW_SPEED * (delta / 1000);

    // 如果移动距离大于剩余距离，直接到达目标点
    if (moveDistance >= distance) {
      ellipse.x = pointer.x;
      ellipse.y = pointer.y;
    } else {
      // 根据角度和移动距离计算新位置
      ellipse.x += Math.cos(angle) * moveDistance;
      ellipse.y += Math.sin(angle) * moveDistance;
    }
  }
}

