API: Phaser.Physics.Arcade.Group, Phaser.Input.Keyboard, Phaser.Physics.Arcade.Factory#velocityFromAngle, Phaser.GameObjects.Graphics
STEPS:
1. 创建物理系统配置，初始化场景
2. 使用 Graphics 绘制玩家和子弹纹理
3. 创建玩家精灵，添加键盘输入（方向键旋转，空格射击）
4. 创建子弹组（Physics Group），设置子弹生命周期
5. 在 update 中处理旋转输入，空格键触发射击，根据玩家角度发射子弹
6. 添加状态变量（子弹发射数量）用于验证
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.bulletsFired = 0; // 状态信号：已发射子弹数量
    this.lastFireTime = 0; // 射击冷却时间
    this.fireRate = 300; // 射击间隔（毫秒）
  }

  preload() {
    // 使用 Graphics 创建纹理，无需外部资源
  }

  create() {
    // 创建玩家纹理（三角形飞船）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.beginPath();
    playerGraphics.moveTo(20, 0);
    playerGraphics.lineTo(-10, -10);
    playerGraphics.lineTo(-10, 10);
    playerGraphics.closePath();
    playerGraphics.fillPath();
    playerGraphics.generateTexture('player', 30, 20);
    playerGraphics.destroy();

    // 创建子弹纹理（小圆形）
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.setDamping(true);
    this.player.setDrag(0.95);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 50,
      runChildUpdate: true
    });

    // 键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();
    this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 添加说明文字
    this.add.text(10, 550, '方向键：旋转  空格键：射击', {
      fontSize: '14px',
      fill: '#ffffff'
    });

    this.updateStatusText();
  }

  update(time, delta) {
    // 旋转控制
    const rotationSpeed = 3; // 旋转速度（度/帧）

    if (this.cursors.left.isDown) {
      this.player.angle -= rotationSpeed;
    }
    if (this.cursors.right.isDown) {
      this.player.angle += rotationSpeed;
    }

    // 射击控制（带冷却时间）
    if (this.spaceKey.isDown && time > this.lastFireTime + this.fireRate) {
      this.fireBullet();
      this.lastFireTime = time;
    }

    // 清理超出屏幕的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active) {
        if (bullet.x < -50 || bullet.x > 850 || bullet.y < -50 || bullet.y > 650) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      }
    });

    this.updateStatusText();
  }

  fireBullet() {
    // 获取或创建子弹
    let bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 设置子弹角度与玩家一致
      bullet.rotation = this.player.rotation;

      // 根据玩家角度计算子弹速度
      // Phaser 的角度是弧度制，0度朝右
      const bulletSpeed = 200;
      const angleInDegrees = this.player.angle;

      // 使用 velocityFromAngle 计算速度向量
      const velocity = this.physics.velocityFromAngle(angleInDegrees, bulletSpeed);
      bullet.setVelocity(velocity.x, velocity.y);

      // 增加发射计数
      this.bulletsFired++;
    }
  }

  updateStatusText() {
    const activeBullets = this.bullets.countActive(true);
    this.statusText.setText(
      `子弹发射数: ${this.bulletsFired}\n` +
      `当前子弹数: ${activeBullets}\n` +
      `玩家角度: ${Math.round(this.player.angle)}°`
    );
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央使用 Graphics 绘制一个白色星形，大小约为 48 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的 5 个外顶点和 5 个内顶点坐标（基于中心点和半径）
4. 使用 beginPath、moveTo、lineTo 依次连接顶点绘制星形路径
5. 使用白色填充星形并渲染到画布中央
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 获取画布中心坐标
  const centerX = this.cameras.main.width / 2;
  const centerY = this.cameras.main.height / 2;

  // 星形参数
  const outerRadius = 48; // 外半径
  const innerRadius = 20; // 内半径
  const points = 5; // 五角星

  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置填充样式为白色
  graphics.fillStyle(0xffffff, 1);

  // 开始绘制路径
  graphics.beginPath();

  // 计算星形的顶点坐标并绘制
  for (let i = 0; i < points * 2; i++) {
    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算角度（从顶部开始，顺时针）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 计算顶点坐标
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // 第一个点使用 moveTo，其余使用 lineTo
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充星形
  graphics.fillPath();
}

new Phaser.Game(config);
