  // 玩家移动控制
  if (!isInvulnerable) {
    player.setVelocity(0);

    if (this.cursors.left.isDown) {
      player.setVelocityX(-160);
    } else if (this.cursors.right.isDown) {
      player.setVelocityX(160);
    }

    if (this.cursors.up.isDown) {
      player.setVelocityY(-160);
    } else if (this.cursors.down.isDown) {
      player.setVelocityY(160);
    }
  }
}

function handleCollision(player, enemy) {
  // 如果已经处于无敌状态，不触发受伤
  if (isInvulnerable) {
    return;
  }

  // 减少生命值
  health -= 10;
  healthText.setText(`Health: ${health}`);

  // 设置无敌状态
  isInvulnerable = true;
  statusText.setText('Status: Hurt (Invulnerable)');
  statusText.setColor('#ff0000');

  // 计算击退方向（从敌人位置指向玩家）
  const angle = Phaser.Math.Angle.Between(
    enemy.x, enemy.y,
    player.x, player.y
  );

  // 击退距离基于速度80计算（速度80对应击退距离80像素）
  const knockbackDistance = 80;
  const knockbackX = Math.cos(angle) * knockbackDistance;
  const knockbackY = Math.sin(angle) * knockbackDistance;

  // 停止玩家当前移动
  player.setVelocity(0, 0);

  // 使用 Tween 实现击退效果
  player.scene.tweens.add({
    targets: player,
    x: player.x + knockbackX,
    y: player.y + knockbackY,
    duration: 200,
    ease: 'Power2',
    onComplete: () => {
      // 击退完成后恢复控制
    }
  });

  // 实现闪烁效果（2秒内闪烁）
  let blinkCount = 0;
  const maxBlinks = 10; // 2秒内闪烁10次
  const blinkInterval = 200; // 每次闪烁间隔200ms

  const blinkTimer = player.scene.time.addEvent({
    delay: blinkInterval,
    callback: () => {
      blinkCount++;
      // 切换透明度
      player.alpha = player.alpha === 1 ? 0.3 : 1;

      // 闪烁结束
      if (blinkCount >= maxBlinks) {
        player.alpha = 1;
        isInvulnerable = false;
        statusText.setText('Status: Normal');
        statusText.setColor('#00ff00');
        blinkTimer.remove();
      }
    },
    loop: true
  });

  // 检查游戏结束
  if (health <= 0) {
    statusText.setText('Status: Game Over');
    statusText.setColor('#ff0000');
    player.scene.physics.pause();
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 让一个三角形以每秒 240 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Graphics#fillTriangle, Graphics#rotation, Scene#update
STEPS:
1. 创建 Graphics 对象用于绘制三角形
2. 使用 fillTriangle 方法绘制一个三角形
3. 在 update 方法中根据 delta 时间累加旋转角度（240度/秒 = 4.189弧度/秒）
4. 将旋转角度应用到 Graphics 对象的 rotation 属性
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象用于绘制三角形
  this.triangle = this.add.graphics();

  // 设置三角形的位置到屏幕中心
  this.triangle.x = 400;
  this.triangle.y = 300;

  // 设置填充颜色为蓝色
  this.triangle.fillStyle(0x00aaff, 1);

  // 绘制一个等腰三角形（顶点相对于 Graphics 对象的原点）
  // 参数：x1, y1, x2, y2, x3, y3
  this.triangle.fillTriangle(
    0, -60,    // 顶部顶点
    -50, 60,   // 左下顶点
    50, 60     // 右下顶点
  );

  // 初始化旋转角度
  this.currentRotation = 0;
}

function update(time, delta) {
  // 每秒 240 度 = 240 * (Math.PI / 180) 弧度/秒 ≈ 4.189 弧度/秒
  const rotationSpeed = 240 * (Math.PI / 180); // 弧度/秒

  // 根据 delta（毫秒）计算本帧应该旋转的角度
  const rotationDelta = rotationSpeed * (delta / 1000);

  // 累加旋转角度
  this.currentRotation += rotationDelta;

  // 应用旋转到三角形
  this.triangle.rotation = this.currentRotation;
}

new Phaser.Game(config);
