// 状态信号变量
let collisionCount = 0;
let activeObjects = 0;

function preload() {
  // 使用 Graphics 创建蓝色圆形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x0066ff, 1);
  graphics.fillCircle(20, 20, 20);
  graphics.generateTexture('blueCircle', 40, 40);
  graphics.destroy();
