      `Active Objects: ${activeObjects}`,
      `Collisions: ${collisionCount}`,
      `Speed: 300 px/s`
    ]);
  });

  // 添加说明文本
  this.add.text(400, 580, 'Blue objects moving at 300 speed with bounce', {
    fontSize: '14px',
    fill: '#ffffff',
    align: 'center'
  }).setOrigin(0.5);
}

function update(time, delta) {
  // 游戏循环更新（物理系统自动处理移动和碰撞）
