API: Graphics.fillStar, Input.Keyboard.createCursorKeys, Physics.Arcade.Sprite, World.setBounds, Sprite.setCollideWorldBounds
STEPS:
1. 创建 Graphics 对象绘制蓝色星形并生成纹理
2. 使用 Arcade 物理系统创建星形精灵
3. 通过 createCursorKeys 获取方向键输入
4. 在 update 中根据方向键设置精灵速度
5. 设置精灵碰撞世界边界以限制移动范围
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let star;
let cursors;
const SPEED = 120;

function preload() {
  // 使用 Graphics 创建蓝色星形纹理
  const graphics = this.add.graphics();

  // 设置蓝色填充
  graphics.fillStyle(0x0066ff, 1);

  // 绘制星形 (中心点, 外半径, 内半径, 点数)
  graphics.fillStar(32, 32, 5, 30, 15);

  // 生成纹理
  graphics.generateTexture('star', 64, 64);

  // 销毁 graphics 对象
  graphics.destroy();
}

function create() {
  // 创建物理精灵，位置在画布中心
  star = this.physics.add.sprite(400, 300, 'star');

  // 设置精灵与世界边界碰撞
  star.setCollideWorldBounds(true);

  // 设置精灵的阻尼，使其停止时更自然
  star.setDamping(true);
  star.setDrag(0.99);

  // 创建方向键控制
  cursors = this.input.keyboard.createCursorKeys();
}

function update(time, delta) {
  // 重置速度
  star.setVelocity(0, 0);

  // 检测方向键输入并设置速度
  if (cursors.left.isDown) {
    star.setVelocityX(-SPEED);
  } else if (cursors.right.isDown) {
    star.setVelocityX(SPEED);
  }

  if (cursors.up.isDown) {
    star.setVelocityY(-SPEED);
  } else if (cursors.down.isDown) {
    star.setVelocityY(SPEED);
  }

  // 如果同时按下两个方向键，需要归一化速度向量
  // 避免对角线移动速度过快
  if ((cursors.left.isDown || cursors.right.isDown) && 
      (cursors.up.isDown || cursors.down.isDown)) {
    star.body.velocity.normalize().scale(SPEED);
  }
}

new Phaser.Game(config);
```

