const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象用于绘制
  const graphics = this.add.graphics();

  // 设置白色填充
  graphics.fillStyle(0xffffff, 1);

  // 计算画布中心点
  const centerX = 400;
  const centerY = 300;

  // 定义三角形大小（从中心到顶点的距离）
  const size = 18;

  // 计算等边三角形的三个顶点坐标
  // 顶点1：顶部中心
  const x1 = centerX;
  const y1 = centerY - size;

  // 顶点2：左下角
  const x2 = centerX - size * Math.cos(Math.PI / 6);
  const y2 = centerY + size * Math.sin(Math.PI / 6);

  // 顶点3：右下角
  const x3 = centerX + size * Math.cos(Math.PI / 6);
  const y3 = centerY + size * Math.sin(Math.PI / 6);

  // 绘制填充的三角形
  graphics.fillTriangle(x1, y1, x2, y2, x3, y3);

  // 可选：添加白色描边使三角形更清晰
  graphics.lineStyle(2, 0xffffff, 1);
  graphics.strokeTriangle(x1, y1, x2, y2, x3, y3);
}

