}

function create() {
  // 绘制8个随机位置的橙色菱形
  for (let i = 0; i < 8; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置橙色填充
    graphics.fillStyle(0xFFA500, 1);

    // 定义菱形的四个顶点（相对于中心点）
