[PLAN]
REQ: 让一个六边形以每秒 300 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#fillStyle, Phaser.GameObjects.Graphics#beginPath, Phaser.GameObjects.Graphics#lineTo, Phaser.GameObjects.Graphics#closePath, Phaser.GameObjects.Graphics#fillPath, Phaser.Scene#update
STEPS:
1. 创建 Graphics 对象并绘制六边形路径
2. 在 create 中初始化六边形，设置其位置在屏幕中心
3. 在 update 中根据 delta 时间增量计算旋转角度（300度/秒 = 300 * delta / 1000）
4. 使用 setRotation 方法更新六边形的旋转角度
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let hexagon;

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象用于绘制六边形
  hexagon = this.add.graphics();

  // 设置填充颜色
  hexagon.fillStyle(0x00ff00, 1);

  // 绘制六边形
  const radius = 80; // 六边形半径
  const sides = 6;

  hexagon.beginPath();

  for (let i = 0; i < sides; i++) {
    const angle = (Math.PI * 2 / sides) * i - Math.PI / 2; // 从顶部开始
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;

    if (i === 0) {
      hexagon.moveTo(x, y);
    } else {
      hexagon.lineTo(x, y);
    }
  }

  hexagon.closePath();
  hexagon.fillPath();

  // 设置六边形位置到屏幕中心
  hexagon.x = config.width / 2;
  hexagon.y = config.height / 2;

  // 初始化旋转角度
  hexagon.rotation = 0;
}

function update(time, delta) {
  // 每秒旋转 300 度
  // 将角度转换为弧度：300度 = 300 * (Math.PI / 180) 弧度
  const rotationSpeed = 300 * (Math.PI / 180); // 弧度/秒

  // 根据 delta 时间（毫秒）计算本帧应旋转的角度
  hexagon.rotation += rotationSpeed * (delta / 1000);

  // 可选：防止角度无限增长，保持在 0-2π 范围内
  if (hexagon.rotation > Math.PI * 2) {
    hexagon.rotation -= Math.PI * 2;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央绘制一个橙色星形，大小约为16像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布尺寸为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的5个外顶点和5个内顶点坐标（基于中心点和半径）
4. 使用 Graphics API 绘制星形路径并填充橙色
5. 将星形定位到画布中央
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置橙色填充
  graphics.fillStyle(0xFFA500, 1);

  // 画布中心坐标
  const centerX = 400;
  const centerY = 300;

  // 星形参数
  const outerRadius = 16; // 外半径
  const innerRadius = 8;  // 内半径（约为外半径的一半）
  const points = 5;       // 五角星

  // 开始绘制路径
  graphics.beginPath();

  // 绘制星形的顶点
  for (let i = 0; i < points * 2; i++) {
    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算角度（从顶部开始，逆时针）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 计算顶点坐标
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // 第一个点使用 moveTo，其他点使用 lineTo
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

new Phaser.Game(config);
