REQ: 实现角色受伤效果，碰撞时蓝色角色闪烁1秒并播放击退效果
API: Phaser.Physics.Arcade, Phaser.Tweens, Phaser.Time.TimerEvent, Phaser.Graphics
STEPS:
1. 创建蓝色玩家角色和红色敌人，使用Graphics绘制
2. 配置Arcade物理系统，设置碰撞检测
3. 实现碰撞处理函数：触发闪烁效果（alpha值切换）和击退效果（tween动画）
4. 使用TimerEvent控制闪烁持续1秒，使用Tween实现击退动画
5. 添加受伤状态标记防止重复触发，添加health变量作为状态信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.health = 100; // 状态信号：玩家生命值
    this.isHurt = false; // 受伤状态标记
    this.knockbackSpeed = 360; // 击退速度
  }

  preload() {
    // 使用Graphics创建纹理，无需外部资源
  }

  create() {
    // 创建蓝色玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0000ff, 1);
    playerGraphics.fillCircle(20, 20, 20);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();

    // 创建红色敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillCircle(20, 20, 20);
    enemyGraphics.generateTexture('enemy', 40, 40);
    enemyGraphics.destroy();

    // 创建玩家精灵
    this.player = this.physics.add.sprite(200, 300, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人精灵
    this.enemy = this.physics.add.sprite(600, 300, 'enemy');
    this.enemy.setVelocityX(-100); // 敌人向左移动
    this.enemy.setBounce(1, 1);
    this.enemy.setCollideWorldBounds(true);

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemy,
      this.handleCollision,
      null,
      this
    );

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 显示状态信息
    this.healthText = this.add.text(16, 16, `Health: ${this.health}`, {
      fontSize: '24px',
      fill: '#ffffff'
    });

    this.statusText = this.add.text(16, 50, 'Status: Normal', {
      fontSize: '20px',
      fill: '#00ff00'
    });

    // 添加说明文字
    this.add.text(16, 550, 'Use Arrow Keys to Move | Collide with Red Enemy to Trigger Hurt Effect', {
      fontSize: '16px',
      fill: '#ffff00'
    });
  }

  handleCollision(player, enemy) {
    // 如果已经在受伤状态，不重复触发
    if (this.isHurt) {
      return;
    }

    // 标记受伤状态
    this.isHurt = true;
    this.health -= 10; // 减少生命值
    this.healthText.setText(`Health: ${this.health}`);
    this.statusText.setText('Status: HURT!');
    this.statusText.setColor('#ff0000');

    // 计算击退方向（从敌人位置指向玩家）
    const angle = Phaser.Math.Angle.Between(
      enemy.x,
      enemy.y,
      player.x,
      player.y
    );

    // 计算击退距离（基于速度360，击退0.3秒的距离）
    const knockbackDistance = (this.knockbackSpeed * 0.3) / 60; // 转换为像素
    const knockbackX = Math.cos(angle) * knockbackDistance;
    const knockbackY = Math.sin(angle) * knockbackDistance;

    // 击退效果（使用Tween）
    this.tweens.add({
      targets: player,
      x: player.x + knockbackX,
      y: player.y + knockbackY,
      duration: 300,
      ease: 'Power2'
    });

    // 闪烁效果（1秒内切换alpha值）
    let blinkCount = 0;
    const blinkTimer = this.time.addEvent({
      delay: 100, // 每100ms切换一次
      callback: () => {
        player.alpha = player.alpha === 1 ? 0.3 : 1;
        blinkCount++;

        // 1秒后停止闪烁（10次切换）
        if (blinkCount >= 10) {
          blinkTimer.remove();
          player.alpha = 1; // 恢复完全可见
          this.isHurt = false; // 解除受伤状态
          this.statusText.setText('Status: Normal');
          this.statusText.setColor('#00ff00');
        }
      },
      loop: true
    });
  }

  update(time, delta) {
    // 玩家移动控制
    if (!this.isHurt) {
      if (this.cursors.left.isDown) {
        this.player.setVelocityX(-200);
      } else if (this.cursors.right.isDown) {
        this.player.setVelocityX(200);
      } else {
        this.player.setVelocityX(0);
      }

      if (this.cursors.up.isDown) {
        this.player.setVelocityY(-200);
      } else if (this.cursors.down.isDown) {
        this.player.setVelocityY(200);
      } else {
        this.player.setVelocityY(0);
      }
    } else {
      // 受伤时无法控制移动
      this.player.setVelocity(0, 0);
    }

    // 检查生命值
    if (this.health <= 0) {
      this.statusText.setText('Status: GAME OVER');
      this.statusText.setColor('#ff0000');
      this.physics.pause();
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现8关紫色物品收集游戏，每关收集完所有物品后进入下一关，显示关卡和分数
API: Phaser.Scene, Phaser.Physics.Arcade, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.GameObjects.Group
STEPS:
1. 创建主游戏场景，初始化物理系统和关卡系统
2. 使用 Graphics 生成玩家（蓝色方块）和紫色收集物纹理
3. 实现键盘控制玩家移动（方向键）
4. 每关随机生成指定数量的紫色收集物
5. 检测碰撞，收集物品增加分数并移除物品
6. 当前关所有物品收集完毕后，进入下一关（最多8关）
7. 显示当前关卡和总分数的UI文本
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.level = 1;
    this.score = 0;
    this.maxLevel = 8;
    this.itemsPerLevel = 5;
  }

  preload() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0000ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建紫色收集物纹理（圆形）
    const itemGraphics = this.add.graphics();
    itemGraphics.fillStyle(0x9b30ff, 1);
    itemGraphics.fillCircle(12, 12, 12);
    itemGraphics.generateTexture('purpleItem', 24, 24);
    itemGraphics.destroy();

    // 创建地面纹理（绿色）
    const groundGraphics = this.add.graphics();
    groundGraphics.fillStyle(0x00aa00, 1);
    groundGraphics.fillRect(0, 0, 800, 40);
    groundGraphics.generateTexture('ground', 800, 40);
    groundGraphics.destroy();
  }

  create() {
    // 添加背景色
    this.cameras.main.setBackgroundColor('#87ceeb');

    // 创建地面
    this.ground = this.physics.add.staticSprite(400, 580, 'ground');
    this.ground.setOrigin(0.5, 0.5);
    this.ground.refreshBody();

    // 创建玩家
    this.player = this.physics.add.sprite(100, 500, 'player');
    this.player.setBounce(0.2);
    this.player.setCollideWorldBounds(true);

    // 玩家与地面碰撞
    this.physics.add.collider(this.player, this.ground);

    // 创建收集物组
    this.items = this.physics.add.group();

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建UI文本
    this.levelText = this.add.text(16, 16, `Level: ${this.level}`, {
      fontSize: '24px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.levelText.setScrollFactor(0);

    this.scoreText = this.add.text(16, 50, `Score: ${this.score}`, {
      fontSize: '24px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.scoreText.setScrollFactor(0);

    // 游戏状态文本（用于显示通关或进度）
    this.statusText = this.add.text(400, 100, '', {
      fontSize: '32px',
      fill: '#ffff00',
      backgroundColor: '#000000',
      padding: { x: 15, y: 10 }
    });
    this.statusText.setOrigin(0.5);
    this.statusText.setScrollFactor(0);

    // 碰撞检测
    this.physics.add.overlap(this.player, this.items, this.collectItem, null, this);

    // 生成第一关
    this.generateLevel();
  }

  generateLevel() {
    // 清空现有物品
    this.items.clear(true, true);

    // 显示关卡开始提示
    this.statusText.setText(`Level ${this.level} Start!`);
    this.time.delayedCall(1500, () => {
      this.statusText.setText('');
    });

    // 根据关卡计算物品数量（每关增加）
    const itemCount = this.itemsPerLevel + (this.level - 1);

    // 使用固定种子生成位置（基于关卡数）
    const seed = this.level * 12345;
    const random = this.createSeededRandom(seed);

    // 生成紫色收集物
    for (let i = 0; i < itemCount; i++) {
      const x = random() * 700 + 50; // 50-750
      const y = random() * 400 + 50; // 50-450

      const item = this.items.create(x, y, 'purpleItem');
      item.setBounce(0.5);
      item.setCollideWorldBounds(true);
      item.setVelocity(
        (random() - 0.5) * 100,
        (random() - 0.5) * 100
      );
    }

    // 物品与地面碰撞
    this.physics.add.collider(this.items, this.ground);
    // 物品之间碰撞
    this.physics.add.collider(this.items, this.items);

    // 更新UI
    this.levelText.setText(`Level: ${this.level}`);
  }

  collectItem(player, item) {
    // 移除收集物
    item.destroy();

    // 增加分数（每关分数权重不同）
    this.score += this.level * 10;
    this.scoreText.setText(`Score: ${this.score}`);

    // 检查是否收集完所有物品
    if (this.items.countActive(true) === 0) {
      this.levelComplete();
    }
  }

  levelComplete() {
    // 关卡完成
    if (this.level < this.maxLevel) {
      this.level++;

      // 显示关卡完成提示
      this.statusText.setText('Level Complete!');

      // 延迟进入下一关
      this.time.delayedCall(2000, () => {
        this.generateLevel();
      });
    } else {
      // 游戏通关
      this.statusText.setText(`Game Complete! Final Score: ${this.score}`);
      this.statusText.setStyle({ fontSize: '28px' });

      // 停止玩家移动
      this.player.setVelocity(0, 0);
      this.gameComplete = true;
    }
  }

  update() {
    if (this.gameComplete) {
      return;
    }

    // 玩家移动控制
    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-200);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(200);
    } else {
      this.player.setVelocityX(0);
    }

    // 跳跃（只有在地面上才能跳）
    if (this.cursors.up.isDown && this.player.body.touching.down) {
      this.player.setVelocityY(-400);
    }
  }

  // 创建可预测的随机数生成器
  createSeededRandom(seed) {
    let value = seed;
    return function() {
      value = (value * 9301 + 49297) % 233280;
      return value / 233280;
    };
  }
}

