REQ: 在画布中央绘制一个绿色菱形，大小约为24像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布尺寸为 800x600
2. 在 create 生命周期中创建 Graphics 对象
3. 计算画布中心点坐标 (400, 300)
4. 使用 beginPath 开始路径绘制，通过 moveTo 和 lineTo 绘制菱形的四个顶点
5. 设置绿色填充样式，调用 fillPath 填充菱形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: {
    preload: preload,
    create: create
  },
  backgroundColor: '#2d2d2d'
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 获取画布中心点
  const centerX = this.cameras.main.width / 2;
  const centerY = this.cameras.main.height / 2;

  // 菱形大小（从中心到顶点的距离）
  const size = 24;

  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置绿色填充样式
  graphics.fillStyle(0x00ff00, 1);

  // 开始绘制路径
  graphics.beginPath();

  // 绘制菱形的四个顶点（上、右、下、左）
  graphics.moveTo(centerX, centerY - size);           // 上顶点
  graphics.lineTo(centerX + size, centerY);           // 右顶点
  graphics.lineTo(centerX, centerY + size);           // 下顶点
  graphics.lineTo(centerX - size, centerY);           // 左顶点

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

new Phaser.Game(config);
