```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.mapSize = 15;
    this.tileSize = 40;
    this.obstacleRate = 0.3;
    this.map = [];
    this.player = null;
    this.playerGridX = 0;
    this.playerGridY = 0;
    this.path = [];
    this.moveCount = 0; // 可验证状态
    this.isMoving = false;
    this.moveSpeed = 200; // 像素/秒
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 生成地图数据
    this.generateMap();

    // 绘制地图
    this.drawMap();

    // 创建玩家
    this.createPlayer();

    // 添加点击事件
    this.input.on('pointerdown', this.handleClick, this);

    // 显示状态文本
    this.statusText = this.add.text(10, this.mapSize * this.tileSize + 10, 
      'Move Count: 0 | Click to move player', 
      { fontSize: '16px', fill: '#fff' });
  }

  generateMap() {
    // 初始化地图为全空
    for (let y = 0; y < this.mapSize; y++) {
      this.map[y] = [];
      for (let x = 0; x < this.mapSize; x++) {
        this.map[y][x] = 0; // 0 = 可通行
      }
    }

    // 随机放置障碍物
    const totalTiles = this.mapSize * this.mapSize;
    const obstacleCount = Math.floor(totalTiles * this.obstacleRate);

    let placed = 0;
    while (placed < obstacleCount) {
      const x = Phaser.Math.Between(0, this.mapSize - 1);
      const y = Phaser.Math.Between(0, this.mapSize - 1);

      // 确保起始位置(0,0)不是障碍
      if ((x === 0 && y === 0) || this.map[y][x] === 1) {
        continue;
      }

      this.map[y][x] = 1; // 1 = 障碍
      placed++;
    }
  }

  drawMap() {
    const graphics = this.add.graphics();

    for (let y = 0; y < this.mapSize; y++) {
      for (let x = 0; x < this.mapSize; x++) {
        const px = x * this.tileSize;
        const py = y * this.tileSize;

        if (this.map[y][x] === 1) {
          // 障碍物 - 深灰色
          graphics.fillStyle(0x333333, 1);
        } else {
          // 地板 - 浅灰色
          graphics.fillStyle(0xcccccc, 1);
        }

        graphics.fillRect(px, py, this.tileSize, this.tileSize);

        // 绘制网格线
        graphics.lineStyle(1, 0x666666, 0.5);
        graphics.strokeRect(px, py, this.tileSize, this.tileSize);
      }
    }
  }

  createPlayer() {
    const graphics = this.add.graphics();
    graphics.fillStyle(0x00ff00, 1);
    graphics.fillCircle(this.tileSize / 2, this.tileSize / 2, this.tileSize / 3);
    graphics.generateTexture('player', this.tileSize, this.tileSize);
    graphics.destroy();

    this.player = this.add.sprite(
      this.tileSize / 2, 
      this.tileSize / 2, 
      'player'
    );
    this.playerGridX = 0;
    this.playerGridY = 0;
  }

  handleClick(pointer) {
    if (this.isMoving) return;

    // 转换为网格坐标
    const gridX = Math.floor(pointer.x / this.tileSize);
    const gridY = Math.floor(pointer.y / this.tileSize);

    // 检查是否在地图范围内且可通行
    if (gridX < 0 || gridX >= this.mapSize || 
        gridY < 0 || gridY >= this.mapSize ||
        this.map[gridY][gridX] === 1) {
      return;
    }

    // 寻路
    this.path = this.findPath(
      this.playerGridX, this.playerGridY,
      gridX, gridY
    );

    if (this.path.length > 0) {
      this.moveAlongPath();
    }
  }

  findPath(startX, startY, endX, endY) {
    // A* 寻路算法
    const openList = [];
    const closedList = new Set();
    const cameFrom = new Map();

    const start = { x: startX, y: startY, g: 0, h: 0, f: 0 };
    start.h = this.heuristic(startX, startY, endX, endY);
    start.f = start.h;
    openList.push(start);

    while (openList.length > 0) {
      // 找到f值最小的节点
      openList.sort((a, b) => a.f - b.f);
      const current = openList.shift();

      if (current.x === endX && current.y === endY) {
        return this.reconstructPath(cameFrom, current);
      }

      const key = `${current.x},${current.y}`;
      closedList.add(key);

      // 检查四个方向的邻居
      const neighbors = [
        { x: current.x + 1, y: current.y },
        { x: current.x - 1, y: current.y },
        { x: current.x, y: current.y + 1 },
        { x: current.x, y: current.y - 1 }
      ];

      for (const neighbor of neighbors) {
        const nx = neighbor.x;
        const ny = neighbor.y;
        const nKey = `${nx},${ny}`;

        // 检查是否越界或是障碍或已访问
        if (nx < 0 || nx >= this.mapSize || 
            ny < 0 || ny >= this.mapSize ||
            this.map[ny][nx] === 1 ||
            closedList.has(nKey)) {
          continue;
        }

        const g = current.g + 1;
        const h = this.heuristic(nx, ny, endX, endY);
        const f = g + h;

        const existingNode = openList.find(n => n.x === nx && n.y === ny);

        if (!existingNode) {
          openList.push({ x: nx, y: ny, g, h, f });
          cameFrom.set(nKey, { x: current.x, y: current.y });
        } else if (g < existingNode.g) {
          existingNode.g = g;
          existingNode.f = f;
          cameFrom.set(nKey, { x: current.x, y: current.y });
        }
      }
    }

    return []; // 没有找到路径
  }

  heuristic(x1, y1, x2, y2) {
    // 曼哈顿距离
    return Math.abs(x1 - x2) + Math.abs(y1 - y2);
  }

  reconstructPath(cameFrom, current) {
    const path = [];
    let node = current;

    while (true) {
      path.unshift({ x: node.x, y: node.y });
      const key = `${node.x},${node.y}`;
      if (!cameFrom.has(key)) break;
      node = cameFrom.get(key);
    }

    // 移除起始点
    path.shift();
    return path;
  }

  moveAlongPath() {
    if (this.path.length === 0) {
      this.isMoving = false;
      return;
    }

    this.isMoving = true;
    const nextPos = this.path.shift();

    const targetX = nextPos.x * this.tileSize + this.tileSize / 2;
    const targetY = nextPos.y * this.tileSize + this.tileSize / 2;

    const distance = Phaser.Math.Distance.Between(
      this.player.x, this.player.y, targetX, targetY
    );
    const duration = (distance / this.moveSpeed) * 1000;

    this.tweens.add({
      targets: this.player,
      x: targetX,
      y: targetY,
      duration: duration,
      onComplete: () => {
        this.playerGridX = nextPos.x;
        this.playerGridY = nextPos.y;
        this.moveCount++;
        this.statusText.setText(
          `Move Count: ${this.moveCount} | Click to move player`
        );
        this.moveAlongPath();
      }
    });
  }

  update(time, delta) {
    // 可以在这里添加其他更新逻辑
  }
}

const config = {
  type: Phaser.AUTO,
  width: 600,
  height: 650,
  backgroundColor: '#222222',
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现 AI 追踪对战游戏，玩家收集 15 个物品获胜，被 AI 碰到失败
API: Phaser.Physics.Arcade.Sprite, Phaser.Physics.Arcade.moveToObject, Phaser.Input.Keyboard.createCursorKeys, Phaser.Physics.Arcade.overlap
STEPS:
1. 创建玩家（绿色方块）和 AI（紫色方块），使用 Graphics 生成纹理
2. 随机生成 15 个可收集物品（黄色圆点）
3. 在 update 中使用 moveToObject 让 AI 以 160 速度追踪玩家
4. 使用键盘控制玩家移动（速度 200）
5. 检测玩家与物品的碰撞（收集物品，score++）
6. 检测玩家与 AI 的碰撞（游戏失败）
7. 当 score 达到 15 时游戏胜利，显示结果文本
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.score = 0;
    this.gameOver = false;
    this.gameWon = false;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（绿色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建 AI 纹理（紫色方块）
    const aiGraphics = this.add.graphics();
    aiGraphics.fillStyle(0x9900ff, 1);
    aiGraphics.fillRect(0, 0, 32, 32);
    aiGraphics.generateTexture('ai', 32, 32);
    aiGraphics.destroy();

    // 创建物品纹理（黄色圆点）
    const itemGraphics = this.add.graphics();
    itemGraphics.fillStyle(0xffff00, 1);
    itemGraphics.fillCircle(8, 8, 8);
    itemGraphics.generateTexture('item', 16, 16);
    itemGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建 AI
    this.ai = this.physics.add.sprite(100, 100, 'ai');
    this.ai.setCollideWorldBounds(true);

    // 创建物品组
    this.items = this.physics.add.group();

    // 使用固定种子生成物品位置（确保确定性）
    const seed = 12345;
    let random = seed;
    const seededRandom = () => {
      random = (random * 9301 + 49297) % 233280;
      return random / 233280;
    };

    for (let i = 0; i < 15; i++) {
      const x = 50 + seededRandom() * 700;
      const y = 50 + seededRandom() * 500;
      const item = this.items.create(x, y, 'item');
      item.setCollideWorldBounds(true);
    }

    // 设置键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 设置碰撞检测
    this.physics.add.overlap(this.player, this.items, this.collectItem, null, this);
    this.physics.add.overlap(this.player, this.ai, this.hitAI, null, this);

    // 创建 UI 文本
    this.scoreText = this.add.text(16, 16, 'Score: 0 / 15', {
      fontSize: '24px',
      fill: '#ffffff'
    });

    this.resultText = this.add.text(400, 300, '', {
      fontSize: '48px',
      fill: '#ffffff',
      fontStyle: 'bold'
    });
    this.resultText.setOrigin(0.5);
    this.resultText.setVisible(false);

    // 添加边界
    this.add.graphics()
      .lineStyle(2, 0xffffff, 1)
      .strokeRect(0, 0, 800, 600);
  }

  update(time, delta) {
    if (this.gameOver || this.gameWon) {
      return;
    }

    // 玩家移动控制
    this.player.setVelocity(0);

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-200);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(200);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-200);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(200);
    }

    // AI 追踪玩家（速度 160）
    this.physics.moveToObject(this.ai, this.player, 160);
  }

  collectItem(player, item) {
    item.destroy();
    this.score++;
    this.scoreText.setText('Score: ' + this.score + ' / 15');

    // 检查是否获胜
    if (this.score >= 15) {
      this.gameWon = true;
      this.endGame('YOU WIN!', 0x00ff00);
    }
  }

  hitAI(player, ai) {
    if (!this.gameOver) {
      this.gameOver = true;
      this.endGame('GAME OVER!', 0xff0000);
    }
  }

  endGame(message, color) {
    // 停止所有移动
    this.player.setVelocity(0);
    this.ai.setVelocity(0);

    // 显示结果
    this.resultText.setText(message);
    this.resultText.setColor('#' + color.toString(16).padStart(6, '0'));
    this.resultText.setVisible(true);

    // 添加重启提示
    const restartText = this.add.text(400, 360, 'Press SPACE to restart', {
      fontSize: '20px',
      fill: '#ffffff'
    });
    restartText.setOrigin(0.5);

    // 监听空格键重启
    this.input.keyboard.once('keydown-SPACE', () => {
      this.scene.restart();
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
