REQ: 绘制10个随机位置的灰色六边形，每个大小为32像素
API: Phaser.GameObjects.Graphics, Graphics#fillStyle, Graphics#beginPath, Graphics#lineTo, Graphics#closePath, Graphics#fillPath, Phaser.Math.Between
STEPS:
1. 创建 Phaser Game 配置，设置场景宽度800x600
2. 在 create 方法中循环10次，每次创建一个 Graphics 对象
3. 使用数学计算六边形的6个顶点坐标（半径16像素）
4. 为每个六边形设置随机位置（x: 50-750, y: 50-550，确保不超出边界）
5. 使用 Graphics API 绘制填充的灰色六边形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 绘制10个随机位置的灰色六边形
  for (let i = 0; i < 10; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置灰色填充
    graphics.fillStyle(0x808080, 1);

    // 六边形参数
    const radius = 16; // 半径16像素，总大小32像素
    const sides = 6;

    // 随机位置（确保六边形完全在画布内）
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 550);

    // 开始绘制路径
    graphics.beginPath();

    // 计算六边形的6个顶点
    for (let j = 0; j < sides; j++) {
      // 从顶部开始，顺时针绘制（-90度起始）
      const angle = (Math.PI / 3) * j - Math.PI / 2;
      const vertexX = x + radius * Math.cos(angle);
      const vertexY = y + radius * Math.sin(angle);

      if (j === 0) {
        graphics.moveTo(vertexX, vertexY);
      } else {
        graphics.lineTo(vertexX, vertexY);
      }
    }

    // 闭合路径
    graphics.closePath();

    // 填充六边形
    graphics.fillPath();
  }
}

