function create() {
  // 使用 Graphics 绘制灰色菱形
  const graphics = this.add.graphics();

  // 设置灰色填充
  graphics.fillStyle(0x808080, 1);

  // 绘制菱形（使用四个点构成的多边形）
  // 菱形中心在 (50, 50)，宽度100，高度100
  graphics.beginPath();
  graphics.moveTo(50, 0);      // 顶点
  graphics.lineTo(100, 50);    // 右点
  graphics.lineTo(50, 100);    // 底点
  graphics.lineTo(0, 50);      // 左点
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('diamond', 100, 100);
  graphics.destroy();

  // 创建菱形精灵，放置在屏幕中心
  const diamond = this.add.sprite(400, 300, 'diamond');

  // 创建抖动动画效果
  // 使用多个连续的小幅度移动来模拟抖动
  this.tweens.add({
    targets: diamond,
    x: '+=10',           // 向右移动10像素
    duration: 50,        // 快速移动
    yoyo: true,          // 来回移动
    repeat: 0,           // 单次不重复
    onComplete: () => {
