REQ: 20个橙色小球以240速度在封闭空间内移动，碰撞边界和彼此时弹开
API: Phaser.Physics.Arcade, Graphics.fillCircle, Physics.add.group, Body.setBounce, Physics.add.collider
STEPS:
1. 创建物理系统配置，启用 arcade 物理引擎
2. 使用 Graphics 生成橙色圆形纹理
3. 创建物理组，添加 20 个小球精灵
4. 为每个小球设置随机初始速度（速度大小为 240）
5. 设置小球的弹性系数为 1（完全弹性碰撞）
6. 设置世界边界碰撞
7. 添加小球之间的碰撞检测
8. 添加状态信号（碰撞计数器）用于验证
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.collisionCount = 0; // 状态信号：碰撞计数
    this.ballCount = 20; // 小球数量
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建橙色圆形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xFF8800, 1); // 橙色
    graphics.fillCircle(16, 16, 16); // 半径16的圆
    graphics.generateTexture('orangeBall', 32, 32);
    graphics.destroy();

    // 创建物理组
    this.balls = this.physics.add.group({
      defaultKey: 'orangeBall',
      collideWorldBounds: true, // 与世界边界碰撞
      bounceX: 1, // X轴弹性系数为1（完全弹性）
      bounceY: 1  // Y轴弹性系数为1（完全弹性）
    });

    // 创建20个小球
    const speed = 240;
    for (let i = 0; i < this.ballCount; i++) {
      // 随机位置（避免边界）
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 550);

      const ball = this.balls.create(x, y, 'orangeBall');

      // 设置圆形碰撞体
      ball.setCircle(16);

      // 随机方向的速度，速度大小为240
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed;
      ball.setVelocity(vx, vy);
    }

    // 添加小球之间的碰撞检测
    this.physics.add.collider(this.balls, this.balls, this.onBallCollision, null, this);

    // 显示碰撞计数器（用于验证）
    this.collisionText = this.add.text(10, 10, 'Collisions: 0', {
      fontSize: '20px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.collisionText.setDepth(1000);

    // 显示小球数量
    this.ballCountText = this.add.text(10, 40, `Balls: ${this.ballCount}`, {
      fontSize: '20px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.ballCountText.setDepth(1000);

    // 显示平均速度（用于验证弹性碰撞）
    this.speedText = this.add.text(10, 70, 'Avg Speed: 240', {
      fontSize: '20px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.speedText.setDepth(1000);
  }

  onBallCollision(ball1, ball2) {
    // 碰撞计数器增加
    this.collisionCount++;
    this.collisionText.setText(`Collisions: ${this.collisionCount}`);
  }

  update(time, delta) {
    // 计算平均速度（验证能量守恒）
    let totalSpeed = 0;
    this.balls.getChildren().forEach(ball => {
      const speed = Math.sqrt(ball.body.velocity.x ** 2 + ball.body.velocity.y ** 2);
      totalSpeed += speed;
    });
    const avgSpeed = totalSpeed / this.ballCount;
    this.speedText.setText(`Avg Speed: ${avgSpeed.toFixed(1)}`);
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 }, // 无重力
      debug: false
    }
  },
  scene: GameScene
};

