let ellipseCount = 0;
let timerEvent = null;

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 初始化椭圆计数器
  ellipseCount = 0;

  // 创建定时器，每3秒触发一次
  timerEvent = this.time.addEvent({
    delay: 3000,              // 3秒
    callback: spawnEllipse,   // 回调函数
