  graphics.fillStyle(0xffffff, 1);

  // 绘制菱形路径（中心点在32,32，边长约45像素）
  const path = new Phaser.Geom.Polygon([
    32, 0,    // 上顶点
    64, 32,   // 右顶点
    32, 64,   // 下顶点
    0, 32     // 左顶点
  ]);

