REQ: 绿色方块以速度160平滑跟随鼠标指针移动
API: Phaser.GameObjects.Graphics, Phaser.Input.InputPlugin.activePointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 使用 Graphics 绘制绿色方块并生成纹理
2. 创建 Sprite 对象作为可移动的方块
3. 在 update 中获取鼠标指针位置
4. 计算方块到鼠标的距离和角度
5. 根据速度和 delta 时间平滑移动方块向鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let square;
const FOLLOW_SPEED = 160; // 跟随速度（像素/秒）

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制绿色方块并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('squareTex', 50, 50);
  graphics.destroy();

  // 创建方块精灵，初始位置在屏幕中心
  square = this.add.sprite(400, 300, 'squareTex');
  square.setOrigin(0.5, 0.5);
}

function update(time, delta) {
  // 获取当前活动的鼠标指针
  const pointer = this.input.activePointer;

  // 计算方块到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    square.x,
    square.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素才移动（避免抖动）
  if (distance > 1) {
    // 计算方块到鼠标的角度
    const angle = Phaser.Math.Angle.Between(
      square.x,
      square.y,
      pointer.x,
      pointer.y
    );

    // 根据速度和时间增量计算本帧应移动的距离
    const moveDistance = FOLLOW_SPEED * (delta / 1000);

    // 如果本帧移动距离大于实际距离，直接到达目标位置
    if (moveDistance >= distance) {
      square.x = pointer.x;
      square.y = pointer.y;
    } else {
      // 根据角度和移动距离更新方块位置
      square.x += Math.cos(angle) * moveDistance;
      square.y += Math.sin(angle) * moveDistance;
    }
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央使用 Graphics 绘制一个粉色星形，大小约为 32 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser 游戏配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的 5 个外顶点和 5 个内顶点坐标（基于中心点和半径）
4. 使用 beginPath/moveTo/lineTo 绘制星形路径
5. 使用粉色填充星形并渲染到画布中央
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置粉色填充
  graphics.fillStyle(0xff69b4, 1);

  // 画布中心坐标
  const centerX = 400;
  const centerY = 300;

  // 星形参数
  const outerRadius = 32; // 外半径
  const innerRadius = 16; // 内半径
  const points = 5; // 五角星

  // 开始绘制路径
  graphics.beginPath();

  // 计算并绘制星形的顶点
  for (let i = 0; i < points * 2; i++) {
    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算角度（从顶部开始，逆时针旋转）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 计算顶点坐标
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // 第一个点使用 moveTo，其他点使用 lineTo
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充星形
  graphics.fillPath();
}

new Phaser.Game(config);
```

