REQ: 灰色六边形平滑跟随鼠标指针移动，跟随速度为360
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Angle.Between, Phaser.Math.Distance.Between
STEPS:
1. 使用 Graphics 绘制灰色六边形并生成纹理
2. 创建 Sprite 对象使用六边形纹理
3. 在 update 中获取鼠标指针位置
4. 计算六边形到鼠标的距离和角度
5. 根据速度360和delta时间，向鼠标方向移动六边形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let hexagon;
let pointer;
const FOLLOW_SPEED = 360; // 每秒移动360像素

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制灰色六边形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1); // 灰色

  // 绘制六边形（中心点为原点）
  const hexRadius = 40;
  const hexPoints = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 每个顶点间隔60度
    const x = hexRadius * Math.cos(angle);
    const y = hexRadius * Math.sin(angle);
    hexPoints.push(new Phaser.Math.Vector2(x, y));
  }

  graphics.beginPath();
  graphics.moveTo(hexPoints[0].x, hexPoints[0].y);
  for (let i = 1; i < hexPoints.length; i++) {
    graphics.lineTo(hexPoints[i].x, hexPoints[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理（尺寸需要足够容纳六边形）
  graphics.generateTexture('hexagon', hexRadius * 2 + 10, hexRadius * 2 + 10);
  graphics.destroy();

  // 创建六边形精灵，初始位置在屏幕中心
  hexagon = this.add.sprite(400, 300, 'hexagon');

  // 获取指针引用
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // 计算六边形到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    hexagon.x,
    hexagon.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素才移动（避免抖动）
  if (distance > 1) {
    // 计算移动角度
    const angle = Phaser.Math.Angle.Between(
      hexagon.x,
      hexagon.y,
      pointer.x,
      pointer.y
    );

    // 根据速度和delta计算本帧移动距离（delta单位是毫秒）
    const moveDistance = (FOLLOW_SPEED * delta) / 1000;

    // 如果移动距离大于剩余距离，直接到达目标位置
    if (moveDistance >= distance) {
      hexagon.x = pointer.x;
      hexagon.y = pointer.y;
    } else {
      // 按角度方向移动
      hexagon.x += Math.cos(angle) * moveDistance;
      hexagon.y += Math.sin(angle) * moveDistance;
    }
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现角色受伤效果，碰撞时紫色角色闪烁2秒并击退
API: Phaser.Physics.Arcade, Phaser.Tweens.TweenManager, Phaser.GameObjects.Graphics, Phaser.Scene.time
STEPS:
1. 创建两个物理精灵（紫色角色和敌人），使用 Graphics 生成纹理
2. 设置碰撞检测，当角色与敌人碰撞时触发受伤逻辑
3. 实现闪烁效果：使用 alpha 透明度补间动画循环2秒
4. 实现击退效果：根据碰撞方向和速度240计算击退向量，使用 Tween 移动角色
5. 添加无敌时间状态，防止重复触发受伤
6. 显示健康值和受伤次数作为可验证状态
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.health = 100;
    this.hitCount = 0;
    this.isInvincible = false;
  }

  preload() {
    // 使用 Graphics 生成纹理
    this.createTextures();
  }

  createTextures() {
    // 创建紫色角色纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x9c27b0, 1); // 紫色
    playerGraphics.fillRect(0, 0, 40, 40);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();

    // 创建红色敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1); // 红色
    enemyGraphics.fillCircle(20, 20, 20);
    enemyGraphics.generateTexture('enemy', 40, 40);
    enemyGraphics.destroy();
  }

  create() {
    // 创建紫色角色（玩家）
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.setBounce(0);

    // 创建敌人
    this.enemy = this.physics.add.sprite(600, 300, 'enemy');
    this.enemy.setVelocity(-100, 0);
    this.enemy.setCollideWorldBounds(true);
    this.enemy.setBounce(1);

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemy,
      this.handleHit,
      null,
      this
    );

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 显示状态信息
    this.statusText = this.add.text(16, 16, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.updateStatusText();

    // 提示文本
    this.add.text(16, 550, 'Use Arrow Keys to Move. Collide with Red Enemy to Test Hit Effect', {
      fontSize: '14px',
      fill: '#ffff00'
    });
  }

  handleHit(player, enemy) {
    // 如果处于无敌状态，不触发受伤
    if (this.isInvincible) {
      return;
    }

    // 减少健康值
    this.health -= 20;
    this.hitCount++;
    this.isInvincible = true;

    // 计算击退方向
    const angle = Phaser.Math.Angle.Between(
      enemy.x,
      enemy.y,
      player.x,
      player.y
    );

    // 基于速度240计算击退距离（速度越快，击退越远）
    const knockbackSpeed = 240;
    const knockbackDistance = 100; // 击退距离
    const knockbackDuration = 300; // 击退持续时间（毫秒）

    // 计算击退目标位置
    const knockbackX = player.x + Math.cos(angle) * knockbackDistance;
    const knockbackY = player.y + Math.sin(angle) * knockbackDistance;

    // 停止玩家当前的速度
    player.setVelocity(0, 0);

    // 击退效果（使用 Tween）
    this.tweens.add({
      targets: player,
      x: knockbackX,
      y: knockbackY,
      duration: knockbackDuration,
      ease: 'Power2',
      onComplete: () => {
        // 击退完成后恢复控制
      }
    });

    // 闪烁效果（2秒）
    const blinkDuration = 2000;
    const blinkInterval = 100; // 每100ms切换一次透明度

    // 创建闪烁 Tween
    this.tweens.add({
      targets: player,
      alpha: 0.3,
      duration: blinkInterval,
      yoyo: true,
      repeat: Math.floor(blinkDuration / (blinkInterval * 2)) - 1,
      onComplete: () => {
        // 闪烁结束，恢复正常
        player.alpha = 1;
        this.isInvincible = false;
      }
    });

    // 更新状态显示
    this.updateStatusText();

    // 如果健康值归零，显示游戏结束
    if (this.health <= 0) {
      this.health = 0;
      this.showGameOver();
    }
  }

  updateStatusText() {
    this.statusText.setText(
      `Health: ${this.health} | Hit Count: ${this.hitCount} | Invincible: ${this.isInvincible}`
    );
  }

  showGameOver() {
    // 停止所有物理对象
    this.physics.pause();

    // 显示游戏结束文本
    const gameOverText = this.add.text(400, 300, 'GAME OVER', {
      fontSize: '64px',
      fill: '#ff0000',
      backgroundColor: '#000000',
      padding: { x: 20, y: 10 }
    });
    gameOverText.setOrigin(0.5);

    // 重启提示
    const restartText = this.add.text(400, 370, 'Press SPACE to Restart', {
      fontSize: '24px',
      fill: '#ffffff'
    });
    restartText.setOrigin(0.5);

    // 监听空格键重启
    this.input.keyboard.once('keydown-SPACE', () => {
      this.scene.restart();
    });
  }

  update(time, delta) {
    // 如果游戏结束，不更新
    if (this.health <= 0) {
      return;
    }

    // 玩家移动控制（仅在非无敌状态或无击退动画时）
    if (!this.isInvincible || this.player.alpha === 1) {
      const speed = 200;

      if (this.cursors.left.isDown) {
        this.player.setVelocityX(-speed);
      } else if (this.cursors.right.isDown) {
        this.player.setVelocityX(speed);
      } else {
        this.player.setVelocityX(0);
      }

      if (this.cursors.up.isDown) {
        this.player.setVelocityY(-speed);
      } else if (this.cursors.down.isDown) {
        this.player.setVelocityY(speed);
      } else {
        this.player.setVelocityY(0);
      }
    }

    // 更新状态显示
    this.updateStatusText();
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

// 启动游戏
new Phaser.Game(config);
```

