API: Phaser.GameObjects.Graphics, Phaser.Input.Keyboard.KeyCodes, Phaser.Input.Keyboard.addKey
STEPS:
1. 创建 Scene 并配置 Game
2. 使用 Graphics 绘制六边形并生成纹理
3. 创建 Sprite 使用生成的六边形纹理
4. 添加 WASD 键盘输入监听
5. 在 update 中根据按键状态更新六边形位置（速度 80 像素/秒）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let hexagon;
let keyW, keyA, keyS, keyD;
const SPEED = 80; // 像素/秒

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();

  // 六边形参数
  const hexRadius = 30;
  const centerX = hexRadius;
  const centerY = hexRadius;

  // 绘制六边形（6个顶点）
  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(3, 0x00aa00, 1);

  graphics.beginPath();
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i - Math.PI / 6; // 从顶部开始
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', hexRadius * 2, hexRadius * 2);
  graphics.destroy();

  // 创建六边形精灵，放置在屏幕中央
  hexagon = this.add.sprite(400, 300, 'hexagon');

  // 设置 WASD 键
  keyW = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W);
  keyA = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A);
  keyS = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S);
  keyD = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D);
}

function update(time, delta) {
  // 计算本帧应移动的距离（速度 * 时间差）
  const distance = SPEED * (delta / 1000);

  // 根据按键状态更新位置
  if (keyW.isDown) {
    hexagon.y -= distance;
  }
  if (keyS.isDown) {
    hexagon.y += distance;
  }
  if (keyA.isDown) {
    hexagon.x -= distance;
  }
  if (keyD.isDown) {
    hexagon.x += distance;
  }

  // 边界限制（可选）
  hexagon.x = Phaser.Math.Clamp(hexagon.x, 0, 800);
  hexagon.y = Phaser.Math.Clamp(hexagon.y, 0, 600);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 使用对象池管理15个红色可复用对象，离开屏幕后自动回收并重新使用
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Sprite, this.add.text
STEPS:
1. 创建 Graphics 生成红色方块纹理
2. 使用 Physics.Arcade.Group 创建对象池，设置 maxSize 为 15
3. 在 create 中初始化对象池，配置对象的初始属性和回收逻辑
4. 定时从对象池中获取对象并发射到屏幕
5. 在 update 中检测对象是否离开屏幕边界，离开则回收到对象池
6. 添加文本显示活跃对象数和总回收次数作为可验证状态
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.activeCount = 0;
    this.recycleCount = 0;
    this.spawnCount = 0;
  }

  preload() {
    // 创建红色方块纹理
    const graphics = this.make.graphics({ x: 0, y: 0, add: false });
    graphics.fillStyle(0xff0000, 1);
    graphics.fillRect(0, 0, 32, 32);
    graphics.generateTexture('redBox', 32, 32);
    graphics.destroy();
  }

  create() {
    // 创建对象池 Group，最大 15 个对象
    this.objectPool = this.physics.add.group({
      defaultKey: 'redBox',
      maxSize: 15,
      runChildUpdate: false,
      createCallback: (obj) => {
        obj.setActive(false);
        obj.setVisible(false);
      }
    });

    // 创建状态显示文本
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 定时发射对象（每 500ms）
    this.time.addEvent({
      delay: 500,
      callback: this.spawnObject,
      callbackScope: this,
      loop: true
    });

    // 更新状态显示
    this.updateStatus();
  }

  spawnObject() {
    // 从对象池获取或创建对象
    const obj = this.objectPool.get();

    if (obj) {
      // 随机生成位置（从屏幕顶部）
      const x = Phaser.Math.Between(50, 750);
      const y = -50;

      // 激活并设置属性
      obj.setActive(true);
      obj.setVisible(true);
      obj.setPosition(x, y);

      // 设置随机速度
      const velocityX = Phaser.Math.Between(-100, 100);
      const velocityY = Phaser.Math.Between(100, 300);
      obj.setVelocity(velocityX, velocityY);

      // 设置旋转速度
      obj.setAngularVelocity(Phaser.Math.Between(-180, 180));

      this.spawnCount++;
      this.updateActiveCount();
    }
  }

  update(time, delta) {
    // 检查所有活跃对象
    const activeObjects = this.objectPool.getChildren().filter(obj => obj.active);

    activeObjects.forEach(obj => {
      // 检查是否离开屏幕边界（包含所有方向）
      if (obj.y > 650 || obj.y < -50 || obj.x < -50 || obj.x > 850) {
        this.recycleObject(obj);
      }
    });
  }

  recycleObject(obj) {
    // 回收对象到池中
    obj.setActive(false);
    obj.setVisible(false);
    obj.setVelocity(0, 0);
    obj.setAngularVelocity(0);

    this.recycleCount++;
    this.updateActiveCount();
  }

  updateActiveCount() {
    this.activeCount = this.objectPool.getChildren().filter(obj => obj.active).length;
    this.updateStatus();
  }

  updateStatus() {
    this.statusText.setText([
      `对象池大小: ${this.objectPool.getLength()}/${this.objectPool.maxSize}`,
      `活跃对象: ${this.activeCount}`,
      `已发射: ${this.spawnCount}`,
      `已回收: ${this.recycleCount}`,
      `回收率: ${this.spawnCount > 0 ? Math.round(this.recycleCount / this.spawnCount * 100) : 0}%`
    ]);
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

