REQ: 灰色六边形平滑跟随鼠标指针移动，跟随速度为360
API: Phaser.GameObjects.Graphics, Phaser.Input.InputPlugin, Phaser.Math.Angle.Between, Phaser.Math.Distance.Between
STEPS:
1. 使用 Graphics 绘制灰色六边形并生成纹理
2. 创建 Sprite 对象使用该纹理
3. 在 create 中监听鼠标输入获取指针位置
4. 在 update 中计算六边形到鼠标的角度和距离
5. 根据速度360和delta时间计算移动距离，平滑移动六边形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let hexagon;
let pointer;
const FOLLOW_SPEED = 360; // 每秒移动的像素数

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制灰色六边形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1); // 灰色

  // 绘制六边形（中心在原点）
  const hexRadius = 40;
  const hexPoints = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 每个角60度
    const x = Math.cos(angle) * hexRadius;
    const y = Math.sin(angle) * hexRadius;
    hexPoints.push(x, y);
  }

  graphics.fillPoints(hexPoints, true);

  // 生成纹理
  graphics.generateTexture('hexagon', hexRadius * 2, hexRadius * 2);
  graphics.destroy();

  // 创建六边形精灵，初始位置在屏幕中心
  hexagon = this.add.sprite(400, 300, 'hexagon');

  // 获取指针引用
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // 计算六边形到鼠标指针的距离
  const distance = Phaser.Math.Distance.Between(
    hexagon.x,
    hexagon.y,
    pointer.x,
    pointer.y
  );

  // 如果距离足够近，直接设置位置，避免抖动
  if (distance < 2) {
    hexagon.x = pointer.x;
    hexagon.y = pointer.y;
    return;
  }

  // 计算六边形到鼠标指针的角度
  const angle = Phaser.Math.Angle.Between(
    hexagon.x,
    hexagon.y,
    pointer.x,
    pointer.y
  );

  // 计算本帧应该移动的距离（速度 * 时间）
  const moveDistance = FOLLOW_SPEED * (delta / 1000);

  // 如果移动距离大于剩余距离，直接到达目标点
  if (moveDistance >= distance) {
    hexagon.x = pointer.x;
    hexagon.y = pointer.y;
  } else {
    // 根据角度和移动距离更新位置
    hexagon.x += Math.cos(angle) * moveDistance;
    hexagon.y += Math.sin(angle) * moveDistance;
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 绘制20个随机位置的灰色菱形，每个大小为80像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Phaser.Math.Between
STEPS:
