REQ: 实现双跳功能，角色可跳跃两次后才需落地，跳跃力度240，重力300
API: Phaser.Physics.Arcade.Sprite, Phaser.Input.Keyboard, Phaser.Graphics, Phaser.Physics.Arcade.Body
STEPS:
1. 创建物理引擎配置，设置重力为300
2. 使用Graphics绘制玩家角色和地面平台
3. 添加键盘输入监听，检测空格键或上方向键
4. 实现双跳逻辑：记录跳跃次数，最多允许2次跳跃
5. 当角色接触地面时重置跳跃次数
6. 添加状态变量显示当前剩余跳跃次数
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 300 },
      debug: false
    }
  },
  scene: { preload, create, update }
};

let player;
let platforms;
let cursors;
let jumpKey;
let jumpCount = 0; // 当前已跳跃次数
let maxJumps = 2; // 最大跳跃次数
let statusText;

function preload() {
  // 使用Graphics生成纹理，无需外部资源
}

function create() {
  // 创建玩家纹理
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x00ff00, 1);
  playerGraphics.fillRect(0, 0, 32, 48);
  playerGraphics.generateTexture('player', 32, 48);
  playerGraphics.destroy();

  // 创建平台纹理
  const platformGraphics = this.add.graphics();
  platformGraphics.fillStyle(0x666666, 1);
  platformGraphics.fillRect(0, 0, 400, 32);
  platformGraphics.generateTexture('platform', 400, 32);
  platformGraphics.destroy();

  // 创建地面平台组
  platforms = this.physics.add.staticGroup();

  // 地面
  platforms.create(400, 568, 'platform').setScale(2).refreshBody();

  // 其他平台
  platforms.create(600, 400, 'platform');
  platforms.create(50, 250, 'platform').setScale(0.5).refreshBody();
  platforms.create(750, 220, 'platform').setScale(0.5).refreshBody();

  // 创建玩家
  player = this.physics.add.sprite(100, 450, 'player');
  player.setBounce(0);
  player.setCollideWorldBounds(true);

  // 玩家与平台碰撞
  this.physics.add.collider(player, platforms, () => {
    // 当玩家接触地面时，重置跳跃次数
    if (player.body.touching.down) {
      jumpCount = 0;
    }
  });

  // 设置键盘输入
  cursors = this.input.keyboard.createCursorKeys();
  jumpKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

  // 状态文本显示
  statusText = this.add.text(16, 16, '', {
    fontSize: '20px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 添加说明文字
  this.add.text(16, 50, '按空格键或上方向键跳跃\n最多可连续跳跃2次', {
    fontSize: '16px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });
}

function update() {
  // 左右移动
  if (cursors.left.isDown) {
    player.setVelocityX(-160);
  } else if (cursors.right.isDown) {
    player.setVelocityX(160);
  } else {
    player.setVelocityX(0);
  }

  // 双跳逻辑
  // 检测跳跃键是否刚按下（使用 justDown 避免长按连续触发）
  if (Phaser.Input.Keyboard.JustDown(cursors.up) || Phaser.Input.Keyboard.JustDown(jumpKey)) {
    // 如果跳跃次数小于最大跳跃次数，允许跳跃
    if (jumpCount < maxJumps) {
      player.setVelocityY(-240);
      jumpCount++;
    }
  }

  // 当玩家接触地面时，重置跳跃次数
  if (player.body.touching.down) {
    jumpCount = 0;
  }

  // 更新状态显示
  const remainingJumps = maxJumps - jumpCount;
  const onGround = player.body.touching.down ? '是' : '否';
  statusText.setText(
    `剩余跳跃次数: ${remainingJumps}/${maxJumps}\n` +
    `已使用跳跃: ${jumpCount}\n` +
    `是否在地面: ${onGround}\n` +
    `Y速度: ${Math.round(player.body.velocity.y)}`
  );
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现20格血条显示，鼠标右键扣血，每2.5秒自动回复1点生命值
API: Graphics, Input.on, Time.addEvent, TimerEvent
STEPS:
1. 创建20格血条UI，使用Graphics绘制红色格子表示当前生命值
2. 监听鼠标右键点击事件，每次点击扣除1点生命值并更新血条显示
3. 使用TimerEvent创建2.5秒循环定时器，自动回复1点生命值（不超过最大值）
4. 实现updateHealthBar方法动态刷新血条显示
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.maxHealth = 20;
    this.currentHealth = 20;
    this.healthBarGraphics = null;
    this.healthText = null;
    this.regenTimer = null;
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 创建标题文本
    this.add.text(400, 50, '血条系统演示', {
      fontSize: '32px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 创建提示文本
    this.add.text(400, 100, '鼠标右键：扣血 | 每2.5秒自动回复1点', {
      fontSize: '18px',
      color: '#cccccc'
    }).setOrigin(0.5);

    // 创建血条容器
    this.healthBarGraphics = this.add.graphics();

    // 创建生命值文本
    this.healthText = this.add.text(400, 450, '', {
      fontSize: '24px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 初始化血条显示
    this.updateHealthBar();

    // 监听鼠标右键点击事件
    this.input.on('pointerdown', (pointer) => {
      if (pointer.rightButtonDown()) {
        this.takeDamage(1);
      }
    });

    // 创建自动回血定时器（每2.5秒触发一次）
    this.regenTimer = this.time.addEvent({
      delay: 2500,
      callback: this.regenerateHealth,
      callbackScope: this,
      loop: true
    });

    // 添加调试信息文本
    this.debugText = this.add.text(10, 10, '', {
      fontSize: '16px',
      color: '#00ff00'
    });
    this.updateDebugInfo();
  }

  update(time, delta) {
    // 更新调试信息
    this.updateDebugInfo();
  }

  /**
   * 更新血条显示
   */
  updateHealthBar() {
    this.healthBarGraphics.clear();

    const barWidth = 30;  // 每格血条宽度
    const barHeight = 40; // 血条高度
    const gap = 5;        // 格子间距
    const startX = 400 - (this.maxHealth * (barWidth + gap) - gap) / 2; // 居中起始位置
    const startY = 200;

    // 绘制所有血条格子
    for (let i = 0; i < this.maxHealth; i++) {
      const x = startX + i * (barWidth + gap);

      // 绘制背景（灰色边框）
      this.healthBarGraphics.lineStyle(2, 0x666666, 1);
      this.healthBarGraphics.strokeRect(x, startY, barWidth, barHeight);

      // 如果当前格子应该被填充（生命值未耗尽）
      if (i < this.currentHealth) {
        // 根据生命值比例改变颜色
        const healthPercent = this.currentHealth / this.maxHealth;
        let fillColor;
        if (healthPercent > 0.6) {
          fillColor = 0x00ff00; // 绿色（健康）
        } else if (healthPercent > 0.3) {
          fillColor = 0xffff00; // 黄色（警告）
        } else {
          fillColor = 0xff0000; // 红色（危险）
        }

        this.healthBarGraphics.fillStyle(fillColor, 1);
        this.healthBarGraphics.fillRect(x + 2, startY + 2, barWidth - 4, barHeight - 4);
      }
    }

    // 更新生命值文本
    this.healthText.setText(`生命值: ${this.currentHealth} / ${this.maxHealth}`);
  }

  /**
   * 扣血逻辑
   */
  takeDamage(amount) {
    if (this.currentHealth > 0) {
      this.currentHealth = Math.max(0, this.currentHealth - amount);
      this.updateHealthBar();

      // 创建伤害提示
      const damageText = this.add.text(
        Phaser.Math.Between(300, 500),
        150,
        `-${amount}`,
        { fontSize: '32px', color: '#ff0000', fontStyle: 'bold' }
      ).setOrigin(0.5);

      // 伤害数字动画
      this.tweens.add({
        targets: damageText,
        y: 100,
        alpha: 0,
        duration: 800,
        ease: 'Power2',
        onComplete: () => {
          damageText.destroy();
        }
      });

      if (this.currentHealth === 0) {
        this.showGameOverMessage();
      }
    }
  }

  /**
   * 回血逻辑
   */
  regenerateHealth() {
    if (this.currentHealth < this.maxHealth && this.currentHealth > 0) {
      this.currentHealth = Math.min(this.maxHealth, this.currentHealth + 1);
      this.updateHealthBar();

      // 创建回血提示
      const healText = this.add.text(
        Phaser.Math.Between(300, 500),
        150,
        '+1',
        { fontSize: '28px', color: '#00ff00', fontStyle: 'bold' }
      ).setOrigin(0.5);

      // 回血数字动画
      this.tweens.add({
        targets: healText,
        y: 100,
        alpha: 0,
        duration: 800,
        ease: 'Power2',
        onComplete: () => {
          healText.destroy();
        }
      });
    }
  }

  /**
   * 显示游戏结束消息
   */
  showGameOverMessage() {
    const gameOverText = this.add.text(400, 300, 'GAME OVER', {
      fontSize: '48px',
      color: '#ff0000',
      fontStyle: 'bold'
    }).setOrigin(0.5).setAlpha(0);

    this.tweens.add({
      targets: gameOverText,
      alpha: 1,
      duration: 500,
      ease: 'Power2'
    });

    // 停止回血定时器
    if (this.regenTimer) {
      this.regenTimer.remove();
    }
  }

  /**
   * 更新调试信息
   */
  updateDebugInfo() {
    const timerProgress = this.regenTimer ? 
      (this.regenTimer.getElapsed() / this.regenTimer.delay * 100).toFixed(1) : 0;

    this.debugText.setText([
      `当前生命值: ${this.currentHealth}`,
      `最大生命值: ${this.maxHealth}`,
      `回血进度: ${timerProgress}%`,
      `定时器运行: ${this.regenTimer && !this.regenTimer.paused ? 'Yes' : 'No'}`
    ]);
  }
}

// Phaser 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: GameScene,
  input: {
    mouse: {
      target: null,
      capture: true
    }
  }
};

// 创建游戏实例
const game = new Phaser.Game(config);
```

