    const size = 40; // 三角形大小
    const x = pointer.x;
    const y = pointer.y;

    // 绘制一个等边三角形（顶点朝上）
    graphics.beginPath();
    graphics.moveTo(x, y - size); // 顶点
    graphics.lineTo(x - size * 0.866, y + size * 0.5); // 左下顶点
    graphics.lineTo(x + size * 0.866, y + size * 0.5); // 右下顶点
    graphics.closePath();
    graphics.fillPath();

    // 添加描边使三角形更明显
    graphics.lineStyle(2, 0xffffff, 0.8);
