  for (let i = 0; i < 10; i++) {
    const refGraphics = this.add.graphics();
    const colors = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00, 0xff00ff];
    refGraphics.fillStyle(colors[i % colors.length], 0.5);
    refGraphics.fillRect(i * 500, 200, 80, 80);
  }

  // 使用 Graphics 创建圆形纹理
