3. 创建物理组，添加 8 个白色圆形精灵
4. 为每个物体设置随机初始位置和随机速度方向（速度大小为200）
5. 设置物体边界碰撞反弹和物体间碰撞检测
6. 添加状态信号变量记录碰撞次数
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态信号变量
let collisionCount = 0;
let objectCount = 8;
let objectsGroup;

function preload() {
  // 使用 Graphics 生成白色圆形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);
  graphics.fillCircle(16, 16, 16);
  graphics.generateTexture('whiteCircle', 32, 32);
  graphics.destroy();
}

function create() {
  // 创建物理组
  objectsGroup = this.physics.add.group({
    key: 'whiteCircle',
    repeat: objectCount - 1,
    bounceX: 1,
    bounceY: 1,
    collideWorldBounds: true
  });

  // 为每个物体设置随机位置和速度
  const objects = objectsGroup.getChildren();
  objects.forEach((obj, index) => {
    // 随机位置（避免边缘）
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 550);
    obj.setPosition(x, y);

    // 随机角度，固定速度200
    const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
    const velocityX = Math.cos(angle) * 200;
    const velocityY = Math.sin(angle) * 200;
    obj.setVelocity(velocityX, velocityY);

    // 设置反弹系数
    obj.setBounce(1);
    obj.setCollideWorldBounds(true);
  });

  // 设置物体间碰撞检测
  this.physics.add.collider(objectsGroup, objectsGroup, handleCollision, null, this);

  // 显示状态信息
  this.statusText = this.add.text(10, 10, '', {
    fontSize: '16px',
    fill: '#ffffff'
  });

  updateStatusText.call(this);
}

function update(time, delta) {
  updateStatusText.call(this);
}

function handleCollision(obj1, obj2) {
  // 记录碰撞次数
  collisionCount++;
}

function updateStatusText() {
  this.statusText.setText([
    `Objects: ${objectCount}`,
    `Collisions: ${collisionCount}`,
    `Speed: 200 px/s`
  ]);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 使用 WASD 键控制星形以 200 像素/秒速度移动
API: Phaser.GameObjects.Graphics, Phaser.Input.Keyboard.addKeys, Phaser.GameObjects.Sprite
STEPS:
1. 创建 Graphics 对象绘制星形并生成纹理
2. 使用生成的纹理创建 Sprite 作为可移动对象
3. 通过 addKeys 监听 WASD 键盘输入
4. 在 update 中根据按键状态更新星形位置，速度为 200 像素/秒
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let star;
let keys;
const SPEED = 200; // 像素/秒

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制星形
  const graphics = this.add.graphics();

  // 绘制五角星
  graphics.fillStyle(0xffff00, 1); // 黄色
  graphics.lineStyle(2, 0xffa500, 1); // 橙色边框

  // 星形的顶点坐标（以中心为原点）
  const points = [];
  const outerRadius = 30;
  const innerRadius = 12;
  const numPoints = 5;

  for (let i = 0; i < numPoints * 2; i++) {
    const angle = (i * Math.PI) / numPoints - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    points.push({
      x: 32 + Math.cos(angle) * radius,
      y: 32 + Math.sin(angle) * radius
    });
  }

  // 绘制星形路径
  graphics.beginPath();
  graphics.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) {
    graphics.lineTo(points[i].x, points[i].y);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('star', 64, 64);
  graphics.destroy();

  // 创建星形精灵，初始位置在屏幕中央
  star = this.add.sprite(400, 300, 'star');

  // 设置键盘输入 - WASD
  keys = this.input.keyboard.addKeys({
    w: Phaser.Input.Keyboard.KeyCodes.W,
    a: Phaser.Input.Keyboard.KeyCodes.A,
    s: Phaser.Input.Keyboard.KeyCodes.S,
    d: Phaser.Input.Keyboard.KeyCodes.D
  });
}

function update(time, delta) {
  // 计算每帧移动距离 = 速度 * 时间增量（秒）
  const distance = SPEED * (delta / 1000);

  // 根据按键状态更新星形位置
  if (keys.w.isDown) {
    star.y -= distance; // 向上移动
  }
  if (keys.s.isDown) {
    star.y += distance; // 向下移动
  }
  if (keys.a.isDown) {
    star.x -= distance; // 向左移动
  }
  if (keys.d.isDown) {
    star.x += distance; // 向右移动
  }

  // 限制星形在屏幕范围内
  star.x = Phaser.Math.Clamp(star.x, 0, 800);
  star.y = Phaser.Math.Clamp(star.y, 0, 600);
}

new Phaser.Game(config);
```

