      fontSize: '64px',
      fill: '#ff0000',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 6
    });
    this.gameOverText.setOrigin(0.5);
    this.gameOverText.setVisible(false);

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加说明文本
    this.add.text(16, 560, 'Arrow Keys to Move - Avoid Red Enemies!', {
      fontSize: '20px',
      fill: '#cccccc',
      fontFamily: 'Arial'
    });
  }

  update(time, delta) {
    // 如果游戏结束，停止更新
    if (this.health <= 0) {
      return;
    }

    // 玩家移动控制
    const speed = 200;
    this.player.setVelocity(0);

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    }
  }

  handleCollision(player, enemy) {
    // 如果处于无敌状态，不处理碰撞
    if (this.isInvincible) {
      return;
    }

    // 扣除生命值
    this.health -= 1;
    this.updateHealthDisplay();

    // 检查是否死亡
    if (this.health <= 0) {
      this.handleGameOver();
      return;
    }

    // 触发无敌状态
    this.activateInvincibility();
  }

  activateInvincibility() {
    this.isInvincible = true;

    // 切换到橙色纹理
    this.player.setTexture('playerInvincible');

    // 更新无敌状态提示
    this.invincibleText.setText('INVINCIBLE!');

    // 创建闪烁效果（透明度变化）
    this.tweens.add({
      targets: this.player,
      alpha: 0.3,
      duration: 100,
      yoyo: true,
      repeat: 9, // 重复9次，共10次变化，约1秒
      onComplete: () => {
        // 恢复正常状态
        this.player.setAlpha(1);
        this.player.setTexture('player');
        this.isInvincible = false;
        this.invincibleText.setText('');
      }
    });
  }

  updateHealthDisplay() {
    this.healthText.setText(`Health: ${this.health}/${this.maxHealth}`);

    // 根据血量改变颜色
    if (this.health <= 3) {
      this.healthText.setFill('#ff0000'); // 低血量红色
    } else if (this.health <= 7) {
      this.healthText.setFill('#ffaa00'); // 中等血量橙色
    } else {
      this.healthText.setFill('#ffffff'); // 高血量白色
    }
  }

  handleGameOver() {
    // 停止所有敌人移动
    this.enemies.getChildren().forEach(enemy => {
      enemy.setVelocity(0, 0);
    });

    // 停止玩家移动
    this.player.setVelocity(0, 0);

    // 显示游戏结束文本
    this.gameOverText.setVisible(true);

    // 添加闪烁效果
    this.tweens.add({
      targets: this.gameOverText,
      alpha: 0.3,
      duration: 500,
      yoyo: true,
      repeat: -1
    });

    // 显示最终血量
    this.healthText.setText(`Health: 0/${this.maxHealth}`);
    this.healthText.setFill('#ff0000');
  }
}

