[PLAN]
REQ: 六边形在3秒内缩放到32%后恢复，循环播放
API: Graphics.fillPolygon, Scene.tweens.add, Tween.yoyo, Tween.repeat
STEPS:
1. 使用 Graphics 绘制六边形形状
2. 创建 Tween 动画，将 scale 从 1 缩放到 0.32
3. 设置 yoyo 为 true 实现自动恢复
4. 设置 repeat 为 -1 实现无限循环
5. 设置 duration 为 3000ms（3秒）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象绘制六边形
  const graphics = this.add.graphics();

  // 设置六边形的中心点和半径
  const centerX = 400;
  const centerY = 300;
  const radius = 100;

  // 计算六边形的六个顶点坐标
  const hexagon = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i - Math.PI / 2; // 从顶部开始
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);
    hexagon.push(x, y);
  }

  // 绘制填充的六边形
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillPolygon(hexagon);

  // 设置六边形的原点为中心点，方便缩放
  graphics.x = 0;
  graphics.y = 0;

  // 创建缩放动画
  this.tweens.add({
    targets: graphics,
    scaleX: 0.32,        // 缩放到 32%
    scaleY: 0.32,        // 缩放到 32%
    duration: 3000,      // 3秒完成缩放
    yoyo: true,          // 自动反向播放（恢复原始大小）
    repeat: -1,          // 无限循环
    ease: 'Sine.easeInOut' // 使用平滑的缓动函数
  });

  // 添加提示文本
  const text = this.add.text(400, 550, '六边形缩放动画（3秒循环）', {
    fontSize: '20px',
    color: '#ffffff'
  });
  text.setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 黄色矩形以240速度移动并在画布边界反弹
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Rectangle, Phaser.Physics.Arcade
STEPS:
1. 创建带有 Arcade 物理系统的游戏配置
2. 使用 Graphics 绘制黄色矩形并生成纹理
3. 创建物理精灵并设置初始速度为240
4. 在 update 中检测边界碰撞并反转速度实现反弹
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  },
  backgroundColor: '#2d2d2d'
};

let rectangle;
const SPEED = 240;

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 创建黄色矩形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffff00, 1); // 黄色
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('yellowRect', 50, 50);
  graphics.destroy();

  // 创建物理精灵
  rectangle = this.physics.add.sprite(400, 300, 'yellowRect');

  // 设置初始速度（随机方向）
  const angle = Phaser.Math.Between(0, 360);
  this.physics.velocityFromAngle(angle, SPEED, rectangle.body.velocity);

  // 设置碰撞边界
  rectangle.setCollideWorldBounds(true);
  rectangle.setBounce(1, 1); // 完全弹性碰撞
}

function update(time, delta) {
  // 检查边界碰撞并反转速度
  const bounds = this.physics.world.bounds;

  // 左右边界
  if (rectangle.x <= rectangle.width / 2 && rectangle.body.velocity.x < 0) {
    rectangle.body.velocity.x = Math.abs(rectangle.body.velocity.x);
  } else if (rectangle.x >= bounds.width - rectangle.width / 2 && rectangle.body.velocity.x > 0) {
    rectangle.body.velocity.x = -Math.abs(rectangle.body.velocity.x);
  }

  // 上下边界
  if (rectangle.y <= rectangle.height / 2 && rectangle.body.velocity.y < 0) {
    rectangle.body.velocity.y = Math.abs(rectangle.body.velocity.y);
  } else if (rectangle.y >= bounds.height - rectangle.height / 2 && rectangle.body.velocity.y > 0) {
    rectangle.body.velocity.y = -Math.abs(rectangle.body.velocity.y);
  }

  // 保持速度恒定为240
  const currentSpeed = Math.sqrt(
    rectangle.body.velocity.x ** 2 + 
    rectangle.body.velocity.y ** 2
  );

  if (currentSpeed !== 0 && Math.abs(currentSpeed - SPEED) > 1) {
    rectangle.body.velocity.x = (rectangle.body.velocity.x / currentSpeed) * SPEED;
    rectangle.body.velocity.y = (rectangle.body.velocity.y / currentSpeed) * SPEED;
  }
}

new Phaser.Game(config);
```

