[PLAN]
REQ: 实现波次敌人生成系统，每波8个灰色敌人速度200，消灭后等2秒进入下一波并显示波次
API: Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Time.TimerEvent, Phaser.Physics.Arcade.Group
STEPS:
1. 创建物理系统和玩家角色（可移动射击）
2. 创建敌人组，使用Graphics绘制灰色方块作为敌人纹理
3. 实现波次管理系统，每波生成8个敌人，敌人速度200向下移动
4. 实现碰撞检测（子弹击中敌人）和敌人消灭逻辑
5. 当前波敌人全部消灭后，使用TimerEvent延迟2秒生成下一波
6. 显示当前波次文本，暴露wave/enemiesAlive等状态变量用于验证
[/PLAN]

```javascript
class WaveSpawnerScene extends Phaser.Scene {
  constructor() {
    super('WaveSpawnerScene');
    // 可验证的状态变量
    this.wave = 1;
    this.enemiesAlive = 0;
    this.totalEnemiesKilled = 0;
    this.isWaveActive = false;
  }

  preload() {
    // 创建玩家纹理
    const playerGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillRect(-20, -20, 40, 40);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();

    // 创建敌人纹理（灰色）
    const enemyGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    enemyGraphics.fillStyle(0x808080, 1);
    enemyGraphics.fillRect(-15, -15, 30, 30);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();

    // 创建子弹纹理
    const bulletGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillRect(-2, -5, 4, 10);
    bulletGraphics.generateTexture('bullet', 4, 10);
    bulletGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 550, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 30
    });

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();
    this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);
    this.lastFired = 0;

    // 碰撞检测：子弹击中敌人
    this.physics.add.overlap(this.bullets, this.enemies, this.hitEnemy, null, this);

    // 碰撞检测：敌人碰到玩家（游戏结束）
    this.physics.add.overlap(this.player, this.enemies, this.gameOver, null, this);

    // UI文本
    this.waveText = this.add.text(16, 16, `Wave: ${this.wave}`, {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial'
    });

    this.enemiesText = this.add.text(16, 48, `Enemies: ${this.enemiesAlive}`, {
      fontSize: '20px',
      fill: '#ffffff',
      fontFamily: 'Arial'
    });

    this.statusText = this.add.text(16, 80, '', {
      fontSize: '20px',
      fill: '#ffff00',
      fontFamily: 'Arial'
    });

    this.killCountText = this.add.text(16, 112, `Total Killed: ${this.totalEnemiesKilled}`, {
      fontSize: '18px',
      fill: '#00ff00',
      fontFamily: 'Arial'
    });

    // 开始第一波
    this.spawnWave();
  }

  update(time, delta) {
    // 玩家移动
    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-300);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(300);
    } else {
      this.player.setVelocityX(0);
    }

    // 射击
    if (this.spaceKey.isDown && time > this.lastFired + 200) {
      this.shoot();
      this.lastFired = time;
    }

    // 清理出界的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && bullet.y < -10) {
        bullet.setActive(false);
        bullet.setVisible(false);
      }
    });

    // 清理出界的敌人（到达底部）
    this.enemies.children.entries.forEach(enemy => {
      if (enemy.active && enemy.y > 610) {
        enemy.destroy();
        this.enemiesAlive--;
        this.updateUI();
        this.checkWaveComplete();
      }
    });

    // 更新UI
    this.updateUI();
  }

  shoot() {
    const bullet = this.bullets.get(this.player.x, this.player.y - 30);
    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);
      bullet.setVelocityY(-400);
    }
  }

  spawnWave() {
    this.isWaveActive = true;
    this.statusText.setText('');

    // 每波生成8个敌人
    const enemiesPerWave = 8;
    const spacing = 80;
    const startX = 400 - (enemiesPerWave - 1) * spacing / 2;

    for (let i = 0; i < enemiesPerWave; i++) {
      const enemy = this.enemies.create(
        startX + i * spacing,
        50,
        'enemy'
      );

      // 设置敌人速度为200（向下）
      enemy.setVelocityY(200);
      this.enemiesAlive++;
    }

    this.updateUI();
  }

  hitEnemy(bullet, enemy) {
    // 销毁子弹和敌人
    bullet.setActive(false);
    bullet.setVisible(false);
    enemy.destroy();

    this.enemiesAlive--;
    this.totalEnemiesKilled++;

    this.updateUI();
    this.checkWaveComplete();
  }

  checkWaveComplete() {
    // 检查当前波是否完成
    if (this.isWaveActive && this.enemiesAlive === 0) {
      this.isWaveActive = false;
      this.statusText.setText('Wave Complete! Next wave in 2s...');

      // 2秒后开始下一波
      this.time.delayedCall(2000, () => {
        this.wave++;
        this.spawnWave();
      }, [], this);
    }
  }

  updateUI() {
    this.waveText.setText(`Wave: ${this.wave}`);
    this.enemiesText.setText(`Enemies: ${this.enemiesAlive}`);
    this.killCountText.setText(`Total Killed: ${this.totalEnemiesKilled}`);
  }

  gameOver(player, enemy) {
    this.physics.pause();
    this.statusText.setText('GAME OVER!');
    this.statusText.setStyle({ fill: '#ff0000', fontSize: '32px' });
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#000000',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: WaveSpawnerScene
};

// 创建游戏实例
const game = new Phaser.Game(config);

// 暴露状态用于验证
game.getState = function() {
  const scene = game.scene.scenes[0];
  return {
    wave: scene.wave,
    enemiesAlive: scene.enemiesAlive,
    totalEnemiesKilled: scene.totalEnemiesKilled,
    isWaveActive: scene.isWaveActive
  };
};
```

[PLAN]
REQ: 每隔 0.5 秒在随机位置生成橙色菱形，最多 12 个
API: Phaser.Time.Clock#addEvent, Phaser.GameObjects.Graphics, Phaser.Geom.Point
STEPS:
1. 创建 Scene 配置，初始化游戏画布
2. 在 create 中使用 Graphics 绘制菱形形状并生成纹理
3. 使用 TimerEvent 每 0.5 秒触发一次生成逻辑
4. 在回调函数中生成随机坐标，创建菱形精灵
5. 计数器达到 12 个时停止定时器
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

let diamondCount = 0;
const MAX_DIAMONDS = 12;

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制橙色菱形并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xFF8C00, 1); // 橙色

  // 绘制菱形（四个点连接成菱形）
  const size = 30;
  graphics.beginPath();
  graphics.moveTo(size, 0);        // 上顶点
  graphics.lineTo(size * 2, size); // 右顶点
  graphics.lineTo(size, size * 2); // 下顶点
  graphics.lineTo(0, size);        // 左顶点
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('diamond', size * 2, size * 2);
  graphics.destroy();

  // 添加标题文本
  this.add.text(400, 30, 'Orange Diamonds Generator', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  // 添加计数器文本
  const counterText = this.add.text(400, 70, `Diamonds: ${diamondCount}/${MAX_DIAMONDS}`, {
    fontSize: '20px',
    color: '#FFD700'
  }).setOrigin(0.5);

  // 创建定时器事件，每 0.5 秒生成一个菱形
  const timerEvent = this.time.addEvent({
    delay: 500,                    // 0.5 秒 = 500 毫秒
    callback: spawnDiamond,
    callbackScope: this,
    loop: true,
    args: [counterText, timerEvent]
  });

  // 生成菱形的函数
  function spawnDiamond(counterText, timerEvent) {
    if (diamondCount >= MAX_DIAMONDS) {
      // 达到最大数量，停止定时器
      timerEvent.remove();

      // 显示完成消息
      this.add.text(400, 550, 'All diamonds generated!', {
        fontSize: '22px',
        color: '#00FF00'
      }).setOrigin(0.5);

      return;
    }

    // 生成随机位置（避免边缘，留出菱形大小的空间）
    const margin = 40;
    const randomX = Phaser.Math.Between(margin, config.width - margin);
    const randomY = Phaser.Math.Between(120, config.height - margin);

    // 创建菱形精灵
    const diamond = this.add.image(randomX, randomY, 'diamond');

    // 添加简单的缩放动画效果
    diamond.setScale(0);
    this.tweens.add({
      targets: diamond,
      scale: 1,
      duration: 200,
      ease: 'Back.easeOut'
    });

    // 增加计数器
    diamondCount++;

    // 更新计数器文本
    counterText.setText(`Diamonds: ${diamondCount}/${MAX_DIAMONDS}`);
  }
}

// 启动游戏
new Phaser.Game(config);
```

[PLAN]
REQ: 每隔 0.5 秒在随机位置生成绿色星形，最多生成 3 个
API: Phaser.Time.Clock#addEvent, Phaser.GameObjects.Graphics, Phaser.GameObjects.Star, Phaser.Time.TimerEvent
STEPS:
1. 使用 Graphics 绘制绿色星形并生成纹理
2. 在 create 中使用 addEvent 创建定时器，每 0.5 秒触发一次
3. 在定时器回调中生成星形精灵并随机放置位置
4. 记录已生成星形数量，达到 3 个后移除定时器
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 程序化生成绿色星形纹理
  const graphics = this.add.graphics();

  // 绘制绿色星形
  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(2, 0x00aa00, 1);

  // 绘制五角星
  const centerX = 32;
  const centerY = 32;
  const outerRadius = 30;
  const innerRadius = 12;
  const points = 5;

  graphics.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('greenStar', 64, 64);
  graphics.destroy();
}

function create() {
  // 记录已生成的星形数量
  let starCount = 0;
  const maxStars = 3;

  // 创建定时器事件，每 0.5 秒触发一次
  const timerEvent = this.time.addEvent({
    delay: 500, // 0.5 秒 = 500 毫秒
    callback: () => {
      if (starCount < maxStars) {
        // 生成随机位置
        const x = Phaser.Math.Between(50, 750);
