REQ: 实现粉色三角形在4秒内左右往返循环移动的补间动画
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.Tween
STEPS:
1. 创建 Graphics 对象绘制粉色三角形
2. 使用 tweens.add 创建补间动画，设置 x 坐标从左到右移动
3. 配置 duration 为 4000ms，yoyo 为 true 实现往返，repeat 为 -1 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 创建 Graphics 对象绘制粉色三角形
  const graphics = this.add.graphics();

  // 设置粉色填充
  graphics.fillStyle(0xff69b4, 1);

  // 绘制三角形（使用三个顶点）
  graphics.beginPath();
  graphics.moveTo(0, -30);      // 顶点
  graphics.lineTo(-25, 30);     // 左下角
  graphics.lineTo(25, 30);      // 右下角
  graphics.closePath();
  graphics.fillPath();

  // 设置初始位置（左侧，垂直居中）
  graphics.x = 100;
  graphics.y = 300;

  // 创建补间动画：从左到右移动，4秒完成，往返循环
  this.tweens.add({
    targets: graphics,
    x: 700,                    // 目标 x 坐标（右侧）
    duration: 4000,            // 持续时间 4 秒
    yoyo: true,                // 启用往返效果（到达终点后反向返回）
    repeat: -1,                // 无限循环（-1 表示永久重复）
    ease: 'Linear'             // 线性缓动，匀速移动
  });
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央绘制一个蓝色菱形，大小约为 80 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算画布中心点坐标 (400, 300)
4. 使用 beginPath 开始路径绘制
5. 通过 moveTo 和 lineTo 绘制菱形的四个顶点（上下左右各距中心 40 像素）
6. 使用 closePath 闭合路径
7. 设置蓝色填充样式并使用 fillPath 填充菱形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象用于绘制
  const graphics = this.add.graphics();

  // 计算画布中心点
  const centerX = this.cameras.main.width / 2;  // 400
  const centerY = this.cameras.main.height / 2; // 300

  // 菱形大小（从中心到顶点的距离）
  const size = 40;

  // 设置蓝色填充样式
  graphics.fillStyle(0x0000ff, 1);

  // 开始绘制路径
  graphics.beginPath();

  // 绘制菱形的四个顶点（上、右、下、左）
  graphics.moveTo(centerX, centerY - size);        // 上顶点
  graphics.lineTo(centerX + size, centerY);        // 右顶点
  graphics.lineTo(centerX, centerY + size);        // 下顶点
  graphics.lineTo(centerX - size, centerY);        // 左顶点

  // 闭合路径
  graphics.closePath();

  // 填充菱形
  graphics.fillPath();
}

new Phaser.Game(config);
