[PLAN]
REQ: 实现粉色星形平滑跟随鼠标指针移动，跟随速度为360
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 使用 Graphics 绘制粉色星形并生成纹理
2. 创建星形精灵对象并设置初始位置
3. 在 update 中获取鼠标指针位置
4. 计算星形到鼠标的距离和角度
5. 根据速度360和delta时间平滑移动星形朝向鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

function preload() {
  // 创建粉色星形纹理
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // 绘制星形
  const starPoints = [];
  const outerRadius = 40;
  const innerRadius = 20;
  const points = 5;

  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    starPoints.push({
      x: 50 + Math.cos(angle) * radius,
      y: 50 + Math.sin(angle) * radius
    });
  }

  graphics.fillStyle(0xff69b4, 1); // 粉色
  graphics.beginPath();
  graphics.moveTo(starPoints[0].x, starPoints[0].y);
  for (let i = 1; i < starPoints.length; i++) {
    graphics.lineTo(starPoints[i].x, starPoints[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy();
}

function create() {
  // 创建星形精灵
  this.star = this.add.sprite(400, 300, 'star');

  // 存储跟随速度
  this.followSpeed = 360;

  // 添加提示文本
  this.add.text(10, 10, 'Move your mouse!', {
    fontSize: '20px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 获取鼠标指针位置
  const pointer = this.input.activePointer;

  // 计算星形到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    this.star.x,
    this.star.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素，才进行移动（避免抖动）
  if (distance > 1) {
    // 计算角度
    const angle = Phaser.Math.Angle.Between(
      this.star.x,
      this.star.y,
      pointer.x,
      pointer.y
    );

    // 根据速度和时间差计算移动距离
    const moveDistance = this.followSpeed * (delta / 1000);

    // 如果移动距离大于剩余距离，直接到达目标点
    if (moveDistance >= distance) {
      this.star.x = pointer.x;
      this.star.y = pointer.y;
    } else {
      // 平滑移动
      this.star.x += Math.cos(angle) * moveDistance;
      this.star.y += Math.sin(angle) * moveDistance;
    }
  }

  // 可选：让星形旋转增加视觉效果
  this.star.rotation += 0.02;
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现橙色敌人以200速度追踪玩家，玩家速度240可躲避
API: Phaser.Physics.Arcade.Sprite, Phaser.Physics.Arcade.ArcadePhysics#moveToObject, Phaser.Input.Keyboard.createCursorKeys, Phaser.GameObjects.Graphics#generateTexture
STEPS:
1. 创建带物理系统的场景配置
2. 使用Graphics生成玩家（蓝色方块）和敌人（橙色圆形）纹理
3. 在create中创建玩家精灵（速度240）和敌人精灵（速度200）
4. 在update中处理键盘输入控制玩家移动
5. 在update中使用moveToObject让敌人追踪玩家
6. 添加碰撞检测和状态信号（health/score）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态信号变量
let player;
let enemy;
let cursors;
let health = 100;
let score = 0;
let healthText;
let scoreText;
let statusText;

const PLAYER_SPEED = 200 * 1.2; // 240
const ENEMY_SPEED = 200;

function preload() {
  // 创建玩家纹理（蓝色方块）
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x0088ff, 1);
  playerGraphics.fillRect(0, 0, 32, 32);
  playerGraphics.generateTexture('player', 32, 32);
  playerGraphics.destroy();

  // 创建敌人纹理（橙色圆形）
  const enemyGraphics = this.add.graphics();
  enemyGraphics.fillStyle(0xff8800, 1);
  enemyGraphics.fillCircle(20, 20, 20);
  enemyGraphics.generateTexture('enemy', 40, 40);
  enemyGraphics.destroy();
}

function create() {
  // 创建玩家
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(true);

  // 创建敌人
  enemy = this.physics.add.sprite(100, 100, 'enemy');
  enemy.setCollideWorldBounds(true);

  // 设置键盘输入
  cursors = this.input.keyboard.createCursorKeys();

  // 添加WASD键支持
  this.wasd = this.input.keyboard.addKeys({
    up: Phaser.Input.Keyboard.KeyCodes.W,
    down: Phaser.Input.Keyboard.KeyCodes.S,
    left: Phaser.Input.Keyboard.KeyCodes.A,
    right: Phaser.Input.Keyboard.KeyCodes.D
  });

  // 碰撞检测
  this.physics.add.overlap(player, enemy, hitEnemy, null, this);

  // 创建UI文本
  healthText = this.add.text(16, 16, 'Health: 100', {
    fontSize: '20px',
    fill: '#ffffff'
  });

  scoreText = this.add.text(16, 46, 'Score: 0', {
    fontSize: '20px',
    fill: '#ffffff'
  });

  statusText = this.add.text(400, 16, 'Use Arrow Keys or WASD to move. Avoid the orange enemy!', {
    fontSize: '16px',
    fill: '#ffff00'
  });
  statusText.setOrigin(0.5, 0);

  // 添加提示文本
  this.add.text(400, 580, 'Player Speed: 240 | Enemy Speed: 200', {
    fontSize: '14px',
    fill: '#aaaaaa'
  }).setOrigin(0.5, 1);
}

function update(time, delta) {
  // 重置玩家速度
  player.setVelocity(0);

  // 处理玩家移动（方向键）
  if (cursors.left.isDown || this.wasd.left.isDown) {
    player.setVelocityX(-PLAYER_SPEED);
  } else if (cursors.right.isDown || this.wasd.right.isDown) {
    player.setVelocityX(PLAYER_SPEED);
  }

  if (cursors.up.isDown || this.wasd.up.isDown) {
    player.setVelocityY(-PLAYER_SPEED);
  } else if (cursors.down.isDown || this.wasd.down.isDown) {
    player.setVelocityY(PLAYER_SPEED);
  }

  // 对角线移动时归一化速度
  if (player.body.velocity.x !== 0 && player.body.velocity.y !== 0) {
    player.body.velocity.normalize().scale(PLAYER_SPEED);
  }

  // 敌人追踪玩家
  this.physics.moveToObject(enemy, player, ENEMY_SPEED);

  // 每秒增加分数（存活时间）
  if (time % 100 < delta) {
    score += 1;
    scoreText.setText('Score: ' + score);
  }

  // 游戏结束检测
  if (health <= 0) {
    this.physics.pause();
    statusText.setText('GAME OVER! Final Score: ' + score);
    statusText.setStyle({ fill: '#ff0000', fontSize: '24px' });
  }
}

function hitEnemy(player, enemy) {
  // 受到伤害
  health -= 10;
  healthText.setText('Health: ' + health);

  // 击退效果
  const angle = Phaser.Math.Angle.Between(enemy.x, enemy.y, player.x, player.y);
  player.setVelocity(
    Math.cos(angle) * 300,
    Math.sin(angle) * 300
  );

  // 敌人短暂后退
  enemy.setVelocity(
    -Math.cos(angle) * 150,
    -Math.sin(angle) * 150
  );

  // 闪烁效果
  player.setTint(0xff0000);
  this.time.delayedCall(200, () => {
    player.clearTint();
  });

  // 检查游戏结束
  if (health <= 0) {
    health = 0;
    healthText.setText('Health: 0');
  }
}

new Phaser.Game(config);
```

