class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.score = 0;
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 创建分数文本显示在右上角
    // 使用 originX: 1 让文本右对齐
    this.scoreText = this.add.text(780, 20, 'Score: 0', {
