      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
    this.scoreText.setOrigin(1, 0); // 右上角对齐

    // 创建定时器，每 2.5 秒加 8 分
    this.scoreTimer = this.time.addEvent({
      delay: 2500,           // 2.5 秒 = 2500 毫秒
      callback: this.addScore,
      callbackScope: this,
      loop: true             // 循环执行
    });

    // 添加提示信息（可选）
    this.add.text(400, 300, 'Score increases by 8 every 2.5 seconds', {
