    alpha: 1,                  // 目标透明度为 1（完全不透明）
    duration: 1500,            // 持续时间 1.5 秒（1500 毫秒）
    ease: 'Linear',            // 线性缓动
    yoyo: true,                // 往返播放（不透明后再变回透明）
    repeat: -1                 // 无限循环
  });

  // 添加文字说明
  this.add.text(400, 550, 'Circle fading from transparent to opaque (looping)', {
