[PLAN]
REQ: 20个敌人以速度200追踪玩家，玩家需躲避
API: Phaser.Physics.Arcade, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Group, Phaser.Math.Angle.Between
STEPS:
1. 创建物理系统配置，初始化 arcade 物理引擎
2. 使用 Graphics 生成玩家和敌人的纹理（不同颜色区分）
3. 创建玩家精灵，设置键盘控制（WASD/方向键）
4. 创建 20 个敌人的物理组，设置初始随机位置
5. 在 update 中让每个敌人计算朝向玩家的角度并移动
6. 添加碰撞检测，碰到敌人减少生命值
7. 显示生命值和存活时间作为状态信号
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let enemies;
let cursors;
let wasd;
let health = 100;
let survivalTime = 0;
let healthText;
let timeText;
let gameOver = false;
let lastHitTime = 0;

function preload() {
  // 创建玩家纹理（蓝色方块）
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x00aaff, 1);
  playerGraphics.fillCircle(16, 16, 16);
  playerGraphics.generateTexture('player', 32, 32);
  playerGraphics.destroy();

  // 创建敌人纹理（红色方块）
  const enemyGraphics = this.add.graphics();
  enemyGraphics.fillStyle(0xff0000, 1);
  enemyGraphics.fillCircle(12, 12, 12);
  enemyGraphics.generateTexture('enemy', 24, 24);
  enemyGraphics.destroy();
}

function create() {
  // 创建玩家
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(true);
  player.setDrag(500);
  player.setMaxVelocity(300);

  // 创建敌人组
  enemies = this.physics.add.group({
    key: 'enemy',
    repeat: 19, // 创建20个敌人
    setXY: {
      x: Phaser.Math.Between(50, 750),
      y: Phaser.Math.Between(50, 550),
      stepX: 0,
      stepY: 0
    }
  });

  // 随机分散敌人位置
  enemies.children.iterate((enemy) => {
    enemy.setPosition(
      Phaser.Math.Between(50, 750),
      Phaser.Math.Between(50, 550)
    );
    enemy.setCollideWorldBounds(true);
    enemy.setBounce(0.5);
  });

  // 设置碰撞检测
  this.physics.add.overlap(player, enemies, hitEnemy, null, this);

  // 键盘控制
  cursors = this.input.keyboard.createCursorKeys();
  wasd = this.input.keyboard.addKeys({
    up: Phaser.Input.Keyboard.KeyCodes.W,
    down: Phaser.Input.Keyboard.KeyCodes.S,
    left: Phaser.Input.Keyboard.KeyCodes.A,
    right: Phaser.Input.Keyboard.KeyCodes.D
  });

  // UI 文本
  healthText = this.add.text(16, 16, 'Health: 100', {
    fontSize: '20px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  timeText = this.add.text(16, 50, 'Time: 0s', {
    fontSize: '20px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 添加说明文本
  this.add.text(400, 16, 'Use Arrow Keys or WASD to move. Avoid the red enemies!', {
    fontSize: '16px',
    fill: '#ffff00',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  }).setOrigin(0.5, 0);
}

function update(time, delta) {
  if (gameOver) {
    return;
  }

  // 更新存活时间
  survivalTime += delta / 1000;
  timeText.setText('Time: ' + survivalTime.toFixed(1) + 's');

  // 玩家移动控制
  const acceleration = 600;

  if (cursors.left.isDown || wasd.left.isDown) {
    player.setAccelerationX(-acceleration);
  } else if (cursors.right.isDown || wasd.right.isDown) {
    player.setAccelerationX(acceleration);
  } else {
    player.setAccelerationX(0);
  }

  if (cursors.up.isDown || wasd.up.isDown) {
    player.setAccelerationY(-acceleration);
  } else if (cursors.down.isDown || wasd.down.isDown) {
    player.setAccelerationY(acceleration);
  } else {
    player.setAccelerationY(0);
  }

  // 敌人追踪玩家
  enemies.children.iterate((enemy) => {
    if (enemy.active) {
      // 计算敌人到玩家的角度
      const angle = Phaser.Math.Angle.Between(
        enemy.x,
        enemy.y,
        player.x,
        player.y
      );

      // 设置敌人速度，朝向玩家移动
      const speed = 200;
      enemy.setVelocity(
        Math.cos(angle) * speed,
        Math.sin(angle) * speed
      );

      // 旋转敌人朝向玩家
      enemy.rotation = angle;
    }
  });

  // 检查游戏结束
  if (health <= 0 && !gameOver) {
    gameOver = true;
    player.setTint(0x888888);
    player.setVelocity(0, 0);
    player.setAcceleration(0, 0);

    enemies.children.iterate((enemy) => {
      enemy.setVelocity(0, 0);
    });

    const gameOverText = this.add.text(400, 300, 'GAME OVER\nSurvived: ' + survivalTime.toFixed(1) + 's', {
      fontSize: '48px',
      fill: '#ff0000',
      backgroundColor: '#000000',
      padding: { x: 20, y: 10 },
      align: 'center'
    });
    gameOverText.setOrigin(0.5);
  }
}

function hitEnemy(player, enemy) {
  const currentTime = Date.now();

  // 添加无敌时间（0.5秒），避免连续扣血
  if (currentTime - lastHitTime > 500) {
    health -= 10;
    lastHitTime = currentTime;

    // 更新生命值显示
    healthText.setText('Health: ' + Math.max(0, health));

    // 玩家受击闪烁效果
    player.setTint(0xff0000);
    player.scene.time.delayedCall(100, () => {
      if (!gameOver) {
        player.clearTint();
      }
    });

    // 击退效果
    const angle = Phaser.Math.Angle.Between(
      enemy.x,
      enemy.y,
      player.x,
      player.y
    );
    player.setVelocity(
      Math.cos(angle) * 400,
      Math.sin(angle) * 400
    );
  }
}

const game = new Phaser.Game(config);
```

[PLAN]
REQ: 记录玩家2秒内的键盘/鼠标操作序列，按鼠标左键开始回放，支持可调速度回放
API: Scene, Input.Keyboard, Input.Mouse, Graphics, Text, Time.Clock
STEPS:
1. 创建一个可移动的玩家方块，使用WASD键控制移动
2. 记录2秒内的所有操作（键盘按键状态和时间戳）
3. 2秒后停止记录，显示提示等待鼠标左键开始回放
4. 回放时按照记录的时间戳和操作重现玩家移动
5. 提供速度调节UI（1x, 2x, 0.5x），使用数字键1/2/3切换
6. 显示当前状态（录制中/等待回放/回放中）和回放进度
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 全局状态变量
let player;
let graphics;
let statusText;
let instructionText;
let speedText;
let progressText;

// 录制相关
let recordingStartTime = 0;
let recordingDuration = 2000; // 2秒
let isRecording = false;
let isWaitingForReplay = false;
let isReplaying = false;

// 操作记录
let actionLog = [];
let replayStartTime = 0;
let replaySpeed = 1.0; // 回放速度倍率
let currentReplayIndex = 0;

// 玩家状态
let playerSpeed = 200;
let playerX = 400;
let playerY = 300;

// 键盘输入
let keys = {};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建玩家方块（使用Graphics）
  graphics = this.add.graphics();
  drawPlayer(playerX, playerY);

  // 创建UI文本
  statusText = this.add.text(10, 10, '', {
    fontSize: '24px',
    color: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  instructionText = this.add.text(10, 50, 
    'WASD: 移动 | 录制2秒后点击鼠标左键回放\n数字键 1/2/3: 切换速度 (1x/2x/0.5x)', {
    fontSize: '16px',
    color: '#ffff00',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  speedText = this.add.text(10, 120, '', {
    fontSize: '18px',
    color: '#00ff00',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  progressText = this.add.text(10, 160, '', {
    fontSize: '18px',
    color: '#00ffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 设置键盘输入
  keys.W = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W);
  keys.A = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A);
  keys.S = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S);
  keys.D = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D);

  // 速度切换键
  keys.ONE = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.ONE);
  keys.TWO = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.TWO);
  keys.THREE = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.THREE);

  // 鼠标点击事件
  this.input.on('pointerdown', (pointer) => {
    if (pointer.leftButtonDown() && isWaitingForReplay) {
      startReplay(this);
    }
  });

  // 开始录制
  startRecording(this);
}

function update(time, delta) {
  // 处理速度切换
  if (Phaser.Input.Keyboard.JustDown(keys.ONE)) {
    replaySpeed = 1.0;
  } else if (Phaser.Input.Keyboard.JustDown(keys.TWO)) {
    replaySpeed = 2.0;
  } else if (Phaser.Input.Keyboard.JustDown(keys.THREE)) {
    replaySpeed = 0.5;
  }

  speedText.setText(`回放速度: ${replaySpeed}x`);

  if (isRecording) {
    // 录制阶段
    const elapsed = time - recordingStartTime;

    if (elapsed >= recordingDuration) {
      // 录制结束
      stopRecording();
    } else {
      // 记录当前操作
      recordActions(time, delta);
      // 更新玩家位置
      updatePlayerPosition(delta);

      const remaining = ((recordingDuration - elapsed) / 1000).toFixed(1);
      statusText.setText(`录制中... 剩余: ${remaining}秒`);
      progressText.setText(`已记录操作: ${actionLog.length} 条`);
    }
  } else if (isReplaying) {
    // 回放阶段
    replayActions(time);

    const progress = ((currentReplayIndex / actionLog.length) * 100).toFixed(0);
    statusText.setText(`回放中... 进度: ${progress}%`);
    progressText.setText(`操作 ${currentReplayIndex}/${actionLog.length}`);
  } else if (isWaitingForReplay) {
    statusText.setText('录制完成！点击鼠标左键开始回放');
    progressText.setText(`已记录 ${actionLog.length} 条操作`);
  }

  // 重绘玩家
  drawPlayer(playerX, playerY);
}

function startRecording(scene) {
  isRecording = true;
  isWaitingForReplay = false;
  isReplaying = false;
  recordingStartTime = scene.time.now;
  actionLog = [];

  // 重置玩家位置
  playerX = 400;
  playerY = 300;
}

function recordActions(time, delta) {
  // 记录当前时间戳和按键状态
  const action = {
    timestamp: time - recordingStartTime,
    keys: {
      W: keys.W.isDown,
      A: keys.A.isDown,
      S: keys.S.isDown,
      D: keys.D.isDown
    },
    delta: delta
  };

  actionLog.push(action);
}

function updatePlayerPosition(delta) {
  const moveDistance = (playerSpeed * delta) / 1000;

  if (keys.W.isDown) {
    playerY -= moveDistance;
  }
  if (keys.S.isDown) {
    playerY += moveDistance;
  }
  if (keys.A.isDown) {
    playerX -= moveDistance;
  }
  if (keys.D.isDown) {
    playerX += moveDistance;
  }

  // 边界限制
  playerX = Phaser.Math.Clamp(playerX, 25, 775);
  playerY = Phaser.Math.Clamp(playerY, 25, 575);
}

function stopRecording() {
  isRecording = false;
  isWaitingForReplay = true;
}

function startReplay(scene) {
  isWaitingForReplay = false;
  isReplaying = true;
  replayStartTime = scene.time.now;
  currentReplayIndex = 0;

  // 重置玩家位置到起始点
  playerX = 400;
  playerY = 300;
}

function replayActions(time) {
  if (currentReplayIndex >= actionLog.length) {
    // 回放结束，重新开始录制
    isReplaying = false;
    const scene = game.scene.scenes[0];
    startRecording(scene);
    return;
  }

  const elapsed = (time - replayStartTime) * replaySpeed;

  // 播放所有应该在当前时间之前的操作
  while (currentReplayIndex < actionLog.length) {
    const action = actionLog[currentReplayIndex];

    if (action.timestamp > elapsed) {
      break;
    }

    // 根据记录的按键状态更新位置
    const adjustedDelta = action.delta * replaySpeed;
    const moveDistance = (playerSpeed * adjustedDelta) / 1000;

    if (action.keys.W) {
      playerY -= moveDistance;
    }
    if (action.keys.S) {
      playerY += moveDistance;
    }
    if (action.keys.A) {
      playerX -= moveDistance;
    }
    if (action.keys.D) {
      playerX += moveDistance;
    }

    // 边界限制
    playerX = Phaser.Math.Clamp(playerX, 25, 775);
    playerY = Phaser.Math.Clamp(playerY, 25, 575);

    currentReplayIndex++;
  }
}

function drawPlayer(x, y) {
  graphics.clear();

  // 绘制玩家方块
  if (isRecording) {
    graphics.fillStyle(0x00ff00, 1); // 绿色 - 录制中
  } else if (isReplaying) {
    graphics.fillStyle(0xff0000, 1); // 红色 - 回放中
  } else {
    graphics.fillStyle(0xffff00, 1); // 黄色 - 等待中
  }

  graphics.fillRect(x - 25, y - 25, 50, 50);

  // 绘制方向指示器
  graphics.fillStyle(0xffffff, 1);
  graphics.fillCircle(x, y - 15, 5);
}

const game = new Phaser.Game(config);
```

