    // 发射速度（每秒发射的粒子数）
    frequency: 100,

    // 粒子生命周期（毫秒）
    lifespan: 2000,

    // 粒子速度范围
    speed: { min: 100, max: 200 },

    // 粒子发射角度（360度全方向）
    angle: { min: 0, max: 360 },

