  );
  graphicsBlue.generateTexture('blueTriangle', 70, 80);
  graphicsBlue.destroy();

  // 创建三角形精灵
  const triangle = this.add.sprite(initialX, initialY, 'redTriangle');

  // 设置为可交互和可拖拽
