      padding: { x: 10, y: 5 }
    });
    this.killText.setScrollFactor(0);
    this.killText.setDepth(100);

    // 添加提示文本
    this.add.text(400, 550, 'Press WASD to shoot bullets', {
      fontSize: '18px',
      fill: '#ffffff'
    }).setOrigin(0.5);
  }

  spawnEnemy() {
    // 随机位置生成敌人（避免在中心区域）
    let x, y;
    const side = Phaser.Math.Between(0, 3);

    switch(side) {
      case 0: // 上边
        x = Phaser.Math.Between(50, 750);
        y = 50;
        break;
      case 1: // 右边
        x = 750;
        y = Phaser.Math.Between(50, 550);
        break;
      case 2: // 下边
        x = Phaser.Math.Between(50, 750);
        y = 550;
        break;
      case 3: // 左边
        x = 50;
        y = Phaser.Math.Between(50, 550);
        break;
    }

    const enemy = this.enemies.create(x, y, 'enemy');
    enemy.setVelocity(
      Phaser.Math.Between(-50, 50),
      Phaser.Math.Between(-50, 50)
    );
    enemy.setBounce(1);
    enemy.setCollideWorldBounds(true);
  }

  shootBullet(dirX, dirY) {
    // 从对象池获取或创建子弹
    const bullet = this.bullets.get(this.player.x, this.player.y, 'bullet');

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 设置子弹速度（速度200）
      bullet.setVelocity(dirX * 200, dirY * 200);

      // 子弹超出边界时销毁
      this.time.delayedCall(3000, () => {
        if (bullet.active) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      });
    }
  }

  hitEnemy(bullet, enemy) {
    // 销毁子弹和敌人
    bullet.setActive(false);
    bullet.setVisible(false);
    enemy.destroy();

    // 增加击杀数
    this.killCount++;
    this.killText.setText('Kills: ' + this.killCount);

    // 播放简单的击中效果
    const flash = this.add.graphics();
    flash.fillStyle(0xffffff, 0.8);
    flash.fillCircle(enemy.x, enemy.y, 20);
    this.tweens.add({
      targets: flash,
      alpha: 0,
      duration: 200,
      onComplete: () => flash.destroy()
    });
  }

  update(time, delta) {
    // 清理超出边界的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && (
        bullet.x < 0 || bullet.x > 800 ||
        bullet.y < 0 || bullet.y > 600
      )) {
        bullet.setActive(false);
        bullet.setVisible(false);
      }
    });
  }
}

