    duration: 1500,              // 动画时长 1.5 秒
    ease: 'Linear',              // 线性缓动
    yoyo: false,                 // 不使用来回效果
    repeat: -1,                  // 无限循环
    repeatDelay: 0,              // 重复间隔为 0
    onRepeat: function() {
      // 每次重复时重置透明度为 0
      graphics.setAlpha(0);
    }
  });

  // 添加文字说明
  this.add.text(400, 500, '椭圆透明度循环渐变动画', {
    fontSize: '24px',
    color: '#ffffff'
