    const square = this.add.image(pointer.x, pointer.y, 'whiteSquare');

    // 可选：添加一些视觉反馈
    this.tweens.add({
      targets: square,
      scale: { from: 0, to: 1 },
      duration: 200,
      ease: 'Back.easeOut'
    });
  });

  // 添加提示文字
  this.add.text(400, 300, 'Click anywhere to create white squares', {
    fontSize: '20px',
    color: '#ffffff',
    align: 'center'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
