REQ: 在随机位置绘制12个黄色菱形，每个大小为48像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.fillPath, Graphics.setPosition, Phaser.Geom.Polygon
STEPS:
1. 创建 Phaser Game 配置，使用 800x600 画布
2. 在 create 方法中循环12次
3. 每次循环创建一个 Graphics 对象
4. 使用 fillPath 和 Polygon 绘制菱形（4个顶点：上、右、下、左）
5. 为每个菱形设置随机位置（考虑边界，避免超出画布）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 菱形大小
  const diamondSize = 48;
  const halfSize = diamondSize / 2;

  // 绘制12个随机位置的黄色菱形
  for (let i = 0; i < 12; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置黄色填充
    graphics.fillStyle(0xffff00, 1);

    // 定义菱形的4个顶点（相对于中心点）
    // 上、右、下、左
    const diamond = new Phaser.Geom.Polygon([
      0, -halfSize,      // 上顶点
      halfSize, 0,       // 右顶点
      0, halfSize,       // 下顶点
      -halfSize, 0       // 左顶点
    ]);

    // 填充菱形路径
    graphics.fillPoints(diamond.points, true);

    // 设置随机位置（考虑边界，留出菱形大小的边距）
    const randomX = Phaser.Math.Between(halfSize, 800 - halfSize);
    const randomY = Phaser.Math.Between(halfSize, 600 - halfSize);
    graphics.setPosition(randomX, randomY);
  }
}

new Phaser.Game(config);
```

