2. 创建一个 Sprite 使用该纹理
3. 使用 Tween 动画设置缩放属性，从 1 到 0.24，yoyo 模式返回，循环播放
4. 设置 Tween 持续时间为 1000ms（1秒），yoyo 为 true，loop 为 -1（无限循环）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制圆形并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1); // 绿色圆形
  graphics.fillCircle(50, 50, 50); // 中心点 (50, 50)，半径 50
  graphics.generateTexture('circle', 100, 100);
  graphics.destroy(); // 生成纹理后销毁 graphics 对象

  // 在屏幕中心创建圆形精灵
  const circle = this.add.sprite(400, 300, 'circle');

  // 创建缩放 Tween 动画
  this.tweens.add({
