    scaleY: 0.24,             // Y 轴缩放到 24%
    duration: 1000,           // 持续时间 1 秒
    yoyo: true,               // 动画结束后反向播放（恢复到原始大小）
    loop: -1,                 // 无限循环（-1 表示永远循环）
    ease: 'Linear'            // 线性缓动
  });

  // 添加文本说明
  this.add.text(400, 50, '圆形缩放动画（1秒缩放到24%，然后恢复，循环播放）', {
