[PLAN]
REQ: 实现可拖拽的白色星形，拖拽时变色，松手后回到初始位置
API: Graphics.fillStyle, Graphics.fillStar, setInteractive, on('drag'), on('dragstart'), on('dragend')
STEPS:
1. 使用 Graphics 绘制白色星形并生成纹理
2. 创建 Sprite 并启用拖拽交互
3. 监听 dragstart 事件改变颜色为黄色
4. 监听 drag 事件更新星形位置
5. 监听 dragend 事件恢复白色并回到初始位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 记录星形初始位置
  const initialX = 400;
  const initialY = 300;

  // 使用 Graphics 绘制白色星形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);
  graphics.fillStar(50, 50, 5, 25, 50, 0);
  graphics.generateTexture('whiteStar', 100, 100);
  graphics.destroy();

  // 创建黄色星形纹理（用于拖拽时）
  const graphicsYellow = this.add.graphics();
  graphicsYellow.fillStyle(0xffff00, 1);
  graphicsYellow.fillStar(50, 50, 5, 25, 50, 0);
  graphicsYellow.generateTexture('yellowStar', 100, 100);
  graphicsYellow.destroy();

  // 创建星形精灵
  const star = this.add.sprite(initialX, initialY, 'whiteStar');

  // 启用交互和拖拽
  star.setInteractive({ draggable: true });

  // 监听拖拽开始事件 - 改变颜色
  this.input.on('dragstart', (pointer, gameObject) => {
    gameObject.setTexture('yellowStar');
    // 可选：添加缩放效果
    gameObject.setScale(1.1);
  });

  // 监听拖拽事件 - 更新位置
  this.input.on('drag', (pointer, gameObject, dragX, dragY) => {
    gameObject.x = dragX;
    gameObject.y = dragY;
  });

  // 监听拖拽结束事件 - 恢复颜色和位置
  this.input.on('dragend', (pointer, gameObject) => {
    // 恢复白色纹理
    gameObject.setTexture('whiteStar');
    // 恢复原始缩放
    gameObject.setScale(1);

    // 使用补间动画平滑回到初始位置
    this.tweens.add({
      targets: gameObject,
      x: initialX,
      y: initialY,
      duration: 300,
      ease: 'Back.easeOut'
    });
  });

  // 添加提示文本
  const text = this.add.text(400, 50, '拖拽星形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  });
  text.setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 使用 WASD 键控制六边形以 80 像素/秒的速度移动
API: Phaser.GameObjects.Graphics, Phaser.Input.Keyboard.KeyCodes, Scene.input.keyboard.addKey
STEPS:
1. 创建 Scene 并配置 Game
2. 使用 Graphics 绘制六边形并生成纹理
3. 创建 Sprite 使用六边形纹理
4. 添加 WASD 键盘输入监听
5. 在 update 中根据按键状态移动六边形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let hexagon;
let cursors;
const SPEED = 80;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(2, 0xffffff, 1);

  // 绘制六边形（中心点在 32, 32）
  const hexRadius = 30;
  const hexPoints = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i;
    const x = 32 + hexRadius * Math.cos(angle);
    const y = 32 + hexRadius * Math.sin(angle);
    hexPoints.push(x, y);
  }

  graphics.beginPath();
  graphics.moveTo(hexPoints[0], hexPoints[1]);
  for (let i = 2; i < hexPoints.length; i += 2) {
    graphics.lineTo(hexPoints[i], hexPoints[i + 1]);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 64, 64);
  graphics.destroy();

  // 创建六边形精灵，放置在屏幕中央
  hexagon = this.add.sprite(400, 300, 'hexagon');

  // 添加 WASD 键盘输入
  cursors = {
    w: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W),
    a: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A),
    s: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S),
    d: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D)
  };

  // 添加提示文本
  this.add.text(10, 10, 'Use WASD to move the hexagon', {
    fontSize: '18px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 计算移动距离（速度 * 时间）
  const distance = SPEED * (delta / 1000);

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 检查 WASD 键状态并设置移动方向
  if (cursors.w.isDown) {
    velocityY = -1;
  } else if (cursors.s.isDown) {
    velocityY = 1;
  }

  if (cursors.a.isDown) {
    velocityX = -1;
  } else if (cursors.d.isDown) {
    velocityX = 1;
  }

  // 归一化对角线移动速度（避免对角线移动过快）
  if (velocityX !== 0 && velocityY !== 0) {
    const normalizer = Math.sqrt(2);
    velocityX /= normalizer;
    velocityY /= normalizer;
  }

  // 应用移动
  hexagon.x += velocityX * distance;
  hexagon.y += velocityY * distance;

  // 边界限制（可选）
  hexagon.x = Phaser.Math.Clamp(hexagon.x, 0, 800);
  hexagon.y = Phaser.Math.Clamp(hexagon.y, 0, 600);
}

new Phaser.Game(config);
```

