REQ: 在画布中央绘制一个黄色六边形，大小约为 80 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算六边形的 6 个顶点坐标（中心点在画布中央，半径为 40 像素）
4. 使用 Graphics API 绘制六边形路径并填充黄色
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置填充颜色为黄色
  graphics.fillStyle(0xffff00, 1);

  // 画布中心点
  const centerX = 400;
  const centerY = 300;

  // 六边形半径（从中心到顶点的距离）
  const radius = 40;

  // 开始绘制路径
  graphics.beginPath();

  // 计算并绘制六边形的 6 个顶点
  // 六边形的顶点角度间隔为 60 度（Math.PI / 3）
  // 从顶部开始（-90 度或 -Math.PI / 2）
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i - (Math.PI / 2);
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

