[PLAN]
REQ: 实现鼠标右键发射橙色子弹，子弹速度160，离开边界自动回收到对象池
API: Phaser.Physics.Arcade.Group, Phaser.Input.Events.POINTER_DOWN, Graphics.generateTexture, Group.get, Group.killAndHide
STEPS:
1. 创建物理引擎配置，启用 arcade 物理系统
2. 使用 Graphics 绘制橙色圆形作为子弹纹理
3. 创建物理组作为子弹对象池，配置自动回收机制
4. 监听鼠标右键点击事件（pointerdown + button === 2）
5. 发射子弹时从对象池获取，设置位置和速度
6. 在 update 中检查子弹边界，超出边界则回收
7. 添加 bulletsFired 状态变量用于验证
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态变量
let bulletsFired = 0;
let activeBullets = 0;
let bulletsGroup;
let infoText;

function preload() {
  // 创建橙色子弹纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xff8800, 1); // 橙色
  graphics.fillCircle(8, 8, 8); // 圆形子弹，半径8
  graphics.generateTexture('bullet', 16, 16);
  graphics.destroy();
}

function create() {
  // 创建子弹对象池（使用物理组）
  bulletsGroup = this.physics.add.group({
    defaultKey: 'bullet',
    maxSize: 50, // 对象池最大容量
    runChildUpdate: false,
    createCallback: function(bullet) {
      // 初始化子弹时的回调
      bullet.setActive(false);
      bullet.setVisible(false);
    }
  });

  // 监听鼠标右键点击事件
  this.input.on('pointerdown', (pointer) => {
    // 检查是否为右键（button === 2）
    if (pointer.rightButtonDown()) {
      fireBullet.call(this, pointer.x, pointer.y);
    }
  });

  // 显示信息文本
  infoText = this.add.text(10, 10, '', {
    fontSize: '16px',
    fill: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 添加提示文本
  this.add.text(400, 300, '右键点击发射橙色子弹', {
    fontSize: '24px',
    fill: '#ff8800'
  }).setOrigin(0.5);

  updateInfoText();
}

function update(time, delta) {
  // 检查所有活跃的子弹
  const bullets = bulletsGroup.getChildren();
  activeBullets = 0;

  bullets.forEach((bullet) => {
    if (bullet.active) {
      activeBullets++;

      // 检查子弹是否离开边界
      if (bullet.x < -20 || bullet.x > 820 || 
          bullet.y < -20 || bullet.y > 620) {
        // 回收子弹到对象池
        bulletsGroup.killAndHide(bullet);
        bullet.setActive(false);
        bullet.body.stop();
      }
    }
  });

  updateInfoText();
}

function fireBullet(targetX, targetY) {
  // 从对象池获取子弹（如果池中没有可用对象，会自动创建新的）
  const bullet = bulletsGroup.get(400, 300);

  if (bullet) {
    // 激活子弹
    bullet.setActive(true);
    bullet.setVisible(true);

    // 设置子弹位置（从屏幕中心发射）
    bullet.setPosition(400, 300);

    // 计算发射方向
    const angle = Phaser.Math.Angle.Between(400, 300, targetX, targetY);

    // 设置子弹速度（速度为160）
    const velocityX = Math.cos(angle) * 160;
    const velocityY = Math.sin(angle) * 160;
    bullet.setVelocity(velocityX, velocityY);

    // 旋转子弹朝向目标方向
    bullet.setRotation(angle);

    // 增加发射计数
    bulletsFired++;
  }
}

function updateInfoText() {
  infoText.setText([
    `总发射数: ${bulletsFired}`,
    `活跃子弹: ${activeBullets}`,
    `对象池大小: ${bulletsGroup.getLength()}`,
    `提示: 右键点击发射子弹`
  ]);
}

// 启动游戏
new Phaser.Game(config);
```

[PLAN]
REQ: 实现鼠标点击发射子弹射击敌人，命中后敌人消失并显示击杀数
API: Phaser.Physics.Arcade.Group, Phaser.Input.Pointer, Phaser.Physics.Arcade.World#overlap, Phaser.GameObjects.Text, Phaser.GameObjects.Graphics
STEPS:
1. 创建玩家飞船和敌人群组，使用 Graphics 绘制形状
2. 监听鼠标点击事件，创建子弹并设置速度为 160
3. 使用物理碰撞检测子弹与敌人的重叠
4. 命中时销毁敌人和子弹，增加击杀计数
5. 在屏幕上显示击杀数文本
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.killCount = 0; // 可验证的状态信号
  }

  preload() {
    // 使用 Graphics 创建纹理，无需外部资源
  }

  create() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillTriangle(0, -20, -15, 15, 15, 15);
    playerGraphics.generateTexture('player', 30, 35);
    playerGraphics.destroy();

    // 创建子弹纹理
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(0, 0, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();

    // 创建敌人纹理
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillRect(-15, -15, 30, 30);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 50
    });

    // 创建敌人组
    this.enemies = this.physics.add.group({
      defaultKey: 'enemy'
    });

    // 生成初始敌人
    this.spawnEnemies();

    // 定时生成敌人
    this.time.addEvent({
      delay: 2000,
      callback: this.spawnEnemies,
      callbackScope: this,
      loop: true
    });

    // 监听鼠标点击事件
    this.input.on('pointerdown', this.shootBullet, this);

    // 设置子弹与敌人的碰撞检测
    this.physics.add.overlap(
      this.bullets,
      this.enemies,
      this.hitEnemy,
      null,
      this
    );

    // 显示击杀数文本
    this.killText = this.add.text(16, 16, 'Kills: 0', {
      fontSize: '32px',
      fill: '#ffffff',
      fontFamily: 'Arial'
    });
    this.killText.setDepth(100);

    // 添加提示文本
    this.add.text(400, 50, 'Click to Shoot!', {
      fontSize: '24px',
      fill: '#ffff00',
      fontFamily: 'Arial'
    }).setOrigin(0.5);
  }

  spawnEnemies() {
    // 随机生成 3-5 个敌人
    const count = Phaser.Math.Between(3, 5);
    for (let i = 0; i < count; i++) {
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 250);

      const enemy = this.enemies.create(x, y, 'enemy');
      enemy.setVelocity(
        Phaser.Math.Between(-50, 50),
        Phaser.Math.Between(20, 60)
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }
  }

  shootBullet(pointer) {
    // 从玩家位置发射子弹
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 计算子弹朝向鼠标点击位置的方向
      const angle = Phaser.Math.Angle.Between(
        this.player.x,
        this.player.y,
        pointer.x,
        pointer.y
      );

      // 设置子弹速度为 160
      this.physics.velocityFromRotation(angle, 160, bullet.body.velocity);

      // 子弹超出屏幕后自动销毁
      this.time.delayedCall(3000, () => {
        if (bullet.active) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      });
    }
  }

  hitEnemy(bullet, enemy) {
    // 销毁子弹和敌人
    bullet.setActive(false);
    bullet.setVisible(false);
    enemy.destroy();

    // 增加击杀计数
    this.killCount++;
    this.killText.setText('Kills: ' + this.killCount);

    // 添加击中特效
    const hitEffect = this.add.graphics();
    hitEffect.fillStyle(0xffffff, 0.8);
    hitEffect.fillCircle(enemy.x, enemy.y, 20);

    this.tweens.add({
      targets: hitEffect,
      alpha: 0,
      scale: 2,
      duration: 300,
      onComplete: () => hitEffect.destroy()
    });
  }

  update(time, delta) {
    // 移除超出屏幕的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && (
        bullet.y < -10 || bullet.y > 610 ||
        bullet.x < -10 || bullet.x > 810
      )) {
        bullet.setActive(false);
        bullet.setVisible(false);
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#1a1a2e',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

