REQ: 实现可拖拽的蓝色方块，拖拽时变色，松手后回到初始位置
API: Graphics.fillRect, GameObject.setInteractive, Input.setDraggable, DRAG_START, DRAG_END
STEPS:
1. 使用 Graphics 创建蓝色方块纹理
2. 创建 Sprite 并设置为可交互和可拖拽
3. 监听 DRAG_START 事件改变方块颜色为红色
4. 监听 DRAG 事件更新方块位置
5. 监听 DRAG_END 事件恢复蓝色并回到初始位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 创建蓝色方块纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x0000ff, 1);
  graphics.fillRect(0, 0, 100, 100);
  graphics.generateTexture('blueBox', 100, 100);
  graphics.destroy();

  // 创建红色方块纹理（拖拽时使用）
  const redGraphics = this.add.graphics();
  redGraphics.fillStyle(0xff0000, 1);
  redGraphics.fillRect(0, 0, 100, 100);
  redGraphics.generateTexture('redBox', 100, 100);
  redGraphics.destroy();
}

function create() {
  // 记录初始位置
  const initialX = 400;
  const initialY = 300;

  // 创建可拖拽的方块
  const box = this.add.sprite(initialX, initialY, 'blueBox');

  // 设置为可交互和可拖拽
  box.setInteractive({ draggable: true });

  // 添加提示文本
  const text = this.add.text(400, 100, '拖拽蓝色方块试试！', {
    fontSize: '24px',
    color: '#ffffff'
  });
  text.setOrigin(0.5);

  // 监听拖拽开始事件 - 改变颜色为红色
  box.on('dragstart', function(pointer) {
    this.setTexture('redBox');
  });

  // 监听拖拽事件 - 更新位置
  box.on('drag', function(pointer, dragX, dragY) {
    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件 - 恢复蓝色并回到初始位置
  box.on('dragend', function(pointer) {
    this.setTexture('blueBox');

    // 使用补间动画平滑回到初始位置
    this.scene.tweens.add({
      targets: this,
      x: initialX,
      y: initialY,
      duration: 300,
      ease: 'Back.easeOut'
    });
  });
}

new Phaser.Game(config);
