let rotatingContainer;
const ROTATION_SPEED = Phaser.Math.DegToRad(160); // 每秒 160 度转换为弧度

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 创建一个容器用于旋转
  rotatingContainer = this.add.container(400, 300);

