REQ: 每3秒从顶部随机位置生成灰色下落障碍物，速度160
API: Phaser.Time.Clock#addEvent, Phaser.Physics.Arcade.Sprite, Phaser.GameObjects.Graphics#generateTexture, Phaser.Physics.Arcade.Group
STEPS:
1. 创建物理系统配置，启用 arcade 物理引擎
2. 在 create 中使用 Graphics 生成灰色障碍物纹理
3. 创建物理组管理障碍物
4. 使用 TimerEvent 每3秒触发一次生成逻辑
5. 生成时在顶部随机 x 位置创建障碍物，设置向下速度160
6. 添加状态变量记录生成的障碍物数量作为验证信号
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态信号变量
let obstacleCount = 0;
let obstaclesGroup;
let spawnTimer;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 生成灰色障碍物纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1); // 灰色
  graphics.fillRect(0, 0, 40, 40); // 40x40 的方块
  graphics.generateTexture('obstacle', 40, 40);
  graphics.destroy();

  // 创建物理组来管理障碍物
  obstaclesGroup = this.physics.add.group({
    defaultKey: 'obstacle',
    maxSize: 50 // 限制最大数量
  });

  // 创建定时器，每3秒生成一个障碍物
  spawnTimer = this.time.addEvent({
    delay: 3000, // 3秒 = 3000毫秒
    callback: spawnObstacle,
    callbackScope: this,
    loop: true // 循环执行
  });

  // 添加文本显示障碍物数量（用于验证）
  this.obstacleText = this.add.text(16, 16, 'Obstacles: 0', {
    fontSize: '24px',
    fill: '#ffffff'
  });

  // 立即生成第一个障碍物（可选）
  spawnObstacle.call(this);
}

function spawnObstacle() {
  // 在顶部随机 x 位置生成障碍物
  const randomX = Phaser.Math.Between(40, 760); // 留出边界空间
  const obstacle = obstaclesGroup.get(randomX, -40);

  if (obstacle) {
    obstacle.setActive(true);
    obstacle.setVisible(true);

    // 设置向下速度为 160
    obstacle.setVelocityY(160);

    // 更新计数
    obstacleCount++;

    // 更新显示文本
    if (this.obstacleText) {
      this.obstacleText.setText('Obstacles: ' + obstacleCount);
    }
  }
}

function update(time, delta) {
  // 清理超出屏幕底部的障碍物
  obstaclesGroup.children.entries.forEach((obstacle) => {
    if (obstacle.active && obstacle.y > 650) {
      // 回收到对象池
      obstacle.setActive(false);
      obstacle.setVisible(false);
      obstacle.setVelocity(0, 0);
    }
  });
}

const game = new Phaser.Game(config);
```

[PLAN]
REQ: 创建青色椭圆的2秒缩放循环动画
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, this.add.graphics, this.tweens.add
STEPS:
1. 使用 Graphics 绘制青色椭圆形状
2. 将 Graphics 转换为可复用的纹理
3. 创建使用该纹理的精灵对象
4. 使用 tweens 创建缩放动画，设置循环和悠悠球效果
5. 配置动画持续时间为2秒并启动
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制青色椭圆
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ffff, 1); // 青色

  // 绘制椭圆（中心点在 0,0，宽度100，高度60）
  graphics.fillEllipse(0, 0, 100, 60);

  // 将 Graphics 转换为纹理
  graphics.generateTexture('ellipseTexture', 100, 60);

  // 销毁 Graphics 对象（纹理已生成）
  graphics.destroy();

  // 创建使用该纹理的精灵，放置在屏幕中心
  const ellipse = this.add.sprite(400, 300, 'ellipseTexture');

  // 创建缩放动画
  this.tweens.add({
    targets: ellipse,           // 动画目标对象
    scaleX: 1.5,                // X轴缩放到1.5倍
