REQ: 实现一个青色菱形在3秒内左右往返循环移动的补间动画
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制青色菱形并生成纹理
2. 创建 Sprite 对象并应用菱形纹理
3. 使用 tweens 创建 x 轴移动补间动画，设置 duration 为 3000ms
4. 配置 yoyo 为 true 实现往返效果，设置 repeat 为 -1 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制青色菱形
  const graphics = this.add.graphics();

  // 设置青色填充
  graphics.fillStyle(0x00ffff, 1);

  // 绘制菱形（中心点在 32, 32，边长约 64）
  graphics.beginPath();
  graphics.moveTo(32, 0);      // 上顶点
  graphics.lineTo(64, 32);     // 右顶点
  graphics.lineTo(32, 64);     // 下顶点
  graphics.lineTo(0, 32);      // 左顶点
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('diamond', 64, 64);
  graphics.destroy();

  // 创建菱形精灵，初始位置在左侧
  const diamond = this.add.sprite(100, 300, 'diamond');

  // 创建补间动画：从左到右移动
  this.tweens.add({
    targets: diamond,           // 动画目标
    x: 700,                     // 目标 x 坐标（右侧）
    duration: 3000,             // 持续时间 3 秒
    yoyo: true,                 // 往返效果（到达终点后返回起点）
    repeat: -1,                 // 无限循环（-1 表示永远重复）
    ease: 'Linear'              // 线性缓动，匀速移动
  });
}

new Phaser.Game(config);
