REQ: 使用方向键控制青色圆形在画布边界内移动
API: Graphics.fillCircle, Input.Keyboard.createCursorKeys, GameObjects.Graphics.generateTexture, Sprite.setVelocity
STEPS:
1. 使用 Graphics 绘制青色圆形并生成纹理
2. 创建 Sprite 并启用 Arcade 物理引擎
3. 使用 createCursorKeys 监听方向键输入
4. 在 update 中根据方向键设置速度
5. 设置 collideWorldBounds 限制移动范围
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let cursors;
const PLAYER_SPEED = 80;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制青色圆形并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ffff, 1); // 青色
  graphics.fillCircle(20, 20, 20); // 在 (20, 20) 位置绘制半径为 20 的圆
  graphics.generateTexture('playerCircle', 40, 40);
  graphics.destroy();

  // 创建玩家精灵，位置在画布中心
  player = this.physics.add.sprite(400, 300, 'playerCircle');

  // 设置碰撞世界边界
  player.setCollideWorldBounds(true);

  // 创建方向键控制
  cursors = this.input.keyboard.createCursorKeys();
}

function update(time, delta) {
  // 重置速度
  player.setVelocity(0, 0);

  // 检测方向键并设置速度
  if (cursors.left.isDown) {
    player.setVelocityX(-PLAYER_SPEED);
  } else if (cursors.right.isDown) {
    player.setVelocityX(PLAYER_SPEED);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-PLAYER_SPEED);
  } else if (cursors.down.isDown) {
    player.setVelocityY(PLAYER_SPEED);
  }

  // 如果同时按下两个方向键，需要归一化速度以保持恒定速度
  if ((cursors.left.isDown || cursors.right.isDown) && 
      (cursors.up.isDown || cursors.down.isDown)) {
    player.body.velocity.normalize().scale(PLAYER_SPEED);
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 让一个方块以每秒 300 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#fillRect, Phaser.GameObjects.Graphics#rotation, Phaser.Scene#update
STEPS:
1. 使用 Graphics 创建一个方块形状
2. 将方块的旋转中心设置为中心点
3. 在 update 方法中根据 delta 时间累加旋转角度（300度/秒 = 300 * (Math.PI/180) 弧度/秒）
4. 应用旋转角度到方块的 rotation 属性
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let square;
const rotationSpeed = 300; // 度/秒

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建一个 Graphics 对象绘制方块
  square = this.add.graphics();

  // 设置填充颜色为蓝色
  square.fillStyle(0x3498db, 1);

  // 绘制一个 100x100 的方块，中心点在 (0, 0)
  // 这样旋转时会围绕中心旋转
  square.fillRect(-50, -50, 100, 100);

  // 将方块放置在画布中心
  square.x = 400;
  square.y = 300;
}

function update(time, delta) {
  // 将旋转速度从度/秒转换为弧度/秒
  const rotationSpeedRad = Phaser.Math.DegToRad(rotationSpeed);

  // 根据 delta 时间（毫秒）计算本帧应旋转的角度
  // delta 是毫秒，需要除以 1000 转换为秒
  const rotationThisFrame = rotationSpeedRad * (delta / 1000);

  // 累加旋转角度
  square.rotation += rotationThisFrame;
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现玩家可旋转朝向，按鼠标左键向当前朝向发射子弹，子弹速度360
API: Phaser.Physics.Arcade.Group, Phaser.Physics.Arcade.Factory#velocityFromAngle, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics
STEPS:
1. 创建物理系统配置，初始化场景
2. 使用 Graphics 生成玩家和子弹纹理
3. 创建玩家精灵，支持键盘旋转控制
4. 创建子弹组（Physics.Arcade.Group）管理子弹
5. 监听鼠标左键点击事件，发射子弹
6. 在 update 中处理旋转输入和子弹回收
7. 添加状态信号（shotsFired 计数器）
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.shotsFired = 0; // 状态信号：发射子弹数量
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（三角形飞船）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.beginPath();
    playerGraphics.moveTo(20, 0);
    playerGraphics.lineTo(-10, -10);
    playerGraphics.lineTo(-10, 10);
    playerGraphics.closePath();
    playerGraphics.fillPath();
    playerGraphics.generateTexture('player', 30, 20);
    playerGraphics.destroy();

    // 创建子弹纹理（小圆点）
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.setDamping(true);
    this.player.setDrag(0.95);

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 50,
      runChildUpdate: true
    });

    // 键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 鼠标左键射击
    this.input.on('pointerdown', (pointer) => {
      if (pointer.leftButtonDown()) {
        this.shootBullet();
      }
    });

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff'
    });

    // 添加说明文字
    this.add.text(10, 550, 'Controls: Arrow Keys to Rotate | Left Click to Shoot', {
      fontSize: '14px',
      fill: '#aaaaaa'
    });
  }

  shootBullet() {
    // 从子弹组获取或创建子弹
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 设置子弹角度与玩家一致
      bullet.setRotation(this.player.rotation);

      // 根据玩家角度计算速度（角度转为度数）
      const angleInDegrees = Phaser.Math.RadToDeg(this.player.rotation);
      const velocity = this.physics.velocityFromAngle(angleInDegrees, 360);

      bullet.setVelocity(velocity.x, velocity.y);

      // 子弹生命周期管理
      bullet.lifespan = 3000; // 3秒后销毁
      bullet.spawnTime = this.time.now;

      // 更新状态
      this.shotsFired++;
    }
  }

  update(time, delta) {
    // 玩家旋转控制
    if (this.cursors.left.isDown) {
      this.player.angle -= 3;
    } else if (this.cursors.right.isDown) {
      this.player.angle += 3;
    }

    // 可选：上下键移动（增强体验）
    if (this.cursors.up.isDown) {
      const angleInDegrees = Phaser.Math.RadToDeg(this.player.rotation);
      const velocity = this.physics.velocityFromAngle(angleInDegrees, 200);
      this.player.setVelocity(velocity.x, velocity.y);
    }

    // 子弹生命周期管理
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active) {
        // 检查子弹是否超出边界
        if (bullet.x < -20 || bullet.x > 820 || 
            bullet.y < -20 || bullet.y > 620) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }

        // 检查子弹是否超时
        if (time - bullet.spawnTime > bullet.lifespan) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      }
    });

    // 更新状态显示
    const activeBullets = this.bullets.countActive(true);
    this.statusText.setText([
      `Shots Fired: ${this.shotsFired}`,
      `Active Bullets: ${activeBullets}`,
      `Player Angle: ${Math.round(this.player.angle)}°`
    ]);
  }
}

