    statusText.setText([
      `Objects: ${objectCount}`,
      `Speed: ${movementSpeed}`,
      `Collisions: ${collisionCount}`
    ]);
  });
}

function handleCollision(obj1, obj2) {
  // 记录碰撞次数
  collisionCount++;
}

