REQ: 创建1600x1200大场景，设置相机边界限制相机移动范围
API: setBounds, setBackgroundColor, fillRect, createCursorKeys, scrollX, scrollY
STEPS:
1. 创建1600x1200的大场景，使用Graphics绘制背景网格便于观察
2. 使用camera.setBounds设置相机边界为场景大小
3. 添加键盘控制让相机可以移动，验证边界限制
4. 在场景四周绘制边界标记，方便观察相机是否被正确限制
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 获取主相机
  const camera = this.cameras.main;

  // 设置相机边界为 1600x1200 的场景大小
  camera.setBounds(0, 0, 1600, 1200);

  // 绘制场景背景 - 使用网格便于观察
  const graphics = this.add.graphics();

  // 绘制浅色背景
  graphics.fillStyle(0x404040, 1);
  graphics.fillRect(0, 0, 1600, 1200);

  // 绘制网格线
  graphics.lineStyle(1, 0x606060, 0.5);

  // 垂直网格线
  for (let x = 0; x <= 1600; x += 100) {
    graphics.beginPath();
    graphics.moveTo(x, 0);
    graphics.lineTo(x, 1200);
    graphics.strokePath();
  }

  // 水平网格线
  for (let y = 0; y <= 1200; y += 100) {
    graphics.beginPath();
    graphics.moveTo(0, y);
    graphics.lineTo(1600, y);
    graphics.strokePath();
  }

  // 绘制场景边界标记
  graphics.lineStyle(4, 0xff0000, 1);
