[PLAN]
REQ: 绘制12个随机位置的灰色六边形，每个大小为32像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Phaser.Math.Between
STEPS:
1. 创建 Phaser Game 配置，设置场景和画布尺寸
2. 在 create 方法中循环12次，每次创建一个 Graphics 对象
3. 使用数学计算绘制正六边形的6个顶点坐标（半径16像素）
4. 为每个六边形设置随机位置（x: 50-750, y: 50-550，避免边缘裁剪）
5. 使用灰色填充六边形路径
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 绘制12个随机位置的灰色六边形
  for (let i = 0; i < 12; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置灰色填充
    graphics.fillStyle(0x808080, 1);

    // 六边形参数
    const size = 32; // 六边形大小（顶点到中心的距离）
    const radius = size / 2; // 半径为16像素

    // 随机位置（留出边距避免六边形被裁剪）
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 550);

    // 开始绘制路径
    graphics.beginPath();

    // 计算六边形的6个顶点并绘制
    // 从顶部顶点开始，逆时针绘制
    for (let j = 0; j < 6; j++) {
      const angle = (Math.PI / 3) * j - Math.PI / 2; // 每个顶点间隔60度，起始角度-90度
      const vx = x + radius * Math.cos(angle);
      const vy = y + radius * Math.sin(angle);

      if (j === 0) {
        graphics.moveTo(vx, vy);
      } else {
        graphics.lineTo(vx, vy);
      }
    }

    // 闭合路径
    graphics.closePath();

    // 填充路径
    graphics.fillPath();
  }
}

new Phaser.Game(config);
