REQ: 创建一个星形并使用 Tween 动画在 3 秒内缩放到 64%，然后恢复，循环播放
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Star, Phaser.Tweens.TweenManager, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制一个星形纹理
2. 创建 Sprite 对象并应用星形纹理
3. 使用 tweens.add 创建缩放动画，从 1 缩放到 0.64
4. 设置 yoyo 为 true 实现往返效果，duration 为 3000ms
5. 设置 repeat 为 -1 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制星形纹理
  const graphics = this.add.graphics();

  // 设置星形样式
  graphics.fillStyle(0xffff00, 1); // 黄色填充
  graphics.lineStyle(3, 0xffa500, 1); // 橙色描边

  // 绘制星形（中心点在 64, 64）
  const points = [];
  const outerRadius = 60;
  const innerRadius = 25;
  const numPoints = 5;

  for (let i = 0; i < numPoints * 2; i++) {
    const angle = (i * Math.PI) / numPoints - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const x = 64 + Math.cos(angle) * radius;
    const y = 64 + Math.sin(angle) * radius;
    points.push(x, y);
  }

  graphics.beginPath();
  graphics.moveTo(points[0], points[1]);
  for (let i = 2; i < points.length; i += 2) {
    graphics.lineTo(points[i], points[i + 1]);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('star', 128, 128);
  graphics.destroy();

  // 创建星形精灵并居中
  const star = this.add.sprite(400, 300, 'star');

  // 创建缩放动画
  this.tweens.add({
    targets: star,
    scaleX: 0.64,  // 缩放到 64%
    scaleY: 0.64,
    duration: 3000,  // 3 秒
    yoyo: true,  // 往返动画（缩小后再放大）
    repeat: -1,  // 无限循环
    ease: 'Sine.easeInOut'  // 平滑的缓动效果
  });

  // 添加文字说明
  this.add.text(400, 50, 'Star Scaling Animation', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  this.add.text(400, 550, 'Scale: 100% → 64% → 100% (3s loop)', {
    fontSize: '16px',
    color: '#aaaaaa'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

