  diamond.setInteractive();
  this.input.setDraggable(diamond);

  // 监听拖拽开始事件
  diamond.on('dragstart', function(pointer) {
    // 拖拽时改变为橙色
    this.setTexture('diamondOrange');
  });

  // 监听拖拽事件
  diamond.on('drag', function(pointer, dragX, dragY) {
    // 更新位置跟随鼠标
    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件
  diamond.on('dragend', function(pointer) {
