REQ: 实现15个绿色物体可拖拽，松手后按Y坐标自动排列
API: Graphics.fillRect, setInteractive, on('drag'), on('dragend'), sort, tween
STEPS:
1. 创建15个绿色矩形物体，使用Graphics生成纹理
2. 为每个物体启用拖拽交互（setInteractive + setDraggable）
3. 监听drag事件实时更新物体位置
4. 监听dragend事件，触发排序逻辑
5. 按Y坐标对所有物体排序，使用缓动动画移动到新位置
6. 添加状态变量记录拖拽次数和当前排序状态
[/PLAN]

```javascript
class DragSortScene extends Phaser.Scene {
  constructor() {
    super('DragSortScene');
    this.dragCount = 0; // 状态信号：拖拽次数
    this.isSorting = false; // 状态信号：是否正在排序
    this.objects = []; // 存储所有可拖拽对象
  }

  preload() {
    // 创建绿色矩形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0x00ff00, 1);
    graphics.fillRect(0, 0, 80, 50);
    graphics.generateTexture('greenBox', 80, 50);
    graphics.destroy();
  }

  create() {
    // 添加标题文本
    this.add.text(400, 30, '拖拽绿色物体，松手后自动按Y坐标排序', {
      fontSize: '20px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 添加状态显示
    this.statusText = this.add.text(400, 60, '拖拽次数: 0 | 状态: 就绪', {
      fontSize: '16px',
      color: '#ffff00'
    }).setOrigin(0.5);

    // 创建15个绿色物体，随机分布
    const startX = 150;
    const startY = 120;
    const spacing = 40;

    for (let i = 0; i < 15; i++) {
      // 随机位置
      const x = startX + (i % 5) * 120 + Math.random() * 40;
      const y = startY + Math.floor(i / 5) * 120 + Math.random() * 60;

      // 创建精灵
      const box = this.add.sprite(x, y, 'greenBox');
      box.setInteractive({ draggable: true });

      // 添加序号文本
      const text = this.add.text(x, y, (i + 1).toString(), {
        fontSize: '24px',
        color: '#000000',
        fontStyle: 'bold'
      }).setOrigin(0.5);

      // 将文本绑定到物体上
      box.textLabel = text;
      box.originalIndex = i;

      this.objects.push(box);

      // 拖拽开始
      box.on('dragstart', (pointer) => {
        box.setTint(0xffff00); // 高亮显示
        box.setDepth(1000); // 置顶
        box.textLabel.setDepth(1001);
      });

      // 拖拽中
      box.on('drag', (pointer, dragX, dragY) => {
        box.x = dragX;
        box.y = dragY;
        box.textLabel.x = dragX;
        box.textLabel.y = dragY;
      });

      // 拖拽结束
      box.on('dragend', (pointer) => {
        box.clearTint(); // 恢复颜色
        box.setDepth(0);
        box.textLabel.setDepth(1);

        this.dragCount++;
        this.updateStatus('排序中...');

        // 触发排序
        this.sortObjects();
      });
    }

    // 添加重置按钮
    const resetButton = this.add.text(400, 550, '重置位置', {
      fontSize: '18px',
      color: '#ffffff',
      backgroundColor: '#333333',
      padding: { x: 20, y: 10 }
    }).setOrigin(0.5).setInteractive();

    resetButton.on('pointerdown', () => {
      this.resetPositions();
    });

    resetButton.on('pointerover', () => {
      resetButton.setStyle({ backgroundColor: '#555555' });
    });

    resetButton.on('pointerout', () => {
      resetButton.setStyle({ backgroundColor: '#333333' });
    });
  }

  sortObjects() {
    if (this.isSorting) return;

    this.isSorting = true;

    // 按Y坐标排序
    const sorted = [...this.objects].sort((a, b) => a.y - b.y);

    // 计算新的排列位置（垂直排列）
    const startX = 400;
    const startY = 120;
    const spacing = 28;

    sorted.forEach((box, index) => {
      const targetY = startY + index * spacing;

      // 使用缓动动画移动到新位置
      this.tweens.add({
        targets: [box, box.textLabel],
        x: startX,
        y: targetY,
        duration: 500,
        ease: 'Power2',
        onComplete: () => {
          if (index === sorted.length - 1) {
            this.isSorting = false;
            this.updateStatus('就绪');
          }
        }
      });
    });
  }

  resetPositions() {
    if (this.isSorting) return;

    this.isSorting = true;
    this.updateStatus('重置中...');

    // 恢复到初始随机位置
    const startX = 150;
    const startY = 120;

    this.objects.forEach((box, i) => {
      const x = startX + (i % 5) * 120 + Math.random() * 40;
      const y = startY + Math.floor(i / 5) * 120 + Math.random() * 60;

      this.tweens.add({
        targets: [box, box.textLabel],
        x: x,
        y: y,
        duration: 400,
        ease: 'Power2',
        onComplete: () => {
          if (i === this.objects.length - 1) {
            this.isSorting = false;
            this.dragCount = 0;
            this.updateStatus('就绪');
          }
        }
      });
    });
  }

  updateStatus(status) {
    this.statusText.setText(`拖拽次数: ${this.dragCount} | 状态: ${status}`);
  }

  update(time, delta) {
    // 可以在这里添加额外的更新逻辑
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: DragSortScene,
  parent: 'game-container'
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现20关青色物品收集游戏，带关卡进度和分数显示
API: Phaser.Scene, Phaser.Physics.Arcade, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text
STEPS:
1. 创建 GameScene 类，初始化关卡系统（level 1-20）和分数系统
2. 使用 Graphics 绘制玩家（青色方块）和可收集物品（青色圆圈）
3. 配置 Arcade 物理系统，实现玩家移动和碰撞检测
4. 每关随机生成固定数量的收集物，收集完毕后进入下一关
5. 显示当前关卡和分数的 UI 文本
6. 实现键盘控制（方向键）和关卡切换逻辑
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.level = 1;
    this.score = 0;
    this.maxLevel = 20;
    this.itemsPerLevel = 5;
    this.seed = 12345; // 固定随机种子
  }

  preload() {
    // 创建玩家纹理（青色方块）
    const playerGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    playerGraphics.fillStyle(0x00ffff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建收集物纹理（青色圆圈）
    const itemGraphics = this.make.graphics({ x: 0, y: 0, add: false });
    itemGraphics.fillStyle(0x00ffff, 1);
    itemGraphics.fillCircle(12, 12, 12);
    itemGraphics.generateTexture('item', 24, 24);
    itemGraphics.destroy();
  }

  create() {
    // 创建背景
    const bg = this.add.graphics();
    bg.fillStyle(0x1a1a2e, 1);
    bg.fillRect(0, 0, 800, 600);

    // 创建玩家
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.setBounce(0);
    this.player.setDamping(true);
    this.player.setDrag(0.9);

    // 创建收集物组
    this.items = this.physics.add.group();

    // 创建 UI 文本
    this.levelText = this.add.text(16, 16, `Level: ${this.level}`, {
      fontSize: '24px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    });

    this.scoreText = this.add.text(16, 48, `Score: ${this.score}`, {
      fontSize: '24px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    });

    this.itemsText = this.add.text(16, 80, '', {
      fontSize: '20px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    });

    // 创建提示文本
    this.hintText = this.add.text(400, 550, 'Use Arrow Keys to Move', {
      fontSize: '18px',
      fill: '#888888',
      fontFamily: 'Arial'
    }).setOrigin(0.5);

    // 设置键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 碰撞检测
    this.physics.add.overlap(this.player, this.items, this.collectItem, null, this);

    // 生成当前关卡的物品
    this.generateLevel();
  }

  generateLevel() {
    // 清空现有物品
    this.items.clear(true, true);

    // 使用种子生成伪随机数
    const random = this.seededRandom(this.seed + this.level);

    // 生成物品数量随关卡递增
    const itemCount = this.itemsPerLevel + Math.floor((this.level - 1) / 2);

    for (let i = 0; i < itemCount; i++) {
      // 生成随机位置，避免边缘
      const x = 100 + random() * 600;
      const y = 150 + random() * 350;

      const item = this.items.create(x, y, 'item');
      item.setCircle(12);
      item.setImmovable(true);
    }

    // 更新 UI
    this.updateUI();
  }

  seededRandom(seed) {
    // 简单的伪随机数生成器
    let value = seed;
    return function() {
      value = (value * 9301 + 49297) % 233280;
      return value / 233280;
    };
  }

  collectItem(player, item) {
    // 收集物品
    item.destroy();
    this.score += 10 * this.level; // 分数随关卡递增

    // 播放简单的视觉反馈
    const flash = this.add.graphics();
    flash.fillStyle(0x00ffff, 0.5);
    flash.fillCircle(item.x, item.y, 30);
    this.tweens.add({
      targets: flash,
      alpha: 0,
      scale: 2,
      duration: 300,
      onComplete: () => flash.destroy()
    });

    // 更新 UI
    this.updateUI();

    // 检查是否收集完所有物品
    if (this.items.countActive() === 0) {
      this.nextLevel();
    }
  }

  nextLevel() {
    this.level++;

    if (this.level > this.maxLevel) {
      // 游戏完成
      this.showGameComplete();
    } else {
      // 显示关卡过渡
      this.showLevelTransition();
    }
  }

  showLevelTransition() {
    // 创建过渡效果
    const overlay = this.add.graphics();
    overlay.fillStyle(0x000000, 0.7);
    overlay.fillRect(0, 0, 800, 600);
    overlay.setDepth(100);

    const text = this.add.text(400, 300, `Level ${this.level}`, {
      fontSize: '48px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    }).setOrigin(0.5).setDepth(101);

    // 淡入淡出效果
    this.tweens.add({
      targets: [overlay, text],
      alpha: 0,
      duration: 1500,
      delay: 500,
      onComplete: () => {
        overlay.destroy();
        text.destroy();
        this.generateLevel();
      }
    });
  }

  showGameComplete() {
    // 游戏完成界面
    const overlay = this.add.graphics();
    overlay.fillStyle(0x000000, 0.8);
    overlay.fillRect(0, 0, 800, 600);
    overlay.setDepth(100);

    const title = this.add.text(400, 250, 'GAME COMPLETE!', {
      fontSize: '48px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    }).setOrigin(0.5).setDepth(101);

    const finalScore = this.add.text(400, 320, `Final Score: ${this.score}`, {
      fontSize: '32px',
      fill: '#00ffff',
      fontFamily: 'Arial'
    }).setOrigin(0.5).setDepth(101);

    const restartHint = this.add.text(400, 380, 'Refresh to Play Again', {
      fontSize: '20px',
      fill: '#888888',
      fontFamily: 'Arial'
    }).setOrigin(0.5).setDepth(101);

    // 停止玩家移动
    this.player.setVelocity(0, 0);
    this.physics.pause();
  }

  updateUI() {
    this.levelText.setText(`Level: ${this.level}/${this.maxLevel}`);
    this.scoreText.setText(`Score: ${this.score}`);
    this.itemsText.setText(`Items: ${this.items.countActive()}`);
  }

  update(time, delta) {
    if (this.physics.world.isPaused) {
      return;
    }

    // 玩家移动控制
    const speed = 200;

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    } else {
      this.player.setVelocityY(0);
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#1a1a2e',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

const game = new Phaser.Game(config);
