  const deltaInSeconds = delta / 1000;

  // 每秒旋转 200 度，转换为弧度
  const rotationSpeed = Phaser.Math.DegToRad(200);

  // 累加旋转角度
  diamond.rotation += rotationSpeed * deltaInSeconds;
}

