  this.time.addEvent({
    delay: 1000,                // 延迟时间（毫秒）
    callback: updateTimer,      // 回调函数
    callbackScope: this,        // 回调函数的作用域
    loop: true,                 // 循环执行
    repeat: 9                   // 重复9次（总共执行10次：初始 + 9次重复）
  });
}

function updateTimer() {
  // 减少剩余时间
  remainingTime--;

  // 更新文本显示
  if (remainingTime > 0) {
    timeText.setText(remainingTime.toString());
  } else {
    // 倒计时结束，显示"时间到"
    timeText.setText('时间到');
    timeText.setFontSize('64px');
    timeText.setColor('#ff0000');
  }
}

