      ((this.healTimer.elapsed / this.healTimer.delay) * 100).toFixed(1) : 0;

    this.debugText.setText([
      `当前生命: ${this.currentHealth}/${this.maxHealth}`,
      `回血进度: ${timerProgress}%`,
      `定时器状态: ${this.healTimer && !this.healTimer.paused ? '运行中' : '已停止'}`
    ]);
  }

  update(time, delta) {
