[PLAN]
REQ: 绘制12个随机位置的绿色六边形，每个大小为16像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Phaser.Math.Between
STEPS:
1. 创建 Phaser Game 配置，设置 800x600 画布
2. 在 create 方法中循环12次
3. 每次循环创建一个 Graphics 对象
4. 使用三角函数计算六边形的6个顶点坐标（半径8像素）
5. 使用 beginPath/moveTo/lineTo 绘制六边形路径
6. 使用 fillStyle 设置绿色并填充
7. 使用 Phaser.Math.Between 随机设置每个六边形的位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建12个随机位置的绿色六边形
  for (let i = 0; i < 12; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置填充颜色为绿色
    graphics.fillStyle(0x00ff00, 1);

    // 六边形的半径（大小16像素，半径为8）
    const radius = 8;

    // 开始绘制路径
    graphics.beginPath();

    // 计算六边形的6个顶点
    for (let j = 0; j < 6; j++) {
      // 六边形每个角度间隔60度（PI/3弧度）
      const angle = (Math.PI / 3) * j;
      const x = radius * Math.cos(angle);
      const y = radius * Math.sin(angle);

      if (j === 0) {
        graphics.moveTo(x, y);
      } else {
        graphics.lineTo(x, y);
      }
    }

    // 闭合路径
    graphics.closePath();

    // 填充路径
    graphics.fillPath();

    // 设置随机位置
    const randomX = Phaser.Math.Between(20, 780);
    const randomY = Phaser.Math.Between(20, 580);
    graphics.setPosition(randomX, randomY);
  }
}

new Phaser.Game(config);
```

