        offsetY: 2,
        color: '#000000',
        blur: 5,
        fill: true
      }
    }).setOrigin(0.5);

    this.add.text(width / 2, height / 2 + 60, 'Watch the fade effects!', {
      fontSize: '24px',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5);
  }

  updateStatusText() {
    this.statusText.setText([
      `Status: ${this.effectStatus}`,
      `Fade In: ${this.fadeInComplete ? '✓' : '✗'}`,
      `Fade Out: ${this.fadeOutComplete ? '✓' : '✗'}`
    ]);
  }

  update(time, delta) {
    // 可以在这里添加额外的动画或逻辑
  }
}

