REQ: 绘制10个随机位置的紫色方块，每个大小为64像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.fillRect, Math.random
STEPS:
1. 创建 Phaser Game 配置，设置画布大小为 800x600
2. 在 create 方法中使用循环创建10个 Graphics 对象
3. 为每个 Graphics 对象设置紫色填充样式（0x800080）
4. 使用 Math.random 生成随机 x、y 坐标（确保方块不超出边界）
5. 在随机位置绘制 64x64 的矩形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: {
    preload: preload,
    create: create
  },
  backgroundColor: '#2d2d2d'
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建10个随机位置的紫色方块
  for (let i = 0; i < 10; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置紫色填充样式
    graphics.fillStyle(0x800080, 1);

    // 生成随机位置（确保方块完全在画布内）
    // x 范围: 0 到 (800 - 64)
    // y 范围: 0 到 (600 - 64)
    const randomX = Math.random() * (config.width - 64);
    const randomY = Math.random() * (config.height - 64);

    // 绘制 64x64 的矩形
    graphics.fillRect(randomX, randomY, 64, 64);
  }
}

new Phaser.Game(config);
