function preload() {
  // 使用 Graphics 创建三角形纹理
  const graphics = this.add.graphics();

  // 绘制三角形
  graphics.fillStyle(0x00ff00, 1);
  graphics.beginPath();
  graphics.moveTo(50, 0);      // 顶点
  graphics.lineTo(100, 100);   // 右下
  graphics.lineTo(0, 100);     // 左下
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('triangle', 100, 100);
  graphics.destroy();
}

