    scaleY: 0.24,        // 缩放到 24%
    duration: 2000,      // 2 秒
    yoyo: true,          // 自动恢复到原始值
    loop: -1,            // 无限循环
    ease: 'Sine.easeInOut'  // 平滑的缓动效果
  });

  // 添加文本说明
