REQ: 六边形在1.5秒内缩放到80%后恢复，循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制六边形并生成纹理
2. 创建 Sprite 使用六边形纹理
3. 使用 Tween 实现缩放动画（scale: 1 → 0.8 → 1）
4. 设置 loop: -1 实现无限循环，duration: 1500ms
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();

  // 六边形参数
  const hexRadius = 60;
  const centerX = 100;
  const centerY = 100;

  // 绘制六边形
  graphics.fillStyle(0x00aaff, 1);
  graphics.lineStyle(3, 0xffffff, 1);

  graphics.beginPath();

  // 绘制六个顶点
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i - Math.PI / 2; // 从顶部开始
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 200, 200);
  graphics.destroy();

  // 创建六边形 Sprite 并居中显示
  const hexagon = this.add.sprite(400, 300, 'hexagon');

  // 创建缩放动画
  this.tweens.add({
    targets: hexagon,
    scaleX: 0.8,
    scaleY: 0.8,
    duration: 1500,
    ease: 'Sine.easeInOut',
    yoyo: true, // 自动反向播放（缩放回1）
    loop: -1, // 无限循环
    repeat: 0 // yoyo 模式下不需要额外 repeat
  });

  // 添加提示文本
  this.add.text(400, 500, '六边形循环缩放动画', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
