REQ: 使用 WASD 键控制方块以 200 像素/秒的速度移动
API: this.input.keyboard.addKey(), this.add.graphics(), this.time.delta
STEPS:
1. 创建 Graphics 对象绘制一个方块并生成纹理
2. 创建 Sprite 对象作为玩家可控方块
3. 在 create 中绑定 WASD 四个按键
4. 在 update 中根据按键状态和 delta 时间计算位移，更新方块位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let keys;
const SPEED = 200; // 像素/秒

function preload() {
  // 使用 Graphics 创建方块纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('playerBlock', 50, 50);
  graphics.destroy();
}

function create() {
  // 创建玩家方块，初始位置在屏幕中心
  player = this.add.sprite(400, 300, 'playerBlock');

  // 绑定 WASD 键
  keys = {
    W: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W),
    A: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A),
    S: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S),
    D: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D)
  };

  // 添加提示文本
  this.add.text(10, 10, 'Use WASD to move the block', {
    fontSize: '16px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 计算每帧的移动距离 = 速度 * 时间（秒）
  const distance = SPEED * (delta / 1000);

  // 根据按键状态更新位置
  if (keys.W.isDown) {
    player.y -= distance; // 向上移动
  }
  if (keys.S.isDown) {
    player.y += distance; // 向下移动
  }
  if (keys.A.isDown) {
    player.x -= distance; // 向左移动
  }
  if (keys.D.isDown) {
    player.x += distance; // 向右移动
  }

  // 限制方块在屏幕范围内
  player.x = Phaser.Math.Clamp(player.x, 25, 775);
  player.y = Phaser.Math.Clamp(player.y, 25, 575);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现可拖拽的青色三角形，拖拽时变色，松手后回到初始位置
API: Graphics.fillTriangle, setInteractive, on('drag'), on('dragstart'), on('dragend')
STEPS:
1. 使用 Graphics 绘制青色三角形并生成纹理
2. 创建 Sprite 并设置为可交互和可拖拽
3. 监听 dragstart 事件改变颜色为黄色
4. 监听 drag 事件更新位置
5. 监听 dragend 事件恢复青色并回到初始位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 创建青色三角形纹理
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });
  graphics.fillStyle(0x00ffff, 1); // 青色
  graphics.fillTriangle(
    50, 0,    // 顶点
    0, 100,   // 左下
    100, 100  // 右下
  );
  graphics.generateTexture('cyanTriangle', 100, 100);
  graphics.destroy();

  // 创建黄色三角形纹理
  const graphicsYellow = this.make.graphics({ x: 0, y: 0, add: false });
  graphicsYellow.fillStyle(0xffff00, 1); // 黄色
  graphicsYellow.fillTriangle(
    50, 0,
    0, 100,
    100, 100
  );
  graphicsYellow.generateTexture('yellowTriangle', 100, 100);
  graphicsYellow.destroy();
}

function create() {
  // 添加提示文本
  this.add.text(400, 50, '拖拽三角形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  // 记录初始位置
  const initialX = 400;
  const initialY = 300;

  // 创建三角形精灵
  const triangle = this.add.sprite(initialX, initialY, 'cyanTriangle');

  // 设置为可交互和可拖拽
  triangle.setInteractive({ draggable: true });

  // 监听拖拽开始事件
  triangle.on('dragstart', function(pointer) {
    // 改变为黄色
    this.setTexture('yellowTriangle');
    this.setScale(1.1); // 稍微放大一点
  });

  // 监听拖拽中事件
  triangle.on('drag', function(pointer, dragX, dragY) {
    // 更新位置
    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件
  triangle.on('dragend', function(pointer) {
    // 恢复青色
    this.setTexture('cyanTriangle');
    this.setScale(1); // 恢复原始大小

    // 使用补间动画回到初始位置
    this.scene.tweens.add({
      targets: this,
      x: initialX,
      y: initialY,
      duration: 300,
      ease: 'Back.easeOut'
    });
  });

  // 添加状态提示文本
  const statusText = this.add.text(400, 550, '状态: 等待拖拽', {
    fontSize: '18px',
    color: '#aaaaaa'
  }).setOrigin(0.5);

  // 更新状态文本
  triangle.on('dragstart', function() {
    statusText.setText('状态: 拖拽中...');
  });

  triangle.on('dragend', function() {
    statusText.setText('状态: 返回初始位置');
    this.scene.time.delayedCall(500, () => {
      statusText.setText('状态: 等待拖拽');
    });
  });
}

new Phaser.Game(config);
