5. 根据按键方向更新方块位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let player;
let keys;
const SPEED = 360; // 像素/秒

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制方块并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('playerBlock', 50, 50);
  graphics.destroy();

  // 创建玩家方块，初始位置在屏幕中央
  player = this.add.sprite(400, 300, 'playerBlock');

  // 绑定 WASD 键
  keys = {
    W: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W),
    A: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A),
    S: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S),
    D: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D)
  };
}

function update(time, delta) {
  // 计算本帧的移动距离 = 速度 * 时间差（转换为秒）
  const distance = SPEED * (delta / 1000);

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 检测按键状态并设置移动方向
  if (keys.W.isDown) {
    velocityY = -1; // 向上
  } else if (keys.S.isDown) {
    velocityY = 1; // 向下
  }

  if (keys.A.isDown) {
    velocityX = -1; // 向左
  } else if (keys.D.isDown) {
    velocityX = 1; // 向右
  }

  // 如果同时按下两个方向键，需要归一化速度向量
  if (velocityX !== 0 && velocityY !== 0) {
    const length = Math.sqrt(velocityX * velocityX + velocityY * velocityY);
    velocityX /= length;
    velocityY /= length;
  }

  // 更新玩家位置
  player.x += velocityX * distance;
  player.y += velocityY * distance;

  // 边界限制（可选）
  player.x = Phaser.Math.Clamp(player.x, 25, 775);
  player.y = Phaser.Math.Clamp(player.y, 25, 575);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 绘制10个随机位置的青色六边形，每个大小为16像素
API: Phaser.GameObjects.Graphics, Graphics#fillStyle, Graphics#beginPath, Graphics#lineTo, Graphics#closePath, Graphics#fillPath, Math.random
STEPS:
1. 创建 Phaser.Game 配置，设置场景和画布尺寸
2. 在 create 方法中创建 Graphics 对象
3. 编写六边形绘制函数，根据中心点和半径计算6个顶点坐标
4. 循环10次，每次生成随机位置并绘制青色六边形
5. 使用 fillStyle 设置青色，使用 beginPath/lineTo/closePath/fillPath 绘制填充六边形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  const graphics = this.add.graphics();

  // 设置青色填充颜色 (cyan: #00FFFF)
  graphics.fillStyle(0x00FFFF, 1);

  /**
   * 绘制六边形
   * @param {number} x - 中心点 x 坐标
   * @param {number} y - 中心点 y 坐标
   * @param {number} radius - 六边形半径（从中心到顶点的距离）
   */
  function drawHexagon(x, y, radius) {
    graphics.beginPath();

    // 计算六边形的6个顶点坐标
    // 从顶部开始，顺时针绘制
    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI / 3) * i - Math.PI / 2; // 每个角60度，起始角度-90度使顶点朝上
      const px = x + radius * Math.cos(angle);
      const py = y + radius * Math.sin(angle);

      if (i === 0) {
        graphics.moveTo(px, py);
      } else {
        graphics.lineTo(px, py);
      }
    }

    graphics.closePath();
    graphics.fillPath();
  }

  // 绘制10个随机位置的六边形
  const hexagonRadius = 16; // 六边形大小为16像素
  const margin = hexagonRadius + 10; // 边距，确保六边形不会超出画布

  for (let i = 0; i < 10; i++) {
    // 生成随机位置，确保六边形完全在画布内
    const randomX = Phaser.Math.Between(margin, config.width - margin);
    const randomY = Phaser.Math.Between(margin, config.height - margin);

    drawHexagon(randomX, randomY, hexagonRadius);
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现白色连击计数系统，1秒内连续点击增加combo，超时重置，连击10次触发特效
API: Phaser.Time.TimerEvent, Phaser.Input.Pointer, Phaser.GameObjects.Text, Phaser.GameObjects.Graphics, Phaser.GameObjects.Particles.ParticleEmitter
STEPS:
1. 创建白色背景和combo文字显示
2. 监听点击事件，每次点击combo+1并重置计时器
3. 使用TimerEvent实现1秒超时机制，超时时重置combo为0
4. 当combo达到10时触发粒子特效和文字放大动画
5. 使用Graphics程序化生成粒子纹理，确保无外部资源依赖
[/PLAN]

```javascript
class ComboScene extends Phaser.Scene {
  constructor() {
    super('ComboScene');
    this.combo = 0;
    this.comboTimer = null;
    this.COMBO_TIMEOUT = 1000; // 1秒超时
    this.COMBO_THRESHOLD = 10; // 连击10次触发特效
  }

  preload() {
    // 程序化生成粒子纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xffffff, 1);
    graphics.fillCircle(8, 8, 8);
    graphics.generateTexture('particle', 16, 16);
    graphics.destroy();
  }

  create() {
    // 创建白色背景
    const bg = this.add.graphics();
    bg.fillStyle(0xffffff, 1);
    bg.fillRect(0, 0, 800, 600);

    // 创建提示文字
    this.add.text(400, 100, 'Click to build combo!', {
      fontSize: '24px',
      color: '#333333',
      fontFamily: 'Arial'
    }).setOrigin(0.5);

    this.add.text(400, 140, '(1 second timeout)', {
      fontSize: '16px',
      color: '#666666',
      fontFamily: 'Arial'
    }).setOrigin(0.5);

    // 创建combo显示文字
    this.comboText = this.add.text(400, 300, 'COMBO: 0', {
      fontSize: '48px',
      color: '#ff0000',
      fontFamily: 'Arial',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    // 创建状态文字
    this.statusText = this.add.text(400, 400, '', {
      fontSize: '32px',
      color: '#00ff00',
      fontFamily: 'Arial',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    // 创建粒子发射器（初始不活跃）
    this.particles = this.add.particles(0, 0, 'particle', {
      speed: { min: 100, max: 300 },
      angle: { min: 0, max: 360 },
      scale: { start: 1, end: 0 },
      lifespan: 1000,
      gravityY: 200,
      tint: [0xff0000, 0xff6600, 0xffff00, 0x00ff00, 0x0000ff, 0xff00ff],
      active: false,
      frequency: -1
    });

    // 监听点击事件
    this.input.on('pointerdown', this.onPointerDown, this);

    // 创建调试信息
    this.debugText = this.add.text(10, 10, '', {
      fontSize: '14px',
      color: '#333333',
      fontFamily: 'Arial'
    });

    // 初始化计时器变量
    this.lastClickTime = 0;
  }

  onPointerDown(pointer) {
    const currentTime = this.time.now;

    // 增加combo
    this.combo++;
    this.lastClickTime = currentTime;

    // 更新显示
    this.updateComboDisplay();

    // 重置计时器
    if (this.comboTimer) {
      this.comboTimer.destroy();
    }

    // 创建新的超时计时器
    this.comboTimer = this.time.delayedCall(this.COMBO_TIMEOUT, () => {
      this.resetCombo();
    });

    // 检查是否达到连击阈值
    if (this.combo === this.COMBO_THRESHOLD) {
      this.triggerComboEffect();
    }

    // 点击反馈动画
    this.tweens.add({
      targets: this.comboText,
      scaleX: 1.2,
      scaleY: 1.2,
      duration: 100,
      yoyo: true,
      ease: 'Quad.easeOut'
    });
  }

  updateComboDisplay() {
    this.comboText.setText(`COMBO: ${this.combo}`);

    // 根据combo数量改变颜色
    if (this.combo >= this.COMBO_THRESHOLD) {
      this.comboText.setColor('#ff00ff');
    } else if (this.combo >= 5) {
      this.comboText.setColor('#ff6600');
    } else {
      this.comboText.setColor('#ff0000');
    }
  }

  resetCombo() {
    this.combo = 0;
    this.updateComboDisplay();
    this.statusText.setText('');
    this.comboText.setColor('#ff0000');

    // 重置文字缩放
    this.comboText.setScale(1);
  }

  triggerComboEffect() {
    // 显示祝贺文字
    this.statusText.setText('🎉 COMBO MASTER! 🎉');

    // 文字放大动画
    this.tweens.add({
      targets: this.comboText,
      scaleX: 1.5,
      scaleY: 1.5,
      duration: 300,
      yoyo: true,
      ease: 'Back.easeOut'
    });

    // 状态文字闪烁动画
    this.tweens.add({
      targets: this.statusText,
      alpha: 0,
      duration: 200,
      yoyo: true,
      repeat: 5,
      ease: 'Sine.easeInOut'
    });

    // 触发粒子爆炸效果
    this.particles.setPosition(400, 300);
    this.particles.explode(50);

    // 屏幕震动效果
    this.cameras.main.shake(300, 0.01);

    // 额外的粒子效果（环形爆发）
    for (let i = 0; i < 12; i++) {
      const angle = (i / 12) * Math.PI * 2;
      const x = 400 + Math.cos(angle) * 100;
      const y = 300 + Math.sin(angle) * 100;

      this.particles.setPosition(x, y);
      this.particles.explode(5);
    }
  }

  update(time, delta) {
    // 更新调试信息
    const timeLeft = this.comboTimer ? 
      Math.max(0, this.COMBO_TIMEOUT - (time - this.lastClickTime)) : 0;

    this.debugText.setText([
      `Combo: ${this.combo}`,
      `Time Left: ${Math.ceil(timeLeft / 1000)}s`,
      `Status: ${this.combo >= this.COMBO_THRESHOLD ? 'THRESHOLD REACHED!' : 'Building...'}`,
      `Clicks to threshold: ${Math.max(0, this.COMBO_THRESHOLD - this.combo)}`
    ]);

    // 如果有计时器，显示进度条
    if (this.comboTimer && this.combo > 0) {
      const progress = timeLeft / this.COMBO_TIMEOUT;

      // 绘制进度条
      if (!this.progressBar) {
        this.progressBar = this.add.graphics();
      }

      this.progressBar.clear();
      this.progressBar.fillStyle(0x333333, 0.3);
      this.progressBar.fillRect(300, 350, 200, 10);

      this.progressBar.fillStyle(0xff0000, 1);
      this.progressBar.fillRect(300, 350, 200 * progress, 10);
    } else if (this.progressBar) {
      this.progressBar.clear();
    }
  }
}

const config = {
