    // 绘制六边形（大小64像素，半径32像素）
    const radius = 32;
    const sides = 6;

    graphics.beginPath();

    // 计算六边形的6个顶点
    for (let j = 0; j < sides; j++) {
      const angle = (Math.PI / 3) * j - Math.PI / 2; // 从顶部开始，每60度一个顶点
      const px = Math.cos(angle) * radius;
      const py = Math.sin(angle) * radius;

      if (j === 0) {
        graphics.moveTo(px, py);
      } else {
