    alpha: 1,                    // 目标透明度为 1（完全不透明）
    duration: 500,               // 持续时间 0.5 秒
    ease: 'Linear',              // 线性缓动
    yoyo: true,                  // 反向播放（从 1 回到 0）
    repeat: -1                   // 无限循环
  });
}

