REQ: 绘制12个随机位置的灰色六边形，每个大小为32像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Phaser.Math.Between
STEPS:
1. 创建 Phaser.Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象用于绘制
3. 编写六边形绘制函数，计算六边形的6个顶点坐标（基于中心点和半径）
4. 使用循环12次，每次生成随机坐标（x: 50-750, y: 50-550）
5. 在每个随机位置绘制灰色填充的六边形（大小32像素，即半径16）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  const graphics = this.add.graphics();

  // 设置灰色填充
  graphics.fillStyle(0x808080, 1);

  // 绘制六边形的辅助函数
  function drawHexagon(graphics, x, y, radius) {
    graphics.beginPath();

    // 计算六边形的6个顶点
    // 从顶部开始，顺时针绘制
    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI / 3) * i - Math.PI / 2; // -90度开始，每60度一个顶点
      const px = x + radius * Math.cos(angle);
      const py = y + radius * Math.sin(angle);

      if (i === 0) {
        graphics.moveTo(px, py);
      } else {
        graphics.lineTo(px, py);
      }
    }

    graphics.closePath();
    graphics.fillPath();
  }

  // 绘制12个随机位置的六边形
  const hexRadius = 16; // 大小32像素，半径为16
  const margin = 50; // 边距，确保六边形不会超出画布

  for (let i = 0; i < 12; i++) {
    // 生成随机位置
    const randomX = Phaser.Math.Between(margin, 800 - margin);
    const randomY = Phaser.Math.Between(margin, 600 - margin);

    // 绘制六边形
    drawHexagon(graphics, randomX, randomY, hexRadius);
  }
}

new Phaser.Game(config);
