    scaleX: 0.8,                  // X轴缩放到 80%
    scaleY: 0.8,                  // Y轴缩放到 80%
    duration: 3000,               // 持续时间 3秒
    yoyo: true,                   // 启用往返效果（缩放到80%后自动恢复）
