REQ: 青色玩家通过方向键移动，移出边界时从对侧循环出现，速度80
API: Phaser.Physics.Arcade.Sprite, this.input.keyboard.createCursorKeys(), sprite.setVelocity(), Graphics.generateTexture()
STEPS:
1. 创建带物理系统的场景配置
2. 使用 Graphics 绘制青色方块并生成纹理作为玩家
3. 创建物理精灵，设置碰撞边界为 false
4. 监听键盘输入控制玩家移动（速度80）
5. 在 update 中检测玩家位置，实现边界循环逻辑
6. 添加状态变量记录玩家穿越边界次数
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let cursors;
let wrapCount = 0; // 状态信号：记录穿越边界次数
let wrapCountText;

function preload() {
  // 使用 Graphics 创建青色玩家纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ffff, 1); // 青色
  graphics.fillRect(0, 0, 32, 32);
  graphics.generateTexture('player', 32, 32);
  graphics.destroy();
}

function create() {
  // 创建玩家精灵
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(false); // 关闭世界边界碰撞，允许移出边界

  // 创建键盘输入
  cursors = this.input.keyboard.createCursorKeys();

  // 显示状态信息
  wrapCountText = this.add.text(16, 16, 'Wraps: 0', {
    fontSize: '20px',
    fill: '#ffffff'
  });

  // 添加说明文字
  this.add.text(16, 50, 'Use Arrow Keys to Move\nSpeed: 80 pixels/sec', {
    fontSize: '16px',
    fill: '#aaaaaa'
  });

  // 显示边界提示
  const graphics = this.add.graphics();
  graphics.lineStyle(2, 0xffff00, 0.5);
  graphics.strokeRect(0, 0, config.width, config.height);
}

function update() {
  // 重置速度
  player.setVelocity(0, 0);

  // 键盘控制移动（速度80）
  if (cursors.left.isDown) {
    player.setVelocityX(-80);
  } else if (cursors.right.isDown) {
    player.setVelocityX(80);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-80);
  } else if (cursors.down.isDown) {
    player.setVelocityY(80);
  }

  // 边界循环逻辑
  const halfWidth = player.width / 2;
  const halfHeight = player.height / 2;

  // 左右边界循环
  if (player.x < -halfWidth) {
    player.x = config.width + halfWidth;
    wrapCount++;
    updateWrapCount();
  } else if (player.x > config.width + halfWidth) {
    player.x = -halfWidth;
    wrapCount++;
    updateWrapCount();
  }

  // 上下边界循环
  if (player.y < -halfHeight) {
    player.y = config.height + halfHeight;
    wrapCount++;
    updateWrapCount();
  } else if (player.y > config.height + halfHeight) {
    player.y = -halfHeight;
    wrapCount++;
    updateWrapCount();
  }
}

function updateWrapCount() {
  wrapCountText.setText('Wraps: ' + wrapCount);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现角色碰撞时闪烁1.5秒并播放击退效果
API: Phaser.Physics.Arcade, Phaser.Tweens, Phaser.Time.TimerEvent, Phaser.Graphics
STEPS:
1. 创建玩家角色和敌人，使用 Graphics 绘制白色方块作为玩家纹理
2. 设置 Arcade 物理系统，添加碰撞检测
3. 碰撞时触发受伤逻辑：计算击退方向和距离（基于速度120）
4. 使用 Tween 实现击退位移动画
5. 使用 Timer 和 alpha 切换实现闪烁效果（1.5秒内循环切换透明度）
6. 添加无敌时间防止连续受伤，显示 health 状态变量
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.health = 100;
    this.isInvincible = false;
    this.score = 0;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（白色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0xffffff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（红色方块）
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillRect(0, 0, 32, 32);
    enemyGraphics.generateTexture('enemy', 32, 32);
    enemyGraphics.destroy();

    // 创建玩家精灵
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人精灵
    this.enemy = this.physics.add.sprite(500, 300, 'enemy');
    this.enemy.setVelocity(-50, 0); // 敌人向左移动

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.enemy,
      this.onPlayerHit,
      null,
      this
    );

    // 添加键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 显示状态文本
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff'
    });
    this.updateStatusText();

    // 添加提示文本
    this.add.text(10, 550, '使用方向键移动玩家，碰到红色敌人触发受伤效果', {
      fontSize: '14px',
      fill: '#00ff00'
    });
  }

  update() {
    // 玩家移动控制
    if (!this.isInvincible || this.player.body) {
      const speed = 200;
      this.player.setVelocity(0);

      if (this.cursors.left.isDown) {
        this.player.setVelocityX(-speed);
      } else if (this.cursors.right.isDown) {
        this.player.setVelocityX(speed);
      }

      if (this.cursors.up.isDown) {
        this.player.setVelocityY(-speed);
      } else if (this.cursors.down.isDown) {
        this.player.setVelocityY(speed);
      }
    }

    // 敌人边界反弹
    if (this.enemy.x <= 16 || this.enemy.x >= 784) {
      this.enemy.setVelocityX(-this.enemy.body.velocity.x);
    }
  }

  onPlayerHit(player, enemy) {
    // 如果已经处于无敌状态，不触发受伤
    if (this.isInvincible) {
      return;
    }

    // 扣除生命值
    this.health -= 10;
    this.score += 1; // 记录受击次数
    this.updateStatusText();

    // 设置无敌状态
    this.isInvincible = true;

    // 计算击退方向（从敌人指向玩家）
    const angle = Phaser.Math.Angle.Between(
      enemy.x,
      enemy.y,
      player.x,
      player.y
    );

    // 击退距离基于速度120
    const knockbackSpeed = 120;
    const knockbackDistance = 80; // 击退距离
    const knockbackDuration = 300; // 击退持续时间（毫秒）

    // 计算击退目标位置
    const targetX = player.x + Math.cos(angle) * knockbackDistance;
    const targetY = player.y + Math.sin(angle) * knockbackDistance;

    // 停止玩家当前速度
    player.setVelocity(0);

    // 使用 Tween 实现击退效果
    this.tweens.add({
      targets: player,
      x: targetX,
      y: targetY,
      duration: knockbackDuration,
      ease: 'Power2'
    });

    // 实现闪烁效果（1.5秒）
    const blinkDuration = 1500;
    const blinkInterval = 100; // 每100ms切换一次透明度
    let blinkCount = 0;
    const maxBlinks = blinkDuration / blinkInterval;

    // 创建闪烁定时器
    const blinkTimer = this.time.addEvent({
      delay: blinkInterval,
      callback: () => {
        blinkCount++;
        // 切换透明度（0.3 和 1.0 之间）
        player.alpha = player.alpha === 1 ? 0.3 : 1;

        // 闪烁结束
        if (blinkCount >= maxBlinks) {
          player.alpha = 1; // 恢复完全不透明
          this.isInvincible = false; // 解除无敌状态
          blinkTimer.remove();
        }
      },
      loop: true
    });

    // 检查游戏结束
    if (this.health <= 0) {
      this.gameOver();
    }
  }

  updateStatusText() {
    this.statusText.setText(
      `Health: ${this.health} | Hits: ${this.score} | Invincible: ${this.isInvincible}`
    );
  }

  gameOver() {
    this.physics.pause();
    this.add.text(400, 300, 'GAME OVER', {
      fontSize: '48px',
      fill: '#ff0000'
    }).setOrigin(0.5);

    this.add.text(400, 350, `Total Hits: ${this.score}`, {
      fontSize: '24px',
      fill: '#ffffff'
    }).setOrigin(0.5);
  }
}

