[PLAN]
REQ: 六边形在1.5秒内缩放到64%再恢复，循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制六边形并生成纹理
2. 创建使用该纹理的精灵对象
3. 使用 Tween 实现缩放动画：从 1 缩放到 0.64，yoyo 模式自动恢复
4. 设置 loop: -1 实现无限循环，duration: 1500 毫秒
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();

  // 设置六边形参数
  const hexRadius = 80; // 六边形半径
  const centerX = 100; // 绘制中心点
  const centerY = 100;

  // 绘制六边形
  graphics.fillStyle(0x00aaff, 1);
  graphics.beginPath();

  // 计算六边形的六个顶点
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 每个角60度
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();

  // 添加描边
  graphics.lineStyle(4, 0xffffff, 1);
  graphics.strokePath();

  // 生成纹理
  const textureSize = hexRadius * 2 + 20;
  graphics.generateTexture('hexagon', textureSize, textureSize);
  graphics.destroy(); // 销毁 graphics 对象

  // 创建精灵对象
  const hexSprite = this.add.sprite(400, 300, 'hexagon');

  // 创建缩放动画
  this.tweens.add({
    targets: hexSprite,
    scaleX: 0.64,
    scaleY: 0.64,
    duration: 1500, // 1.5秒
    yoyo: true, // 自动恢复到原始值
    loop: -1, // 无限循环
    ease: 'Sine.easeInOut' // 使用平滑的缓动函数
  });

  // 添加文字说明
  this.add.text(400, 500, 'Hexagon scaling: 100% → 64% → 100%', {
    fontSize: '20px',
    color: '#ffffff',
    align: 'center'
  }).setOrigin(0.5);
}

