  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 800 }, // 初始重力向下
      debug: false
    }
  },
  scene: GravitySwitchScene
};

new Phaser.Game(config);
