REQ: 让一个六边形在 2 秒内从原始大小缩放到 80%，然后恢复，循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制一个六边形并生成纹理
2. 创建一个使用该纹理的精灵对象
3. 使用 Tween 创建缩放动画，从 1 缩放到 0.8，然后回到 1
4. 设置 Tween 循环播放（loop: -1）和 yoyo 效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();

  // 六边形参数
  const hexRadius = 80;
  const centerX = hexRadius;
  const centerY = hexRadius;

  // 计算六边形的六个顶点
  const points = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 60度间隔
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);
    points.push({ x, y });
  }

  // 绘制填充的六边形
  graphics.fillStyle(0x00ff88, 1);
  graphics.beginPath();
  graphics.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) {
    graphics.lineTo(points[i].x, points[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 绘制六边形边框
  graphics.lineStyle(4, 0xffffff, 1);
  graphics.strokePath();

  // 生成纹理
  const textureSize = hexRadius * 2 + 10;
  graphics.generateTexture('hexagon', textureSize, textureSize);
  graphics.destroy();

  // 创建六边形精灵并居中显示
  const hexSprite = this.add.sprite(400, 300, 'hexagon');

  // 创建缩放动画
  this.tweens.add({
    targets: hexSprite,
    scaleX: 0.8,
    scaleY: 0.8,
    duration: 2000, // 2秒
    yoyo: true, // 自动回到原始值
    loop: -1, // 无限循环
    ease: 'Sine.easeInOut' // 使用平滑的缓动效果
  });

  // 添加文字说明
  this.add.text(400, 50, '六边形缩放动画', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  this.add.text(400, 550, '缩放范围: 100% ↔ 80% (循环播放)', {
    fontSize: '18px',
    color: '#aaaaaa'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

