let starCount = 0; // 用于生成唯一的纹理键名

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 添加提示文本
  const text = this.add.text(400, 50, '点击画面生成星形', {
    fontSize: '24px',
    color: '#ffffff',
    fontFamily: 'Arial'
  });
  text.setOrigin(0.5);

  // 监听点击事件
  this.input.on('pointerdown', (pointer) => {
    createStarAt(this, pointer.x, pointer.y);
  });
