2. 在 create 中使用 Graphics 或 Rectangle 绘制一个方块
3. 使用 addKey 绑定 WASD 四个按键
4. 在 update 中检测按键状态，根据 delta 时间计算移动距离
5. 更新方块位置实现移动效果
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let cursors;
const SPEED = 360; // 像素/秒

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 创建一个方块（使用 Rectangle 游戏对象）
  player = this.add.rectangle(400, 300, 50, 50, 0x00ff00);

  // 绑定 WASD 键
  cursors = {
    W: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W),
    A: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A),
    S: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S),
    D: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D)
  };
}

function update(time, delta) {
  // 将 delta 从毫秒转换为秒
  const deltaSeconds = delta / 1000;

  // 计算本帧应该移动的距离
  const moveDistance = SPEED * deltaSeconds;

  // 重置速度
  let velocityX = 0;
  let velocityY = 0;

  // 检测 WASD 键状态并设置速度
  if (cursors.W.isDown) {
    velocityY = -1; // 向上
  }
  if (cursors.S.isDown) {
    velocityY = 1; // 向下
  }
  if (cursors.A.isDown) {
    velocityX = -1; // 向左
  }
  if (cursors.D.isDown) {
    velocityX = 1; // 向右
  }

  // 处理对角线移动（归一化速度向量）
  if (velocityX !== 0 && velocityY !== 0) {
    const length = Math.sqrt(velocityX * velocityX + velocityY * velocityY);
    velocityX /= length;
    velocityY /= length;
  }

  // 更新玩家位置
  player.x += velocityX * moveDistance;
  player.y += velocityY * moveDistance;

  // 边界限制（可选）
  player.x = Phaser.Math.Clamp(player.x, 25, 775);
  player.y = Phaser.Math.Clamp(player.y, 25, 575);
}

new Phaser.Game(config);
