REQ: 创建一个倒计时 3 秒的计时器，屏幕中央显示剩余时间，归零时显示"时间到"
API: Phaser.GameObjects.Text, Phaser.Time.Clock#addEvent, Phaser.Time.TimerEvent
STEPS:
1. 在 create 中创建文本对象显示倒计时数字，居中对齐
2. 使用 this.time.addEvent 创建定时器，每秒触发一次回调
3. 在回调中递减计数器并更新文本显示
4. 当计数器归零时，更新文本为"时间到"并停止计时器
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

let countdownText;
let timeLeft = 3;

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建倒计时文本，居中显示
  countdownText = this.add.text(
    400, 
    300, 
    timeLeft.toString(), 
    {
      fontSize: '128px',
      color: '#ffffff',
      fontStyle: 'bold'
    }
  );

  // 设置文本原点为中心，使其居中对齐
  countdownText.setOrigin(0.5, 0.5);

  // 创建定时器事件，每秒触发一次
  this.time.addEvent({
    delay: 1000,                // 每 1000 毫秒（1 秒）触发一次
    callback: updateCountdown,  // 回调函数
    callbackScope: this,        // 回调函数的作用域
    loop: true                  // 循环执行
  });
}

function updateCountdown() {
  // 递减时间
  timeLeft--;

  if (timeLeft > 0) {
    // 更新显示的数字
    countdownText.setText(timeLeft.toString());
  } else {
    // 时间到，显示提示文本
    countdownText.setText('时间到');
    countdownText.setFontSize('64px');

    // 停止计时器（通过移除所有事件）
    this.time.removeAllEvents();
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现一个绿色六边形在2.5秒内左右往返循环移动的补间动画
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制绿色六边形并生成纹理
2. 创建精灵对象并设置初始位置在左侧
3. 使用 tweens 创建补间动画，设置 yoyo 和 loop 实现往返循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制绿色六边形
  const graphics = this.add.graphics();

  // 设置绘制样式
  graphics.fillStyle(0x00ff00, 1);
  graphics.lineStyle(2, 0x00aa00, 1);

  // 绘制六边形（中心点在 50, 50，半径 40）
  const hexRadius = 40;
  const centerX = 50;
  const centerY = 50;
  const sides = 6;

  // 计算六边形的顶点
  const points = [];
  for (let i = 0; i < sides; i++) {
    const angle = (Math.PI * 2 * i) / sides - Math.PI / 2; // -PI/2 让顶点朝上
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);
    points.push(x, y);
  }

  // 绘制多边形
  graphics.beginPath();
  graphics.moveTo(points[0], points[1]);
  for (let i = 2; i < points.length; i += 2) {
    graphics.lineTo(points[i], points[i + 1]);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 100, 100);
  graphics.destroy(); // 销毁 graphics 对象，只保留纹理

  // 创建精灵对象，初始位置在左侧
  const hexSprite = this.add.sprite(100, 300, 'hexagon');

  // 创建补间动画：从左到右，2.5秒，往返循环
  this.tweens.add({
    targets: hexSprite,
    x: 700, // 移动到右侧
    duration: 2500, // 2.5秒
    ease: 'Linear', // 线性缓动
    yoyo: true, // 往返效果
    repeat: -1 // 无限循环 (-1 表示永久重复)
  });

  // 添加文字提示
  this.add.text(400, 50, '绿色六边形往返循环动画', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

// 创建游戏实例
new Phaser.Game(config);
```

