REQ: 实现一个可拖拽的圆形，拖拽时缩放到 1.2 倍，松手后恢复原大小
API: Graphics.fillCircle, Graphics.generateTexture, setInteractive, on('drag'), on('dragstart'), on('dragend'), setScale
STEPS:
1. 使用 Graphics 绘制圆形并生成纹理
2. 创建 Sprite 并设置为可交互和可拖拽
3. 监听 dragstart 事件，将圆形缩放到 1.2 倍
4. 监听 drag 事件，更新圆形位置跟随鼠标
5. 监听 dragend 事件，将圆形恢复到原大小
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制圆形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00aaff, 1);
  graphics.fillCircle(50, 50, 50); // 圆心在 (50, 50)，半径 50

  // 生成纹理
  graphics.generateTexture('circle', 100, 100);
  graphics.destroy(); // 销毁 graphics 对象，因为已经生成了纹理

  // 创建可拖拽的圆形精灵
  const circle = this.add.sprite(400, 300, 'circle');

  // 设置为可交互并启用拖拽
  circle.setInteractive({ draggable: true });

  // 监听拖拽开始事件 - 放大到 1.2 倍
  circle.on('dragstart', function(pointer, dragX, dragY) {
    this.setScale(1.2);
  });

  // 监听拖拽中事件 - 更新位置
  circle.on('drag', function(pointer, dragX, dragY) {
    this.x = dragX;
    this.y = dragY;
  });

  // 监听拖拽结束事件 - 恢复原大小
  circle.on('dragend', function(pointer, dragX, dragY) {
    this.setScale(1);
  });

  // 添加提示文本
  const text = this.add.text(400, 50, '拖拽圆形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  });
  text.setOrigin(0.5);
}

new Phaser.Game(config);
```

