REQ: 按空格键发射粉色子弹，速度360，离开边界回收到对象池
API: Phaser.Physics.Arcade.Group, Phaser.Input.Keyboard.KeyCodes.SPACE, Graphics.generateTexture, Group.get, Group.killAndHide
STEPS:
1. 创建物理系统配置，初始化场景
2. 使用 Graphics 生成粉色子弹纹理和玩家纹理
3. 创建物理精灵组作为子弹对象池，配置回收条件
4. 监听空格键输入事件
5. 按空格键时从对象池获取子弹并发射
6. 在 update 中检测子弹边界，离开边界则回收
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.bulletsFired = 0; // 可验证状态：发射的子弹总数
    this.activeBullets = 0; // 可验证状态：当前活跃子弹数
  }

  preload() {
    // 创建粉色子弹纹理
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xff69b4, 1); // 粉色
    bulletGraphics.fillCircle(8, 8, 8);
    bulletGraphics.generateTexture('bullet', 16, 16);
    bulletGraphics.destroy();

    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x4169e1, 1);
    playerGraphics.fillRect(0, 0, 40, 40);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();
  }

  create() {
    // 创建玩家精灵
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建子弹组（对象池）
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 20, // 对象池最大容量
      runChildUpdate: false
    });

    // 监听空格键
    this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

    // 添加文本显示状态
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff'
    });

    // 添加说明文本
    this.add.text(10, 550, 'Press SPACE to fire pink bullets', {
      fontSize: '16px',
      fill: '#ffff00'
    });

    this.updateStatusText();
  }

  update(time, delta) {
    // 检测空格键按下
    if (Phaser.Input.Keyboard.JustDown(this.spaceKey)) {
      this.fireBullet();
    }

    // 检查子弹是否离开边界并回收
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active) {
        // 检测是否离开屏幕边界
        if (bullet.y < -20 || bullet.y > 620 || 
            bullet.x < -20 || bullet.x > 820) {
          this.recycleBullet(bullet);
        }
      }
    });

    this.updateStatusText();
  }

  fireBullet() {
    // 从对象池获取子弹
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 设置子弹速度（向上发射）
      bullet.body.velocity.y = -360;
      bullet.body.velocity.x = 0;

      // 更新统计
      this.bulletsFired++;
      this.activeBullets++;
    }
  }

  recycleBullet(bullet) {
    // 回收子弹到对象池
    bullet.setActive(false);
    bullet.setVisible(false);
    bullet.body.velocity.set(0);
    this.activeBullets--;
  }

  updateStatusText() {
    this.statusText.setText([
      `Bullets Fired: ${this.bulletsFired}`,
      `Active Bullets: ${this.activeBullets}`,
      `Pool Size: ${this.bullets.getLength()}`,
      `Pool Available: ${this.bullets.maxSize - this.bullets.countActive(true)}`
    ]);
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

