class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.jumpCount = 0; // 当前已使用的跳跃次数
    this.totalJumps = 0; // 总跳跃统计（可验证状态）
    this.maxJumps = 2; // 最大跳跃次数
  }

  preload() {
