API: this.add.graphics(), this.input.keyboard.createCursorKeys(), graphics.fillEllipse(), Phaser.Math.Clamp
STEPS:
1. 使用 Graphics 绘制灰色椭圆并生成纹理
2. 创建 Sprite 对象并设置为生成的椭圆纹理
3. 使用 createCursorKeys() 获取方向键输入
4. 在 update 中根据方向键更新椭圆位置
5. 使用 Phaser.Math.Clamp 限制椭圆位置在画布边界内
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create, update },
  backgroundColor: '#2d2d2d'
};

let ellipse;
let cursors;
const SPEED = 120;
const ELLIPSE_WIDTH = 60;
const ELLIPSE_HEIGHT = 40;

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制灰色椭圆并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1); // 灰色
  graphics.fillEllipse(ELLIPSE_WIDTH / 2, ELLIPSE_HEIGHT / 2, ELLIPSE_WIDTH, ELLIPSE_HEIGHT);
  graphics.generateTexture('ellipseTex', ELLIPSE_WIDTH, ELLIPSE_HEIGHT);
  graphics.destroy();

  // 创建椭圆 Sprite，初始位置在画布中心
  ellipse = this.add.sprite(400, 300, 'ellipseTex');

  // 创建方向键控制
  cursors = this.input.keyboard.createCursorKeys();

  // 添加说明文字
  this.add.text(10, 10, 'Use Arrow Keys to Move', {
    fontSize: '16px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 计算移动距离（速度 * 时间差，转换为秒）
  const moveDistance = SPEED * (delta / 1000);

  // 根据方向键输入更新位置
  if (cursors.left.isDown) {
    ellipse.x -= moveDistance;
  }
  if (cursors.right.isDown) {
    ellipse.x += moveDistance;
  }
  if (cursors.up.isDown) {
    ellipse.y -= moveDistance;
  }
  if (cursors.down.isDown) {
    ellipse.y += moveDistance;
  }

  // 限制椭圆在画布边界内（考虑椭圆半径）
  const halfWidth = ELLIPSE_WIDTH / 2;
  const halfHeight = ELLIPSE_HEIGHT / 2;

  ellipse.x = Phaser.Math.Clamp(
    ellipse.x,
    halfWidth,
    config.width - halfWidth
  );

  ellipse.y = Phaser.Math.Clamp(
    ellipse.y,
    halfHeight,
    config.height - halfHeight
  );
}

new Phaser.Game(config);
```

