REQ: 使用补间动画让红色星形在2.5秒内左右往返循环移动
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics.generateTexture, Phaser.GameObjects.Image, Phaser.Tweens.TweenManager.add, Phaser.Tweens.BaseTween.yoyo, Phaser.Tweens.BaseTween.repeat
STEPS:
1. 使用 Graphics 绘制红色星形并生成纹理
2. 创建使用该纹理的 Image 对象，初始位置在左侧
3. 使用 tweens.add 创建补间动画，设置 x 坐标从左到右
4. 配置 yoyo 为 true 实现往返效果，repeat 为 -1 实现无限循环
5. 设置 duration 为 2500 毫秒（2.5秒）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制红色星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xff0000, 1);

  // 绘制五角星
  const centerX = 50;
  const centerY = 50;
  const outerRadius = 40;
  const innerRadius = 16;
  const points = 5;

  // 计算星形的顶点
  const starPoints = [];
  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (i * Math.PI) / points - Math.PI / 2;
    starPoints.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius
    });
  }

  // 绘制星形路径
  graphics.beginPath();
  graphics.moveTo(starPoints[0].x, starPoints[0].y);
  for (let i = 1; i < starPoints.length; i++) {
    graphics.lineTo(starPoints[i].x, starPoints[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy();

  // 创建星形精灵，初始位置在左侧
  const star = this.add.image(100, 300, 'star');

