  // 使用勾股定理：vx² + vy² = 160²
  // 45度角：vx = vy = 160 / √2 ≈ 113.14
  const speed = 160;
  const angle45 = Math.sqrt(speed * speed / 2);
  this.triangle.setVelocity(angle45, angle45);

  // 设置反弹系数为 1（完全弹性碰撞）
  this.triangle.setBounce(1, 1);

  // 启用世界边界碰撞
