REQ: 实现无尽波次模式，敌人数量和速度递增，显示波次和击杀数统计
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.GameObjects.Text, Phaser.Time.TimerEvent, Phaser.Physics.Arcade.Sprite
STEPS:
1. 创建玩家和敌人的程序化纹理（使用Graphics生成）
2. 初始化物理系统和玩家控制（键盘移动+鼠标射击）
3. 实现波次管理系统：每波敌人数=3+波次数，速度递增
4. 创建敌人生成逻辑，随机位置从屏幕边缘生成
5. 实现碰撞检测（子弹击中敌人，敌人碰撞玩家）
6. 显示UI文本：当前波次、击杀数、游戏状态
7. 波次完成后延迟开始下一波
[/PLAN]

```javascript
class EndlessWaveScene extends Phaser.Scene {
  constructor() {
    super('EndlessWaveScene');
    this.wave = 0;
    this.kills = 0;
    this.enemiesInWave = 0;
    this.enemiesSpawned = 0;
    this.baseEnemySpeed = 80;
    this.isWaveActive = false;
    this.gameOver = false;
  }

  preload() {
    // 程序化生成纹理
    this.createTextures();
  }

  createTextures() {
    // 玩家纹理 - 蓝色三角形
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00aaff, 1);
    playerGraphics.beginPath();
    playerGraphics.moveTo(0, -20);
    playerGraphics.lineTo(-15, 15);
    playerGraphics.lineTo(15, 15);
    playerGraphics.closePath();
    playerGraphics.fill();
    playerGraphics.generateTexture('player', 30, 35);
    playerGraphics.destroy();

    // 敌人纹理 - 红色圆形
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff3333, 1);
    enemyGraphics.fillCircle(15, 15, 15);
    enemyGraphics.lineStyle(2, 0xaa0000, 1);
    enemyGraphics.strokeCircle(15, 15, 15);
    enemyGraphics.generateTexture('enemy', 30, 30);
    enemyGraphics.destroy();

    // 子弹纹理 - 黄色小圆
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.health = 3;

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 30
    });

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();
    this.wasd = {
      up: this.input.keyboard.addKey('W'),
      down: this.input.keyboard.addKey('S'),
      left: this.input.keyboard.addKey('A'),
      right: this.input.keyboard.addKey('D')
    };

    // 鼠标射击
    this.input.on('pointerdown', (pointer) => {
      if (!this.gameOver) {
        this.shootBullet(pointer);
      }
    });

    // 碰撞检测
    this.physics.add.overlap(
      this.bullets,
      this.enemies,
      this.bulletHitEnemy,
      null,
      this
    );

    this.physics.add.overlap(
      this.player,
      this.enemies,
      this.playerHitEnemy,
      null,
      this
    );

    // UI文本
    this.waveText = this.add.text(16, 16, 'Wave: 0', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    this.killsText = this.add.text(16, 48, 'Kills: 0', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    this.healthText = this.add.text(16, 80, 'Health: 3', {
      fontSize: '24px',
      fill: '#00ff00',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    this.statusText = this.add.text(400, 300, '', {
      fontSize: '32px',
      fill: '#ffff00',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 6
    }).setOrigin(0.5);

    // 开始第一波
    this.startNextWave();
  }

  startNextWave() {
    this.wave++;
    this.enemiesInWave = 2 + this.wave; // 从3个开始（wave 1 = 3个敌人）
    this.enemiesSpawned = 0;
    this.isWaveActive = true;

    this.waveText.setText(`Wave: ${this.wave}`);
    this.statusText.setText(`Wave ${this.wave} Starting!`);
    this.statusText.setAlpha(1);

    // 淡出状态文本
    this.tweens.add({
      targets: this.statusText,
      alpha: 0,
      duration: 2000,
      delay: 1000
    });

    // 开始生成敌人
    this.spawnEnemiesForWave();
  }

  spawnEnemiesForWave() {
    // 每隔一段时间生成一个敌人
    const spawnDelay = 1000; // 每秒生成一个

    this.time.addEvent({
      delay: spawnDelay,
      callback: () => {
        if (this.enemiesSpawned < this.enemiesInWave && !this.gameOver) {
          this.spawnEnemy();
          this.enemiesSpawned++;
        }
      },
      repeat: this.enemiesInWave - 1
    });
  }

  spawnEnemy() {
    // 随机从屏幕边缘生成
    const side = Phaser.Math.Between(0, 3); // 0上 1右 2下 3左
    let x, y;

    switch(side) {
      case 0: // 上
        x = Phaser.Math.Between(50, 750);
        y = -30;
        break;
      case 1: // 右
        x = 830;
        y = Phaser.Math.Between(50, 550);
        break;
      case 2: // 下
        x = Phaser.Math.Between(50, 750);
        y = 630;
        break;
      case 3: // 左
        x = -30;
        y = Phaser.Math.Between(50, 550);
        break;
    }

    const enemy = this.enemies.create(x, y, 'enemy');
    enemy.setCollideWorldBounds(false);

    // 速度随波次递增
    const speedMultiplier = 1 + (this.wave - 1) * 0.15;
    enemy.speed = this.baseEnemySpeed * speedMultiplier;
  }

  shootBullet(pointer) {
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 计算方向
      const angle = Phaser.Math.Angle.Between(
        this.player.x,
        this.player.y,
        pointer.x,
        pointer.y
      );

      const speed = 400;
      bullet.setVelocity(
        Math.cos(angle) * speed,
        Math.sin(angle) * speed
      );

      // 子弹生命周期
      this.time.delayedCall(2000, () => {
        if (bullet.active) {
          bullet.setActive(false);
          bullet.setVisible(false);
          bullet.setVelocity(0, 0);
        }
      });
    }
  }

  bulletHitEnemy(bullet, enemy) {
    // 销毁子弹和敌人
    bullet.setActive(false);
    bullet.setVisible(false);
    bullet.setVelocity(0, 0);

    enemy.destroy();

    // 增加击杀数
    this.kills++;
    this.killsText.setText(`Kills: ${this.kills}`);

    // 检查波次是否完成
    this.checkWaveComplete();
  }

  playerHitEnemy(player, enemy) {
    enemy.destroy();

    // 减少生命值
    this.player.health--;
    this.healthText.setText(`Health: ${this.player.health}`);

    // 更新生命值颜色
    if (this.player.health === 2) {
      this.healthText.setFill('#ffff00');
    } else if (this.player.health === 1) {
      this.healthText.setFill('#ff0000');
    }

    // 玩家闪烁效果
    this.tweens.add({
      targets: this.player,
      alpha: 0.3,
      duration: 100,
      yoyo: true,
      repeat: 3
    });

    if (this.player.health <= 0) {
      this.endGame();
    }
  }

  checkWaveComplete() {
    // 检查是否所有敌人都已生成且被消灭
    if (this.enemiesSpawned >= this.enemiesInWave && 
        this.enemies.countActive(true) === 0 && 
        this.isWaveActive) {

      this.isWaveActive = false;
      this.statusText.setText(`Wave ${this.wave} Complete!`);
      this.statusText.setAlpha(1);

      // 延迟开始下一波
      this.time.delayedCall(3000, () => {
        if (!this.gameOver) {
          this.startNextWave();
        }
      });
    }
  }

  endGame() {
    this.gameOver = true;
    this.isWaveActive = false;

    // 停止所有敌人
    this.enemies.children.entries.forEach(enemy => {
      enemy.setVelocity(0, 0);
    });

    this.statusText.setText(`GAME OVER\nWave: ${this.wave}\nKills: ${this.kills}`);
    this.statusText.setAlpha(1);
    this.statusText.setFontSize('36px');

    // 添加重启提示
    this.add.text(400, 400, 'Click to Restart', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5);

    this.input.once('pointerdown', () => {
      this.scene.restart();
    });
  }

  update(time, delta) {
    if (this.gameOver) return;

    // 玩家移动
    const speed = 300;
    this.player.setVelocity(0);

    if (this.cursors.left.isDown || this.wasd.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown || this.wasd.right.isDown) {
      this.player.setVelocityX(speed);
    }

    if (this.cursors.up.isDown || this.wasd.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown || this.wasd.down.isDown) {
      this.player.setVelocityY(speed);
    }

    // 敌人追踪玩家
    this.enemies.children.entries.forEach(enemy => {
      if (enemy.active) {
        const angle = Phaser.Math.Angle.Between(
          enemy.x,
          enemy.y,
          this.player.x,
          this.player.y
        );

        enemy.setVelocity(
          Math.cos(angle) * enemy.speed,
          Math.sin(angle) * enemy.speed
        );

        // 移除超出边界的敌人
        if (enemy.x < -50 || enemy.x > 850 || 
            enemy.y < -50 || enemy.y > 650) {
          enemy.destroy();
        }
      }
    });

    // 移除超出边界的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && 
          (bullet.x < -20 || bullet.x > 820 || 
           bullet.y < -20 || bullet.y > 620)) {
        bullet.setActive(false);
        bullet.setVisible(false);
        bullet.setVelocity(0, 0);
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#1a1a2e',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: EndlessWaveScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 创建一个绿色三角形在3秒内完成弹跳动画并循环
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.GameObjects.Sprite
STEPS:
1. 使用 Graphics 绘制绿色三角形并生成纹理
2. 创建 Sprite 对象使用生成的三角形纹理
3. 使用 Tween 创建弹跳动画（y轴移动+缩放效果模拟弹跳）
4. 设置 Tween 为循环模式，duration 为 3000ms
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制绿色三角形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ff00, 1);

  // 绘制一个等边三角形（中心点在原点）
  graphics.beginPath();
  graphics.moveTo(0, -40);      // 顶点
  graphics.lineTo(-35, 30);     // 左下角
  graphics.lineTo(35, 30);      // 右下角
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('triangle', 70, 70);
  graphics.destroy(); // 销毁 graphics 对象，只保留纹理

  // 创建三角形精灵
  const triangle = this.add.sprite(400, 300, 'triangle');

  // 创建弹跳动画
  // 使用 yoyo 和缩放效果模拟真实的弹跳
  this.tweens.add({
    targets: triangle,
    y: 150,                    // 向上弹跳到 y=150
    scaleY: 1.1,               // 垂直拉伸（起跳时的拉伸效果）
    duration: 750,             // 上升阶段 0.75 秒
    ease: 'Quad.easeOut',      // 减速上升
    yoyo: true,                // 返回原位置
    hold: 0,                   // 在顶点不停留
    repeat: -1,                // 无限循环
    repeatDelay: 0,            // 无延迟
    onYoyo: function() {
      // 下落阶段，三角形被压扁（模拟着地时的形变）
      this.tweens.add({
        targets: triangle,
        scaleY: 0.8,           // 压扁效果
        scaleX: 1.1,           // 横向拉伸
        duration: 375,         // 0.375 秒
        ease: 'Quad.easeIn',   // 加速下落
        yoyo: true,            // 恢复形状
        hold: 100              // 在压扁状态保持 0.1 秒
      });
    },
    callbackScope: this
  });

  // 添加说明文字
  const text = this.add.text(400, 500, '绿色三角形弹跳动画\n循环周期：3秒', {
    fontSize: '20px',
    color: '#ffffff',
    align: 'center'
  });
  text.setOrigin(0.5);
}

new Phaser.Game(config);
```

