class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.isAlive = true; // 状态信号：玩家是否存活
    this.catchCount = 0; // 状态信号：被抓到的次数
    this.escapeTime = 0; // 状态信号：逃脱时间（秒）
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0000ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（黄色圆形）
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xffff00, 1);
    enemyGraphics.fillCircle(20, 20, 20);
    enemyGraphics.generateTexture('enemy', 40, 40);
    enemyGraphics.destroy();

    // 创建玩家精灵
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人精灵
    this.enemy = this.physics.add.sprite(100, 100, 'enemy');
    this.enemy.setCollideWorldBounds(true);

    // 设置键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加碰撞检测
    this.physics.add.overlap(this.player, this.enemy, this.handleCatch, null, this);

    // 添加状态显示文本
    this.statusText = this.add.text(16, 16, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 添加提示文本
    this.add.text(400, 550, '使用方向键移动 | 玩家速度: 360 | 敌人速度: 300', {
      fontSize: '16px',
      fill: '#ffffff'
    }).setOrigin(0.5);

    // 重置游戏功能
    this.input.keyboard.on('keydown-R', () => {
      this.scene.restart();
    });
  }

  update(time, delta) {
    if (!this.isAlive) {
      return;
    }

    // 更新逃脱时间
    this.escapeTime += delta / 1000;

    // 玩家移动控制（速度 300 * 1.2 = 360）
    const playerSpeed = 360;
    this.player.setVelocity(0);

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-playerSpeed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(playerSpeed);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-playerSpeed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(playerSpeed);
    }

    // 对角线移动时归一化速度
    if (this.player.body.velocity.x !== 0 && this.player.body.velocity.y !== 0) {
      this.player.body.velocity.normalize().scale(playerSpeed);
    }

    // 敌人追踪玩家（速度 300）
    const enemySpeed = 300;
    this.physics.moveToObject(this.enemy, this.player, enemySpeed);

    // 计算玩家与敌人的距离
    const distance = Phaser.Math.Distance.Between(
      this.player.x, this.player.y,
      this.enemy.x, this.enemy.y
    );

    // 更新状态文本
    this.statusText.setText(
      `存活: ${this.isAlive ? '是' : '否'}\n` +
      `被抓次数: ${this.catchCount}\n` +
      `逃脱时间: ${this.escapeTime.toFixed(1)}秒\n` +
      `距离敌人: ${distance.toFixed(0)}像素`
    );
  }

  handleCatch(player, enemy) {
    if (!this.isAlive) {
      return;
    }

    // 玩家被抓到
    this.isAlive = false;
    this.catchCount++;

    // 停止所有移动
    this.player.setVelocity(0);
    this.enemy.setVelocity(0);

    // 显示游戏结束信息
    const gameOverText = this.add.text(400, 300, 
      `被抓到了！\n\n` +
      `存活时间: ${this.escapeTime.toFixed(1)}秒\n` +
      `被抓次数: ${this.catchCount}\n\n` +
      `按 R 键重新开始`, 
      {
        fontSize: '32px',
        fill: '#ff0000',
        backgroundColor: '#000000',
        padding: { x: 20, y: 20 },
        align: 'center'
      }
    ).setOrigin(0.5);

    // 添加闪烁效果
    this.tweens.add({
      targets: gameOverText,
      alpha: 0.3,
      duration: 500,
      yoyo: true,
      repeat: -1
    });
  }
}

