REQ: 点击画布任意位置生成64像素橙色三角形
API: Phaser.Input.Events.POINTER_DOWN, Phaser.GameObjects.Graphics, Graphics.fillTriangle
STEPS:
1. 创建 Scene 并配置 Game 实例
2. 在 create 中监听 pointerdown 事件
3. 在点击回调中使用 Graphics 绘制橙色三角形（边长64像素）
4. 将三角形中心定位到点击位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 监听画布点击事件
  this.input.on('pointerdown', (pointer) => {
    // 创建 Graphics 对象用于绘制三角形
    const graphics = this.add.graphics();

    // 设置填充颜色为橙色
    graphics.fillStyle(0xFFA500, 1);

    // 计算等边三角形的顶点坐标
    // 三角形边长为 64 像素
    const size = 64;
    const height = (Math.sqrt(3) / 2) * size; // 等边三角形高度

    // 以点击位置为中心，计算三个顶点坐标
    const x = pointer.x;
    const y = pointer.y;

    // 顶点1（顶部中心）
    const x1 = x;
    const y1 = y - (height * 2 / 3);

    // 顶点2（左下角）
    const x2 = x - size / 2;
    const y2 = y + (height / 3);

    // 顶点3（右下角）
    const x3 = x + size / 2;
    const y3 = y + (height / 3);

    // 绘制填充三角形
    graphics.fillTriangle(x1, y1, x2, y2, x3, y3);
  });

  // 添加提示文本
  this.add.text(10, 10, 'Click anywhere to create orange triangles', {
    fontSize: '18px',
    color: '#ffffff'
  });
}

new Phaser.Game(config);
