    // 状态信号：显示当前索引（用于验证）
    this.particleIndexDisplay.setText(`Particle Index: ${this.currentParticleIndex} / ${this.particleConfigs.length - 1}`);
  }

  update(time, delta) {
    // 可以在这里添加额外的更新逻辑
  }
}

const config = {
