let star;
let cursors;
const SPEED = 120;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制橙色星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xFF8C00, 1); // 橙色

  // 绘制五角星
  // fillStar(x, y, points, innerRadius, outerRadius)
