REQ: 绘制20个随机位置的白色六边形，每个大小为64像素
API: Phaser.GameObjects.Graphics, Graphics.lineStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.strokePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置场景和画布尺寸
2. 在 create 方法中创建 Graphics 对象
3. 编写绘制六边形的函数，计算六边形的6个顶点坐标
4. 循环20次，每次在随机位置绘制一个白色六边形
5. 确保六边形完全在画布范围内
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载资源
}

function create() {
  const graphics = this.add.graphics();

  // 设置白色填充和描边
  graphics.fillStyle(0xffffff, 1);
  graphics.lineStyle(2, 0xffffff, 1);

  // 六边形大小
  const hexSize = 64;
  const hexRadius = hexSize / 2;

  // 绘制六边形的函数
  function drawHexagon(g, x, y, radius) {
    g.beginPath();

    // 计算六边形的6个顶点（从顶部开始，顺时针）
    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI / 3) * i - Math.PI / 2; // -90度起始，使顶点在上方
      const vx = x + radius * Math.cos(angle);
      const vy = y + radius * Math.sin(angle);

      if (i === 0) {
        g.moveTo(vx, vy);
      } else {
        g.lineTo(vx, vy);
      }
    }

    g.closePath();
    g.fillPath();
    g.strokePath();
  }

  // 绘制20个随机位置的六边形
  for (let i = 0; i < 20; i++) {
    // 随机位置，确保六边形完全在画布内
    const x = Phaser.Math.Between(hexRadius, config.width - hexRadius);
    const y = Phaser.Math.Between(hexRadius, config.height - hexRadius);

    drawHexagon(graphics, x, y, hexRadius);
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 让一个方块以每秒 300 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#fillRect, Phaser.GameObjects.Graphics#rotation, Phaser.Scene#update
STEPS:
1. 创建 Graphics 对象绘制方块
2. 在 create 中初始化方块位置和初始旋转角度
3. 在 update 中根据 delta 时间增量计算旋转角度（300度/秒 = 300 * delta / 1000）
4. 使用 setRotation 或直接修改 rotation 属性更新方块旋转
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create, update }
};

let square;

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象绘制方块
  square = this.add.graphics();

  // 设置填充颜色为蓝色
  square.fillStyle(0x00aaff, 1);

  // 绘制一个 100x100 的方块，中心点在 (0, 0)
  // 这样旋转时会围绕中心旋转
  square.fillRect(-50, -50, 100, 100);

  // 设置方块位置到屏幕中心
  square.x = 400;
  square.y = 300;

  // 初始旋转角度为 0
  square.rotation = 0;

  // 添加说明文字
  this.add.text(10, 10, '方块以每秒 300 度的速度旋转', {
    fontSize: '20px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 每秒旋转 300 度
  // 将度数转换为弧度：300 度 = 300 * (Math.PI / 180) 弧度
  // delta 是毫秒，所以除以 1000 转换为秒
  const rotationSpeed = 300 * (Math.PI / 180); // 弧度/秒
  const rotationIncrement = rotationSpeed * (delta / 1000);

  // 更新方块旋转角度
  square.rotation += rotationIncrement;

  // 可选：将旋转角度限制在 0 到 2π 之间，避免数值过大
  if (square.rotation > Math.PI * 2) {
    square.rotation -= Math.PI * 2;
  }
}

new Phaser.Game(config);
