REQ: 白色六边形平滑跟随鼠标指针移动，跟随速度为240
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Distance.Between, Phaser.Math.Angle.Between
STEPS:
1. 使用 Graphics 绘制白色六边形并生成纹理
2. 创建 Sprite 使用生成的六边形纹理
3. 在 update 中获取鼠标指针位置
4. 计算六边形到鼠标的距离和角度
5. 根据速度240和时间增量平滑移动六边形朝向鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let hexagon;
let pointer;

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制白色六边形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);

  // 绘制六边形（中心点为原点）
  const radius = 30;
  const sides = 6;
  const angle = (Math.PI * 2) / sides;

  graphics.beginPath();
  for (let i = 0; i < sides; i++) {
    const x = radius * Math.cos(angle * i - Math.PI / 2);
    const y = radius * Math.sin(angle * i - Math.PI / 2);
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  const textureSize = radius * 2 + 10;
  graphics.generateTexture('hexagon', textureSize, textureSize);
  graphics.destroy();

  // 创建六边形精灵，初始位置在屏幕中心
  hexagon = this.add.sprite(400, 300, 'hexagon');

  // 获取指针引用
  pointer = this.input.activePointer;
}

function update(time, delta) {
  // 计算六边形到鼠标指针的距离
  const distance = Phaser.Math.Distance.Between(
    hexagon.x,
    hexagon.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于1像素，则移动六边形
  if (distance > 1) {
    // 计算移动角度
    const angle = Phaser.Math.Angle.Between(
      hexagon.x,
      hexagon.y,
      pointer.x,
      pointer.y
    );

    // 根据速度和时间增量计算移动距离
    const speed = 240; // 像素/秒
    const moveDistance = speed * (delta / 1000); // 转换为像素/帧

    // 如果移动距离小于剩余距离，则正常移动；否则直接到达目标
    if (moveDistance < distance) {
      hexagon.x += Math.cos(angle) * moveDistance;
      hexagon.y += Math.sin(angle) * moveDistance;
    } else {
      hexagon.x = pointer.x;
      hexagon.y = pointer.y;
    }
  }
}

new Phaser.Game(config);
```

