REQ: 在随机位置绘制12个黄色菱形，每个大小为48像素
API: Phaser.GameObjects.Graphics, Graphics#fillStyle, Graphics#fillPath, Graphics#beginPath, Graphics#moveTo, Graphics#lineTo, Graphics#closePath
STEPS:
1. 创建 Phaser Game 配置，使用 800x600 画布
2. 在 create 方法中循环12次
3. 每次循环创建一个 Graphics 对象
4. 使用 fillStyle 设置黄色填充
5. 使用 beginPath/moveTo/lineTo 绘制菱形路径（四个顶点）
6. 使用 closePath 和 fillPath 完成绘制
7. 使用 setPosition 将菱形放置在随机位置（考虑边界）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 菱形大小
  const diamondSize = 48;
  const halfSize = diamondSize / 2;

  // 绘制12个随机位置的黄色菱形
  for (let i = 0; i < 12; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置黄色填充
    graphics.fillStyle(0xffff00, 1);

    // 开始绘制路径
    graphics.beginPath();

    // 绘制菱形的四个顶点（以中心为原点）
    // 上顶点
    graphics.moveTo(0, -halfSize);
    // 右顶点
    graphics.lineTo(halfSize, 0);
    // 下顶点
    graphics.lineTo(0, halfSize);
    // 左顶点
    graphics.lineTo(-halfSize, 0);

    // 闭合路径
    graphics.closePath();

    // 填充路径
    graphics.fillPath();

    // 设置随机位置（考虑菱形大小，避免超出边界）
    const randomX = Phaser.Math.Between(halfSize, config.width - halfSize);
    const randomY = Phaser.Math.Between(halfSize, config.height - halfSize);
    graphics.setPosition(randomX, randomY);
  }
}

new Phaser.Game(config);
```

