[PLAN]
REQ: 实现AI追踪玩家的对战游戏，玩家收集20个物品获胜，被AI碰到失败
API: Phaser.Physics.Arcade.Sprite, Phaser.Physics.Arcade.moveToObject, Phaser.Physics.Arcade.overlap, Phaser.GameObjects.Graphics
STEPS:
1. 创建玩家精灵（蓝色方块）和AI精灵（绿色方块），使用Graphics生成纹理
2. 随机生成20个可收集物品（黄色圆圈）
3. 在update中实现AI以360速度追踪玩家的逻辑
4. 使用键盘控制玩家移动
5. 检测玩家与物品的碰撞（收集），以及玩家与AI的碰撞（失败）
6. 显示得分和游戏状态文本
7. 实现胜利和失败的游戏结束逻辑
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 游戏状态变量
let player;
let aiEnemy;
let items;
let cursors;
let scoreText;
let statusText;
let score = 0;
let gameOver = false;
let gameWon = false;

const PLAYER_SPEED = 200;
const AI_SPEED = 360;
const TOTAL_ITEMS = 20;

function preload() {
  // 使用Graphics创建纹理，无需外部资源
}

function create() {
  // 创建玩家纹理（蓝色方块）
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x0000ff, 1);
  playerGraphics.fillRect(0, 0, 32, 32);
  playerGraphics.generateTexture('player', 32, 32);
  playerGraphics.destroy();

  // 创建AI纹理（绿色方块）
  const aiGraphics = this.add.graphics();
  aiGraphics.fillStyle(0x00ff00, 1);
  aiGraphics.fillRect(0, 0, 32, 32);
  aiGraphics.generateTexture('ai', 32, 32);
  aiGraphics.destroy();

  // 创建物品纹理（黄色圆圈）
  const itemGraphics = this.add.graphics();
  itemGraphics.fillStyle(0xffff00, 1);
  itemGraphics.fillCircle(8, 8, 8);
  itemGraphics.generateTexture('item', 16, 16);
  itemGraphics.destroy();

  // 创建玩家
  player = this.physics.add.sprite(100, 100, 'player');
  player.setCollideWorldBounds(true);

  // 创建AI敌人
  aiEnemy = this.physics.add.sprite(700, 500, 'ai');
  aiEnemy.setCollideWorldBounds(true);

  // 创建物品组
  items = this.physics.add.group();

  // 使用固定种子生成随机位置（确保确定性）
  const seed = 12345;
  let randomState = seed;

  function seededRandom() {
    randomState = (randomState * 9301 + 49297) % 233280;
    return randomState / 233280;
  }

  // 生成20个物品
  for (let i = 0; i < TOTAL_ITEMS; i++) {
    const x = 50 + seededRandom() * 700;
    const y = 50 + seededRandom() * 500;
    const item = items.create(x, y, 'item');
    item.setCollideWorldBounds(true);
  }

  // 设置碰撞检测
  this.physics.add.overlap(player, items, collectItem, null, this);
  this.physics.add.overlap(player, aiEnemy, hitAI, null, this);

  // 创建键盘控制
  cursors = this.input.keyboard.createCursorKeys();

  // 创建UI文本
  scoreText = this.add.text(16, 16, 'Score: 0 / 20', {
    fontSize: '24px',
    fill: '#ffffff'
  });

  statusText = this.add.text(400, 300, '', {
    fontSize: '48px',
    fill: '#ffffff',
    align: 'center'
  });
  statusText.setOrigin(0.5);

  // 添加说明文本
  this.add.text(16, 550, 'Use Arrow Keys to move | Collect 20 items to win | Avoid the green AI!', {
    fontSize: '16px',
    fill: '#cccccc'
  });
}

function update() {
  if (gameOver || gameWon) {
    return;
  }

  // 玩家移动控制
  player.setVelocity(0);

  if (cursors.left.isDown) {
    player.setVelocityX(-PLAYER_SPEED);
  } else if (cursors.right.isDown) {
    player.setVelocityX(PLAYER_SPEED);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-PLAYER_SPEED);
  } else if (cursors.down.isDown) {
    player.setVelocityY(PLAYER_SPEED);
  }

  // AI追踪玩家逻辑
  this.physics.moveToObject(aiEnemy, player, AI_SPEED);
}

function collectItem(player, item) {
  // 收集物品
  item.destroy();
  score++;

  scoreText.setText('Score: ' + score + ' / 20');

  // 检查是否获胜
  if (score >= TOTAL_ITEMS) {
    gameWon = true;
    player.setVelocity(0);
    aiEnemy.setVelocity(0);
    statusText.setText('YOU WIN!\nCollected all items!');
    statusText.setStyle({ fill: '#00ff00' });
  }
}

function hitAI(player, aiEnemy) {
  // 被AI碰到，游戏失败
  if (!gameOver && !gameWon) {
    gameOver = true;
    player.setVelocity(0);
    aiEnemy.setVelocity(0);
    player.setTint(0xff0000);
    statusText.setText('GAME OVER!\nCaught by AI!');
    statusText.setStyle({ fill: '#ff0000' });
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 创建一个六边形，使用 tween 动画实现 2 秒内缩放到 80% 后恢复，循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制六边形并生成纹理
2. 创建 Sprite 对象使用生成的六边形纹理
3. 使用 tweens 创建缩放动画，从 1 到 0.8 再回到 1
4. 设置 yoyo 和 loop 属性实现循环播放
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制六边形
  const graphics = this.add.graphics();

  // 六边形参数
  const hexRadius = 80;
  const centerX = 100;
  const centerY = 100;

  // 绘制六边形
  graphics.fillStyle(0x00aaff, 1);
  graphics.lineStyle(4, 0xffffff, 1);

  // 计算六边形的六个顶点
  const points = [];
  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i; // 每个角度间隔 60 度
    const x = centerX + hexRadius * Math.cos(angle);
    const y = centerY + hexRadius * Math.sin(angle);
    points.push(new Phaser.Geom.Point(x, y));
  }

  // 绘制填充的六边形
  graphics.beginPath();
  graphics.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) {
    graphics.lineTo(points[i].x, points[i].y);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('hexagon', 200, 200);
  graphics.destroy();

  // 创建六边形精灵并居中显示
  const hexagon = this.add.sprite(400, 300, 'hexagon');

  // 创建缩放动画
  // 从原始大小 (1) 缩放到 80% (0.8)，然后恢复到原始大小
  this.tweens.add({
    targets: hexagon,
    scaleX: 0.8,
    scaleY: 0.8,
    duration: 2000, // 2 秒
    yoyo: true, // 动画结束后反向播放（恢复到原始大小）
    loop: -1, // 无限循环 (-1 表示永久循环)
    ease: 'Sine.easeInOut' // 使用平滑的缓动函数
  });

  // 添加文字说明
  this.add.text(400, 500, '六边形缩放动画 (循环播放)', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

