  width: 800,
  height: 600,
  backgroundColor: '#1a1a2e',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 }, // 无全局重力
      debug: false
    }
  },
  scene: GravityFieldScene
};

new Phaser.Game(config);
