  const diamond = this.add.sprite(400, 300, 'diamond');

  // 创建缩放动画
  this.tweens.add({
    targets: diamond,
    scaleX: 0.16,        // 缩放到 16%
    scaleY: 0.16,        // 缩放到 16%
