  triangle.setOrigin(0.5, 0.5);

  // 创建旋转动画
  this.tweens.add({
    targets: triangle,           // 动画目标对象
    angle: 360,                  // 旋转到 360 度
    duration: 1000,              // 持续时间 1 秒
    ease: 'Linear',              // 线性缓动，保持匀速旋转
    repeat: -1,                  // 无限循环 (-1 表示永久重复)
    onRepeat: function() {
