  }

  create() {
    const worldWidth = 2000;
    const worldHeight = 1500;

    // 设置世界边界
    this.physics.world.setBounds(0, 0, worldWidth, worldHeight);

    // 创建背景网格
    this.createBackground(worldWidth, worldHeight);

    // 程序化生成玩家纹理
    this.createPlayerTexture();

