    const x2 = -size / 2;
    const y2 = height / 3; // 左下角
    const x3 = size / 2;
    const y3 = height / 3; // 右下角

    graphics.fillTriangle(x1, y1, x2, y2, x3, y3);

    // 设置随机位置（考虑三角形大小，避免超出边界）
    const margin = 20;
    const randomX = Phaser.Math.Between(margin, config.width - margin);
