// MenuScene - 菜单场景
class MenuScene extends Phaser.Scene {
  constructor() {
    super('MenuScene');
  }

  preload() {
    // 菜单场景无需预加载资源
  }

  create() {
    const { width, height } = this.cameras.main;

    // 添加标题
    const title = this.add.text(width / 2, height / 3, 'Phaser3 游戏', {
