REQ: 让一个菱形以每秒 360 度的速度持续旋转
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#fillStyle, Phaser.GameObjects.Graphics#beginPath, Phaser.GameObjects.Graphics#moveTo, Phaser.GameObjects.Graphics#lineTo, Phaser.GameObjects.Graphics#closePath, Phaser.GameObjects.Graphics#fillPath, Phaser.GameObjects.Graphics#setRotation, Phaser.Scene#update
STEPS:
1. 创建 Graphics 对象并绘制菱形路径（使用 beginPath/moveTo/lineTo 绘制四个顶点）
2. 设置菱形的原点为中心点，以便旋转效果正确
3. 在 update 方法中根据 delta 时间累加旋转角度，每秒旋转 360 度（2π 弧度）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let diamond;

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象绘制菱形
  diamond = this.add.graphics();

  // 设置填充颜色
  diamond.fillStyle(0x00ff00, 1);

  // 绘制菱形（中心在原点）
  diamond.beginPath();
  diamond.moveTo(0, -60);    // 上顶点
  diamond.lineTo(50, 0);     // 右顶点
  diamond.lineTo(0, 60);     // 下顶点
  diamond.lineTo(-50, 0);    // 左顶点
  diamond.closePath();
  diamond.fillPath();

  // 将菱形位置设置到屏幕中心
  diamond.x = 400;
  diamond.y = 300;
}

function update(time, delta) {
  // 每秒旋转 360 度 = 2π 弧度
  // delta 是毫秒，转换为秒：delta / 1000
  // 旋转速度：2 * Math.PI 弧度/秒
  const rotationSpeed = 2 * Math.PI; // 弧度/秒
  const rotationDelta = rotationSpeed * (delta / 1000);

  // 累加旋转角度
  diamond.rotation += rotationDelta;
}

