API: Phaser.Physics.Arcade, Graphics.fillCircle, Physics.add.sprite, Physics.add.collider, Body.setBounce, Body.setCollideWorldBounds, Body.setVelocity
STEPS:
1. 配置物理系统启用 Arcade Physics
2. 使用 Graphics 生成粉色圆形纹理
3. 创建 8 个物理精灵球体，设置随机位置和速度
4. 设置球体边界碰撞反弹（bounce=1）和世界边界碰撞
5. 添加球体之间的碰撞检测
6. 添加状态信号记录碰撞次数
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.collisionCount = 0; // 状态信号：碰撞计数
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建粉色圆形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xff69b4, 1); // 粉色
    graphics.fillCircle(16, 16, 16); // 半径16的圆
    graphics.generateTexture('pinkBall', 32, 32);
    graphics.destroy();

    // 创建球体组
    this.balls = this.physics.add.group({
      key: 'pinkBall',
      repeat: 7, // 创建8个球（0-7）
      bounceX: 1,
      bounceY: 1,
      collideWorldBounds: true
    });

    // 设置每个球的随机位置和速度
    const speed = 120;
    this.balls.children.entries.forEach((ball, index) => {
      // 随机位置（避免边界）
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 550);
      ball.setPosition(x, y);

      // 随机方向的速度（速度大小为120）
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed;
      ball.body.setVelocity(vx, vy);

      // 确保完全弹性碰撞
      ball.body.setBounce(1, 1);
    });

    // 添加球体之间的碰撞检测
    this.physics.add.collider(this.balls, this.balls, this.onBallCollision, null, this);

    // 显示碰撞计数文本
    this.collisionText = this.add.text(10, 10, 'Collisions: 0', {
      fontSize: '24px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 绘制边界提示
    const border = this.add.graphics();
    border.lineStyle(2, 0xffffff, 0.5);
    border.strokeRect(0, 0, 800, 600);

    // 添加说明文本
    this.add.text(10, 570, 'Pink balls bouncing with elastic collision', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 5, y: 2 }
    });
  }

  onBallCollision(ball1, ball2) {
    // 碰撞回调：增加计数
    this.collisionCount++;
    this.collisionText.setText('Collisions: ' + this.collisionCount);
  }

  update(time, delta) {
    // 确保球速度保持恒定（补偿物理引擎的能量损失）
    this.balls.children.entries.forEach((ball) => {
      const body = ball.body;
      const currentSpeed = Math.sqrt(body.velocity.x ** 2 + body.velocity.y ** 2);

      // 如果速度偏离120太多，进行修正
      if (Math.abs(currentSpeed - 120) > 1) {
        const scale = 120 / currentSpeed;
        body.setVelocity(body.velocity.x * scale, body.velocity.y * scale);
      }
    });
  }
}

