REQ: 实现紫色敌人从上方以120速度落下，玩家左右移动躲避，碰到游戏结束的躲避游戏
API: Phaser.Physics.Arcade, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics, this.physics.add.overlap
STEPS:
1. 创建 Arcade 物理系统配置，初始化游戏场景
2. 使用 Graphics 生成玩家（绿色矩形）和敌人（紫色矩形）纹理
3. 创建玩家精灵，添加键盘左右控制（A/D 或方向键）
4. 创建敌人组，定时从顶部随机位置生成敌人，设置向下速度 120
5. 添加碰撞检测，碰到敌人时触发游戏结束，显示 Game Over 文本
6. 添加得分系统，敌人离开屏幕底部时增加分数
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let player;
let enemies;
let cursors;
let gameOver = false;
let score = 0;
let scoreText;
let gameOverText;
let keysAD;

function preload() {
  // 创建玩家纹理（绿色矩形）
  const playerGraphics = this.add.graphics();
  playerGraphics.fillStyle(0x00ff00, 1);
  playerGraphics.fillRect(0, 0, 40, 40);
  playerGraphics.generateTexture('player', 40, 40);
  playerGraphics.destroy();

  // 创建敌人纹理（紫色矩形）
  const enemyGraphics = this.add.graphics();
  enemyGraphics.fillStyle(0x9900ff, 1);
  enemyGraphics.fillRect(0, 0, 30, 30);
  enemyGraphics.generateTexture('enemy', 30, 30);
  enemyGraphics.destroy();
}

function create() {
  // 创建玩家
  player = this.physics.add.sprite(400, 550, 'player');
  player.setCollideWorldBounds(true);
  player.body.setSize(40, 40);

  // 创建敌人组
  enemies = this.physics.add.group();

  // 设置键盘输入
  cursors = this.input.keyboard.createCursorKeys();
  keysAD = this.input.keyboard.addKeys({
    a: Phaser.Input.Keyboard.KeyCodes.A,
    d: Phaser.Input.Keyboard.KeyCodes.D
  });

  // 创建分数文本
  scoreText = this.add.text(16, 16, 'Score: 0', {
    fontSize: '32px',
    fill: '#ffffff'
  });

  // 创建游戏结束文本（初始隐藏）
  gameOverText = this.add.text(400, 300, 'GAME OVER', {
    fontSize: '64px',
    fill: '#ff0000'
  });
  gameOverText.setOrigin(0.5);
  gameOverText.setVisible(false);

  // 定时生成敌人（每1秒）
  this.time.addEvent({
    delay: 1000,
    callback: spawnEnemy,
    callbackScope: this,
    loop: true
  });

  // 添加碰撞检测
  this.physics.add.overlap(player, enemies, hitEnemy, null, this);
}

function update() {
  if (gameOver) {
    return;
  }

  // 玩家左右移动控制
  if (cursors.left.isDown || keysAD.a.isDown) {
    player.setVelocityX(-300);
  } else if (cursors.right.isDown || keysAD.d.isDown) {
    player.setVelocityX(300);
  } else {
    player.setVelocityX(0);
  }

  // 检查敌人是否离开屏幕底部
  enemies.children.entries.forEach(enemy => {
    if (enemy.y > 600) {
      enemy.destroy();
      score += 10;
      scoreText.setText('Score: ' + score);
    }
  });
}

function spawnEnemy() {
  if (gameOver) {
    return;
  }

  // 在顶部随机位置生成敌人
  const x = Phaser.Math.Between(50, 750);
  const enemy = enemies.create(x, -30, 'enemy');

  // 设置敌人向下速度为 120
  enemy.setVelocityY(120);
  enemy.body.setSize(30, 30);
}

function hitEnemy(player, enemy) {
  // 游戏结束
  gameOver = true;

  // 停止物理引擎
  this.physics.pause();

  // 玩家变红
  player.setTint(0xff0000);

  // 显示游戏结束文本
  gameOverText.setVisible(true);

  // 添加重启提示
  const restartText = this.add.text(400, 370, 'Click to Restart', {
    fontSize: '24px',
    fill: '#ffffff'
  });
  restartText.setOrigin(0.5);

  // 点击重启游戏
  this.input.once('pointerdown', () => {
    this.scene.restart();
    gameOver = false;
    score = 0;
  });
}

const game = new Phaser.Game(config);
```

