2. 使用 Graphics 绘制玩家（蓝色方块）和收集物（金色圆形）
3. 实现键盘控制（方向键）移动玩家
4. 使用物理系统检测玩家与收集物的碰撞
5. 收集完当前关卡所有物品后自动进入下一关，重置场景并增加物品数量
6. 显示当前关卡和总分数的 UI 文本
7. 通关后显示胜利信息
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.level = 1;
    this.score = 0;
    this.maxLevel = 10;
  }

  preload() {
    // 使用 Graphics 创建纹理，无需外部资源
  }

  create() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x4444ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建收集物纹理
    const collectibleGraphics = this.add.graphics();
    collectibleGraphics.fillStyle(0xffdd00, 1);
    collectibleGraphics.fillCircle(12, 12, 12);
    collectibleGraphics.generateTexture('collectible', 24, 24);
    collectibleGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);
    this.player.body.setSize(28, 28);

    // 创建收集物组
    this.collectibles = this.physics.add.group();
    this.createCollectibles();

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.collectibles,
      this.collectItem,
      null,
      this
    );

    // 创建键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建 UI 文本
    this.levelText = this.add.text(16, 16, `Level: ${this.level}`, {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    this.scoreText = this.add.text(16, 50, `Score: ${this.score}`, {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    this.itemsText = this.add.text(16, 84, '', {
      fontSize: '20px',
      fill: '#ffdd00',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 3
    });

    this.updateItemsText();

    // 胜利文本（初始隐藏）
    this.winText = this.add.text(400, 300, '', {
      fontSize: '48px',
      fill: '#00ff00',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 6
    });
    this.winText.setOrigin(0.5);
    this.winText.setVisible(false);
  }

  createCollectibles() {
    // 每关的收集物数量 = 3 + level
    const itemCount = 3 + this.level;

    // 使用固定种子生成位置（基于关卡）
    const seed = this.level * 1000;
    const positions = this.generatePositions(itemCount, seed);

    positions.forEach(pos => {
      const collectible = this.collectibles.create(pos.x, pos.y, 'collectible');
      collectible.setCircle(12);
      collectible.body.setAllowGravity(false);
      collectible.body.immovable = true;
    });
  }

  generatePositions(count, seed) {
    // 简单的伪随机数生成器（确定性）
    let random = seed;
    const nextRandom = () => {
      random = (random * 9301 + 49297) % 233280;
      return random / 233280;
    };

    const positions = [];
    const margin = 50;
    const minDistance = 80;

    for (let i = 0; i < count; i++) {
      let attempts = 0;
      let pos;

      do {
        pos = {
          x: margin + nextRandom() * (800 - 2 * margin),
          y: margin + nextRandom() * (600 - 2 * margin)
        };
        attempts++;
      } while (
        attempts < 50 &&
        (this.tooCloseToPlayer(pos) || this.tooCloseToOthers(pos, positions, minDistance))
      );

      positions.push(pos);
    }

    return positions;
  }

  tooCloseToPlayer(pos) {
    const dx = pos.x - 400;
    const dy = pos.y - 300;
    return Math.sqrt(dx * dx + dy * dy) < 100;
  }

  tooCloseToOthers(pos, others, minDist) {
    return others.some(other => {
      const dx = pos.x - other.x;
      const dy = pos.y - other.y;
      return Math.sqrt(dx * dx + dy * dy) < minDist;
    });
  }

  collectItem(player, collectible) {
    collectible.destroy();
    this.score += 10;
    this.scoreText.setText(`Score: ${this.score}`);
    this.updateItemsText();

    // 检查是否收集完所有物品
    if (this.collectibles.countActive() === 0) {
      this.nextLevel();
    }
  }

  nextLevel() {
    this.level++;

    if (this.level > this.maxLevel) {
      // 游戏通关
      this.showVictory();
    } else {
      // 进入下一关
      this.levelText.setText(`Level: ${this.level}`);

      // 重置玩家位置
      this.player.setPosition(400, 300);
      this.player.setVelocity(0, 0);

      // 创建新关卡的收集物
      this.createCollectibles();
      this.updateItemsText();

      // 显示关卡提示
      const levelUpText = this.add.text(400, 200, `Level ${this.level}!`, {
        fontSize: '36px',
        fill: '#ffff00',
        fontFamily: 'Arial',
        stroke: '#000000',
        strokeThickness: 5
      });
      levelUpText.setOrigin(0.5);

      this.tweens.add({
        targets: levelUpText,
        alpha: 0,
        y: 150,
        duration: 1500,
        ease: 'Power2',
        onComplete: () => levelUpText.destroy()
      });
    }
  }

  showVictory() {
    this.winText.setText(`YOU WIN!\nFinal Score: ${this.score}`);
    this.winText.setVisible(true);
    this.player.setVelocity(0, 0);
    this.cursors = null; // 禁用控制

    // 添加闪烁效果
    this.tweens.add({
      targets: this.winText,
      scaleX: 1.2,
      scaleY: 1.2,
      duration: 500,
      yoyo: true,
      repeat: -1
    });
  }

  updateItemsText() {
    const remaining = this.collectibles.countActive();
    const total = 3 + this.level;
    this.itemsText.setText(`Items: ${total - remaining}/${total}`);
  }

  update(time, delta) {
    if (!this.cursors || this.level > this.maxLevel) return;

    const speed = 200;

    // 重置速度
    this.player.setVelocity(0);

    // 键盘控制
    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    }

    // 对角线移动时标准化速度
    if (this.player.body.velocity.x !== 0 && this.player.body.velocity.y !== 0) {
      this.player.body.velocity.normalize().scale(speed);
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#333333',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 每隔 0.5 秒在随机位置生成蓝色圆形，最多生成 8 个
API: Phaser.Time.Clock#addEvent, Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#fillCircle
STEPS:
1. 创建 Scene 并初始化圆形计数器
2. 在 create 中使用 Graphics 创建蓝色圆形纹理
3. 使用 time.addEvent 创建定时器，每 0.5 秒触发一次
4. 在定时器回调中生成随机位置的圆形精灵
5. 当圆形数量达到 8 个时停止定时器
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

let circleCount = 0;
let timerEvent = null;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 创建蓝色圆形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x0000ff, 1);
  graphics.fillCircle(25, 25, 25); // 在 (25, 25) 位置绘制半径为 25 的圆
  graphics.generateTexture('blueCircle', 50, 50);
  graphics.destroy(); // 生成纹理后销毁 graphics 对象

  // 创建定时器事件，每 0.5 秒执行一次
  timerEvent = this.time.addEvent({
    delay: 500, // 0.5 秒 = 500 毫秒
    callback: spawnCircle,
    callbackScope: this,
    loop: true
  });
}

function spawnCircle() {
  // 检查是否已经生成了 8 个圆形
  if (circleCount >= 8) {
    timerEvent.remove(); // 停止定时器
    return;
  }

  // 生成随机位置（确保圆形完全在画布内）
  const x = Phaser.Math.Between(25, 775);
  const y = Phaser.Math.Between(25, 575);

  // 创建圆形精灵
  const circle = this.add.image(x, y, 'blueCircle');

  // 增加计数器
  circleCount++;

  // 可选：添加一些视觉效果，让圆形从小变大
  circle.setScale(0);
  this.tweens.add({
    targets: circle,
    scale: 1,
    duration: 200,
    ease: 'Back.easeOut'
  });
}

new Phaser.Game(config);
```

[PLAN]
REQ: 橙色玩家移出边界时从对侧出现（循环地图效果），移动速度 300
API: Phaser.Physics.Arcade.Sprite, this.input.keyboard.createCursorKeys(), this.physics.add.sprite(), graphics.generateTexture()
STEPS:
1. 创建 800x600 游戏场景，启用 Arcade 物理系统
2. 使用 Graphics 绘制橙色方块纹理作为玩家
3. 创建物理精灵，设置移动速度 300
4. 监听键盘输入（方向键）控制玩家移动
5. 在 update 中检测边界，实现循环地图效果（左边界->右边界，上边界->下边界等）
6. 添加状态变量记录玩家穿越边界次数作为验证信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.wrapCount = 0; // 状态信号：记录穿越边界次数
  }

  preload() {
    // 使用 Graphics 创建橙色玩家纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xFF8C00, 1); // 橙色
    graphics.fillRect(0, 0, 40, 40);
    graphics.generateTexture('player', 40, 40);
    graphics.destroy();
  }

  create() {
    // 创建玩家精灵（居中位置）
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(false); // 关闭世界边界碰撞，允许移出

    // 设置移动速度
    this.moveSpeed = 300;

    // 创建键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加 WASD 键支持
    this.keys = {
      W: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.W),
      A: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.A),
      S: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.S),
      D: this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.D)
    };

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    this.updateStatusText();
  }

  update(time, delta) {
    // 重置速度
    this.player.setVelocity(0);

    // 处理键盘输入
    if (this.cursors.left.isDown || this.keys.A.isDown) {
      this.player.setVelocityX(-this.moveSpeed);
    } else if (this.cursors.right.isDown || this.keys.D.isDown) {
      this.player.setVelocityX(this.moveSpeed);
    }

    if (this.cursors.up.isDown || this.keys.W.isDown) {
      this.player.setVelocityY(-this.moveSpeed);
    } else if (this.cursors.down.isDown || this.keys.S.isDown) {
      this.player.setVelocityY(this.moveSpeed);
    }

    // 边界循环检测
    const playerWidth = this.player.width;
    const playerHeight = this.player.height;
    let wrapped = false;

    // 左右边界
    if (this.player.x < -playerWidth / 2) {
      this.player.x = this.cameras.main.width + playerWidth / 2;
      wrapped = true;
    } else if (this.player.x > this.cameras.main.width + playerWidth / 2) {
      this.player.x = -playerWidth / 2;
      wrapped = true;
    }

    // 上下边界
    if (this.player.y < -playerHeight / 2) {
      this.player.y = this.cameras.main.height + playerHeight / 2;
      wrapped = true;
    } else if (this.player.y > this.cameras.main.height + playerHeight / 2) {
      this.player.y = -playerHeight / 2;
      wrapped = true;
    }

    // 更新穿越计数
    if (wrapped) {
      this.wrapCount++;
      this.updateStatusText();
    }
  }

  updateStatusText() {
    this.statusText.setText(
      `Position: (${Math.round(this.player.x)}, ${Math.round(this.player.y)})\n` +
      `Wrap Count: ${this.wrapCount}\n` +
      `Speed: ${this.moveSpeed}\n` +
      `Use Arrow Keys or WASD to move`
    );
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现可拖拽的紫色菱形，拖拽时变色，松手后回到初始位置
API: Graphics.fillStyle, Graphics.fillPath, InputPlugin.setDraggable, Events.DRAG, Events.DRAG_START, Events.DRAG_END
STEPS:
1. 使用 Graphics 绘制紫色菱形并生成纹理
2. 创建 Sprite 并设置为可拖拽
3. 监听 DRAG_START 事件改变颜色为亮紫色
4. 监听 DRAG 事件更新位置
5. 监听 DRAG_END 事件恢复颜色并回到初始位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 记录初始位置
  const initialX = 400;
  const initialY = 300;

  // 创建紫色菱形纹理
  const graphics = this.add.graphics();

  // 绘制紫色菱形
  graphics.fillStyle(0x9b59b6, 1); // 紫色
  graphics.beginPath();
  graphics.moveTo(50, 0);    // 上顶点
  graphics.lineTo(100, 50);  // 右顶点
  graphics.lineTo(50, 100);  // 下顶点
  graphics.lineTo(0, 50);    // 左顶点
  graphics.closePath();
  graphics.fillPath();
  graphics.generateTexture('diamond', 100, 100);
  graphics.destroy();

  // 创建拖拽时的亮紫色菱形纹理
  const graphicsDrag = this.add.graphics();
  graphicsDrag.fillStyle(0xd896ff, 1); // 亮紫色
  graphicsDrag.beginPath();
  graphicsDrag.moveTo(50, 0);
  graphicsDrag.lineTo(100, 50);
  graphicsDrag.lineTo(50, 100);
  graphicsDrag.lineTo(0, 50);
  graphicsDrag.closePath();
  graphicsDrag.fillPath();
  graphicsDrag.generateTexture('diamondDrag', 100, 100);
  graphicsDrag.destroy();

  // 创建菱形精灵
  const diamond = this.add.sprite(initialX, initialY, 'diamond');

  // 设置为可交互和可拖拽
  diamond.setInteractive({ draggable: true });

  // 添加提示文本
  const text = this.add.text(400, 50, '拖拽菱形试试！', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  // 监听拖拽开始事件
  this.input.on(Phaser.Input.Events.DRAG_START, (pointer, gameObject) => {
    // 改变为亮紫色
    gameObject.setTexture('diamondDrag');
    // 增加缩放效果
    gameObject.setScale(1.1);
    text.setText('拖拽中...');
  });

  // 监听拖拽事件
  this.input.on(Phaser.Input.Events.DRAG, (pointer, gameObject, dragX, dragY) => {
    // 更新位置跟随鼠标
    gameObject.x = dragX;
    gameObject.y = dragY;
  });

  // 监听拖拽结束事件
  this.input.on(Phaser.Input.Events.DRAG_END, (pointer, gameObject) => {
    // 恢复原始紫色
    gameObject.setTexture('diamond');
    // 恢复缩放
    gameObject.setScale(1);

    // 添加缓动动画回到初始位置
    this.tweens.add({
      targets: gameObject,
      x: initialX,
      y: initialY,
      duration: 500,
      ease: 'Back.easeOut'
    });

    text.setText('拖拽菱形试试！');
  });

  // 添加鼠标悬停效果
  diamond.on('pointerover', () => {
    if (!this.input.dragState) {
      diamond.setScale(1.05);
    }
  });

  diamond.on('pointerout', () => {
    if (!this.input.dragState) {
      diamond.setScale(1);
    }
  });
}

new Phaser.Game(config);
```

[PLAN]
REQ: 创建一个粉色矩形，使用 Tween 动画实现 alpha 透明度变化的闪烁效果，3秒一次循环
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager#add, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制粉色矩形并生成纹理
2. 创建 Sprite 对象使用该纹理
3. 使用 tweens.add 创建 alpha 透明度动画，从1到0再到1，duration 3000ms，loop -1 实现循环闪烁
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制粉色矩形并生成纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xff69b4, 1); // 粉色
  graphics.fillRect(0, 0, 200, 150);
  graphics.generateTexture('pinkRect', 200, 150);
  graphics.destroy();

  // 创建粉色矩形精灵，放置在屏幕中央
  const pinkRect = this.add.sprite(400, 300, 'pinkRect');

  // 创建闪烁动画：透明度从 1 -> 0 -> 1，持续 3 秒，无限循环
  this.tweens.add({
    targets: pinkRect,
    alpha: { from: 1, to: 0 },
    duration: 1500, // 1.5秒淡出
    yoyo: true, // 自动反向播放（淡入）
    repeat: -1, // 无限循环
    ease: 'Sine.easeInOut' // 平滑的缓动效果
  });

  // 添加提示文本
  this.add.text(400, 500, 'Pink Rectangle Blinking (3s cycle)', {
    fontSize: '20px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
