REQ: 绘制3个随机位置的灰色星形，每个大小为64像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.lineTo, Graphics.closePath, Graphics.fillPath, Math.random
STEPS:
1. 创建 Phaser.Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象用于绘制星形
3. 编写绘制星形的函数，使用 beginPath 和 lineTo 绘制5个尖角的星形路径
4. 循环3次，每次生成随机位置（考虑星形大小避免超出边界）
5. 在随机位置绘制灰色填充的星形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  const graphics = this.add.graphics();

  // 设置灰色填充
  graphics.fillStyle(0x808080, 1);

  // 绘制3个随机位置的星形
  for (let i = 0; i < 3; i++) {
    // 生成随机位置，确保星形不超出边界
    // 星形半径为32像素（大小64的一半），留出边距
    const x = 50 + Math.random() * (800 - 100);
    const y = 50 + Math.random() * (600 - 100);

    drawStar(graphics, x, y, 5, 32, 16);
  }
}

/**
 * 绘制星形
 * @param {Phaser.GameObjects.Graphics} graphics - Graphics对象
 * @param {number} cx - 中心x坐标
 * @param {number} cy - 中心y坐标
 * @param {number} spikes - 尖角数量
 * @param {number} outerRadius - 外半径
 * @param {number} innerRadius - 内半径
 */
function drawStar(graphics, cx, cy, spikes, outerRadius, innerRadius) {
  let rot = Math.PI / 2 * 3;
  let x = cx;
  let y = cy;
  const step = Math.PI / spikes;

  graphics.beginPath();
  graphics.moveTo(cx, cy - outerRadius);

  for (let i = 0; i < spikes; i++) {
    x = cx + Math.cos(rot) * outerRadius;
    y = cy + Math.sin(rot) * outerRadius;
    graphics.lineTo(x, y);
    rot += step;

    x = cx + Math.cos(rot) * innerRadius;
    y = cy + Math.sin(rot) * innerRadius;
    graphics.lineTo(x, y);
    rot += step;
  }

  graphics.lineTo(cx, cy - outerRadius);
  graphics.closePath();
  graphics.fillPath();
}

new Phaser.Game(config);
