  if (keyS.isDown) {
    ellipseY += distance; // 向下移动
  }
  if (keyA.isDown) {
    ellipseX -= distance; // 向左移动
  }
  if (keyD.isDown) {
    ellipseX += distance; // 向右移动
  }

  // 边界限制（可选，防止椭圆移出屏幕）
  ellipseX = Phaser.Math.Clamp(ellipseX, 30, 770);
