REQ: 创建青色三角形并实现 2 秒循环抖动动画效果
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics#generateTexture, Phaser.GameObjects.Sprite, Phaser.Tweens.TweenManager#add
STEPS:
1. 使用 Graphics 绘制青色三角形并生成纹理
2. 创建 Sprite 对象使用该纹理
3. 使用 Tween 系统创建抖动效果（x/y 方向随机偏移）
4. 设置 Tween 循环和持续时间为 2 秒
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制青色三角形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x00ffff, 1); // 青色

  // 绘制等边三角形（中心点在原点）
  const size = 60;
  const height = size * Math.sqrt(3) / 2;
  graphics.beginPath();
  graphics.moveTo(0, -height * 2/3); // 顶点
  graphics.lineTo(-size / 2, height * 1/3); // 左下
  graphics.lineTo(size / 2, height * 1/3); // 右下
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('triangle', size, size * 1.2);
  graphics.destroy();

  // 创建三角形精灵
  const triangle = this.add.sprite(400, 300, 'triangle');

  // 创建抖动动画
  // 使用多个 Tween 组合实现抖动效果
  this.tweens.add({
    targets: triangle,
    x: '+=10', // 向右偏移
    y: '+=8',  // 向下偏移
    duration: 50,
    yoyo: true, // 往返
    repeat: -1, // 无限循环
    ease: 'Sine.easeInOut'
  });

  // 添加旋转抖动
  this.tweens.add({
    targets: triangle,
    angle: { from: -5, to: 5 }, // 左右旋转抖动
    duration: 100,
    yoyo: true,
    repeat: -1,
    ease: 'Sine.easeInOut'
  });

  // 添加缩放抖动
  this.tweens.add({
    targets: triangle,
    scaleX: { from: 0.95, to: 1.05 },
    scaleY: { from: 0.95, to: 1.05 },
    duration: 150,
    yoyo: true,
    repeat: -1,
    ease: 'Sine.easeInOut'
  });

  // 创建主循环控制（2秒一个完整周期）
  // 使用时间轴控制抖动的强度变化
  this.tweens.addCounter({
    from: 0,
    to: 1,
    duration: 2000,
    repeat: -1,
    onUpdate: (tween) => {
      const progress = tween.getValue();
      // 使用正弦波形让抖动强度周期性变化
      const intensity = Math.sin(progress * Math.PI * 2) * 0.5 + 0.5;
      // 可以根据 intensity 调整抖动效果（这里作为演示）
    }
  });

  // 添加说明文字
  this.add.text(400, 550, '青色三角形抖动动画 (2秒循环)', {
    fontSize: '20px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 在画布中央绘制一个红色星形，大小约为 24 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的 5 个外顶点和 5 个内顶点坐标（基于中心点和半径）
4. 使用 Graphics API 绘制星形路径并填充红色
5. 将星形定位在画布中央 (400, 300)
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  const graphics = this.add.graphics();

  // 设置填充颜色为红色
  graphics.fillStyle(0xff0000, 1);

  // 画布中心坐标
  const centerX = 400;
  const centerY = 300;

  // 星形参数
  const outerRadius = 24; // 外半径 24 像素
  const innerRadius = outerRadius * 0.4; // 内半径约为外半径的 40%
  const points = 5; // 5 个角的星形

  // 开始绘制路径
  graphics.beginPath();

  // 绘制星形的顶点
  for (let i = 0; i < points * 2; i++) {
    // 计算角度（从顶部开始，逆时针）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算顶点坐标
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // 第一个点移动到该位置，其余点连线
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

new Phaser.Game(config);
```

