REQ: 每隔2秒在随机位置生成黄色星形，最多生成12个
API: Phaser.Time.Clock#addEvent, Phaser.GameObjects.Graphics, Phaser.GameObjects.Image, Phaser.GameObjects.Graphics#generateTexture
STEPS:
1. 在create中使用Graphics绘制黄色星形并生成纹理
2. 使用addEvent创建定时器，每2秒触发一次
3. 在定时器回调中随机生成位置并创建星形图像
4. 计数器达到12个时停止生成
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

let starCount = 0;
const MAX_STARS = 12;

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用Graphics绘制星形并生成纹理
  const graphics = this.add.graphics();

  // 绘制黄色星形
  graphics.fillStyle(0xffff00, 1);
  graphics.lineStyle(2, 0xffa500, 1);

  // 星形的5个顶点
  const points = [];
  const outerRadius = 30;
  const innerRadius = 15;
  const numPoints = 5;

  for (let i = 0; i < numPoints * 2; i++) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (i * Math.PI) / numPoints - Math.PI / 2;
    points.push({
      x: 40 + Math.cos(angle) * radius,
      y: 40 + Math.sin(angle) * radius
    });
  }

  // 绘制星形路径
  graphics.beginPath();
  graphics.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) {
    graphics.lineTo(points[i].x, points[i].y);
  }
  graphics.closePath();
  graphics.fillPath();
  graphics.strokePath();

  // 生成纹理
  graphics.generateTexture('star', 80, 80);
  graphics.destroy();

  // 添加标题文本
  this.add.text(400, 30, '每2秒生成一个星形，最多12个', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);

  // 添加计数器文本
  const counterText = this.add.text(400, 70, `星形数量: 0 / ${MAX_STARS}`, {
    fontSize: '20px',
    color: '#ffff00'
  }).setOrigin(0.5);

  // 创建定时器事件，每2秒生成一个星形
  const timerEvent = this.time.addEvent({
    delay: 2000,                    // 2秒
    callback: () => {
      if (starCount < MAX_STARS) {
        // 生成随机位置（避免太靠近边缘）
        const x = Phaser.Math.Between(80, 720);
        const y = Phaser.Math.Between(120, 520);

        // 创建星形图像
        const star = this.add.image(x, y, 'star');

        // 添加缩放动画效果
        star.setScale(0);
        this.tweens.add({
          targets: star,
          scale: 1,
          duration: 300,
          ease: 'Back.easeOut'
        });

        // 添加旋转动画
        this.tweens.add({
          targets: star,
          angle: 360,
          duration: 2000,
          repeat: -1,
          ease: 'Linear'
        });

        starCount++;
        counterText.setText(`星形数量: ${starCount} / ${MAX_STARS}`);

        // 如果达到最大数量，移除定时器
        if (starCount >= MAX_STARS) {
          timerEvent.remove();

          // 显示完成提示
          this.add.text(400, 560, '已生成全部星形！', {
            fontSize: '18px',
            color: '#00ff00'
          }).setOrigin(0.5);
        }
      }
    },
    callbackScope: this,
    loop: true                      // 循环执行
  });
}

new Phaser.Game(config);
```

[PLAN]
REQ: 四向重力切换游戏，按方向键改变重力方向，玩家和8个物体受重力影响
API: Phaser.Physics.Arcade, Phaser.Input.Keyboard, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.World
STEPS:
1. 创建带 Arcade 物理系统的场景配置，初始重力向下(y=600)
2. 在 create 中使用 Graphics 创建玩家和8个物体的纹理，添加物理精灵
3. 监听方向键输入，根据按键切换世界重力方向(上下左右)
4. 添加边界碰撞，防止物体飞出屏幕
5. 在 update 中更新状态信号(当前重力方向)用于验证
[/PLAN]

```javascript
// 四向重力切换游戏
class GravityScene extends Phaser.Scene {
  constructor() {
    super('GravityScene');
    this.gravityDirection = 'down'; // 状态信号：当前重力方向
    this.gravityMagnitude = 600;
    this.switchCount = 0; // 状态信号：切换次数
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 创建玩家纹理
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillCircle(16, 16, 16);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建物体纹理
    const objectGraphics = this.add.graphics();
    objectGraphics.fillStyle(0xff6600, 1);
    objectGraphics.fillRect(0, 0, 24, 24);
    objectGraphics.generateTexture('object', 24, 24);
    objectGraphics.destroy();

    // 创建玩家（绿色圆形）
    this.player = this.physics.add.sprite(400, 100, 'player');
    this.player.setBounce(0.3);
    this.player.setCollideWorldBounds(true);

    // 创建8个物体（橙色方块）
    this.objects = this.physics.add.group();

    // 使用固定种子生成位置，保证确定性
    const positions = [
      { x: 150, y: 150 },
      { x: 650, y: 150 },
      { x: 200, y: 300 },
      { x: 600, y: 300 },
      { x: 300, y: 200 },
      { x: 500, y: 200 },
      { x: 250, y: 450 },
      { x: 550, y: 450 }
    ];

    positions.forEach(pos => {
      const obj = this.objects.create(pos.x, pos.y, 'object');
      obj.setBounce(0.4);
      obj.setCollideWorldBounds(true);
    });

    // 添加碰撞检测
    this.physics.add.collider(this.player, this.objects);
    this.physics.add.collider(this.objects, this.objects);

    // 设置键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加说明文本
    this.infoText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 添加重力方向指示器
    this.gravityIndicator = this.add.graphics();

    // 初始化重力
    this.updateGravity('down');
    this.updateInfoText();
  }

  update(time, delta) {
    // 检测方向键按下并切换重力
    if (Phaser.Input.Keyboard.JustDown(this.cursors.up)) {
      this.updateGravity('up');
      this.switchCount++;
    } else if (Phaser.Input.Keyboard.JustDown(this.cursors.down)) {
      this.updateGravity('down');
      this.switchCount++;
    } else if (Phaser.Input.Keyboard.JustDown(this.cursors.left)) {
      this.updateGravity('left');
      this.switchCount++;
    } else if (Phaser.Input.Keyboard.JustDown(this.cursors.right)) {
      this.updateGravity('right');
      this.switchCount++;
    }

    // 更新信息显示
    this.updateInfoText();
    this.drawGravityIndicator();
  }

  updateGravity(direction) {
    this.gravityDirection = direction;

    const gravity = { x: 0, y: 0 };

    switch (direction) {
      case 'up':
        gravity.y = -this.gravityMagnitude;
        break;
      case 'down':
        gravity.y = this.gravityMagnitude;
        break;
      case 'left':
        gravity.x = -this.gravityMagnitude;
        break;
      case 'right':
        gravity.x = this.gravityMagnitude;
        break;
    }

    // 设置世界重力
    this.physics.world.gravity.x = gravity.x;
    this.physics.world.gravity.y = gravity.y;
  }

  updateInfoText() {
    const objectCount = this.objects.getChildren().length;
    this.infoText.setText([
      `Gravity Direction: ${this.gravityDirection.toUpperCase()}`,
      `Gravity Magnitude: ${this.gravityMagnitude}`,
      `Switch Count: ${this.switchCount}`,
      `Objects: ${objectCount}`,
      `Player Pos: (${Math.round(this.player.x)}, ${Math.round(this.player.y)})`,
      '',
      'Press Arrow Keys to Change Gravity'
    ]);
  }

  drawGravityIndicator() {
    this.gravityIndicator.clear();
    this.gravityIndicator.lineStyle(4, 0xffff00, 1);
    this.gravityIndicator.fillStyle(0xffff00, 1);

    const centerX = 750;
    const centerY = 550;
    const arrowLength = 30;

    // 绘制箭头指示重力方向
    let endX = centerX;
    let endY = centerY;

    switch (this.gravityDirection) {
      case 'up':
        endY = centerY - arrowLength;
        break;
      case 'down':
        endY = centerY + arrowLength;
        break;
      case 'left':
        endX = centerX - arrowLength;
        break;
      case 'right':
        endX = centerX + arrowLength;
        break;
    }

    // 绘制箭头线
    this.gravityIndicator.beginPath();
    this.gravityIndicator.moveTo(centerX, centerY);
    this.gravityIndicator.lineTo(endX, endY);
    this.gravityIndicator.strokePath();

    // 绘制箭头头部
    const angle = Math.atan2(endY - centerY, endX - centerX);
    const arrowHeadLength = 10;

    this.gravityIndicator.beginPath();
    this.gravityIndicator.moveTo(endX, endY);
    this.gravityIndicator.lineTo(
      endX - arrowHeadLength * Math.cos(angle - Math.PI / 6),
      endY - arrowHeadLength * Math.sin(angle - Math.PI / 6)
    );
    this.gravityIndicator.lineTo(
      endX - arrowHeadLength * Math.cos(angle + Math.PI / 6),
      endY - arrowHeadLength * Math.sin(angle + Math.PI / 6)
    );
    this.gravityIndicator.closePath();
    this.gravityIndicator.fillPath();
  }
}

