REQ: 在画布中央绘制一个蓝色星形，大小约为 16 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布大小为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算星形的 5 个顶点和 5 个内凹点的坐标（基于中心点和半径）
4. 使用 Graphics API 绘制星形路径并填充蓝色
5. 将星形定位在画布中央 (400, 300)
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象
  const graphics = this.add.graphics();

  // 设置填充颜色为蓝色
  graphics.fillStyle(0x0000ff, 1);

  // 画布中心点
  const centerX = 400;
  const centerY = 300;

  // 星形参数
  const outerRadius = 16; // 外半径
  const innerRadius = 7;  // 内半径（约为外半径的 0.4-0.5）
  const points = 5;       // 五角星

  // 开始绘制路径
  graphics.beginPath();

  // 绘制星形的所有顶点
  for (let i = 0; i < points * 2; i++) {
    // 每个点的角度（从顶部开始，逆时针）
    const angle = (i * Math.PI) / points - Math.PI / 2;

    // 交替使用外半径和内半径
    const radius = i % 2 === 0 ? outerRadius : innerRadius;

    // 计算点的坐标
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // 第一个点用 moveTo，其他点用 lineTo
    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  // 闭合路径
  graphics.closePath();

  // 填充路径
  graphics.fillPath();
}

new Phaser.Game(config);
```

