    backgroundColor: '#fff',
    padding: { x: 10, y: 5 }
  });
}

function update() {
  // 左右移动
  if (cursors.left.isDown) {
    player.setVelocityX(-200);
  } else if (cursors.right.isDown) {
    player.setVelocityX(200);
  } else {
    player.setVelocityX(0);
  }

  // 跳跃逻辑
  if (Phaser.Input.Keyboard.JustDown(cursors.up) || Phaser.Input.Keyboard.JustDown(spaceKey)) {
    if (jumpCount < maxJumps) {
      player.setVelocityY(jumpForce);
      jumpCount++;
      totalJumps++;
      updateStatusText();

      // 视觉反馈：跳跃时稍微改变颜色
      player.setTint(jumpCount === 1 ? 0x6666FF : 0x9999FF);
    }
  }

  // 检测是否在空中（用于更精确的跳跃次数控制）
  if (player.body.touching.down) {
    if (jumpCount > 0) {
      // 刚落地，重置跳跃次数
      jumpCount = 0;
      player.clearTint();
      updateStatusText();
    }
  }
}

function onPlayerLand(player, ground) {
  // 碰撞回调：确保落地时重置跳跃次数
  if (jumpCount > 0) {
    jumpCount = 0;
    player.clearTint();
    updateStatusText();
  }
}

function updateStatusText() {
  const remainingJumps = maxJumps - jumpCount;
  statusText.setText(
    `剩余跳跃次数: ${remainingJumps}/${maxJumps}\n` +
    `总跳跃计数: ${totalJumps}`
  );
}

const game = new Phaser.Game(config);
