[PLAN]
REQ: 实现主相机跟随玩家移动，右上角显示缩小的全局视角小地图
API: Phaser.Cameras.Scene2D.Camera, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Sprite, Phaser.Input.Keyboard
STEPS:
1. 创建一个较大的游戏世界（1600x1200），使用 Graphics 绘制地图背景和边界
2. 创建玩家精灵，使用 Graphics 生成纹理，设置物理属性和键盘控制
3. 主相机（main camera）设置跟随玩家，限制在世界边界内
4. 创建第二个相机作为小地图，设置固定位置在右上角，缩小视口显示全局
5. 在世界中添加一些标记物（敌人、道具等）用于验证小地图效果
6. 添加状态信号（玩家位置、速度等）用于验证
[/PLAN]

```javascript
class MiniMapScene extends Phaser.Scene {
  constructor() {
    super('MiniMapScene');
    this.playerSpeed = 200;
    this.worldWidth = 1600;
    this.worldHeight = 1200;
    // 状态信号
    this.playerX = 0;
    this.playerY = 0;
    this.velocity = { x: 0, y: 0 };
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 设置世界边界
    this.physics.world.setBounds(0, 0, this.worldWidth, this.worldHeight);

    // 创建地图背景
    this.createWorldBackground();

    // 创建一些地图标记物（用于验证小地图效果）
    this.createMapMarkers();

    // 创建玩家
    this.createPlayer();

    // 设置主相机跟随玩家
    this.setupMainCamera();

    // 创建小地图相机
    this.setupMiniMapCamera();

    // 设置键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加文本显示状态
    this.createStatusText();
  }

  createWorldBackground() {
    const graphics = this.add.graphics();

    // 绘制棋盘格背景
    const tileSize = 100;
    for (let y = 0; y < this.worldHeight; y += tileSize) {
      for (let x = 0; x < this.worldWidth; x += tileSize) {
        const isEven = ((x / tileSize) + (y / tileSize)) % 2 === 0;
        graphics.fillStyle(isEven ? 0x2d5016 : 0x3a6b1f, 1);
        graphics.fillRect(x, y, tileSize, tileSize);
      }
    }

    // 绘制世界边界
    graphics.lineStyle(4, 0xff0000, 1);
    graphics.strokeRect(2, 2, this.worldWidth - 4, this.worldHeight - 4);
  }

  createMapMarkers() {
    // 创建一些标记物（敌人）
    const enemyPositions = [
      { x: 300, y: 300 },
      { x: 800, y: 400 },
      { x: 1200, y: 600 },
      { x: 400, y: 900 },
      { x: 1400, y: 200 },
      { x: 1000, y: 1000 }
    ];

    enemyPositions.forEach(pos => {
      const graphics = this.add.graphics();
      graphics.fillStyle(0xff0000, 1);
      graphics.fillCircle(pos.x, pos.y, 20);

      // 添加边框
      graphics.lineStyle(2, 0x990000, 1);
      graphics.strokeCircle(pos.x, pos.y, 20);
    });

    // 创建一些道具标记
    const itemPositions = [
      { x: 600, y: 200 },
      { x: 1300, y: 800 },
      { x: 200, y: 700 },
      { x: 900, y: 900 }
    ];

    itemPositions.forEach(pos => {
      const graphics = this.add.graphics();
      graphics.fillStyle(0xffff00, 1);
      graphics.fillRect(pos.x - 15, pos.y - 15, 30, 30);

      graphics.lineStyle(2, 0xcccc00, 1);
      graphics.strokeRect(pos.x - 15, pos.y - 15, 30, 30);
    });
  }

  createPlayer() {
    // 使用 Graphics 创建玩家纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0x00ff00, 1);
    graphics.fillCircle(16, 16, 16);
    graphics.lineStyle(3, 0x00cc00, 1);
    graphics.strokeCircle(16, 16, 16);

    // 添加方向指示
    graphics.fillStyle(0xffffff, 1);
    graphics.fillCircle(16, 8, 4);

    graphics.generateTexture('player', 32, 32);
    graphics.destroy();

    // 创建玩家精灵，位置在世界中心
    this.player = this.physics.add.sprite(
      this.worldWidth / 2,
      this.worldHeight / 2,
      'player'
    );

    // 设置物理属性
    this.player.setCollideWorldBounds(true);
    this.player.setDrag(500);
    this.player.setMaxVelocity(this.playerSpeed);
  }

  setupMainCamera() {
    // 主相机跟随玩家
    this.cameras.main.startFollow(this.player, true, 0.1, 0.1);
    this.cameras.main.setBounds(0, 0, this.worldWidth, this.worldHeight);
    this.cameras.main.setZoom(1);
  }

  setupMiniMapCamera() {
    // 创建小地图相机
    const miniMapWidth = 200;
    const miniMapHeight = 150;
    const padding = 10;

    // 添加小地图相机
    this.miniMapCamera = this.cameras.add(
      800 - miniMapWidth - padding,  // x: 右上角
      padding,                        // y: 顶部
      miniMapWidth,                   // width
      miniMapHeight                   // height
    );

    // 设置小地图相机显示整个世界
    this.miniMapCamera.setBounds(0, 0, this.worldWidth, this.worldHeight);

    // 计算缩放比例以显示整个世界
    const zoomX = miniMapWidth / this.worldWidth;
    const zoomY = miniMapHeight / this.worldHeight;
    const zoom = Math.min(zoomX, zoomY);
    this.miniMapCamera.setZoom(zoom);

    // 设置小地图背景色和边框
    this.miniMapCamera.setBackgroundColor(0x000000);

    // 使用 Graphics 绘制小地图边框（固定在主相机视图）
    this.miniMapBorder = this.add.graphics();
    this.miniMapBorder.setScrollFactor(0); // 固定在屏幕上
    this.miniMapBorder.lineStyle(3, 0xffffff, 1);
    this.miniMapBorder.strokeRect(
      800 - miniMapWidth - padding - 2,
      padding - 2,
      miniMapWidth + 4,
      miniMapHeight + 4
    );

    // 添加小地图标签
    this.miniMapLabel = this.add.text(
      800 - miniMapWidth - padding,
      padding - 20,
      'MINI MAP',
      {
        fontSize: '12px',
        fontFamily: 'Arial',
        color: '#ffffff',
        backgroundColor: '#000000',
        padding: { x: 4, y: 2 }
      }
    );
    this.miniMapLabel.setScrollFactor(0);
  }

  createStatusText() {
    // 创建状态显示文本（固定在主相机视图）
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '14px',
      fontFamily: 'Arial',
      color: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 8, y: 4 }
    });
    this.statusText.setScrollFactor(0);
    this.statusText.setDepth(1000);
  }

  update(time, delta) {
    // 处理玩家移动
    this.handlePlayerMovement();

    // 更新状态信号
    this.updateStatus();

    // 更新状态显示
    this.updateStatusDisplay();
  }

  handlePlayerMovement() {
    const acceleration = this.playerSpeed * 3;

    // 重置加速度
    this.player.setAcceleration(0);

    // 键盘控制
    if (this.cursors.left.isDown) {
      this.player.setAccelerationX(-acceleration);
    } else if (this.cursors.right.isDown) {
      this.player.setAccelerationX(acceleration);
    }

    if (this.cursors.up.isDown) {
      this.player.setAccelerationY(-acceleration);
    } else if (this.cursors.down.isDown) {
      this.player.setAccelerationY(acceleration);
    }
  }

  updateStatus() {
    // 更新状态信号
    this.playerX = Math.round(this.player.x);
    this.playerY = Math.round(this.player.y);
    this.velocity.x = Math.round(this.player.body.velocity.x);
    this.velocity.y = Math.round(this.player.body.velocity.y);
  }

  updateStatusDisplay() {
    const speed = Math.round(
      Math.sqrt(
        this.velocity.x * this.velocity.x + 
        this.velocity.y * this.velocity.y
      )
    );

    this.statusText.setText([
      'Use Arrow Keys to Move',
      `Position: (${this.playerX}, ${this.playerY})`,
      `Velocity: (${this.velocity.x}, ${this.velocity.y})`,
      `Speed: ${speed}`,
      `Camera: (${Math.round(this.cameras.main.scrollX)}, ${Math.round(this.cameras.main.scrollY)})`
    ]);
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#000000',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: MiniMapScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 20个红色物体以240速度随机移动，碰撞时反弹
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Collider, setBounce, setVelocity
STEPS:
1. 创建物理引擎配置，启用 arcade 物理系统
2. 使用 Graphics 生成红色圆形纹理
3. 创建物理组，添加 20 个红色物体
4. 为每个物体设置随机速度（总速度为 240）和反弹属性
5. 设置物体之间的碰撞检测
6. 添加状态信号变量记录碰撞次数
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态信号变量
let collisionCount = 0;
let objectCount = 20;
let targetSpeed = 240;

function preload() {
  // 使用 Graphics 创建红色圆形纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0xff0000, 1);
  graphics.fillCircle(16, 16, 16);
  graphics.generateTexture('redBall', 32, 32);
  graphics.destroy();
}

function create() {
  // 创建物理组
  const redObjects = this.physics.add.group({
    key: 'redBall',
    repeat: objectCount - 1,
    bounceX: 1,
    bounceY: 1,
    collideWorldBounds: true
  });

  // 为每个物体设置随机位置和速度
  redObjects.children.iterate((object) => {
    // 随机位置
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 550);
    object.setPosition(x, y);

    // 设置圆形碰撞体
    object.setCircle(16);

    // 生成随机角度，然后根据目标速度计算 vx 和 vy
    const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
    const vx = Math.cos(angle) * targetSpeed;
    const vy = Math.sin(angle) * targetSpeed;

    object.setVelocity(vx, vy);

    // 设置完全弹性碰撞
    object.setBounce(1, 1);
  });

  // 设置物体之间的碰撞
  this.physics.add.collider(redObjects, redObjects, onCollision, null, this);

  // 显示状态信息
  this.statusText = this.add.text(10, 10, '', {
    fontSize: '16px',
    fill: '#ffffff'
  });

  // 存储到场景数据中以便访问
  this.redObjects = redObjects;
}

function update() {
  // 更新状态显示
  this.statusText.setText([
    `Objects: ${objectCount}`,
    `Target Speed: ${targetSpeed}`,
    `Collisions: ${collisionCount}`
  ]);

  // 确保物体速度保持在目标速度附近（可选，用于补偿浮点误差）
  this.redObjects.children.iterate((object) => {
    const body = object.body;
    const currentSpeed = Math.sqrt(body.velocity.x ** 2 + body.velocity.y ** 2);

    // 如果速度偏差超过 5%，进行修正
    if (Math.abs(currentSpeed - targetSpeed) > targetSpeed * 0.05) {
      const angle = Math.atan2(body.velocity.y, body.velocity.x);
      body.setVelocity(
        Math.cos(angle) * targetSpeed,
        Math.sin(angle) * targetSpeed
      );
    }
  });
}

function onCollision(obj1, obj2) {
  // 碰撞计数器
  collisionCount++;
}

new Phaser.Game(config);
```

[PLAN]
REQ: 蓝色三角形在1秒内左右往返循环移动
API: this.add.graphics, graphics.fillTriangle, this.tweens.add, yoyo, repeat
STEPS:
1. 使用 Graphics 绘制蓝色三角形并生成纹理
2. 创建 Sprite 并应用三角形纹理
3. 使用 tweens.add 创建补间动画，设置 x 坐标从左到右移动
4. 配置 yoyo 为 true 实现往返效果，repeat 为 -1 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制蓝色三角形
  const graphics = this.add.graphics();
  graphics.fillStyle(0x0066ff, 1);

  // 绘制一个指向右的三角形
  // 中心点在 (25, 25)，三角形大小为 50x50
  graphics.fillTriangle(
    10, 40,  // 左下角
    10, 10,  // 左上角
    40, 25   // 右顶点
  );

  // 生成纹理
  graphics.generateTexture('triangle', 50, 50);
  graphics.destroy();

  // 创建三角形精灵，初始位置在左侧
  const triangle = this.add.sprite(100, 300, 'triangle');

  // 创建补间动画：从左移动到右，往返循环
  this.tweens.add({
    targets: triangle,
    x: 700,              // 目标 x 坐标（右侧）
    duration: 1000,      // 持续时间 1 秒
    ease: 'Linear',      // 线性缓动
    yoyo: true,          // 启用往返效果（到达终点后反向播放）
    repeat: -1           // 无限循环（-1 表示永远重复）
  });

  // 添加提示文本
  this.add.text(400, 50, '蓝色三角形左右往返循环', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现紫色血条 UI，显示 20 格生命值，点击鼠标扣血，血量为 0 显示 Game Over
API: Phaser.GameObjects.Graphics, Phaser.Input.InputPlugin, Phaser.GameObjects.Text, Phaser.Scene
STEPS:
1. 创建 Scene 并初始化 health 变量为 20
2. 使用 Graphics 绘制 20 个紫色方块作为血条格子
3. 监听鼠标左键点击事件，每次点击扣除 1 点生命值
4. 更新血条显示，隐藏对应的血格
5. 当 health 降至 0 时，显示 Game Over 文本并停止游戏交互
[/PLAN]

```javascript
class HealthBarScene extends Phaser.Scene {
  constructor() {
    super('HealthBarScene');
    this.health = 20;
    this.maxHealth = 20;
    this.healthBars = [];
    this.gameOver = false;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建标题文本
    this.add.text(400, 50, 'Click to Lose Health', {
      fontSize: '32px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    // 创建生命值显示文本
    this.healthText = this.add.text(400, 120, `Health: ${this.health}/${this.maxHealth}`, {
      fontSize: '24px',
      color: '#ffffff'
    }).setOrigin(0.5);

    // 创建血条容器
    const barStartX = 150;
    const barStartY = 200;
    const barWidth = 25;
    const barHeight = 40;
    const barGap = 5;

    // 绘制 20 个紫色血格
    for (let i = 0; i < this.maxHealth; i++) {
      const x = barStartX + i * (barWidth + barGap);
      const y = barStartY;

      // 创建血格背景（深灰色）
      const background = this.add.graphics();
      background.fillStyle(0x333333, 1);
      background.fillRect(x, y, barWidth, barHeight);

      // 创建血格（紫色）
      const healthBar = this.add.graphics();
      healthBar.fillStyle(0x9b59b6, 1); // 紫色
      healthBar.fillRect(x, y, barWidth, barHeight);

      // 添加边框
      healthBar.lineStyle(2, 0x8e44ad, 1); // 深紫色边框
      healthBar.strokeRect(x, y, barWidth, barHeight);

      this.healthBars.push(healthBar);
    }

    // Game Over 文本（初始隐藏）
    this.gameOverText = this.add.text(400, 300, 'GAME OVER', {
      fontSize: '64px',
      color: '#ff0000',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 6
    }).setOrigin(0.5).setVisible(false);

    // 重启提示文本（初始隐藏）
    this.restartText = this.add.text(400, 380, 'Click to Restart', {
      fontSize: '24px',
      color: '#ffffff'
    }).setOrigin(0.5).setVisible(false);

    // 监听鼠标左键点击
    this.input.on('pointerdown', this.onPointerDown, this);

    // 添加说明文本
    this.add.text(400, 500, 'Click anywhere to lose 1 health point', {
      fontSize: '18px',
      color: '#aaaaaa'
    }).setOrigin(0.5);
  }

  onPointerDown(pointer) {
    if (this.gameOver) {
      // 游戏结束后点击重启
      this.restartGame();
      return;
    }

    // 扣除生命值
    if (this.health > 0) {
      this.health--;
      this.updateHealthBar();
      this.healthText.setText(`Health: ${this.health}/${this.maxHealth}`);

      // 检查是否游戏结束
      if (this.health === 0) {
        this.triggerGameOver();
      }
    }
  }

  updateHealthBar() {
    // 隐藏对应的血格（从右向左消失）
    const index = this.health;
    if (index >= 0 && index < this.healthBars.length) {
      // 使用淡出效果
      this.tweens.add({
        targets: this.healthBars[index],
        alpha: 0,
        duration: 200,
        ease: 'Power2'
      });
    }
  }

  triggerGameOver() {
    this.gameOver = true;

    // 显示 Game Over 文本
    this.gameOverText.setVisible(true);
    this.restartText.setVisible(true);

    // Game Over 文本动画
    this.gameOverText.setScale(0);
    this.tweens.add({
      targets: this.gameOverText,
      scale: 1,
      duration: 500,
      ease: 'Back.easeOut'
    });

    // 闪烁效果
    this.tweens.add({
      targets: this.gameOverText,
      alpha: 0.5,
      duration: 500,
      yoyo: true,
      repeat: -1
    });
  }

  restartGame() {
    // 重置游戏状态
    this.health = this.maxHealth;
    this.gameOver = false;

    // 隐藏 Game Over 文本
    this.gameOverText.setVisible(false);
    this.restartText.setVisible(false);
    this.tweens.killAll();

    // 恢复所有血格
    this.healthBars.forEach(bar => {
      bar.setAlpha(1);
    });

    // 更新生命值文本
    this.healthText.setText(`Health: ${this.health}/${this.maxHealth}`);
  }

  update(time, delta) {
    // 可以在这里添加额外的更新逻辑
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2c3e50',
  scene: HealthBarScene,
  parent: 'game-container'
};

// 创建游戏实例
new Phaser.Game(config);
```

[PLAN]
REQ: 实现可拖拽的灰色方块，拖拽时变色，松手后回到初始位置
API: Graphics.fillRect, setInteractive, on('drag'), on('dragstart'), on('dragend')
STEPS:
1. 使用 Graphics 绘制灰色方块并生成纹理
2. 创建 Sprite 并设置为可交互和可拖拽
3. 监听 dragstart 事件改变颜色为蓝色
4. 监听 drag 事件更新方块位置
5. 监听 dragend 事件恢复灰色并回到初始位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 创建灰色方块纹理
  const graphics = this.add.graphics();
  graphics.fillStyle(0x808080, 1);
  graphics.fillRect(0, 0, 100, 100);
  graphics.generateTexture('grayBox', 100, 100);
  graphics.destroy();

  // 创建蓝色方块纹理（拖拽时使用）
  const blueGraphics = this.add.graphics();
  blueGraphics.fillStyle(0x4a90e2, 1);
  blueGraphics.fillRect(0, 0, 100, 100);
  blueGraphics.generateTexture('blueBox', 100, 100);
  blueGraphics.destroy();
}

function create() {
  // 初始位置
  const initialX = 400;
  const initialY = 300;

  // 创建可拖拽的方块
  const box = this.add.sprite(initialX, initialY, 'grayBox');

