[PLAN]
REQ: 实现8关橙色收集游戏，每关收集完所有橙色物品后进入下一关，显示关卡和分数
API: Phaser.Scene, Phaser.Physics.Arcade, Phaser.GameObjects.Graphics, Phaser.Input.Keyboard, Phaser.GameObjects.Text, Phaser.Physics.Arcade.Group
STEPS:
1. 创建游戏场景，配置物理系统和输入
2. 使用 Graphics 生成玩家和橙色物品的纹理
3. 在 create 中初始化玩家、橙色物品组、关卡和分数显示
4. 设置碰撞检测，收集橙色物品增加分数
5. 当所有物品收集完毕时，进入下一关（最多8关）
6. 在 update 中处理玩家移动和关卡切换逻辑
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.currentLevel = 1;
    this.maxLevel = 8;
    this.score = 0;
    this.player = null;
    this.oranges = null;
    this.cursors = null;
    this.levelText = null;
    this.scoreText = null;
    this.seed = 12345; // 固定随机种子
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0088ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建橙色物品纹理（橙色圆形）
    const orangeGraphics = this.add.graphics();
    orangeGraphics.fillStyle(0xff8800, 1);
    orangeGraphics.fillCircle(12, 12, 12);
    orangeGraphics.generateTexture('orange', 24, 24);
    orangeGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建橙色物品组
    this.oranges = this.physics.add.group();

    // 设置碰撞检测
    this.physics.add.overlap(this.player, this.oranges, this.collectOrange, null, this);

    // 创建键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建UI文本
    this.levelText = this.add.text(16, 16, `Level: ${this.currentLevel}`, {
      fontSize: '24px',
      fill: '#ffffff'
    });

    this.scoreText = this.add.text(16, 48, `Score: ${this.score}`, {
      fontSize: '24px',
      fill: '#ffffff'
    });

    // 初始化第一关
    this.setupLevel(this.currentLevel);
  }

  setupLevel(level) {
    // 清除现有橙色物品
    this.oranges.clear(true, true);

    // 使用固定种子生成确定性随机位置
    const rng = this.createSeededRandom(this.seed + level);

    // 每关橙色物品数量 = 3 + level
    const orangeCount = 3 + level;

    for (let i = 0; i < orangeCount; i++) {
      const x = 50 + rng() * 700;
      const y = 50 + rng() * 400;

      const orange = this.oranges.create(x, y, 'orange');
      orange.setCollideWorldBounds(true);
      orange.setBounce(0.5);
      orange.setVelocity(
        (rng() - 0.5) * 100,
        (rng() - 0.5) * 100
      );
    }

    // 更新关卡显示
    this.levelText.setText(`Level: ${this.currentLevel}`);
  }

  collectOrange(player, orange) {
    // 收集橙色物品
    orange.destroy();
    this.score += 10;
    this.scoreText.setText(`Score: ${this.score}`);

    // 检查是否收集完所有橙色物品
    if (this.oranges.countActive(true) === 0) {
      this.advanceLevel();
    }
  }

  advanceLevel() {
    if (this.currentLevel < this.maxLevel) {
      this.currentLevel++;

      // 重置玩家位置
      this.player.setPosition(400, 500);
      this.player.setVelocity(0, 0);

      // 设置下一关
      this.time.delayedCall(500, () => {
        this.setupLevel(this.currentLevel);
      });
    } else {
      // 游戏完成
      this.showGameComplete();
    }
  }

  showGameComplete() {
    const completeText = this.add.text(400, 300, 'ALL LEVELS COMPLETE!', {
