REQ: 黄色星形平滑跟随鼠标指针移动，跟随速度为160
API: Phaser.GameObjects.Graphics, Phaser.Input.Pointer, Phaser.Math.Angle.Between, Phaser.Physics.Arcade
STEPS:
1. 使用 Graphics 绘制黄色星形并生成纹理
2. 创建星形精灵并启用物理系统
3. 在 update 中获取鼠标指针位置
4. 计算星形到鼠标的角度和距离
5. 使用速度向量让星形平滑移动到鼠标位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      debug: false
    }
  },
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

let star;
const FOLLOW_SPEED = 160;

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制黄色星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffff00, 1); // 黄色

  // 绘制五角星
  const points = [];
  const outerRadius = 30;
  const innerRadius = 15;
  const numPoints = 5;

  for (let i = 0; i < numPoints * 2; i++) {
    const angle = (i * Math.PI) / numPoints - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    points.push({
      x: Math.cos(angle) * radius + 32,
      y: Math.sin(angle) * radius + 32
    });
  }

  graphics.beginPath();
  graphics.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) {
    graphics.lineTo(points[i].x, points[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 64, 64);
  graphics.destroy();

  // 创建星形精灵并启用物理系统
  star = this.physics.add.sprite(400, 300, 'star');
  star.setCollideWorldBounds(false);

  // 设置阻尼，使移动更平滑
  star.setDamping(true);
  star.setDrag(0.99);
}

function update(time, delta) {
  // 获取鼠标指针位置
  const pointer = this.input.activePointer;

  // 计算星形到鼠标的距离
  const distance = Phaser.Math.Distance.Between(
    star.x,
    star.y,
    pointer.x,
    pointer.y
  );

  // 如果距离大于一个很小的阈值，才移动（避免抖动）
  if (distance > 1) {
    // 计算从星形到鼠标的角度
    const angle = Phaser.Math.Angle.Between(
      star.x,
      star.y,
      pointer.x,
      pointer.y
    );

    // 根据角度设置速度向量
    this.physics.velocityFromRotation(
      angle,
      FOLLOW_SPEED,
      star.body.velocity
    );
  } else {
    // 距离很近时停止移动
    star.body.setVelocity(0, 0);
  }
}

new Phaser.Game(config);
```

[PLAN]
REQ: 使用对象池管理10个绿色可复用对象，离屏自动回收重用
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Sprite, this.physics.add.group
STEPS:
1. 使用 Graphics 生成绿色方块纹理
2. 创建 Physics Group 作为对象池，设置最大数量为10
3. 配置对象池的回收规则（checkWorldBounds + outOfBoundsKill）
4. 定时从对象池获取对象并发射
5. 在 update 中监控活跃对象数量，显示状态信息
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.activeCount = 0;
    this.totalSpawned = 0;
    this.recycledCount = 0;
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    // 1. 使用 Graphics 生成绿色方块纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0x00ff00, 1);
    graphics.fillRect(0, 0, 32, 32);
    graphics.generateTexture('greenBox', 32, 32);
    graphics.destroy();

    // 2. 创建物理对象池 (最多10个对象)
    this.objectPool = this.physics.add.group({
      defaultKey: 'greenBox',
      maxSize: 10,
      runChildUpdate: false,
      createCallback: (obj) => {
        // 配置每个对象的物理属性
        obj.setActive(false);
        obj.setVisible(false);
        obj.body.setAllowGravity(false);
      }
    });

    // 3. 配置边界检测和自动回收
    this.physics.world.on('worldbounds', (body) => {
      // 当对象离开屏幕边界时回收
      if (body.gameObject && body.gameObject.active) {
        this.recycleObject(body.gameObject);
      }
    });

    // 4. 定时发射对象（每0.8秒）
    this.time.addEvent({
      delay: 800,
      callback: this.spawnObject,
      callbackScope: this,
      loop: true
    });

    // 5. 创建状态显示文本
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 6. 添加手动发射按钮提示
    this.add.text(10, 550, 'Click to spawn object', {
      fontSize: '14px',
      fill: '#ffff00'
    });

    this.input.on('pointerdown', () => {
      this.spawnObject();
    });
  }

  spawnObject() {
    // 从对象池获取或创建对象
    let obj = this.objectPool.get();

    if (obj) {
      // 重置对象属性
      const x = Phaser.Math.Between(50, 750);
      const y = 50;

      obj.setPosition(x, y);
      obj.setActive(true);
      obj.setVisible(true);

      // 启用物理体和边界检测
      obj.body.enable = true;
      obj.body.setVelocity(
        Phaser.Math.Between(-100, 100),
        Phaser.Math.Between(100, 200)
      );
      obj.body.setBounce(0.8);
      obj.body.setCollideWorldBounds(true);
      obj.body.onWorldBounds = true;

      this.totalSpawned++;
      this.activeCount = this.objectPool.countActive(true);
    }
  }

  recycleObject(obj) {
    // 回收对象到池中
    obj.setActive(false);
    obj.setVisible(false);
    obj.body.setVelocity(0, 0);
    obj.body.enable = false;

    this.recycledCount++;
    this.activeCount = this.objectPool.countActive(true);
  }

  update(time, delta) {
    // 更新状态信息
    this.activeCount = this.objectPool.countActive(true);
    const poolSize = this.objectPool.getLength();

    this.statusText.setText([
      `Active Objects: ${this.activeCount}`,
      `Pool Size: ${poolSize} / 10`,
      `Total Spawned: ${this.totalSpawned}`,
      `Recycled: ${this.recycledCount}`
    ]);

    // 检查离屏对象并回收
    this.objectPool.children.entries.forEach((obj) => {
      if (obj.active) {
        const bounds = this.physics.world.bounds;
        if (obj.y > bounds.height + 50 || 
            obj.x < -50 || 
            obj.x > bounds.width + 50) {
          this.recycleObject(obj);
        }
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 200 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

