      loop: true             // 循环执行
    });

    // 添加背景色以便更好地看到文本
    const graphics = this.add.graphics();
    graphics.fillStyle(0x222222, 1);
    graphics.fillRect(0, 0, 800, 600);
  }

  addScore() {
    // 每次调用增加 8 分
    this.score += 8;
    // 更新文本显示
    this.scoreText.setText('Score: ' + this.score);
  }

  update(time, delta) {
    // 本例中不需要每帧更新逻辑
  }
}

// Phaser 游戏配置
