[PLAN]
REQ: 3个蓝色小球在封闭空间内以120速度移动，碰撞边界和彼此时弹开
API: Phaser.Physics.Arcade, Graphics.fillCircle, Physics.add.sprite, Physics.add.collider, Body.setBounce, Body.setCollideWorldBounds, Body.setVelocity
STEPS:
1. 创建 Arcade 物理系统配置，启用世界边界
2. 使用 Graphics 生成蓝色圆形纹理
3. 创建 3 个物理精灵球体，设置随机初始速度（总速度为120）
4. 设置球体弹性系数为1（完全弹性碰撞）
5. 启用世界边界碰撞和球体间碰撞检测
6. 添加碰撞计数器作为可验证状态信号
[/PLAN]

```javascript
class BallCollisionScene extends Phaser.Scene {
  constructor() {
    super('BallCollisionScene');
    this.collisionCount = 0; // 可验证的状态信号
    this.ballCollisionCount = 0; // 球体间碰撞计数
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建蓝色圆形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0x0066ff, 1);
    graphics.fillCircle(16, 16, 16);
    graphics.generateTexture('blueBall', 32, 32);
    graphics.destroy();

    // 创建物理球体组
    this.balls = this.physics.add.group();

    // 创建 3 个球体，设置随机方向但固定速度为 120
    const speed = 120;
    const positions = [
      { x: 200, y: 200 },
      { x: 600, y: 200 },
      { x: 400, y: 400 }
    ];

    positions.forEach((pos, index) => {
      const ball = this.physics.add.sprite(pos.x, pos.y, 'blueBall');

      // 设置完全弹性碰撞（反弹系数为 1）
      ball.setBounce(1, 1);

      // 启用世界边界碰撞
      ball.setCollideWorldBounds(true);

      // 设置随机方向的速度，但保持总速度为 120
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const vx = Math.cos(angle) * speed;
      const vy = Math.sin(angle) * speed;
      ball.setVelocity(vx, vy);

      // 设置阻尼为 0，保持匀速运动
      ball.body.setDamping(false);
      ball.body.useDamping = false;

      // 添加到组
      this.balls.add(ball);
    });

    // 设置球体间的碰撞检测
    this.physics.add.collider(this.balls, this.balls, this.onBallCollision, null, this);

    // 监听世界边界碰撞
    this.physics.world.on('worldbounds', () => {
      this.collisionCount++;
    });

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 添加边界可视化
    const bounds = this.add.graphics();
    bounds.lineStyle(2, 0xffffff, 1);
    bounds.strokeRect(0, 0, this.scale.width, this.scale.height);
  }

  onBallCollision(ball1, ball2) {
    // 球体间碰撞回调
    this.ballCollisionCount++;
  }

  update(time, delta) {
    // 更新状态显示
    this.statusText.setText([
      `Wall Collisions: ${this.collisionCount}`,
      `Ball Collisions: ${this.ballCollisionCount}`,
      `Balls Active: ${this.balls.getChildren().length}`
    ]);

    // 确保球体速度保持在 120 左右（由于浮点误差可能会有微小变化）
    this.balls.getChildren().forEach(ball => {
      const body = ball.body;
      const currentSpeed = Math.sqrt(body.velocity.x ** 2 + body.velocity.y ** 2);

      // 如果速度偏差超过 5%，进行修正
      if (Math.abs(currentSpeed - 120) > 6) {
        const scale = 120 / currentSpeed;
        body.setVelocity(body.velocity.x * scale, body.velocity.y * scale);
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 }, // 无重力
      debug: false
    }
  },
  scene: BallCollisionScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 实现黄色角色通过按键切换 idle/run 状态，使用 tween 或帧动画体现差异
API: Phaser.GameObjects.Graphics, Phaser.Input.Keyboard, Phaser.Tweens.TweenManager, Phaser.Animations.AnimationManager
STEPS:
1. 使用 Graphics 创建黄色角色纹理（多帧）
2. 创建 idle 和 run 两种帧动画
3. 监听键盘输入（1键切换到idle，2键切换到run）
4. 根据状态播放对应动画，并添加 tween 效果增强表现
5. 显示当前状态文本作为可验证信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.currentState = 'idle'; // 可验证的状态变量
  }

  preload() {
    // 创建黄色角色的多帧纹理
    this.createCharacterFrames();
  }

  createCharacterFrames() {
    const graphics = this.add.graphics();

    // 创建 idle 状态的3帧（黄色方块，轻微变化）
    for (let i = 0; i < 3; i++) {
      graphics.clear();
      graphics.fillStyle(0xffff00, 1); // 黄色

      // 轻微的大小变化模拟呼吸效果
      const size = 50 + i * 2;
      const offset = (50 - size) / 2;
      graphics.fillRect(offset, offset, size, size);

      // 添加眼睛
      graphics.fillStyle(0x000000, 1);
      graphics.fillCircle(15, 20, 3);
      graphics.fillCircle(35, 20, 3);

      graphics.generateTexture(`idle_${i}`, 50, 50);
    }

    // 创建 run 状态的4帧（黄色方块，倾斜和拉伸）
    for (let i = 0; i < 4; i++) {
      graphics.clear();
      graphics.fillStyle(0xffff00, 1);

      // 跑步时的形变效果
      const skew = i % 2 === 0 ? 5 : -5;
      graphics.fillRect(skew, 0, 50, 50);

      // 添加眼睛（跑步时眼睛更有动感）
      graphics.fillStyle(0x000000, 1);
      const eyeOffset = i % 2 === 0 ? 2 : -2;
      graphics.fillCircle(15 + eyeOffset, 20, 3);
      graphics.fillCircle(35 + eyeOffset, 20, 3);

      // 添加运动线条
      graphics.lineStyle(2, 0xffff00, 0.5);
      graphics.lineBetween(-10, 15 + i * 5, 0, 15 + i * 5);
      graphics.lineBetween(-10, 35 + i * 5, 0, 35 + i * 5);

      graphics.generateTexture(`run_${i}`, 50, 50);
    }

    graphics.destroy();
  }

  create() {
    // 添加背景
    const bg = this.add.graphics();
    bg.fillStyle(0x87ceeb, 1);
    bg.fillRect(0, 0, 800, 600);

    // 创建角色精灵
    this.player = this.add.sprite(400, 300, 'idle_0');
    this.player.setScale(2);

    // 创建 idle 动画
    this.anims.create({
      key: 'idle',
      frames: [
        { key: 'idle_0' },
        { key: 'idle_1' },
        { key: 'idle_2' },
        { key: 'idle_1' }
      ],
      frameRate: 4,
      repeat: -1
    });

    // 创建 run 动画
    this.anims.create({
      key: 'run',
      frames: [
        { key: 'run_0' },
        { key: 'run_1' },
        { key: 'run_2' },
        { key: 'run_3' }
      ],
      frameRate: 10,
      repeat: -1
    });

    // 默认播放 idle 动画
    this.player.play('idle');

    // 添加状态文本显示
    this.stateText = this.add.text(400, 100, 'State: IDLE', {
      fontSize: '32px',
      fontFamily: 'Arial',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 4
    });
    this.stateText.setOrigin(0.5);

    // 添加提示文本
    this.add.text(400, 500, 'Press [1] for IDLE  |  Press [2] for RUN', {
      fontSize: '24px',
      fontFamily: 'Arial',
      color: '#ffffff',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5);

    // 键盘输入监听
    this.key1 = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.ONE);
    this.key2 = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.TWO);

    // 监听按键按下事件
    this.key1.on('down', () => this.switchState('idle'));
    this.key2.on('down', () => this.switchState('run'));

    // 添加粒子效果容器
    this.particleGraphics = this.add.graphics();
  }

  switchState(newState) {
    if (this.currentState === newState) return;

    this.currentState = newState;

    // 停止所有正在进行的 tween
    this.tweens.killTweensOf(this.player);

    if (newState === 'idle') {
      // 切换到 idle 状态
      this.player.play('idle');
      this.stateText.setText('State: IDLE');

      // idle 状态的 tween：轻微上下浮动
      this.tweens.add({
        targets: this.player,
        y: 300 - 10,
        duration: 1000,
        ease: 'Sine.easeInOut',
        yoyo: true,
        repeat: -1
      });

      // 缩放回正常
      this.tweens.add({
        targets: this.player,
        scaleX: 2,
        scaleY: 2,
        duration: 300,
        ease: 'Back.easeOut'
      });

    } else if (newState === 'run') {
      // 切换到 run 状态
      this.player.play('run');
      this.stateText.setText('State: RUN');

      // run 状态的 tween：左右快速移动
      this.tweens.add({
        targets: this.player,
        x: 600,
        duration: 1500,
        ease: 'Linear',
        yoyo: true,
        repeat: -1
      });

      // 轻微倾斜效果
      this.tweens.add({
        targets: this.player,
        angle: -5,
        duration: 150,
        ease: 'Sine.easeInOut',
        yoyo: true,
        repeat: -1
      });

      // 轻微拉伸效果
      this.tweens.add({
        targets: this.player,
        scaleX: 2.2,
        scaleY: 1.9,
        duration: 300,
        ease: 'Sine.easeInOut',
        yoyo: true,
        repeat: -1
      });
    }

    // 状态切换时的闪烁效果
    this.tweens.add({
      targets: this.stateText,
      alpha: 0.3,
      duration: 100,
      yoyo: true,
      repeat: 2
    });
  }

  update(time, delta) {
    // 在 run 状态下添加拖尾粒子效果
    if (this.currentState === 'run' && Math.random() > 0.7) {
      this.particleGraphics.clear();
      this.particleGraphics.fillStyle(0xffff00, 0.3);

      for (let i = 0; i < 3; i++) {
        const offsetX = (Math.random() - 0.5) * 20;
        const offsetY = (Math.random() - 0.5) * 20;
        this.particleGraphics.fillCircle(
          this.player.x + offsetX - 30,
          this.player.y + offsetY,
          5
        );
      }

      // 粒子淡出
      this.tweens.add({
        targets: this.particleGraphics,
        alpha: 0,
        duration: 300,
        onComplete: () => {
          this.particleGraphics.clear();
          this.particleGraphics.alpha = 1;
        }
      });
    }
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: GameScene,
  pixelArt: false,
  parent: 'game-container'
};

new Phaser.Game(config);
```

