[PLAN]
REQ: 让一个星形在 1 秒内从透明渐变到完全不透明，循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager#add, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制一个星形并生成纹理
2. 创建一个使用该纹理的精灵对象，初始透明度设为 0
3. 使用 Tween 动画让精灵的 alpha 属性在 1 秒内从 0 渐变到 1
4. 设置 Tween 为循环模式（yoyo + repeat: -1）实现往复循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 使用 Graphics 绘制星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffff00, 1); // 黄色星形

  // 绘制五角星
  const centerX = 50;
  const centerY = 50;
  const outerRadius = 40;
  const innerRadius = 16;
  const points = 5;

  graphics.beginPath();

  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
      graphics.moveTo(x, y);
    } else {
      graphics.lineTo(x, y);
    }
  }

  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy(); // 销毁 graphics 对象，只保留纹理

  // 创建星形精灵，放置在屏幕中央
  const star = this.add.sprite(400, 300, 'star');
  star.alpha = 0; // 初始设置为完全透明

  // 创建渐变动画 Tween
  this.tweens.add({
    targets: star,           // 动画目标对象
    alpha: 1,                // 目标透明度为 1（完全不透明）
    duration: 1000,          // 持续时间 1 秒（1000 毫秒）
    ease: 'Linear',          // 线性缓动
    yoyo: true,              // 往复播放（透明->不透明->透明）
    repeat: -1               // 无限循环
  });
}

new Phaser.Game(config);
```

