REQ: 在画布中央绘制一个黄色菱形，大小约为 24 像素
API: Phaser.GameObjects.Graphics, Graphics.fillStyle, Graphics.beginPath, Graphics.moveTo, Graphics.lineTo, Graphics.closePath, Graphics.fillPath
STEPS:
1. 创建 Phaser.Game 配置，设置画布尺寸为 800x600
2. 在 create 方法中创建 Graphics 对象
3. 计算菱形四个顶点坐标（中心点为画布中心，菱形边长约 24 像素）
4. 使用 beginPath、moveTo、lineTo 绘制菱形路径
5. 使用黄色填充菱形
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 创建 Graphics 对象用于绘制
  const graphics = this.add.graphics();

  // 设置黄色填充样式
  graphics.fillStyle(0xffff00, 1);

  // 计算画布中心点
  const centerX = 400;
  const centerY = 300;

  // 菱形大小（从中心到顶点的距离）
  const size = 12; // 24像素菱形，半径为12

  // 开始绘制路径
  graphics.beginPath();

  // 绘制菱形的四个顶点（上、右、下、左）
  graphics.moveTo(centerX, centerY - size);        // 上顶点
  graphics.lineTo(centerX + size, centerY);        // 右顶点
  graphics.lineTo(centerX, centerY + size);        // 下顶点
  graphics.lineTo(centerX - size, centerY);        // 左顶点

  // 闭合路径
  graphics.closePath();

  // 填充菱形
  graphics.fillPath();
}

new Phaser.Game(config);
