REQ: 橙色星形在2.5秒内左右往返循环移动
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager, Phaser.Tweens.Tween
STEPS:
1. 使用 Graphics 绘制橙色星形并生成纹理
2. 创建星形精灵并定位到左侧起点
3. 使用 tweens 创建补间动画，设置 yoyo 和 loop 实现往返循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制橙色星形
  const graphics = this.add.graphics();

  // 绘制星形的函数
  const drawStar = (graphics, cx, cy, spikes, outerRadius, innerRadius, color) => {
    let rot = Math.PI / 2 * 3;
    let x = cx;
    let y = cy;
    const step = Math.PI / spikes;

    graphics.fillStyle(color, 1);
    graphics.beginPath();
    graphics.moveTo(cx, cy - outerRadius);

    for (let i = 0; i < spikes; i++) {
      x = cx + Math.cos(rot) * outerRadius;
      y = cy + Math.sin(rot) * outerRadius;
      graphics.lineTo(x, y);
      rot += step;

      x = cx + Math.cos(rot) * innerRadius;
      y = cy + Math.sin(rot) * innerRadius;
      graphics.lineTo(x, y);
      rot += step;
    }

    graphics.lineTo(cx, cy - outerRadius);
    graphics.closePath();
    graphics.fillPath();
  };

  // 绘制橙色星形（中心在 50, 50，用于生成纹理）
  drawStar(graphics, 50, 50, 5, 40, 20, 0xFF8C00);

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy();

  // 创建星形精灵
  const star = this.add.sprite(100, 300, 'star');

  // 创建补间动画：从左到右，然后往返循环
  this.tweens.add({
    targets: star,
    x: 700, // 移动到右侧
    duration: 2500, // 2.5秒
    ease: 'Linear',
    yoyo: true, // 启用往返效果
    repeat: -1 // 无限循环
  });

  // 添加说明文字
  this.add.text(400, 50, '橙色星形左右往返循环', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
