REQ: 实现白色星形在2秒内左右往返循环移动的补间动画
API: Phaser.GameObjects.Graphics, Phaser.GameObjects.Graphics.generateTexture, Phaser.Tweens.TweenManager.add, Phaser.Tweens.BaseTween.yoyo, Phaser.Tweens.BaseTween.loop
STEPS:
1. 使用 Graphics 绘制白色星形并生成纹理
2. 创建使用该纹理的 Sprite 对象，初始位置在左侧
3. 使用 Tweens 创建补间动画，设置 x 坐标从左到右移动，持续 2 秒
4. 启用 yoyo 模式实现往返效果，设置 loop(-1) 实现无限循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要预加载外部资源
}

function create() {
  // 使用 Graphics 绘制白色星形
  const graphics = this.add.graphics();
  graphics.fillStyle(0xffffff, 1);

  // 绘制五角星
  const centerX = 50;
  const centerY = 50;
  const outerRadius = 40;
  const innerRadius = 16;
  const points = 5;

  // 计算星形的顶点坐标
  const starPoints = [];
  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 === 0 ? outerRadius : innerRadius;
    const angle = (i * Math.PI) / points - Math.PI / 2;
    starPoints.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius
    });
  }

  // 绘制星形路径
  graphics.beginPath();
  graphics.moveTo(starPoints[0].x, starPoints[0].y);
  for (let i = 1; i < starPoints.length; i++) {
    graphics.lineTo(starPoints[i].x, starPoints[i].y);
  }
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('star', 100, 100);
  graphics.destroy();

  // 创建星形精灵，初始位置在左侧
  const star = this.add.sprite(100, 300, 'star');

  // 创建补间动画：从左到右移动
  this.tweens.add({
    targets: star,
    x: 700,              // 目标 x 坐标（右侧）
    duration: 2000,      // 持续时间 2 秒
    yoyo: true,          // 启用往返效果
    loop: -1,            // 无限循环
    ease: 'Linear'       // 线性缓动
  });

  // 添加说明文字
  this.add.text(400, 50, '白色星形往返循环移动', {
    fontSize: '24px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

