REQ: 实现灰色敌人以240速度追踪玩家，玩家速度288可躲避
API: Phaser.Physics.Arcade.Sprite, Phaser.Physics.Arcade.ArcadePhysics#moveToObject, Phaser.Input.Keyboard.createCursorKeys
STEPS:
1. 创建物理系统配置，启用 arcade 物理引擎
2. 使用 Graphics 生成玩家（蓝色方块）和敌人（灰色圆形）纹理
3. 创建玩家精灵，设置速度为 288（240*1.2）
4. 创建敌人精灵，设置追踪速度为 240
5. 实现键盘控制玩家移动（WASD/方向键）
6. 在 update 中使用 moveToObject 让敌人追踪玩家
7. 添加碰撞检测，记录被抓次数作为状态信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.caughtCount = 0; // 状态信号：被敌人抓到的次数
    this.escapeTime = 0; // 状态信号：成功躲避的时间
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    // 创建玩家纹理（蓝色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0088ff, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（灰色圆形）
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0x808080, 1);
    enemyGraphics.fillCircle(20, 20, 20);
    enemyGraphics.generateTexture('enemy', 40, 40);
    enemyGraphics.destroy();

    // 创建玩家精灵
    this.player = this.physics.add.sprite(400, 300, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人精灵
    this.enemy = this.physics.add.sprite(100, 100, 'enemy');
    this.enemy.setCollideWorldBounds(true);

    // 设置键盘输入
    this.cursors = this.input.keyboard.createCursorKeys();
    this.wasd = this.input.keyboard.addKeys({
      up: Phaser.Input.Keyboard.KeyCodes.W,
      down: Phaser.Input.Keyboard.KeyCodes.S,
      left: Phaser.Input.Keyboard.KeyCodes.A,
      right: Phaser.Input.Keyboard.KeyCodes.D
    });

    // 添加碰撞检测
    this.physics.add.overlap(this.player, this.enemy, this.onCaught, null, this);

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '18px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 显示控制说明
    this.add.text(10, 550, 'Controls: Arrow Keys or WASD to move', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    this.updateStatusText();
  }

  update(time, delta) {
    // 玩家速度：240 * 1.2 = 288
    const playerSpeed = 288;

    // 重置玩家速度
    this.player.setVelocity(0);

    // 处理玩家移动（支持方向键和WASD）
    if (this.cursors.left.isDown || this.wasd.left.isDown) {
      this.player.setVelocityX(-playerSpeed);
    } else if (this.cursors.right.isDown || this.wasd.right.isDown) {
      this.player.setVelocityX(playerSpeed);
    }

    if (this.cursors.up.isDown || this.wasd.up.isDown) {
      this.player.setVelocityY(-playerSpeed);
    } else if (this.cursors.down.isDown || this.wasd.down.isDown) {
      this.player.setVelocityY(playerSpeed);
    }

    // 对角线移动时归一化速度
    if (this.player.body.velocity.x !== 0 && this.player.body.velocity.y !== 0) {
      this.player.body.velocity.normalize().scale(playerSpeed);
    }

    // 敌人追踪玩家，速度为 240
    this.physics.moveToObject(this.enemy, this.player, 240);

    // 计算逃脱时间（以秒为单位）
    const distance = Phaser.Math.Distance.Between(
      this.player.x, this.player.y,
      this.enemy.x, this.enemy.y
    );

    // 如果距离大于50，认为成功躲避
    if (distance > 50) {
      this.escapeTime += delta / 1000;
    }

    this.updateStatusText();
  }

  onCaught() {
    // 被抓到时增加计数
    this.caughtCount++;

    // 重置玩家和敌人位置
    this.player.setPosition(400, 300);
    this.enemy.setPosition(100, 100);

    // 停止移动
    this.player.setVelocity(0);
    this.enemy.setVelocity(0);

    this.updateStatusText();
  }

  updateStatusText() {
    this.statusText.setText(
      `Caught: ${this.caughtCount} | Escape Time: ${this.escapeTime.toFixed(1)}s\n` +
      `Player Speed: 288 | Enemy Speed: 240`
    );
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#222222',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

