      collectible.setImmovable(true);
    }

    // 添加碰撞检测
    this.physics.add.overlap(
      this.player,
      this.collectibles,
      this.collectItem,
      null,
      this
    );

    // 创建键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 创建计数文本
    this.scoreText = this.add.text(16, 16, '收集: 0/12', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial'
