class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.objects = [];
    this.totalDistance = 0; // 可验证的状态信号
    this.moveSpeed = 300;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
