      padding: { x: 10, y: 5 }
    });

    // 显示平均速度（用于验证速度保持在240左右）
    this.speedText = this.add.text(10, 70, 'Avg Speed: 0', {
      fontSize: '20px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });
