2. 创建角色精灵和状态文本显示
3. 监听键盘输入（空格键切换状态）
4. 在 update 中根据状态更新角色位置和显示
5. 添加可验证的状态变量（currentState, currentSpeed）
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create,
    update: update
  }
};

// 状态枚举
const STATE = {
  IDLE: 0,
  WALK: 1,
  RUN: 2
};

// 状态配置
const STATE_CONFIG = {
  [STATE.IDLE]: { name: '静止', speed: 0, color: 0x00ff00 },
  [STATE.WALK]: { name: '行走', speed: 360, color: 0xffff00 },
  [STATE.RUN]: { name: '跑步', speed: 720, color: 0xff0000 }
};

let player;
let stateText;
let speedText;
let instructionText;
let currentState = STATE.IDLE;
let currentSpeed = 0;
let cursors;
let spaceKey;

function preload() {
  // 使用 Graphics 生成角色纹理
  createPlayerTextures.call(this);
}

function createPlayerTextures() {
  const graphics = this.add.graphics();

  // 为每种状态创建不同颜色的纹理
  Object.keys(STATE_CONFIG).forEach(stateKey => {
    const state = parseInt(stateKey);
    const config = STATE_CONFIG[state];

    graphics.clear();
    graphics.fillStyle(config.color, 1);
    graphics.fillRect(0, 0, 40, 60);

    // 添加一个小细节（眼睛）
    graphics.fillStyle(0xffffff, 1);
    graphics.fillCircle(12, 15, 4);
    graphics.fillCircle(28, 15, 4);

    // 添加方向指示（三角形）
    graphics.fillStyle(0x000000, 1);
    graphics.fillTriangle(20, 45, 15, 35, 25, 35);

    graphics.generateTexture(`player_${state}`, 40, 60);
  });

  graphics.destroy();
}

function create() {
  // 创建玩家精灵
  player = this.add.sprite(100, 300, 'player_0');
  player.setOrigin(0.5, 0.5);

  // 创建状态显示文本
  stateText = this.add.text(20, 20, '', {
    fontSize: '24px',
    fontFamily: 'Arial',
    color: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 创建速度显示文本
  speedText = this.add.text(20, 60, '', {
    fontSize: '20px',
    fontFamily: 'Arial',
    color: '#ffffff',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 创建操作说明文本
  instructionText = this.add.text(20, 100, '按空格键切换状态\n方向键控制移动', {
    fontSize: '16px',
    fontFamily: 'Arial',
    color: '#aaaaaa',
    backgroundColor: '#000000',
    padding: { x: 10, y: 5 }
  });

  // 创建边界提示
  const boundary = this.add.graphics();
  boundary.lineStyle(2, 0x666666, 1);
  boundary.strokeRect(10, 10, 780, 580);

  // 设置键盘输入
  cursors = this.input.keyboard.createCursorKeys();
  spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

  // 监听空格键切换状态
  spaceKey.on('down', () => {
    currentState = (currentState + 1) % 3;
    updatePlayerState();
  });

  // 初始化状态显示
  updatePlayerState();
}

function updatePlayerState() {
  const config = STATE_CONFIG[currentState];
  currentSpeed = config.speed;

  // 更新角色纹理
  player.setTexture(`player_${currentState}`);

  // 更新状态文本
  stateText.setText(`当前状态: ${config.name}`);
  stateText.setBackgroundColor(rgbToHex(config.color));

  // 更新速度文本
  speedText.setText(`速度: ${currentSpeed} px/s`);
}

function update(time, delta) {
  // 计算实际移动距离（速度 * 时间）
  const moveDistance = (currentSpeed * delta) / 1000;

  let velocityX = 0;
  let velocityY = 0;

  // 处理方向键输入
  if (cursors.left.isDown) {
    velocityX = -1;
    player.setFlipX(true);
  } else if (cursors.right.isDown) {
    velocityX = 1;
    player.setFlipX(false);
  }

  if (cursors.up.isDown) {
    velocityY = -1;
  } else if (cursors.down.isDown) {
    velocityY = 1;
  }

  // 归一化对角线移动速度
  if (velocityX !== 0 && velocityY !== 0) {
    const normalizer = Math.sqrt(2) / 2;
    velocityX *= normalizer;
    velocityY *= normalizer;
  }

  // 更新玩家位置
  player.x += velocityX * moveDistance;
  player.y += velocityY * moveDistance;

  // 限制玩家在屏幕范围内
  player.x = Phaser.Math.Clamp(player.x, 30, 770);
  player.y = Phaser.Math.Clamp(player.y, 40, 560);
}

// 辅助函数：将颜色值转换为 CSS 十六进制字符串
function rgbToHex(color) {
  return '#' + color.toString(16).padStart(6, '0');
}

// 启动游戏
new Phaser.Game(config);
```

[PLAN]
REQ: 实现收集物品玩法，场景中生成5个青色可收集物体，玩家碰到后消失并加分，显示score
API: Phaser.Physics.Arcade.Factory#group, Phaser.Physics.Arcade.ArcadePhysics#overlap, Phaser.GameObjects.Text, Phaser.Physics.Arcade.Sprite
STEPS:
1. 创建物理系统配置，启用 arcade 物理引擎
2. 在 create 中使用 Graphics 创建玩家和收集物纹理
3. 创建物理精灵组，生成5个青色收集物随机分布在场景中
4. 添加键盘控制实现玩家移动
5. 使用 overlap 检测玩家与收集物碰撞，碰撞时销毁收集物并增加分数
6. 创建文本对象显示当前分数
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.score = 0;
  }

  preload() {
    // 使用 Graphics 创建纹理，无需外部资源
  }

  create() {
    // 创建玩家纹理（绿色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillRect(0, 0, 40, 40);
    playerGraphics.generateTexture('player', 40, 40);
    playerGraphics.destroy();

    // 创建收集物纹理（青色圆形）
    const collectibleGraphics = this.add.graphics();
    collectibleGraphics.fillStyle(0x00ffff, 1);
    collectibleGraphics.fillCircle(15, 15, 15);
    collectibleGraphics.generateTexture('collectible', 30, 30);
    collectibleGraphics.destroy();

    // 创建玩家精灵
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建收集物组
    this.collectibles = this.physics.add.group();

    // 随机生成5个收集物
    const positions = [
      { x: 150, y: 150 },
      { x: 650, y: 150 },
      { x: 400, y: 200 },
      { x: 250, y: 350 },
      { x: 550, y: 350 }
    ];

    positions.forEach(pos => {
      const collectible = this.collectibles.create(pos.x, pos.y, 'collectible');
      collectible.setCollideWorldBounds(true);
      // 添加轻微的浮动效果
      this.tweens.add({
        targets: collectible,
        y: collectible.y - 10,
        duration: 1000,
        yoyo: true,
        repeat: -1,
        ease: 'Sine.easeInOut'
      });
    });

    // 设置碰撞检测
    this.physics.add.overlap(
      this.player,
      this.collectibles,
      this.collectItem,
      null,
      this
    );

    // 创建分数文本
    this.scoreText = this.add.text(16, 16, 'Score: 0', {
      fontSize: '32px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });
    this.scoreText.setDepth(10);

    // 创建键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 添加提示文本
    this.add.text(400, 550, 'Use Arrow Keys to Move', {
      fontSize: '20px',
      fill: '#ffff00',
      fontFamily: 'Arial'
    }).setOrigin(0.5);
  }

  update() {
    // 玩家移动控制
    const speed = 200;

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    } else {
      this.player.setVelocityX(0);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    } else {
      this.player.setVelocityY(0);
    }
  }

  collectItem(player, collectible) {
    // 销毁收集物
    collectible.destroy();

    // 增加分数
    this.score += 10;

    // 更新分数显示
    this.scoreText.setText('Score: ' + this.score);

    // 添加收集特效（闪烁文本）
    const collectText = this.add.text(collectible.x, collectible.y, '+10', {
      fontSize: '24px',
      fill: '#00ffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5);

    this.tweens.add({
      targets: collectText,
      y: collectText.y - 50,
      alpha: 0,
      duration: 800,
      ease: 'Power2',
      onComplete: () => {
        collectText.destroy();
      }
    });

    // 检查是否收集完所有物品
    if (this.collectibles.countActive(true) === 0) {
      const winText = this.add.text(400, 300, 'All Collected!\nFinal Score: ' + this.score, {
        fontSize: '48px',
        fill: '#ffff00',
        fontFamily: 'Arial',
        stroke: '#000000',
        strokeThickness: 6,
        align: 'center'
      }).setOrigin(0.5);

      // 停止玩家移动
      this.player.setVelocity(0, 0);
      this.cursors = null;
    }
  }
}

// 游戏配置
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

// 创建游戏实例
const game = new Phaser.Game(config);
