REQ: 创建一个菱形图形，使用 Tween 动画在 3 秒内从透明（alpha=0）渐变到完全不透明（alpha=1），并循环播放
API: Phaser.GameObjects.Graphics, Phaser.Tweens.TweenManager#add, Phaser.GameObjects.GameObject.alpha
STEPS:
1. 使用 Graphics 绘制菱形形状并生成纹理
2. 创建 Sprite 使用该纹理，初始 alpha 设为 0
3. 使用 tweens.add 创建透明度动画，从 0 到 1，持续 3000ms，设置 yoyo 和 repeat 实现循环
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: {
    preload: preload,
    create: create
  }
};

function preload() {
  // 不需要加载外部资源
}

function create() {
  // 使用 Graphics 绘制菱形
  const graphics = this.add.graphics();

  // 设置填充颜色为蓝色
  graphics.fillStyle(0x00aaff, 1);

  // 绘制菱形（中心点为 50, 50，宽高各 100）
  graphics.beginPath();
  graphics.moveTo(50, 0);      // 顶点
  graphics.lineTo(100, 50);    // 右点
  graphics.lineTo(50, 100);    // 底点
  graphics.lineTo(0, 50);      // 左点
  graphics.closePath();
  graphics.fillPath();

  // 生成纹理
  graphics.generateTexture('diamond', 100, 100);
  graphics.destroy();

  // 创建菱形精灵，放置在屏幕中央
  const diamond = this.add.sprite(400, 300, 'diamond');

  // 设置初始透明度为 0（完全透明）
  diamond.setAlpha(0);

  // 创建透明度渐变动画
  this.tweens.add({
    targets: diamond,           // 动画目标对象
    alpha: 1,                   // 目标透明度值
    duration: 3000,             // 持续时间 3 秒
    ease: 'Linear',             // 线性缓动
    yoyo: true,                 // 反向播放（1 -> 0）
    repeat: -1                  // 无限循环（-1 表示永久重复）
  });
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现12个白色小球在封闭空间内以80速度移动，碰到边界和彼此时弹开
API: Phaser.Physics.Arcade.Group, Phaser.GameObjects.Graphics, Phaser.Physics.Arcade.Body.setBounce, Phaser.Physics.Arcade.World.setBoundsCollision, Phaser.Physics.Arcade.Collider
STEPS:
1. 配置 Arcade 物理系统，创建游戏场景
2. 使用 Graphics 生成白色圆形纹理作为小球外观
3. 创建物理组，添加12个小球并设置随机初始速度(80)
4. 为每个小球设置弹性系数(bounce=1)实现完全弹性碰撞
5. 启用世界边界碰撞和小球之间的碰撞检测
6. 添加碰撞计数器作为可验证状态信号
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.collisionCount = 0; // 可验证的状态信号
  }

  preload() {
    // 无需加载外部资源
  }

  create() {
    const { width, height } = this.cameras.main;

    // 使用 Graphics 生成白色圆形纹理
    const graphics = this.add.graphics();
    graphics.fillStyle(0xffffff, 1);
    graphics.fillCircle(16, 16, 16); // 半径16的圆
    graphics.generateTexture('ball', 32, 32);
    graphics.destroy();

    // 创建物理组
    this.balls = this.physics.add.group({
      key: 'ball',
      repeat: 11, // 创建12个小球 (1 + 11)
      bounceX: 1, // 完全弹性碰撞
      bounceY: 1,
      collideWorldBounds: true // 与世界边界碰撞
    });

    // 设置世界边界碰撞
    this.physics.world.setBoundsCollision(true, true, true, true);

    // 为每个小球设置随机位置和速度
    const balls = this.balls.getChildren();
    balls.forEach((ball, index) => {
      // 随机位置（避免重叠）
      const x = Phaser.Math.Between(50, width - 50);
      const y = Phaser.Math.Between(50, height - 50);
      ball.setPosition(x, y);

      // 随机方向，固定速度80
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const velocityX = Math.cos(angle) * 80;
      const velocityY = Math.sin(angle) * 80;
      ball.setVelocity(velocityX, velocityY);

      // 设置圆形碰撞体
      ball.body.setCircle(16);
    });

    // 小球之间的碰撞检测
    this.physics.add.collider(this.balls, this.balls, () => {
      this.collisionCount++;
    });

    // 显示状态信息
    this.statusText = this.add.text(10, 10, '', {
      fontSize: '16px',
      fill: '#ffffff',
      backgroundColor: '#000000',
      padding: { x: 10, y: 5 }
    });

    // 添加边界碰撞计数
    this.boundaryCollisionCount = 0;
    balls.forEach(ball => {
      ball.body.onWorldBounds = true;
    });

    this.physics.world.on('worldbounds', () => {
      this.boundaryCollisionCount++;
    });
  }

  update(time, delta) {
    // 更新状态显示
    this.statusText.setText([
      `Balls: ${this.balls.getChildren().length}`,
      `Ball Collisions: ${this.collisionCount}`,
      `Boundary Collisions: ${this.boundaryCollisionCount}`,
      `Speed: 80 px/s`
    ]);

    // 验证速度保持在80左右（考虑浮点误差）
    const balls = this.balls.getChildren();
    balls.forEach(ball => {
      const speed = Math.sqrt(
        ball.body.velocity.x ** 2 + 
        ball.body.velocity.y ** 2
      );

      // 如果速度偏差较大，重新归一化到80
      if (Math.abs(speed - 80) > 1) {
        const normalizedVx = (ball.body.velocity.x / speed) * 80;
        const normalizedVy = (ball.body.velocity.y / speed) * 80;
        ball.setVelocity(normalizedVx, normalizedVy);
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 }, // 无重力
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

