  scene: { preload, create }
};

function preload() {
  // 无需预加载外部资源
}

function create() {
  // 创建 Graphics 对象绘制黄色六边形
  const graphics = this.add.graphics();

  // 计算六边形顶点坐标（中心在 64, 64，半径 50）
  const radius = 50;
  const centerX = 64;
  const centerY = 64;
  const hexagonPoints = [];

  for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 3) * i - Math.PI / 2; // 从顶部开始
    const x = centerX + radius * Math.cos(angle);
    const y = centerY + radius * Math.sin(angle);
    hexagonPoints.push(x, y);
  }

  // 绘制黄色六边形
  graphics.fillStyle(0xffff00, 1);
  graphics.fillPolygon(hexagonPoints);

  // 生成纹理
  graphics.generateTexture('hexagon', 128, 128);
  graphics.destroy(); // 销毁 graphics 对象，不再需要

  // 创建精灵对象
  const hexagonSprite = this.add.sprite(400, 300, 'hexagon');

  // 创建淡入淡出动画
  // 使用 yoyo 实现淡入淡出效果，duration 1000ms 表示淡入+淡出总共 2 秒
  // 要实现 1 秒完成淡入淡出，每个方向需要 500ms
  this.tweens.add({
    targets: hexagonSprite,
    alpha: 0,           // 从当前 alpha(1) 淡出到 0
    duration: 500,      // 淡出持续 500ms
    yoyo: true,         // 启用 yoyo 效果，淡出后自动淡入
    repeat: -1,         // 无限循环
    ease: 'Linear'      // 线性缓动
  });

  // 添加提示文本
  this.add.text(400, 500, '黄色六边形淡入淡出循环动画', {
    fontSize: '20px',
    color: '#ffffff'
  }).setOrigin(0.5);
}

new Phaser.Game(config);
```

[PLAN]
REQ: 实现鼠标点击发射子弹射击敌人，命中后敌人消失并显示击杀数
API: this.physics.add.sprite, this.input.on, this.physics.add.overlap, this.add.text, Graphics.generateTexture
STEPS:
1. 创建玩家飞船（使用 Graphics 生成三角形纹理）
2. 创建敌人组（使用 Graphics 生成红色方块纹理），随机生成位置
3. 创建子弹组（使用 Graphics 生成黄色圆形纹理）
4. 监听鼠标左键点击事件，从玩家位置发射子弹（速度240）
5. 设置子弹与敌人的碰撞检测，命中时销毁双方并增加击杀数
6. 显示击杀数文本并实时更新
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.killCount = 0; // 可验证的状态信号
  }

  preload() {
    // 创建玩家纹理（蓝色三角形飞船）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x0088ff, 1);
    playerGraphics.beginPath();
    playerGraphics.moveTo(16, 0);
    playerGraphics.lineTo(0, 32);
    playerGraphics.lineTo(32, 32);
    playerGraphics.closePath();
    playerGraphics.fillPath();
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 创建敌人纹理（红色方块）
    const enemyGraphics = this.add.graphics();
    enemyGraphics.fillStyle(0xff0000, 1);
    enemyGraphics.fillRect(0, 0, 40, 40);
    enemyGraphics.generateTexture('enemy', 40, 40);
    enemyGraphics.destroy();

    // 创建子弹纹理（黄色圆形）
    const bulletGraphics = this.add.graphics();
    bulletGraphics.fillStyle(0xffff00, 1);
    bulletGraphics.fillCircle(4, 4, 4);
    bulletGraphics.generateTexture('bullet', 8, 8);
    bulletGraphics.destroy();
  }

  create() {
    // 创建玩家
    this.player = this.physics.add.sprite(400, 500, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建敌人组
    this.enemies = this.physics.add.group();

    // 生成初始敌人（5个）
    for (let i = 0; i < 5; i++) {
      const x = Phaser.Math.Between(50, 750);
      const y = Phaser.Math.Between(50, 250);
      const enemy = this.enemies.create(x, y, 'enemy');
      enemy.setVelocity(
        Phaser.Math.Between(-50, 50),
        Phaser.Math.Between(-50, 50)
      );
      enemy.setBounce(1);
      enemy.setCollideWorldBounds(true);
    }

    // 创建子弹组
    this.bullets = this.physics.add.group({
      defaultKey: 'bullet',
      maxSize: 30
    });

    // 监听鼠标左键点击
    this.input.on('pointerdown', (pointer) => {
      this.fireBullet(pointer);
    });

    // 设置子弹与敌人的碰撞检测
    this.physics.add.overlap(
      this.bullets,
      this.enemies,
      this.hitEnemy,
      null,
      this
    );

    // 显示击杀数文本
    this.killText = this.add.text(16, 16, 'Kills: 0', {
      fontSize: '24px',
      fill: '#ffffff',
      fontFamily: 'Arial',
      stroke: '#000000',
      strokeThickness: 4
    });

    // 添加提示文本
    this.add.text(400, 550, 'Click to shoot!', {
      fontSize: '18px',
      fill: '#00ff00',
      fontFamily: 'Arial'
    }).setOrigin(0.5);

    // 定时生成新敌人
    this.time.addEvent({
      delay: 3000,
      callback: this.spawnEnemy,
      callbackScope: this,
      loop: true
    });
  }

  fireBullet(pointer) {
    // 从玩家位置发射子弹
    const bullet = this.bullets.get(this.player.x, this.player.y);

    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);

      // 计算从玩家到鼠标点击位置的方向
      const angle = Phaser.Math.Angle.Between(
        this.player.x,
        this.player.y,
        pointer.x,
        pointer.y
      );

      // 设置子弹速度（速度240）
      this.physics.velocityFromRotation(angle, 240, bullet.body.velocity);

      // 子弹超出屏幕后自动销毁
      this.time.delayedCall(3000, () => {
        if (bullet.active) {
          bullet.setActive(false);
          bullet.setVisible(false);
        }
      });
    }
  }

  hitEnemy(bullet, enemy) {
    // 子弹命中敌人
    bullet.setActive(false);
    bullet.setVisible(false);

    enemy.destroy();

    // 增加击杀数
    this.killCount++;
    this.killText.setText('Kills: ' + this.killCount);

    // 添加击中特效（白色闪光）
    const flash = this.add.graphics();
    flash.fillStyle(0xffffff, 0.8);
    flash.fillCircle(enemy.x, enemy.y, 20);
    this.tweens.add({
      targets: flash,
      alpha: 0,
      duration: 200,
      onComplete: () => flash.destroy()
    });
  }

  spawnEnemy() {
    // 随机生成新敌人
    const x = Phaser.Math.Between(50, 750);
    const y = Phaser.Math.Between(50, 250);
    const enemy = this.enemies.create(x, y, 'enemy');
    enemy.setVelocity(
      Phaser.Math.Between(-50, 50),
      Phaser.Math.Between(-50, 50)
    );
    enemy.setBounce(1);
    enemy.setCollideWorldBounds(true);
  }

  update(time, delta) {
    // 清理超出屏幕的子弹
    this.bullets.children.entries.forEach(bullet => {
      if (bullet.active && (
        bullet.x < -10 || bullet.x > 810 ||
        bullet.y < -10 || bullet.y > 610
      )) {
        bullet.setActive(false);
        bullet.setVisible(false);
      }
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#1a1a2e',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

