    a: Phaser.Input.Keyboard.KeyCodes.A,
    s: Phaser.Input.Keyboard.KeyCodes.S,
    d: Phaser.Input.Keyboard.KeyCodes.D
  });

  // 添加提示文本
  this.add.text(10, 10, 'Use WASD to move the circle', {
    fontSize: '16px',
    color: '#ffffff'
  });
}

function update(time, delta) {
  // 计算每帧的移动距离 = 速度 * 时间（秒）
  const distance = SPEED * (delta / 1000);

  // 检测 W 键（向上）
  if (keys.w.isDown) {
    player.y -= distance;
  }

  // 检测 S 键（向下）
  if (keys.s.isDown) {
    player.y += distance;
  }

  // 检测 A 键（向左）
  if (keys.a.isDown) {
    player.x -= distance;
  }

  // 检测 D 键（向右）
  if (keys.d.isDown) {
    player.x += distance;
  }

  // 边界限制（可选）- 防止圆形移出画布
  player.x = Phaser.Math.Clamp(player.x, 25, 775);
  player.y = Phaser.Math.Clamp(player.y, 25, 575);
}

// 启动游戏
new Phaser.Game(config);
```

[PLAN]
REQ: 实现AI追踪玩家的收集游戏，玩家收集3个物品获胜，被AI碰到失败
API: Phaser.Physics.Arcade.Sprite, Phaser.Physics.Arcade.moveToObject, Phaser.Input.Keyboard.createCursorKeys, Phaser.Physics.Arcade.overlap
STEPS:
1. 创建物理系统和场景配置
2. 使用Graphics生成玩家(绿色方块)、AI(青色圆形)、收集物(黄色星形)纹理
3. 实现玩家键盘控制移动逻辑
4. 实现AI以360速度追踪玩家的moveToObject逻辑
5. 检测玩家与收集物的碰撞，收集计数
6. 检测玩家与AI的碰撞，触发失败
7. 当收集数达到3时触发胜利，显示游戏结果
[/PLAN]

```javascript
class GameScene extends Phaser.Scene {
  constructor() {
    super('GameScene');
    this.score = 0; // 可验证状态
    this.gameOver = false;
    this.gameWon = false;
  }

  preload() {
    // 不需要加载外部资源
  }

  create() {
    const { width, height } = this.cameras.main;

    // 生成玩家纹理（绿色方块）
    const playerGraphics = this.add.graphics();
    playerGraphics.fillStyle(0x00ff00, 1);
    playerGraphics.fillRect(0, 0, 32, 32);
    playerGraphics.generateTexture('player', 32, 32);
    playerGraphics.destroy();

    // 生成AI纹理（青色圆形）
    const aiGraphics = this.add.graphics();
    aiGraphics.fillStyle(0x00ffff, 1);
    aiGraphics.fillCircle(20, 20, 20);
    aiGraphics.generateTexture('ai', 40, 40);
    aiGraphics.destroy();

    // 生成收集物纹理（黄色星形）
    const itemGraphics = this.add.graphics();
    itemGraphics.fillStyle(0xffff00, 1);
    itemGraphics.beginPath();
    for (let i = 0; i < 5; i++) {
      const angle = (i * 144 - 90) * Math.PI / 180;
      const x = 16 + Math.cos(angle) * 16;
      const y = 16 + Math.sin(angle) * 16;
      if (i === 0) {
        itemGraphics.moveTo(x, y);
      } else {
        itemGraphics.lineTo(x, y);
      }
    }
    itemGraphics.closePath();
    itemGraphics.fillPath();
    itemGraphics.generateTexture('item', 32, 32);
    itemGraphics.destroy();

    // 创建玩家
    this.player = this.physics.add.sprite(width / 2, height / 2, 'player');
    this.player.setCollideWorldBounds(true);

    // 创建AI
    this.ai = this.physics.add.sprite(100, 100, 'ai');
    this.ai.setCollideWorldBounds(true);

    // 创建收集物组
    this.items = this.physics.add.group();

    // 使用固定种子生成收集物位置（确定性）
    const positions = [
      { x: 200, y: 150 },
      { x: 600, y: 150 },
      { x: 400, y: 450 }
    ];

    positions.forEach(pos => {
      const item = this.items.create(pos.x, pos.y, 'item');
      item.setCollideWorldBounds(true);
    });

    // 键盘控制
    this.cursors = this.input.keyboard.createCursorKeys();

    // 碰撞检测：玩家收集物品
    this.physics.add.overlap(this.player, this.items, this.collectItem, null, this);

    // 碰撞检测：AI碰到玩家
    this.physics.add.overlap(this.player, this.ai, this.hitByAI, null, this);

    // UI文本
    this.scoreText = this.add.text(16, 16, 'Score: 0 / 3', {
      fontSize: '24px',
      fill: '#ffffff'
    });

    this.resultText = this.add.text(width / 2, height / 2, '', {
      fontSize: '48px',
      fill: '#ffffff'
    });
    this.resultText.setOrigin(0.5);
    this.resultText.setVisible(false);
  }

  update(time, delta) {
    if (this.gameOver) {
      return;
    }

    // 玩家移动控制
    const speed = 200;
    this.player.setVelocity(0);

    if (this.cursors.left.isDown) {
      this.player.setVelocityX(-speed);
    } else if (this.cursors.right.isDown) {
      this.player.setVelocityX(speed);
    }

    if (this.cursors.up.isDown) {
      this.player.setVelocityY(-speed);
    } else if (this.cursors.down.isDown) {
      this.player.setVelocityY(speed);
    }

    // AI追踪玩家，速度360
    this.physics.moveToObject(this.ai, this.player, 360);
  }

  collectItem(player, item) {
    // 收集物品
    item.destroy();
    this.score++;
    this.scoreText.setText('Score: ' + this.score + ' / 3');

    // 检查胜利条件
    if (this.score >= 3) {
      this.gameWon = true;
      this.gameOver = true;
      this.endGame('YOU WIN!', '#00ff00');
    }
  }

  hitByAI(player, ai) {
    // 被AI碰到，游戏失败
    if (!this.gameOver) {
      this.gameOver = true;
      this.gameWon = false;
      this.endGame('GAME OVER!', '#ff0000');
    }
  }

  endGame(message, color) {
    // 停止所有物理对象
    this.player.setVelocity(0);
    this.ai.setVelocity(0);
    this.physics.pause();

    // 显示结果
    this.resultText.setText(message);
    this.resultText.setColor(color);
    this.resultText.setVisible(true);

    // 添加重启提示
    this.time.delayedCall(1000, () => {
      const restartText = this.add.text(
        this.cameras.main.width / 2,
        this.cameras.main.height / 2 + 60,
        'Press SPACE to restart',
        { fontSize: '24px', fill: '#ffffff' }
      );
      restartText.setOrigin(0.5);

      // 空格键重启
      this.input.keyboard.once('keydown-SPACE', () => {
        this.scene.restart();
      });
    });
  }
}

const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  },
  scene: GameScene
};

new Phaser.Game(config);
```

[PLAN]
REQ: 绘制10个随机位置的粉色菱形，每个大小为24像素
API: Phaser.GameObjects.Graphics, Graphics#fillStyle, Graphics#fillPath, Phaser.Geom.Polygon, Phaser.Math.Between
STEPS:
1. 创建 Phaser Game 配置，设置场景宽高
2. 在 create 方法中循环10次
3. 每次循环创建一个 Graphics 对象
4. 使用 fillStyle 设置粉色填充
5. 使用 Polygon 定义菱形路径（4个顶点），大小为24像素
6. 使用 fillPath 填充菱形
7. 使用 Math.Between 生成随机位置坐标
8. 将 Graphics 对象定位到随机位置
[/PLAN]

```javascript
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  backgroundColor: '#2d2d2d',
  scene: { preload, create }
};

function preload() {
  // 无需预加载资源
}

function create() {
  // 绘制10个随机位置的粉色菱形
  for (let i = 0; i < 10; i++) {
    // 创建 Graphics 对象
    const graphics = this.add.graphics();

    // 设置粉色填充 (FFC0CB 是粉色的十六进制值)
    graphics.fillStyle(0xFFC0CB, 1);

    // 定义菱形的4个顶点（大小为24像素）
    // 菱形中心在原点，向上下左右各延伸12像素
    const diamond = new Phaser.Geom.Polygon([
      0, -12,    // 顶部顶点
      12, 0,     // 右侧顶点
      0, 12,     // 底部顶点
      -12, 0     // 左侧顶点
    ]);

    // 填充菱形路径
    graphics.fillPoints(diamond.points, true);

    // 生成随机位置（留出边距，避免菱形超出画布）
    const randomX = Phaser.Math.Between(20, 780);
    const randomY = Phaser.Math.Between(20, 580);

    // 设置 Graphics 对象位置
    graphics.setPosition(randomX, randomY);
  }
}

new Phaser.Game(config);
```
